def _x0_example_tensors(example: Any, device: torch.device) -> dict[str, torch.Tensor]:
    """Move one x0 posterior training example to the requested device."""
    target_values = np.asarray(getattr(example, "target_values"), dtype=np.float32).reshape(-1)
    target_ids = list(getattr(example, "target_ids", []))
    target_count = max(len(target_ids), int(target_values.size))
    structure_features = getattr(example, "target_structure_features", None)
    if structure_features is None:
        structure_array = np.zeros((target_count, 0), dtype=np.float32)
    else:
        structure_array = np.asarray(structure_features, dtype=np.float32)
    return {
        "sequence_tokens": torch.tensor(
            getattr(example, "sequence_tokens"),
            dtype=torch.long,
            device=device,
        ),
        "example_features": torch.tensor(
            getattr(example, "example_features"),
            dtype=torch.float32,
            device=device,
        ),
        "target_features": torch.tensor(
            getattr(example, "target_features"),
            dtype=torch.float32,
            device=device,
        ),
        "target_structure_features": torch.tensor(
            structure_array,
            dtype=torch.float32,
            device=device,
        ),
        "target_values": torch.tensor(
            target_values,
            dtype=torch.float32,
            device=device,
        ),
        "target_sigmas": torch.tensor(
            getattr(example, "target_sigmas"),
            dtype=torch.float32,
            device=device,
        ),
        "family_indices": torch.tensor(
            getattr(example, "family_indices"),
            dtype=torch.long,
            device=device,
        ),
    }

