def _load_x0_checkpoint_if_requested(
    *,
    model: nn.Module,
    provider: Any | None = None,
    checkpoint_path: str | None,
    device: torch.device,
    widen_tensors: bool = False,
    exclude_prefixes: Sequence[str] | None = None,
) -> dict[str, Any]:
    if not checkpoint_path:
        return {"loaded": False, "path": ""}
    path = Path(checkpoint_path)
    if not path.exists():
        raise FileNotFoundError(f"x0 posterior checkpoint not found: {path}")
    checkpoint = torch.load(path, map_location=device)
    state = checkpoint.get("model_state_dict", checkpoint)
    current = model.state_dict()
    compatible: dict[str, torch.Tensor] = {}
    skipped: list[str] = []
    excluded: list[str] = []
    widened: list[str] = []
    prefixes = tuple(str(prefix) for prefix in (exclude_prefixes or ()) if str(prefix))
    for key, value in state.items():
        if prefixes and key.startswith(prefixes):
            excluded.append(key)
            continue
        if key in current and tuple(current[key].shape) == tuple(value.shape):
            compatible[key] = value
        elif (
            bool(widen_tensors)
            and key in current
            and isinstance(value, torch.Tensor)
            and isinstance(current[key], torch.Tensor)
            and current[key].ndim == value.ndim
            and current[key].ndim > 0
        ):
            adapted = current[key].detach().clone()
            slices = tuple(
                slice(0, min(int(target), int(source)))
                for target, source in zip(adapted.shape, value.shape)
            )
            adapted[slices] = value.detach().to(device=adapted.device, dtype=adapted.dtype)[
                slices
            ]
            if adapted.ndim == 2 and int(adapted.shape[1]) > int(value.shape[1]):
                # Preserve the old function at load time while keeping new output rows
                # trainable: new input channels start disconnected, then wake up as
                # upstream widened rows learn non-zero activations.
                adapted[:, int(value.shape[1]) :] = 0
            compatible[key] = adapted
            widened.append(key)
        else:
            skipped.append(key)
    missing, unexpected = model.load_state_dict(compatible, strict=False)
    provider_state = checkpoint.get("provider_trainable_state_dict", {})
    provider_state_keys = 0
    if provider is not None and isinstance(provider_state, dict) and provider_state:
        from atypemu.training.bioemu_latent_nmr import (
            _load_bioemu_provider_trainable_state_dict,
        )

        provider_state_keys = int(len(provider_state))
        _load_bioemu_provider_trainable_state_dict(provider, provider_state)
    return {
        "loaded": True,
        "path": str(path),
        "compatible_keys": int(len(compatible)),
        "provider_trainable_state_keys": int(provider_state_keys),
        "excluded_keys": excluded[:100],
        "widened_keys": widened[:100],
        "skipped_keys": skipped[:100],
        "missing_keys": list(missing)[:100],
        "unexpected_keys": list(unexpected)[:100],
        "checkpoint_epoch": checkpoint.get("epoch"),
    }


def _x0_abs_stats(tensor: torch.Tensor) -> dict[str, float]:
    if tensor.numel() == 0:
        return {"abs_mean": 0.0, "abs_max": 0.0}
    detached = tensor.detach().float()
    return {
        "abs_mean": float(detached.abs().mean().cpu()),
        "abs_max": float(detached.abs().max().cpu()),
    }


def _x0_generator_for_tensor(tensor: torch.Tensor, seed: int) -> torch.Generator:
    generator_device: torch.device | str = "cpu"
    if tensor.device.type == "cuda":
        generator_device = tensor.device
    generator = torch.Generator(device=generator_device)
    generator.manual_seed(int(seed))
    return generator


def _maybe_wakeup_official_x2d_adapter(
    provider: Any | None,
    config: StudentTrainingConfig,
    device: torch.device,
) -> dict[str, Any]:
    """Give zero-loaded official x2d actuator layers a small nonzero start."""

    init_std = max(
        float(getattr(config, "bioemu_official_x2d_adapter_wakeup_init_std", 0.0)),
        0.0,
    )
    condition_output_std = max(
        float(
            getattr(
                config,
                "bioemu_official_x2d_adapter_wakeup_condition_output_std",
                0.0,
            )
        ),
        0.0,
    )
    threshold = max(
        float(
            getattr(
                config,
                "bioemu_official_x2d_adapter_wakeup_zero_threshold",
                1.0e-12,
            )
        ),
        0.0,
    )
    seed = int(getattr(config, "bioemu_official_x2d_adapter_wakeup_seed", 1009))
    force = bool(getattr(config, "bioemu_official_x2d_adapter_wakeup_force", False))
    enabled = init_std > 0.0 or condition_output_std > 0.0
    summary: dict[str, Any] = {
        "enabled": bool(enabled),
        "applied": False,
        "applied_tensors": 0,
        "eligible_tensors": 0,
        "init_std": float(init_std),
        "condition_output_std": float(condition_output_std),
        "zero_threshold": float(threshold),
        "seed": int(seed),
        "force": bool(force),
        "targets": [],
    }
    if not enabled:
        summary["reason"] = "disabled"
        return summary
    loaded_model = getattr(provider, "_model", None) if provider is not None else None
    adapter = None
    if isinstance(loaded_model, nn.Module):
        adapter = getattr(loaded_model, "atypemu_x2d_adapter", None)
    if adapter is None and provider is not None:
        adapter = getattr(provider, "_x2d_adapter", None)
    if not isinstance(adapter, nn.Module):
        summary["reason"] = "official_x2d_adapter_not_loaded"
        return summary

    targets: list[tuple[str, torch.Tensor, float]] = []
    up = getattr(adapter, "up", None)
    if init_std > 0.0 and isinstance(up, nn.Linear):
        targets.append(("up.weight", up.weight, init_std))
        if up.bias is not None:
            targets.append(("up.bias", up.bias, init_std))
    condition_output = getattr(adapter, "condition_output", None)
    if condition_output_std > 0.0 and isinstance(condition_output, nn.Linear):
        targets.append(
            ("condition_output.weight", condition_output.weight, condition_output_std)
        )
    if not targets:
        summary["reason"] = "no_matching_x2d_actuator_tensors"
        return summary

    applied = 0
    target_summaries: list[dict[str, Any]] = []
    with torch.no_grad():
        for target_index, (name, tensor, std) in enumerate(targets):
            before = _x0_abs_stats(tensor)
            should_apply = force or before["abs_max"] <= threshold
            target_summary: dict[str, Any] = {
                "name": name,
                "std": float(std),
                "applied": bool(should_apply),
                "before_abs_mean": before["abs_mean"],
                "before_abs_max": before["abs_max"],
            }
            if should_apply:
                generator = _x0_generator_for_tensor(
                    tensor,
                    seed + 104729 * (target_index + 1),
                )
                tensor.normal_(mean=0.0, std=float(std), generator=generator)
                applied += 1
            after = _x0_abs_stats(tensor)
            target_summary.update(
                {
                    "after_abs_mean": after["abs_mean"],
                    "after_abs_max": after["abs_max"],
                }
            )
            target_summaries.append(target_summary)

    summary["eligible_tensors"] = int(len(targets))
    summary["applied_tensors"] = int(applied)
    summary["applied"] = bool(applied > 0)
    summary["reason"] = "applied" if applied > 0 else "all_targets_above_threshold"
    summary["targets"] = target_summaries
    summary["device"] = str(device)
    return summary


def _load_x0_capacity_adapter_checkpoint_if_requested(
    *,
    model: nn.Module,
    checkpoint_path: str | None,
    device: torch.device,
) -> dict[str, Any]:
    """Load only the zero-init decoder capacity adapter from a side checkpoint.

    Stage-A decoder pretraining is built without Stage-C evidence features, so
    loading a Stage-A checkpoint as the primary checkpoint would replace the
    validated posterior/evidence heads.  This side-load keeps those heads from
    the primary Stage-C checkpoint and imports only the larger adapter weights.
    """

    if not checkpoint_path:
        return {"loaded": False, "path": ""}
    path = Path(checkpoint_path)
    if not path.exists():
        raise FileNotFoundError(f"x0 capacity adapter checkpoint not found: {path}")
    checkpoint = torch.load(path, map_location=device)
    state = checkpoint.get("model_state_dict", checkpoint)
    current = model.state_dict()
    prefix = "decoder.capacity_adapter_mean_delta."
    compatible: dict[str, torch.Tensor] = {}
    skipped: list[str] = []
    for key, value in state.items():
        if not key.startswith(prefix):
            continue
        if key in current and tuple(current[key].shape) == tuple(value.shape):
            compatible[key] = value
        else:
            skipped.append(key)
    if not compatible:
        raise ValueError(
            "No compatible decoder capacity adapter tensors were found in "
            f"{path}. Check adapter hidden/depth/capacity settings."
        )
    missing, unexpected = model.load_state_dict(compatible, strict=False)
    return {
        "loaded": True,
        "path": str(path),
        "compatible_keys": int(len(compatible)),
        "skipped_keys": skipped[:100],
        "missing_keys": list(missing)[:100],
        "unexpected_keys": list(unexpected)[:100],
        "checkpoint_epoch": checkpoint.get("epoch"),
    }


def _maybe_reinitialize_posterior_modes_on_load(
    model: nn.Module,
    config: StudentTrainingConfig,
) -> dict[str, Any]:
    """Optionally re-seed only the internal posterior-mode symmetry breaker."""

    std = max(float(getattr(config, "bioemu_x0_posterior_mode_reinit_std_on_load", 0.0)), 0.0)
    mode_module = getattr(model, "posterior_mode_mixture", None)
    if std <= 0.0 or mode_module is None:
        return {"posterior_mode_reinit_applied": False}
    energy_head = getattr(mode_module, "energy_delta_head", None)
    if energy_head is None or len(energy_head) <= 0:
        return {"posterior_mode_reinit_applied": False}
    final_layer = energy_head[-1]
    if not isinstance(final_layer, nn.Linear):
        return {"posterior_mode_reinit_applied": False}
    nn.init.normal_(final_layer.weight, mean=0.0, std=std)
    if final_layer.bias is not None:
        nn.init.zeros_(final_layer.bias)
    reset_logits = bool(getattr(config, "bioemu_x0_posterior_mode_reinit_reset_logits", False))
    if reset_logits:
        mode_logits = getattr(mode_module, "mode_logits", None)
        if isinstance(mode_logits, nn.Parameter):
            with torch.no_grad():
                mode_logits.zero_()
        logit_head = getattr(mode_module, "mode_logit_head", None)
        if logit_head is not None and len(logit_head) > 0 and isinstance(logit_head[-1], nn.Linear):
            nn.init.zeros_(logit_head[-1].weight)
            if logit_head[-1].bias is not None:
                nn.init.zeros_(logit_head[-1].bias)
    return {
        "posterior_mode_reinit_applied": True,
        "posterior_mode_reinit_std": float(std),
        "posterior_mode_reinit_reset_logits": reset_logits,
    }


def _trainable_parameter_snapshot(
    parameters: list[nn.Parameter],
) -> list[tuple[nn.Parameter, torch.Tensor]]:
    """Capture trainable tensors so unstable optimizer steps can be rolled back."""

    return [
        (parameter, parameter.detach().cpu().clone())
        for parameter in parameters
        if parameter.requires_grad
    ]


def _restore_parameter_snapshot(
    snapshot: list[tuple[nn.Parameter, torch.Tensor]],
) -> None:
    """Restore model parameters from a snapshot captured before optimizer.step()."""

    with torch.no_grad():
        for parameter, value in snapshot:
            parameter.copy_(value.to(device=parameter.device, dtype=parameter.dtype))


def _parameter_update_summary(
    snapshot: Sequence[tuple[nn.Parameter, torch.Tensor]],
    *,
    prefix: str,
    parameter_ids: set[int] | None = None,
) -> dict[str, float]:
    """Summarize how much a selected parameter subset moved after an optimizer step."""

    selected_count = 0
    updated_count = 0
    update_value_count = 0
    nonfinite_update_value_count = 0
    update_norm_sq = 0.0
    update_abs_max = 0.0
    for parameter, before in snapshot:
        if parameter_ids is not None and id(parameter) not in parameter_ids:
            continue
        if not parameter.requires_grad or not parameter.is_floating_point():
            continue
        selected_count += 1
        current = parameter.detach().cpu()
        delta = current - before.to(device=current.device, dtype=current.dtype)
        update_value_count += int(delta.numel())
        finite_mask = torch.isfinite(delta)
        finite_count = int(torch.count_nonzero(finite_mask).detach().cpu())
        nonfinite_update_value_count += int(delta.numel() - finite_count)
        if finite_count <= 0:
            continue
        finite_delta = delta[finite_mask]
        abs_delta = finite_delta.abs()
        update_abs_max = max(
            update_abs_max,
            float(abs_delta.max().detach().cpu()) if abs_delta.numel() else 0.0,
        )
        norm_sq = float(torch.sum(finite_delta.square()).detach().cpu())
        if norm_sq > 0.0:
            updated_count += 1
            update_norm_sq += norm_sq
    return {
        f"{prefix}_update_parameter_tensors": float(selected_count),
        f"{prefix}_updated_parameter_tensors": float(updated_count),
        f"{prefix}_update_values": float(update_value_count),
        f"{prefix}_nonfinite_update_values": float(nonfinite_update_value_count),
        f"{prefix}_update_norm": float(math.sqrt(max(update_norm_sq, 0.0))),
        f"{prefix}_update_abs_max": float(update_abs_max),
    }


def _parameter_nonfinite_count(parameters: list[nn.Parameter]) -> int:
    """Count non-finite values across trainable floating-point parameters."""

    total = 0
    for parameter in parameters:
        if not parameter.requires_grad or not parameter.is_floating_point():
            continue
        finite = torch.isfinite(parameter.detach())
        if not bool(finite.all()):
            total += int(parameter.numel() - torch.count_nonzero(finite).detach().cpu())
    return int(total)


def _gradient_nonfinite_count(parameters: list[nn.Parameter]) -> int:
    """Count non-finite values across accumulated gradients."""

    total = 0
    for parameter in parameters:
        grad = parameter.grad
        if grad is None or not grad.is_floating_point():
            continue
        finite = torch.isfinite(grad.detach())
        if not bool(finite.all()):
            total += int(grad.numel() - torch.count_nonzero(finite).detach().cpu())
    return int(total)


def _optimizer_trainable_parameters(
    optimizer: torch.optim.Optimizer,
) -> list[nn.Parameter]:
    """Return unique trainable tensors that the optimizer can actually update."""

    parameters: list[nn.Parameter] = []
    seen: set[int] = set()
    for group in optimizer.param_groups:
        for parameter in group.get("params", []):
            if not isinstance(parameter, nn.Parameter):
                continue
            if not parameter.requires_grad:
                continue
            parameter_id = id(parameter)
            if parameter_id in seen:
                continue
            seen.add(parameter_id)
            parameters.append(parameter)
    return parameters


def _provider_trainable_parameter_ids(provider: Any) -> set[int]:
    """Identify trainable provider tensors for optimizer/gradient diagnostics."""

    loaded_model = getattr(provider, "_model", None)
    if not isinstance(loaded_model, nn.Module):
        return set()
    return {id(parameter) for parameter in loaded_model.parameters() if parameter.requires_grad}


def _provider_named_trainable_parameter_groups(
    provider: Any,
) -> dict[str, list[nn.Parameter]]:
    """Group provider adapter tensors for generator-architecture audits."""

    loaded_model = getattr(provider, "_model", None)
    if not isinstance(loaded_model, nn.Module):
        return {}
    groups: dict[str, list[nn.Parameter]] = {
        "x1d": [],
        "x1d_core": [],
        "x1d_conditioning": [],
        "x2d": [],
        "x2d_core": [],
        "x2d_conditioning": [],
        "conditioning": [],
    }
    for name, parameter in loaded_model.named_parameters():
        if not parameter.requires_grad:
            continue
        is_x1d = "atypemu_x1d_adapter" in name
        is_x2d = "atypemu_x2d_adapter" in name
        is_conditioning = ".condition_" in name or "_condition" in name
        if is_x1d:
            groups["x1d"].append(parameter)
            groups["x1d_conditioning" if is_conditioning else "x1d_core"].append(
                parameter
            )
        if is_x2d:
            groups["x2d"].append(parameter)
            groups["x2d_conditioning" if is_conditioning else "x2d_core"].append(
                parameter
            )
        if is_conditioning:
            groups["conditioning"].append(parameter)
    return {key: value for key, value in groups.items() if value}


def _prior_logit_adapter_trainable_parameters(model: nn.Module) -> list[nn.Parameter]:
    adapter = getattr(model, "prior_logit_adapter", None)
    if not isinstance(adapter, nn.Module):
        return []
    return [parameter for parameter in adapter.parameters() if parameter.requires_grad]


def _posterior_energy_extra_trainable_parameters(model: nn.Module) -> list[nn.Parameter]:
    prefixes = (
        "energy_head.energy_extra_head.",
        "energy_head.energy_support_attention_head.",
    )
    return [
        parameter
        for name, parameter in model.named_parameters()
        if parameter.requires_grad and any(name.startswith(prefix) for prefix in prefixes)
    ]


def _parameter_id_set(parameters: Sequence[nn.Parameter]) -> set[int]:
    return {id(parameter) for parameter in parameters}


