def _update_provider_metadata_metrics(
    accumulator: _SplitAccumulator,
    provider_metadata: Mapping[str, Any] | None,
) -> None:
    """Expose provider actuator state in split summaries."""

    if not isinstance(provider_metadata, Mapping):
        return
    for key in _PROVIDER_METADATA_SCALAR_KEYS:
        value = provider_metadata.get(key)
        if isinstance(value, bool):
            accumulator.update_scalar_metric(f"provider_{key}", 1.0 if value else 0.0)
        elif isinstance(value, (int, float)) and math.isfinite(float(value)):
            accumulator.update_scalar_metric(f"provider_{key}", float(value))


def _update_compact_geometry_edge_metrics(
    accumulator: _SplitAccumulator,
    edge_diagnostics: Mapping[str, float] | None,
) -> None:
    """Expose compact geometry edge health in train/validation summaries."""

    if not isinstance(edge_diagnostics, Mapping):
        return
    for name, value in edge_diagnostics.items():
        if isinstance(value, bool):
            accumulator.update_scalar_metric(name, 1.0 if value else 0.0)
        elif isinstance(value, (int, float)) and math.isfinite(float(value)):
            accumulator.update_scalar_metric(name, float(value))


def _x0_sequence_embedding_residue_feature_dim(config: StudentTrainingConfig) -> int:
    """Return the residue feature width reserved for frozen PLM context."""

    return max(
        int(getattr(config, "bioemu_x0_sequence_embedding_residue_feature_dim", 0) or 0),
        0,
    )


def _x0_sequence_embedding_residue_context(
    *,
    sequence_embedding_provider: Any | None,
    entity_uid: str,
    sequence_tokens: torch.Tensor,
    sample_count: int,
    feature_dim: int,
    dtype: torch.dtype,
    device: torch.device,
    fail_on_missing: bool = False,
    accumulator: _SplitAccumulator | None = None,
) -> torch.Tensor | None:
    """Return `[K, L, D]` detached PLM residue context for x0 features."""

    width = max(int(feature_dim), 0)
    if width <= 0:
        return None
    residue_count = int(sequence_tokens.numel())
    support_count = max(int(sample_count), 1)
    zeros = torch.zeros(
        support_count,
        residue_count,
        width,
        dtype=dtype,
        device=device,
    )
    if sequence_embedding_provider is None:
        if accumulator is not None:
            accumulator.update_scalar_metric("x0_sequence_embedding_active", 0.0)
            accumulator.update_scalar_metric("x0_sequence_embedding_missing", 1.0)
        return zeros
    try:
        residue_features = sequence_embedding_provider.residue_features(
            entity_uid=str(entity_uid),
            sequence_tokens=sequence_tokens,
            hidden_dim=width,
            device=device,
        )
    except Exception:
        if accumulator is not None:
            accumulator.update_scalar_metric("x0_sequence_embedding_active", 0.0)
            accumulator.update_scalar_metric("x0_sequence_embedding_error", 1.0)
        if bool(fail_on_missing):
            raise
        return zeros
    if not isinstance(residue_features, torch.Tensor):
        if accumulator is not None:
            accumulator.update_scalar_metric("x0_sequence_embedding_active", 0.0)
            accumulator.update_scalar_metric("x0_sequence_embedding_missing", 1.0)
        return zeros
    features = residue_features.to(device=device, dtype=dtype).detach()
    if features.ndim != 2:
        if accumulator is not None:
            accumulator.update_scalar_metric("x0_sequence_embedding_active", 0.0)
            accumulator.update_scalar_metric("x0_sequence_embedding_bad_shape", 1.0)
        return zeros
    features = features[:residue_count, :width]
    residue_pad = residue_count - int(features.shape[0])
    feature_pad = width - int(features.shape[1])
    if residue_pad > 0 or feature_pad > 0:
        features = F.pad(
            features,
            (0, max(feature_pad, 0), 0, max(residue_pad, 0)),
        )
    features = torch.nan_to_num(features, nan=0.0, posinf=8.0, neginf=-8.0).clamp(
        min=-8.0,
        max=8.0,
    )
    if accumulator is not None:
        accumulator.update_scalar_metric("x0_sequence_embedding_active", 1.0)
        accumulator.update_scalar_metric("x0_sequence_embedding_feature_dim", float(width))
        accumulator.update_scalar_metric(
            "x0_sequence_embedding_abs_mean",
            float(torch.mean(torch.abs(features)).detach().cpu()),
        )
    return features.unsqueeze(0).expand(support_count, -1, -1)


def _repeat_or_trim_x0_tensor(
    tensor: torch.Tensor,
    size: int,
    *,
    dim: int,
) -> torch.Tensor:
    size = max(int(size), 1)
    dim = int(dim)
    current = int(tensor.shape[dim])
    if current == size:
        return tensor
    if current > size:
        return tensor.narrow(dim, 0, size)
    repeats = [1] * tensor.ndim
    repeats[dim] = int(math.ceil(size / max(current, 1)))
    expanded = tensor.repeat(*repeats)
    return expanded.narrow(dim, 0, size)


def _resize_x0_last_dim(tensor: torch.Tensor, size: int) -> torch.Tensor:
    size = max(int(size), 1)
    current = int(tensor.shape[-1])
    if current == size:
        return tensor
    if current > size:
        return tensor[..., :size]
    padding = tensor.new_zeros(*tensor.shape[:-1], size - current)
    return torch.cat([tensor, padding], dim=-1)


def _x0_residue_latent_with_pair_bridge(
    latent: Any,
    config: StudentTrainingConfig,
    accumulator: _SplitAccumulator,
) -> torch.Tensor:
    """Inject official x2d pair summaries into the x0 decoder feature path."""

    residue_latent = latent.residue_latent
    pair_latent = getattr(latent, "pair_residue_latent", None)
    pair_weight = max(float(getattr(config, "bioemu_x2d_pair_latent_weight", 0.0)), 0.0)
    if pair_weight <= 0.0 or not torch.is_tensor(pair_latent):
        accumulator.update_scalar_metric("x0_pair_bridge_active", 0.0)
        return residue_latent
    pair_latent = pair_latent.to(device=residue_latent.device, dtype=residue_latent.dtype)
    if int(pair_latent.shape[0]) != int(residue_latent.shape[0]):
        pair_latent = _repeat_or_trim_x0_tensor(
            pair_latent,
            int(residue_latent.shape[0]),
            dim=0,
        )
    if int(pair_latent.shape[1]) != int(residue_latent.shape[1]):
        pair_latent = _repeat_or_trim_x0_tensor(
            pair_latent,
            int(residue_latent.shape[1]),
            dim=1,
        )
    if int(pair_latent.shape[-1]) != int(residue_latent.shape[-1]):
        pair_latent = _resize_x0_last_dim(pair_latent, int(residue_latent.shape[-1]))
    bridged = residue_latent + residue_latent.new_tensor(pair_weight) * pair_latent
    accumulator.update_scalar_metric("x0_pair_bridge_active", 1.0)
    accumulator.update_scalar_metric("x0_pair_bridge_weight", pair_weight)
    accumulator.update_scalar_metric(
        "x0_pair_bridge_pair_abs_mean",
        float(pair_latent.detach().abs().mean().cpu()),
    )
    accumulator.update_scalar_metric(
        "x0_pair_bridge_delta_abs_mean",
        float((bridged - residue_latent).detach().abs().mean().cpu()),
    )
    accumulator.update_scalar_metric(
        "x0_pair_bridge_pair_requires_grad",
        1.0 if pair_latent.requires_grad else 0.0,
    )
    return bridged


def _gradient_summary(
    parameters: Sequence[nn.Parameter],
    *,
    prefix: str,
) -> dict[str, float]:
    """Summarize finite/nonzero gradient coverage without materializing big tensors."""

    parameter_count = 0
    grad_parameter_count = 0
    nonzero_grad_parameter_count = 0
    grad_value_count = 0
    nonfinite_grad_value_count = 0
    grad_norm_sq = 0.0
    grad_abs_max = 0.0
    for parameter in parameters:
        if not parameter.requires_grad:
            continue
        parameter_count += 1
        grad = parameter.grad
        if grad is None or not torch.is_tensor(grad):
            continue
        grad_detached = grad.detach()
        if not grad_detached.is_floating_point():
            continue
        grad_parameter_count += 1
        grad_value_count += int(grad_detached.numel())
        finite_mask = torch.isfinite(grad_detached)
        finite_count = int(torch.count_nonzero(finite_mask).detach().cpu())
        nonfinite_grad_value_count += int(grad_detached.numel() - finite_count)
        if finite_count <= 0:
            continue
        finite_values = grad_detached[finite_mask]
        abs_values = finite_values.abs()
        grad_abs_max = max(
            grad_abs_max,
            float(abs_values.max().detach().cpu()) if abs_values.numel() else 0.0,
        )
        norm_sq = float(torch.sum(finite_values.square()).detach().cpu())
        if norm_sq > 0.0:
            nonzero_grad_parameter_count += 1
            grad_norm_sq += norm_sq
    return {
        f"{prefix}_parameter_tensors": float(parameter_count),
        f"{prefix}_grad_parameter_tensors": float(grad_parameter_count),
        f"{prefix}_nonzero_grad_parameter_tensors": float(nonzero_grad_parameter_count),
        f"{prefix}_grad_values": float(grad_value_count),
        f"{prefix}_nonfinite_grad_values": float(nonfinite_grad_value_count),
        f"{prefix}_grad_norm": float(math.sqrt(max(grad_norm_sq, 0.0))),
        f"{prefix}_grad_abs_max": float(grad_abs_max),
    }


def _zero_nonfinite_optimizer_state(optimizer: torch.optim.Optimizer) -> int:
    """Replace non-finite optimizer-state values with zeros and report a count."""

    total = 0
    for state in optimizer.state.values():
        for value in state.values():
            if not torch.is_tensor(value) or not value.is_floating_point():
                continue
            finite = torch.isfinite(value)
            if bool(finite.all()):
                continue
            total += int(value.numel() - torch.count_nonzero(finite).detach().cpu())
            value.masked_fill_(~finite, 0.0)
    return int(total)


def _project_gradients_against_guard(
    parameters: list[nn.Parameter],
    guard_grads: Sequence[torch.Tensor | None],
    *,
    strength: float = 1.0,
    min_guard_norm: float = 1.0e-12,
) -> dict[str, float]:
    """Remove total-gradient components that would increase a guard loss."""

    dot = 0.0
    guard_norm_sq = 0.0
    grad_norm_sq = 0.0
    used_params = 0
    for parameter, guard_grad in zip(parameters, guard_grads):
        grad = parameter.grad
        if grad is None or guard_grad is None:
            continue
        if not torch.isfinite(grad).all() or not torch.isfinite(guard_grad).all():
            continue
        dot += float(torch.sum(grad.detach() * guard_grad.detach()).cpu())
        guard_norm_sq += float(torch.sum(guard_grad.detach().square()).cpu())
        grad_norm_sq += float(torch.sum(grad.detach().square()).cpu())
        used_params += 1
    metrics = {
        "nonregression_gradient_projection_params": float(used_params),
        "nonregression_gradient_projection_dot": float(dot),
        "nonregression_gradient_projection_guard_norm": float(
            math.sqrt(max(guard_norm_sq, 0.0))
        ),
        "nonregression_gradient_projection_grad_norm": float(
            math.sqrt(max(grad_norm_sq, 0.0))
        ),
        "nonregression_gradient_projection_applied": 0.0,
        "nonregression_gradient_projection_scale": 0.0,
    }
    if used_params <= 0 or guard_norm_sq <= float(min_guard_norm):
        return metrics
    grad_norm = math.sqrt(max(grad_norm_sq, 0.0))
    guard_norm = math.sqrt(max(guard_norm_sq, 0.0))
    if grad_norm > 0.0 and guard_norm > 0.0:
        metrics["nonregression_gradient_projection_cosine"] = float(
            dot / max(grad_norm * guard_norm, 1.0e-30)
        )
    if dot >= 0.0:
        return metrics
    projection_strength = min(max(float(strength), 0.0), 1.0)
    scale = projection_strength * dot / max(guard_norm_sq, float(min_guard_norm))
    for parameter, guard_grad in zip(parameters, guard_grads):
        grad = parameter.grad
        if grad is None or guard_grad is None:
            continue
        if not torch.isfinite(grad).all() or not torch.isfinite(guard_grad).all():
            continue
        grad.sub_(guard_grad.detach(), alpha=scale)
    metrics["nonregression_gradient_projection_applied"] = 1.0
    metrics["nonregression_gradient_projection_scale"] = float(scale)
    return metrics


def _is_cuda_oom_error(exc: BaseException) -> bool:
    if isinstance(exc, torch.cuda.OutOfMemoryError):
        return True
    return "out of memory" in str(exc).lower()


def _provider_sample_with_oom_retry(
    *,
    provider: Any,
    entity_uid: str,
    sequence_tokens: torch.Tensor,
    sample_count: int,
    seed: int,
    device: torch.device,
    config: StudentTrainingConfig,
    conditioning_features: torch.Tensor | None = None,
    accumulator: Any | None = None,
) -> Any:
    """Sample BioEmu support, retrying smaller K for OOM-prone examples."""

    def _sample(count: int) -> Any:
        kwargs: dict[str, Any] = {
            "entity_uid": entity_uid,
            "sequence_tokens": sequence_tokens,
            "sample_count": int(count),
            "seed": int(seed),
            "device": device,
        }
        if conditioning_features is not None:
            kwargs["conditioning_features"] = conditioning_features
        return provider.sample(**kwargs)

    requested_count = max(int(sample_count), 1)
    try:
        return _sample(requested_count)
    except Exception as exc:
        if not (
            bool(getattr(config, "bioemu_x0_provider_sample_oom_retry_enabled", False))
            and _is_cuda_oom_error(exc)
        ):
            raise
        original_exc = exc

    if device.type == "cuda" and torch.cuda.is_available():
        torch.cuda.empty_cache()
    configured_retry = int(
        getattr(config, "bioemu_x0_provider_sample_oom_retry_sample_count", 0)
    )
    retry_counts: list[int] = []
    for candidate in (
        configured_retry,
        int(math.floor(0.75 * requested_count)),
        int(math.floor(0.50 * requested_count)),
        int(math.floor(0.25 * requested_count)),
    ):
        candidate = max(int(candidate), 1)
        if candidate < requested_count and candidate not in retry_counts:
            retry_counts.append(candidate)
    last_exc: BaseException | None = None
    for attempt_index, retry_count in enumerate(retry_counts, start=1):
        if accumulator is not None and hasattr(accumulator, "update_scalar_metric"):
            accumulator.update_scalar_metric("provider_sample_oom_retry", 1.0)
            accumulator.update_scalar_metric(
                "provider_sample_oom_retry_requested_sample_count",
                float(requested_count),
            )
            accumulator.update_scalar_metric(
                "provider_sample_oom_retry_attempt_sample_count",
                float(retry_count),
            )
            accumulator.update_scalar_metric(
                "provider_sample_oom_retry_attempt_index",
                float(attempt_index),
            )
        try:
            latent = _sample(retry_count)
            if accumulator is not None and hasattr(accumulator, "update_scalar_metric"):
                accumulator.update_scalar_metric("provider_sample_oom_retry_success", 1.0)
                accumulator.update_scalar_metric(
                    "provider_sample_oom_retry_success_sample_count",
                    float(retry_count),
                )
            return latent
        except Exception as retry_exc:
            if not _is_cuda_oom_error(retry_exc):
                raise
            last_exc = retry_exc
            if device.type == "cuda" and torch.cuda.is_available():
                torch.cuda.empty_cache()
    if last_exc is not None:
        raise last_exc
    raise original_exc


def _combine_gradient_projection_guard_loss(
    current: torch.Tensor | None,
    candidate: torch.Tensor,
) -> torch.Tensor:
    if current is None:
        return candidate
    return current + candidate


def x0_checkpoint_metric_value(
    val_summary: dict[str, Any],
    train_summary: dict[str, Any],
    config: StudentTrainingConfig,
) -> tuple[float, str]:
    """Return a minimization metric for x0 checkpoint selection."""

    metric_name = str(getattr(config, "bioemu_x0_checkpoint_metric", "loss") or "loss")
    metric_key = metric_name.strip().lower()
    summary = val_summary if val_summary.get("loss_examples", 0) > 0 else train_summary
    health_summary = dict(summary)
    fallback = float(summary.get("loss", train_summary.get("loss", 0.0)))
    require_model_dependent_source = bool(
        getattr(
            config,
            "bioemu_x0_checkpoint_metric_require_model_dependent_source",
            False,
        )
    )

    def _checkpoint_source_contract_metric(
        label: str,
        *,
        model_dependent: bool,
    ) -> tuple[float, str] | None:
        if require_model_dependent_source and not bool(model_dependent):
            return float("inf"), f"{label}:model_independent_source"
        return None

    def _family_ccc_values(metric_payload: Any) -> tuple[list[float], dict[str, float]]:
        ccc_values_local: list[float] = []
        ccc_by_family_local: dict[str, float] = {}
        if not isinstance(metric_payload, dict):
            return ccc_values_local, ccc_by_family_local
        for family_name in CHEMICAL_SHIFT_FAMILIES:
            payload = metric_payload.get(family_name, {})
            if not isinstance(payload, dict):
                continue
            value = payload.get("ccc")
            if value is None:
                continue
            value_float = float(value)
            if math.isfinite(value_float):
                ccc_values_local.append(value_float)
                ccc_by_family_local[family_name] = value_float
        return ccc_values_local, ccc_by_family_local

    def _weighted_family_metric(
        ccc_by_family_local: dict[str, float],
    ) -> float | None:
        raw_weights = getattr(config, "bioemu_x0_checkpoint_metric_family_weights", {})
        weights = raw_weights if isinstance(raw_weights, dict) else {}
        weighted_sum = 0.0
        total_weight = 0.0
        for family_name, ccc_value in ccc_by_family_local.items():
            weight = float(weights.get(family_name, 1.0))
            if weight <= 0.0 or not math.isfinite(weight):
                continue
            weighted_sum += weight * ccc_value
            total_weight += weight
        if total_weight <= 0.0:
            return None
        return -float(weighted_sum / total_weight)

    def _target_gap_metric(gaps: list[float]) -> float:
        if not gaps:
            return float("inf")
        mean_gap = float(sum(gaps) / len(gaps))
        metric = mean_gap
        max_blend = max(
            float(
                getattr(
                    config,
                    "bioemu_x0_checkpoint_metric_target_gap_max_blend",
                    0.0,
                )
                or 0.0
            ),
            0.0,
        )
        if max_blend > 0.0:
            metric += max_blend * float(max(gaps))
        low_tail_blend = max(
            float(
                getattr(
                    config,
                    "bioemu_x0_checkpoint_metric_target_gap_low_tail_blend",
                    0.0,
                )
                or 0.0
            ),
            0.0,
        )
        if low_tail_blend > 0.0:
            low_tail_fraction = min(
                max(
                    float(
                        getattr(
                            config,
                            "bioemu_x0_checkpoint_metric_target_gap_low_tail_fraction",
                            0.0,
                        )
                        or 0.0
                    ),
                    1.0 / max(len(gaps), 1),
                ),
                1.0,
            )
            tail_count = max(1, min(len(gaps), math.ceil(len(gaps) * low_tail_fraction)))
            tail_gaps = sorted(gaps, reverse=True)[:tail_count]
            metric += low_tail_blend * float(sum(tail_gaps) / len(tail_gaps))
        return metric

    def _checkpoint_health_metric(
        metric: float,
        label: str,
    ) -> tuple[float, str]:
        raw_gates = getattr(config, "bioemu_x0_checkpoint_metric_health_gates", {})
        gates = raw_gates if isinstance(raw_gates, dict) else {}
        if not gates:
            return float(metric), label

        def _threshold(*keys: str) -> float | None:
            for key in keys:
                value = _x0_float_or_none(gates.get(key))
                if value is not None and math.isfinite(value):
                    return float(value)
            return None

        def _min_gate(
            gate_label: str,
            threshold: float | None,
            aliases: Sequence[str],
        ) -> None:
            if threshold is None or threshold <= 0.0:
                return
            value = _summary_first_finite_float(health_summary, aliases)
            if value is None:
                missing.append(gate_label)
                gaps.append(1.0)
                return
            denominator = max(abs(float(threshold)), 1.0)
            gaps.append(max(0.0, (float(threshold) - float(value)) / denominator))

        def _max_gate(
            gate_label: str,
            threshold: float | None,
            aliases: Sequence[str],
            *,
            allow_zero: bool = False,
        ) -> None:
            if threshold is None or (threshold <= 0.0 and not allow_zero):
                return
            value = _summary_first_finite_float(health_summary, aliases)
            if value is None:
                missing.append(gate_label)
                gaps.append(1.0)
                return
            denominator = max(abs(float(threshold)), 1.0)
            gaps.append(max(0.0, (float(value) - float(threshold)) / denominator))

        gaps: list[float] = []
        missing: list[str] = []
        _min_gate(
            "ess_min",
            _threshold("ess_min", "posterior_ess_min", "min_ess"),
            (
                "posterior_ess",
                "support_shared_q_oracle_ess",
                "sidecar_support_shared_q_oracle_ess",
                "shared_q_oracle_ess",
                "shared_q_oracle_bme_safety_ess",
            ),
        )
        _min_gate(
            "entropy_min",
            _threshold("entropy_min", "posterior_entropy_min", "min_entropy"),
            ("posterior_entropy", "q_entropy", "posterior_mode_entropy"),
        )
        _min_gate(
            "valid_mass_min",
            _threshold("valid_mass_min", "posterior_valid_mass_min"),
            ("posterior_valid_mass", "valid_posterior_mass", "valid_mass", "q_valid_mass"),
        )
        _max_gate(
            "top_mass_max",
            _threshold("top_mass_max", "posterior_top_mass_max", "max_top_mass"),
            (
                "posterior_top_mass",
                "support_shared_q_oracle_top_mass",
                "sidecar_support_shared_q_oracle_top_mass",
                "shared_q_oracle_top_mass",
                "shared_q_oracle_bme_safety_top_mass",
            ),
        )
        _max_gate(
            "invalid_mass_max",
            _threshold("invalid_mass_max", "posterior_invalid_mass_max"),
            (
                "posterior_invalid_mass",
                "invalid_posterior_mass",
                "invalid_mass",
                "q_invalid_mass",
            ),
            allow_zero=True,
        )
        _min_gate(
            "corrected_prior_top_mass_min",
            _threshold(
                "corrected_prior_top_mass_min",
                "prior_corrected_top_mass_min",
                "prior_logit_adapter_corrected_prior_top_mass_min",
            ),
            (
                "prior_logit_adapter_corrected_prior_top_mass",
                "same_conformer_cosatisfaction_generated_prior_student_top_mass",
                "cs_reweighting_teacher_prior_generated_top_mass",
            ),
        )
        _min_gate(
            "corrected_prior_topk_mass_min",
            _threshold(
                "corrected_prior_topk_mass_min",
                "prior_corrected_topk_mass_min",
                "same_conformer_generated_prior_student_topk_mass_min",
            ),
            (
                "same_conformer_cosatisfaction_generated_prior_student_topk_mass",
                "same_conformer_cosatisfaction_generated_prior_student_top_mass",
                "prior_logit_adapter_corrected_prior_top_mass",
            ),
        )
        _max_gate(
            "corrected_prior_top_mass_max",
            _threshold(
                "corrected_prior_top_mass_max",
                "prior_corrected_top_mass_max",
                "prior_logit_adapter_corrected_prior_top_mass_max",
            ),
            (
                "prior_logit_adapter_corrected_prior_top_mass",
                "same_conformer_cosatisfaction_generated_prior_student_top_mass",
                "cs_reweighting_teacher_prior_generated_top_mass",
            ),
        )
        _min_gate(
            "corrected_prior_ess_min",
            _threshold(
                "corrected_prior_ess_min",
                "prior_corrected_ess_min",
                "prior_logit_adapter_corrected_prior_ess_min",
            ),
            (
                "prior_logit_adapter_corrected_prior_ess",
                "same_conformer_cosatisfaction_generated_prior_student_ess",
                "cs_reweighting_teacher_prior_generated_ess",
            ),
        )
        _max_gate(
            "corrected_prior_ess_max",
            _threshold(
                "corrected_prior_ess_max",
                "prior_corrected_ess_max",
                "prior_logit_adapter_corrected_prior_ess_max",
            ),
            (
                "prior_logit_adapter_corrected_prior_ess",
                "same_conformer_cosatisfaction_generated_prior_student_ess",
                "cs_reweighting_teacher_prior_generated_ess",
            ),
        )
        if not gaps:
            return float(metric), label
        max_gap = max(gaps)
        hard_gate = bool(
            getattr(config, "bioemu_x0_checkpoint_metric_health_hard_gate", False)
        )
        if hard_gate and (missing or max_gap > 0.0):
            return float("inf"), f"{label}:health_gate"
        penalty_weight = float(
            getattr(config, "bioemu_x0_checkpoint_metric_health_penalty_weight", 0.0)
            or 0.0
        )
        if penalty_weight > 0.0 and math.isfinite(float(metric)):
            penalty = penalty_weight * float(sum(gaps) / len(gaps))
            return float(metric) + penalty, f"{label}:health_penalty"
        return float(metric), label

    def _support_within_metric_key_candidates(family_name: str) -> list[str]:
        family_key = str(family_name).strip()
        lower_key = family_key.lower().replace(" ", "_")
        if family_key in {"C'", "Cprime", "cprime", "C_PRIME", "c_prime"}:
            prefixes = ["cprime", "c_prime"]
        else:
            prefixes = [lower_key]
        return [f"{prefix}_support_within_fraction" for prefix in prefixes]

    def _checkpoint_support_floor_metric(
        metric: float,
        label: str,
    ) -> tuple[float, str]:
        raw_floors = getattr(
            config,
            "bioemu_x0_checkpoint_metric_support_within_floors",
            {},
        )
        floors = raw_floors if isinstance(raw_floors, dict) else {}
        if not floors:
            return _checkpoint_health_metric(float(metric), label)
        gaps: list[float] = []
        missing: list[str] = []
        for family_name, floor_value in floors.items():
            family_key = str(family_name)
            try:
                floor_float = float(floor_value)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(floor_float):
                continue
            value: float | None = None
            for metric_key_candidate in _support_within_metric_key_candidates(
                family_key
            ):
                candidate = _x0_float_or_none(summary.get(metric_key_candidate))
                if candidate is not None:
                    value = float(candidate)
                    break
            if value is None:
                missing.append(family_key)
                gaps.append(max(1.0, floor_float))
                continue
            gaps.append(max(0.0, floor_float - value))
        if not gaps:
            return float(metric), label
        max_gap = max(gaps)
        hard_gate = bool(
            getattr(
                config,
                "bioemu_x0_checkpoint_metric_support_within_hard_gate",
                False,
            )
        )
        if hard_gate and (missing or max_gap > 0.0):
            return float("inf"), f"{label}:support_floor"
        penalty_weight = float(
            getattr(
                config,
                "bioemu_x0_checkpoint_metric_support_within_penalty_weight",
                0.0,
            )
            or 0.0
        )
        if penalty_weight > 0.0 and math.isfinite(float(metric)):
            penalty = penalty_weight * float(sum(gaps) / len(gaps))
            return _checkpoint_health_metric(
                float(metric) + penalty,
                f"{label}:support_penalty",
            )
        return _checkpoint_health_metric(float(metric), label)

    def _checkpoint_nonregression_metric(
        metric: float,
        label: str,
        ccc_by_family_local: dict[str, float],
    ) -> tuple[float, str]:
        raw_floors = getattr(
            config,
            "bioemu_x0_checkpoint_metric_nonregression_ccc_floors",
            {},
        )
        floors = raw_floors if isinstance(raw_floors, dict) else {}
        if not floors:
            return _checkpoint_support_floor_metric(float(metric), label)
        gaps: list[float] = []
        missing: list[str] = []
        for family_name, floor_value in floors.items():
            family_key = str(family_name)
            try:
                floor_float = float(floor_value)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(floor_float):
                continue
            value = ccc_by_family_local.get(family_key)
            if value is None or not math.isfinite(float(value)):
                missing.append(family_key)
                gaps.append(max(1.0, floor_float))
                continue
            gaps.append(max(0.0, floor_float - float(value)))
        if not gaps:
            return float(metric), label
        max_gap = max(gaps)
        hard_gate = bool(
            getattr(config, "bioemu_x0_checkpoint_metric_nonregression_hard_gate", False)
        )
        if hard_gate and (missing or max_gap > 0.0):
            return float("inf"), f"{label}:nonregression_floor"
        metric_value = float(metric)
        metric_label = label
        penalty_weight = float(
            getattr(
                config,
                "bioemu_x0_checkpoint_metric_nonregression_penalty_weight",
                0.0,
            )
            or 0.0
        )
        if penalty_weight > 0.0 and math.isfinite(metric_value):
            penalty = penalty_weight * float(sum(gaps) / len(gaps))
            metric_value = metric_value + penalty
            metric_label = f"{label}:nonregression_penalty"
        return _checkpoint_support_floor_metric(metric_value, metric_label)

    def _load_multiseed_checkpoint_summary() -> dict[str, Any] | None:
        if (
            summary.get("summary_kind")
            == "bioemu_x0_multiseed_checkpoint_summary_v1"
        ):
            return dict(summary)
        for key in (
            "support_face_multiseed_checkpoint_summary",
            "multiseed_checkpoint_summary",
        ):
            payload = summary.get(key)
            if isinstance(payload, dict):
                return dict(payload)
        path_text = str(
            getattr(config, "bioemu_x0_multiseed_checkpoint_summary_path", "") or ""
        ).strip()
        if path_text:
            path = Path(path_text)
            if path.exists():
                try:
                    payload = json.loads(path.read_text(encoding="utf-8"))
                except json.JSONDecodeError:
                    payload = None
                if isinstance(payload, dict):
                    return payload
        return None

    if "multiseed" in metric_key:
        multiseed_summary = _load_multiseed_checkpoint_summary()
        if not isinstance(multiseed_summary, dict):
            return float("inf"), f"{metric_name}:missing"
        aggregate = dict(multiseed_summary.get("aggregate") or {})
        if not aggregate and isinstance(multiseed_summary.get("entries"), list):
            aggregate = _x0_aggregate_multiseed_entries(
                list(multiseed_summary.get("entries") or [])
            )
        for health_key in (
            "posterior_ess",
            "posterior_entropy",
            "posterior_top_mass",
            "posterior_valid_mass",
            "posterior_invalid_mass",
            "support_shared_q_oracle_ess",
            "support_shared_q_oracle_top_mass",
        ):
            if aggregate.get(health_key) is not None:
                health_summary[health_key] = aggregate.get(health_key)
        multiseed_ccc_by_family: dict[str, float] = {}
        for family_name in CHEMICAL_SHIFT_FAMILIES:
            family_key = "Cprime" if family_name == "C'" else family_name
            value = _x0_float_or_none(aggregate.get(f"min_generated_{family_key}"))
            if value is None and family_name == "C'":
                value = _x0_float_or_none(aggregate.get("min_generated_C'"))
            if value is not None:
                multiseed_ccc_by_family[family_name] = value
        if not multiseed_ccc_by_family:
            return float("inf"), f"{metric_name}:missing"
        multiseed_ccc_values = list(multiseed_ccc_by_family.values())

        def _weighted_multiseed_family_ccc() -> float | None:
            raw_weights = getattr(
                config,
                "bioemu_x0_checkpoint_metric_family_weights",
                {},
            )
            weights = raw_weights if isinstance(raw_weights, dict) else {}
            weighted_sum = 0.0
            total_weight = 0.0
            for family_name, ccc_value in multiseed_ccc_by_family.items():
                weight = float(
                    weights.get(
                        family_name,
                        weights.get("Cprime", 1.0) if family_name == "C'" else 1.0,
                    )
                )
                if weight <= 0.0 or not math.isfinite(weight):
                    continue
                weighted_sum += weight * ccc_value
                total_weight += weight
            if total_weight <= 0.0:
                return None
            return float(weighted_sum / total_weight)

        if (
            metric_key.endswith("_target_face_hold_weighted_ccc")
            or metric_key.endswith("_target_face_held_weighted_ccc")
        ):
            weighted_value = _weighted_multiseed_family_ccc()
            if weighted_value is None:
                return float("inf"), f"{metric_name}:missing"
            held_count = _x0_float_or_none(aggregate.get("target_face_held_count"))
            if held_count is None:
                held_count = 0.0
            return _checkpoint_nonregression_metric(
                -float(held_count) - float(weighted_value),
                metric_name,
                multiseed_ccc_by_family,
            )
        if metric_key.endswith("_family_macro_ccc") or metric_key.endswith(
            "_macro_ccc"
        ):
            macro_value = _x0_float_or_none(aggregate.get("mean_generated_macro"))
            if macro_value is None:
                macro_value = sum(multiseed_ccc_values) / len(multiseed_ccc_values)
            return _checkpoint_nonregression_metric(
                -float(macro_value),
                metric_name,
                multiseed_ccc_by_family,
            )
        if metric_key.endswith("_family_min_ccc") or metric_key.endswith("_min_ccc"):
            return _checkpoint_nonregression_metric(
                -float(min(multiseed_ccc_values)),
                metric_name,
                multiseed_ccc_by_family,
            )
        if metric_key.endswith("_family_target_gap") or metric_key.endswith(
            "_target_gap"
        ):
            target = float(getattr(config, "bioemu_x0_target_family_ccc", 0.95))
            gaps = [max(0.0, target - value) for value in multiseed_ccc_values]
            return _checkpoint_nonregression_metric(
                _target_gap_metric(gaps),
                metric_name,
                multiseed_ccc_by_family,
            )
        if metric_key.endswith("_family_weighted_ccc") or metric_key.endswith(
            "_weighted_ccc"
        ):
            weighted_value = _weighted_multiseed_family_ccc()
            if weighted_value is None:
                return float("inf"), f"{metric_name}:missing"
            return _checkpoint_nonregression_metric(
                -float(weighted_value),
                metric_name,
                multiseed_ccc_by_family,
            )
        return float("inf"), f"{metric_name}:missing"

    family_metrics = summary.get("posterior_ensemble_vs_observed_by_family")
    if not isinstance(family_metrics, dict):
        family_metrics = summary.get("prior_ensemble_vs_observed_by_family")
    ccc_values, ccc_by_family = _family_ccc_values(family_metrics)
    sidecar_ccc_values, sidecar_ccc_by_family = _family_ccc_values(
        summary.get("sidecar_posterior_vs_observed_by_family")
    )
    oracle_metric_sources = {
        "support_rowwise_oracle": "support_rowwise_oracle_by_family",
        "rowwise_oracle": "support_rowwise_oracle_by_family",
        "support_clipped_oracle": "support_clipped_oracle_by_family",
        "clipped_oracle": "support_clipped_oracle_by_family",
        "support_shared_q_oracle": "support_shared_q_oracle_by_family",
        "shared_q_oracle": "support_shared_q_oracle_by_family",
        "sidecar_support_rowwise_oracle": "sidecar_support_rowwise_oracle_by_family",
        "sidecar_rowwise_oracle": "sidecar_support_rowwise_oracle_by_family",
        "sidecar_support_clipped_oracle": "sidecar_support_clipped_oracle_by_family",
        "sidecar_clipped_oracle": "sidecar_support_clipped_oracle_by_family",
        "sidecar_support_shared_q_oracle": "sidecar_support_shared_q_oracle_by_family",
        "sidecar_shared_q_oracle": "sidecar_support_shared_q_oracle_by_family",
    }
    sidecar_metric_keys = {
        "sidecar_posterior_family_macro_ccc",
        "sidecar_family_macro_ccc",
        "sidecar_posterior_family_min_ccc",
        "sidecar_family_min_ccc",
        "sidecar_posterior_family_weighted_ccc",
        "sidecar_family_weighted_ccc",
        "sidecar_posterior_family_target_gap",
        "sidecar_family_target_gap",
    }
    scalar_max_metric_sources = {
        "sidecar_shared_q_energy_target_corr": "sidecar_shared_q_energy_target_corr",
        "sidecar_energy_target_corr": "sidecar_shared_q_energy_target_corr",
        "shared_q_energy_target_corr": "sidecar_shared_q_energy_target_corr",
        "sidecar_shared_q_energy_target_rank_gap": (
            "sidecar_shared_q_energy_target_rank_gap"
        ),
        "sidecar_energy_target_rank_gap": "sidecar_shared_q_energy_target_rank_gap",
        "shared_q_energy_target_rank_gap": "sidecar_shared_q_energy_target_rank_gap",
        "sidecar_pair_rank_energy_target_rank_gap": (
            "sidecar_pair_rank_energy_target_rank_gap"
        ),
        "pair_rank_energy_target_rank_gap": (
            "sidecar_pair_rank_energy_target_rank_gap"
        ),
    }
    scalar_metric_source = scalar_max_metric_sources.get(metric_key)
    if scalar_metric_source is not None:
        scalar_value = _x0_float_or_none(summary.get(scalar_metric_source))
        if scalar_value is None:
            return float("inf"), f"{metric_name}:missing"
        _, support_ccc_by_family = _family_ccc_values(
            summary.get("support_shared_q_oracle_by_family")
        )
        return _checkpoint_nonregression_metric(
            -float(scalar_value),
            metric_name,
            support_ccc_by_family,
        )
    for oracle_prefix, oracle_payload_key in oracle_metric_sources.items():
        if not metric_key.startswith(f"{oracle_prefix}_family_"):
            continue
        source_contract = _checkpoint_source_contract_metric(
            metric_name,
            model_dependent=not oracle_prefix.startswith("sidecar_"),
        )
        if source_contract is not None:
            return source_contract
        oracle_ccc_values, oracle_ccc_by_family = _family_ccc_values(
            summary.get(oracle_payload_key)
        )
        if not oracle_ccc_values:
            return float("inf"), f"{metric_name}:missing"
        if metric_key.endswith("_family_macro_ccc"):
            return _checkpoint_nonregression_metric(
                -float(sum(oracle_ccc_values) / len(oracle_ccc_values)),
                metric_name,
                oracle_ccc_by_family,
            )
        if metric_key.endswith("_family_min_ccc"):
            return _checkpoint_nonregression_metric(
                -float(min(oracle_ccc_values)),
                metric_name,
                oracle_ccc_by_family,
            )
        if metric_key.endswith("_family_target_gap"):
            target = float(getattr(config, "bioemu_x0_target_family_ccc", 0.95))
            gaps = [max(0.0, target - value) for value in oracle_ccc_values]
            return _checkpoint_nonregression_metric(
                _target_gap_metric(gaps),
                metric_name,
                oracle_ccc_by_family,
            )
        if metric_key.endswith("_family_weighted_ccc"):
            weighted_oracle = _weighted_family_metric(oracle_ccc_by_family)
            if weighted_oracle is not None:
                return _checkpoint_nonregression_metric(
                    weighted_oracle,
                    metric_name,
                    oracle_ccc_by_family,
                )
        return float("inf"), f"{metric_name}:missing"
    if sidecar_ccc_values and metric_key in {
        "sidecar_posterior_family_macro_ccc",
        "sidecar_family_macro_ccc",
    }:
        source_contract = _checkpoint_source_contract_metric(
            metric_name,
            model_dependent=False,
        )
        if source_contract is not None:
            return source_contract
        return _checkpoint_nonregression_metric(
            -float(sum(sidecar_ccc_values) / len(sidecar_ccc_values)),
            metric_name,
            sidecar_ccc_by_family,
        )
    if sidecar_ccc_values and metric_key in {
        "sidecar_posterior_family_min_ccc",
        "sidecar_family_min_ccc",
    }:
        source_contract = _checkpoint_source_contract_metric(
            metric_name,
            model_dependent=False,
        )
        if source_contract is not None:
            return source_contract
        return _checkpoint_nonregression_metric(
            -float(min(sidecar_ccc_values)),
            metric_name,
            sidecar_ccc_by_family,
        )
    if sidecar_ccc_values and metric_key in {
        "sidecar_posterior_family_weighted_ccc",
        "sidecar_family_weighted_ccc",
    }:
        source_contract = _checkpoint_source_contract_metric(
            metric_name,
            model_dependent=False,
        )
        if source_contract is not None:
            return source_contract
        weighted_sidecar = _weighted_family_metric(sidecar_ccc_by_family)
        if weighted_sidecar is not None:
            return _checkpoint_nonregression_metric(
                weighted_sidecar,
                metric_name,
                sidecar_ccc_by_family,
            )
    if sidecar_ccc_values and metric_key in {
        "sidecar_posterior_family_target_gap",
        "sidecar_family_target_gap",
    }:
        source_contract = _checkpoint_source_contract_metric(
            metric_name,
            model_dependent=False,
        )
        if source_contract is not None:
            return source_contract
        target = float(getattr(config, "bioemu_x0_target_family_ccc", 0.95))
        gaps = [max(0.0, target - value) for value in sidecar_ccc_values]
        return _checkpoint_nonregression_metric(
            _target_gap_metric(gaps),
            metric_name,
            sidecar_ccc_by_family,
        )
    if metric_key in sidecar_metric_keys:
        return float("inf"), f"{metric_name}:missing"
    if metric_key in {"loss", "val_loss"}:
        return fallback, metric_name
    if ccc_values and metric_key in {
        "posterior_family_macro_ccc",
        "family_macro_ccc",
        "macro_ccc",
    }:
        return _checkpoint_nonregression_metric(
            -float(sum(ccc_values) / len(ccc_values)),
            metric_name,
            ccc_by_family,
        )
    if ccc_values and metric_key in {
        "posterior_family_min_ccc",
        "family_min_ccc",
        "min_ccc",
    }:
        return _checkpoint_nonregression_metric(
            -float(min(ccc_values)),
            metric_name,
            ccc_by_family,
        )
    if ccc_values and metric_key in {
        "posterior_family_target_gap",
        "family_target_gap",
        "target_gap",
    }:
        target = float(getattr(config, "bioemu_x0_target_family_ccc", 0.95))
        gaps = [max(0.0, target - value) for value in ccc_values]
        return _checkpoint_nonregression_metric(
            _target_gap_metric(gaps),
            metric_name,
            ccc_by_family,
        )
    if ccc_values and metric_key in {
        "posterior_family_weighted_ccc",
        "family_weighted_ccc",
        "weighted_ccc",
    }:
        weighted = _weighted_family_metric(ccc_by_family)
        if weighted is not None:
            return _checkpoint_nonregression_metric(
                weighted,
                metric_name,
                ccc_by_family,
            )
    raw_value = summary.get(metric_name)
    if raw_value is not None:
        raw_float = float(raw_value)
        if math.isfinite(raw_float):
            return raw_float, metric_name
    return fallback, "loss"


def x0_checkpoint_report_fields(
    *,
    best_epoch: int,
    best_metric: float,
    best_metric_name: str,
    latest_metric_name: str,
    requested_metric_name: str,
) -> dict[str, Any]:
    """Build JSON-safe checkpoint-selection fields for x0 reports."""

    checkpoint_selected = bool(best_epoch >= 0 and math.isfinite(best_metric))
    resolved_metric_name = (
        str(best_metric_name)
        or str(latest_metric_name)
        or str(requested_metric_name)
    )
    return {
        "best_epoch": int(best_epoch),
        "best_metric": float(best_metric) if checkpoint_selected else None,
        "best_metric_name": resolved_metric_name,
        "best_checkpoint_selected": bool(checkpoint_selected),
        "best_checkpoint_metric_requested": str(requested_metric_name),
        "latest_checkpoint_metric_name": str(latest_metric_name),
        "latest_checkpoint_metric_missing": bool(
            str(latest_metric_name).endswith(":missing")
        ),
    }


def target_aligned_phi_from_residue_family(
    conformer_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
) -> torch.Tensor:
    """Gather residue/family rows from ``phi`` using candidate-free targets.

    ``conformer_phi`` may be conformer-level ``[K, L, F]`` or ensemble-level
    ``[L, F]``. Candidate-free aligned residue indices are one-based in normal
    integrated data, then converted to the zero-based residue axis used here.
    """

    if conformer_phi.ndim not in {2, 3}:
        raise ValueError("conformer_phi must have shape [L, F] or [K, L, F]")
    residue_count = int(conformer_phi.shape[-2])
    family_count = int(conformer_phi.shape[-1])
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")
    residue_indices = _aligned_residue_indices_from_target_features(
        target_features,
        residue_count=residue_count,
    )
    families = family_indices.long().clamp(min=0, max=max(family_count - 1, 0))
    if conformer_phi.ndim == 3:
        return conformer_phi[:, residue_indices, families]
    return conformer_phi[residue_indices, families]


def _aligned_residue_indices_from_target_features(
    target_features: torch.Tensor,
    *,
    residue_count: int,
) -> torch.Tensor:
    if target_features.shape[1] > FEATURE_ALIGNED_RESIDUE_INDEX:
        raw_indices = target_features[:, FEATURE_ALIGNED_RESIDUE_INDEX]
    else:
        raw_indices = target_features[:, 0]
    safe_raw = torch.nan_to_num(raw_indices, nan=1.0, posinf=1.0, neginf=1.0)
    rounded = torch.round(safe_raw).long()
    finite = torch.isfinite(raw_indices)
    finite_values = rounded[finite]
    if (
        finite_values.numel() > 0
        and int(torch.min(finite_values)) >= 1
        and int(torch.max(finite_values)) <= int(residue_count)
    ):
        residue_indices = rounded - 1
    else:
        residue_indices = rounded
    return residue_indices.clamp(min=0, max=max(int(residue_count) - 1, 0))


def target_mechanism_residue_context_features(
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    sequence_tokens: torch.Tensor,
    *,
    sample_count: int,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Aggregate leakage-safe target metadata/mechanism proxies to residues.

    This uses no observed chemical-shift values.  It only compresses row
    metadata and sequence/physics proxy columns already present in
    ``target_features`` into residue-level HN/C' mechanism charts.
    """

    residue_count = int(sequence_tokens.numel())
    output_shape = (
        int(sample_count),
        max(residue_count, 0),
        MECHANISM_RESIDUE_CONTEXT_DIM,
    )
    if residue_count <= 0:
        return torch.zeros(output_shape, dtype=dtype, device=device)
    context = torch.zeros(
        residue_count,
        MECHANISM_RESIDUE_CONTEXT_DIM,
        dtype=dtype,
        device=device,
    )
    if target_features.ndim != 2 or target_features.shape[0] == 0:
        return context.unsqueeze(0).expand(int(sample_count), -1, -1)

    features = target_features.to(device=device, dtype=dtype)
    families = family_indices.to(device=device).long()
    residue_indices = _aligned_residue_indices_from_target_features(
        features,
        residue_count=residue_count,
    )
    raw_indices = features[:, FEATURE_ALIGNED_RESIDUE_INDEX] if features.shape[1] > FEATURE_ALIGNED_RESIDUE_INDEX else features[:, 0]

    def column(index: int, *, default: float = 0.0, clamp: bool = True) -> torch.Tensor:
        if features.shape[1] <= index:
            values = torch.full(
                (features.shape[0],),
                float(default),
                dtype=dtype,
                device=device,
            )
        else:
            values = torch.nan_to_num(features[:, index], nan=float(default))
        return values.clamp(0.0, 1.0) if clamp else values

    family_to_index = {family: index for index, family in enumerate(CHEMICAL_SHIFT_FAMILIES)}
    hn_mask = families == family_to_index.get("HN", -1)
    n_mask = families == family_to_index.get("N", -1)
    cprime_mask = families == family_to_index.get("C'", -1)

    specs: tuple[tuple[int, torch.Tensor, torch.Tensor], ...] = (
        (0, torch.ones_like(families, dtype=torch.bool), torch.ones_like(raw_indices, dtype=dtype)),
        (1, hn_mask, torch.ones_like(raw_indices, dtype=dtype)),
        (2, hn_mask, column(FEATURE_EXCHANGE_RISK)),
        (3, hn_mask, column(FEATURE_RING_CURRENT_PROXY)),
        (4, hn_mask, column(FEATURE_HN_SEQUENCE_CONTEXT_RISK)),
        (5, hn_mask, column(FEATURE_SAMPLE_HN_EXCHANGE_PROXY)),
        (6, hn_mask, column(FEATURE_SAMPLE_CONDITION_RISK)),
        (7, hn_mask, column(FEATURE_DISORDER_PROXY)),
        (8, hn_mask, column(FEATURE_LOCAL_AROMATIC_DENSITY)),
        (9, hn_mask, column(FEATURE_LOCAL_CHARGED_DENSITY)),
        (10, hn_mask, column(FEATURE_ALIGNMENT_RISK)),
        (11, n_mask, torch.ones_like(raw_indices, dtype=dtype)),
        (12, n_mask, column(FEATURE_LOCAL_AROMATIC_DENSITY)),
        (13, n_mask, column(FEATURE_LOCAL_CHARGED_DENSITY)),
        (14, n_mask, column(FEATURE_SAMPLE_CONDITION_RISK)),
        (15, cprime_mask, torch.ones_like(raw_indices, dtype=dtype)),
        (16, cprime_mask, column(FEATURE_CPRIME_PLANE_PROXY)),
        (17, cprime_mask, column(FEATURE_CPRIME_SEQUENCE_CONTEXT_RISK)),
        (18, cprime_mask, column(FEATURE_DISORDER_PROXY)),
        (19, cprime_mask, column(FEATURE_PROLINE_NEIGHBOR)),
        (20, cprime_mask, column(FEATURE_LOCAL_TURN_PROPENSITY)),
        (21, cprime_mask, column(FEATURE_ALIGNMENT_RISK)),
        (22, torch.ones_like(families, dtype=torch.bool), column(FEATURE_SAMPLE_CONDITION_AVAILABLE)),
        (23, torch.ones_like(families, dtype=torch.bool), column(FEATURE_TERMINAL_DISTANCE)),
        (24, torch.ones_like(families, dtype=torch.bool), column(FEATURE_ALIGNMENT_CONFIDENCE)),
        (25, torch.ones_like(families, dtype=torch.bool), column(FEATURE_PROLINE_NEIGHBOR)),
        (26, torch.ones_like(families, dtype=torch.bool), column(FEATURE_RING_CURRENT_PROXY)),
        (27, torch.ones_like(families, dtype=torch.bool), column(FEATURE_LOCAL_CHARGED_DENSITY)),
        (28, torch.ones_like(families, dtype=torch.bool), torch.ones_like(raw_indices, dtype=dtype)),
    )

    count_accumulator = torch.zeros(residue_count, dtype=dtype, device=device)
    for target_row, residue_index in enumerate(residue_indices):
        residue = int(residue_index.detach().cpu())
        count_accumulator[residue] += 1.0
        for output_index, mask, values in specs:
            if bool(mask[target_row]):
                context[residue, output_index] = torch.maximum(
                    context[residue, output_index],
                    values[target_row],
                )
    context[:, 0] = (count_accumulator / float(max(len(CHEMICAL_SHIFT_FAMILIES), 1))).clamp(0.0, 1.0)
    context[:, 28] = (torch.log1p(count_accumulator) / math.log1p(len(CHEMICAL_SHIFT_FAMILIES))).clamp(0.0, 1.0)
    return context.unsqueeze(0).expand(int(sample_count), -1, -1)


def target_shift_grid_from_rows(
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    residue_count: int,
    family_count: int,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Return residue/family target grid and observed mask for selected rows."""

    device = target_values.device
    dtype = target_values.dtype
    target_grid = torch.zeros(residue_count, family_count, dtype=dtype, device=device)
    counts = torch.zeros_like(target_grid)
    if target_features.numel() == 0 or target_values.numel() == 0:
        return target_grid, counts > 0
    residue_indices = _aligned_residue_indices_from_target_features(
        target_features,
        residue_count=residue_count,
    )
    families = family_indices.to(device=device).long().clamp(
        min=0,
        max=max(int(family_count) - 1, 0),
    )
    selected = row_mask.to(device=device, dtype=torch.bool) & torch.isfinite(target_values)
    for row_index in torch.nonzero(selected, as_tuple=False).flatten().tolist():
        residue = int(residue_indices[row_index].detach().cpu())
        family = int(families[row_index].detach().cpu())
        target_grid[residue, family] += target_values[row_index]
        counts[residue, family] += 1.0
    observed_mask = counts > 0
    target_grid = torch.where(observed_mask, target_grid / counts.clamp_min(1.0), target_grid)
    return target_grid, observed_mask


def stage_b_row_split_masks(
    target_count: int,
    *,
    epoch: int,
    example_index: int,
    device: torch.device,
    target_features: torch.Tensor | None = None,
    family_indices: torch.Tensor | None = None,
    residue_count: int | None = None,
    family_count: int | None = None,
    supervised_fraction: float = 0.25,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Deterministically split rows into evidence conditioning and supervision.

    When row metadata is available, the split is performed by unique
    residue/family cells rather than raw rows.  Stage-B supervises an ensemble
    residue-family grid, so raw-row hashing can collapse to one sparse cell per
    example and silently drop HN/CA-style families from training.
    """

    if target_count <= 0:
        empty = torch.zeros(0, dtype=torch.bool, device=device)
        return empty, empty
    if (
        target_features is not None
        and family_indices is not None
        and residue_count is not None
        and int(residue_count) > 0
    ):
        row_count = int(target_count)
        features = target_features.to(device=device)
        families = family_indices.to(device=device).long()
        usable_count = min(row_count, int(features.shape[0]), int(families.numel()))
        supervised = torch.zeros(row_count, dtype=torch.bool, device=device)
        evidence = torch.zeros(row_count, dtype=torch.bool, device=device)
        if usable_count <= 0:
            return evidence, supervised
        inferred_family_count = int(family_count or len(CHEMICAL_SHIFT_FAMILIES))
        inferred_family_count = max(inferred_family_count, int(torch.amax(families[:usable_count]).detach().cpu()) + 1)
        residues = _aligned_residue_indices_from_target_features(
            features[:usable_count],
            residue_count=int(residue_count),
        )
        families = families[:usable_count].clamp(min=0, max=max(inferred_family_count - 1, 0))
        keys = residues.long() * inferred_family_count + families
        fraction = min(max(float(supervised_fraction), 0.05), 0.5)
        for family_index in torch.unique(families).detach().cpu().tolist():
            family_mask = families == int(family_index)
            family_keys = torch.unique(keys[family_mask])
            unique_count = int(family_keys.numel())
            if unique_count <= 0:
                continue
            if unique_count == 1:
                chosen = family_keys
            else:
                hash_scores = (
                    family_keys.long() * 1103515245
                    + int(epoch) * 9176
                    + int(example_index) * 131
                    + int(family_index) * 193
                ) % 1009
                order = torch.argsort(hash_scores)
                supervised_count = max(1, int(math.ceil(float(unique_count) * fraction)))
                supervised_count = min(supervised_count, unique_count - 1)
                chosen = family_keys[order[:supervised_count]]
            chosen_mask = torch.zeros_like(family_mask)
            for chosen_key in chosen:
                chosen_mask |= keys == chosen_key
            supervised[:usable_count] |= chosen_mask
        evidence[:usable_count] = ~supervised[:usable_count]
        if not bool(torch.any(supervised[:usable_count])):
            supervised[usable_count - 1] = True
            evidence[usable_count - 1] = False
        if not bool(torch.any(evidence[:usable_count])) and usable_count > 1:
            evidence[0] = True
            supervised[0] = False
        return evidence, supervised
    rows = torch.arange(int(target_count), device=device)
    bucket = (rows * 1103515245 + int(epoch) * 9176 + int(example_index) * 131) % 5
    supervised = bucket == 0
    evidence = ~supervised
    if not bool(torch.any(supervised)) and target_count > 0:
        supervised = torch.zeros(target_count, dtype=torch.bool, device=device)
        supervised[-1] = True
        evidence = ~supervised
    if not bool(torch.any(evidence)) and target_count > 1:
        evidence = torch.ones(target_count, dtype=torch.bool, device=device)
        evidence[-1] = False
        supervised = ~evidence
    return evidence, supervised


def stage_b_same_conformer_supervision_coherence_masks(
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    evidence_mask: torch.Tensor,
    supervised_mask: torch.Tensor,
    *,
    residue_count: int,
    focus_families: Sequence[str] | None = None,
    required_families: Sequence[str] | None = None,
    min_family_count: int = 2,
    max_residue_groups: int = 0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, torch.Tensor, dict[str, float]]:
    """Keep same-residue co-satisfaction rows together in Stage-B supervision."""

    prefix = "same_conformer_supervision_coherence"
    metrics = {
        f"{prefix}_active": 0.0,
        f"{prefix}_eligible_residue_groups": 0.0,
        f"{prefix}_selected_residue_groups": 0.0,
        f"{prefix}_selected_rows": 0.0,
        f"{prefix}_added_rows": 0.0,
    }
    if (
        target_features.ndim != 2
        or int(target_features.shape[0]) <= 0
        or int(family_indices.numel()) <= 0
        or int(supervised_mask.numel()) <= 0
        or int(residue_count) <= 0
    ):
        return evidence_mask, supervised_mask, metrics

    device = supervised_mask.device
    row_count = int(supervised_mask.numel())
    usable_count = min(
        row_count,
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(evidence_mask.numel()),
    )
    if usable_count <= 0:
        return evidence_mask, supervised_mask, metrics

    family_count = min(len(family_names), max(int(torch.max(family_indices[:usable_count]).detach().cpu()) + 1, 1))
    family_to_index = {
        _x0_canonical_family_name(name): index
        for index, name in enumerate(family_names[:family_count])
    }
    requested = list(focus_families or ("HN", "N", "C'"))
    focus_indices: list[int] = []
    for raw_family in requested:
        family_index = family_to_index.get(_x0_canonical_family_name(raw_family))
        if family_index is not None and family_index not in focus_indices:
            focus_indices.append(int(family_index))
    required_indices: list[int] = []
    for raw_family in required_families or ():
        family_index = family_to_index.get(_x0_canonical_family_name(raw_family))
        if family_index is None:
            continue
        if family_index not in focus_indices:
            focus_indices.append(int(family_index))
        if family_index not in required_indices:
            required_indices.append(int(family_index))
    required_count = max(int(min_family_count), 1)
    if len(focus_indices) < required_count:
        return evidence_mask, supervised_mask, metrics

    features = target_features[:usable_count].to(device=device)
    families = family_indices[:usable_count].to(device=device).long()
    residues = _aligned_residue_indices_from_target_features(
        features,
        residue_count=int(residue_count),
    )
    focus_index_tensor = torch.tensor(focus_indices, dtype=families.dtype, device=device)
    focus_row_mask = torch.isin(families, focus_index_tensor)
    if not bool(torch.any(focus_row_mask)):
        return evidence_mask, supervised_mask, metrics

    selected_row_mask = torch.zeros(usable_count, dtype=torch.bool, device=device)
    eligible_groups: list[int] = []
    for residue_value in torch.unique(residues[focus_row_mask]).detach().cpu().tolist():
        residue = int(residue_value)
        residue_focus_rows = focus_row_mask & (residues == residue)
        present_family_values = set(
            int(value)
            for value in torch.unique(families[residue_focus_rows]).detach().cpu().tolist()
        )
        if len(present_family_values) < required_count:
            continue
        if required_indices and not all(
            int(required_family) in present_family_values
            for required_family in required_indices
        ):
            continue
        eligible_groups.append(residue)

    metrics[f"{prefix}_eligible_residue_groups"] = float(len(eligible_groups))
    group_limit = max(int(max_residue_groups), 0)
    if group_limit > 0:
        eligible_groups = eligible_groups[:group_limit]
    for residue in eligible_groups:
        selected_row_mask |= focus_row_mask & (residues == int(residue))
    if not bool(torch.any(selected_row_mask)):
        return evidence_mask, supervised_mask, metrics

    next_supervised = supervised_mask.clone()
    next_evidence = evidence_mask.clone()
    previous_supervised = next_supervised[:usable_count].clone()
    next_supervised[:usable_count] |= selected_row_mask
    next_evidence[:usable_count] &= ~selected_row_mask
    added_rows = next_supervised[:usable_count] & ~previous_supervised
    metrics.update(
        {
            f"{prefix}_active": 1.0,
            f"{prefix}_selected_residue_groups": float(len(eligible_groups)),
            f"{prefix}_selected_rows": float(
                torch.count_nonzero(selected_row_mask).detach().cpu()
            ),
            f"{prefix}_added_rows": float(
                torch.count_nonzero(added_rows).detach().cpu()
            ),
            f"{prefix}_required_family_count": float(len(required_indices)),
            f"{prefix}_min_family_count": float(required_count),
        }
    )
    return next_evidence, next_supervised, metrics


def stage_b_evidence_features(
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    evidence_mask: torch.Tensor,
    *,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Build compact observed-evidence conditioning for posterior energies."""

    vector = torch.zeros(STAGE_B_EVIDENCE_FEATURE_DIM, dtype=dtype, device=device)
    if target_values.numel() == 0 or target_features.ndim != 2:
        return vector
    features = target_features.to(device=device, dtype=dtype)
    values = target_values.to(device=device, dtype=dtype)
    families = family_indices.to(device=device).long()
    observed = evidence_mask.to(device=device, dtype=torch.bool) & torch.isfinite(values)
    total_rows = max(int(values.numel()), 1)
    centers = values.new_tensor(ATOM_FAMILY_PPM_CENTERS)
    scales = values.new_tensor(ATOM_FAMILY_PPM_SCALES).clamp_min(1.0e-3)
    for family_index in range(len(CHEMICAL_SHIFT_FAMILIES)):
        mask = observed & (families == int(family_index))
        offset = family_index * 6
        count = int(torch.count_nonzero(mask).detach().cpu())
        if count <= 0:
            continue
        normalized = (values[mask] - centers[family_index]) / scales[family_index]
        vector[offset + 0] = 1.0
        vector[offset + 1] = min(float(count) / float(total_rows), 1.0)
        vector[offset + 2] = torch.mean(normalized).clamp(-5.0, 5.0)
        vector[offset + 3] = (
            torch.std(normalized, unbiased=False).clamp(0.0, 5.0)
            if count > 1
            else normalized.new_tensor(0.0)
        )
        vector[offset + 4] = torch.amin(normalized).clamp(-5.0, 5.0)
        vector[offset + 5] = torch.amax(normalized).clamp(-5.0, 5.0)

    def column(index: int) -> torch.Tensor:
        if features.shape[1] <= index:
            return torch.zeros(features.shape[0], dtype=dtype, device=device)
        return torch.nan_to_num(features[:, index], nan=0.0).clamp(0.0, 1.0)

    family_to_index = {family: index for index, family in enumerate(CHEMICAL_SHIFT_FAMILIES)}
    hn_mask = observed & (families == family_to_index.get("HN", -1))
    cprime_mask = observed & (families == family_to_index.get("C'", -1))
    extras = (
        (30, hn_mask, column(FEATURE_EXCHANGE_RISK)),
        (31, hn_mask, column(FEATURE_RING_CURRENT_PROXY)),
        (32, hn_mask, column(FEATURE_HN_SEQUENCE_CONTEXT_RISK)),
        (33, hn_mask, column(FEATURE_SAMPLE_HN_EXCHANGE_PROXY)),
        (34, hn_mask, column(FEATURE_SAMPLE_CONDITION_RISK)),
        (35, cprime_mask, column(FEATURE_CPRIME_PLANE_PROXY)),
        (36, cprime_mask, column(FEATURE_CPRIME_SEQUENCE_CONTEXT_RISK)),
        (37, cprime_mask, column(FEATURE_LOCAL_TURN_PROPENSITY)),
        (38, cprime_mask, column(FEATURE_DISORDER_PROXY)),
        (39, observed, column(FEATURE_SAMPLE_CONDITION_AVAILABLE)),
    )
    for offset, mask, values_for_mask in extras:
        if bool(torch.any(mask)):
            vector[offset] = torch.mean(values_for_mask[mask]).clamp(0.0, 1.0)
    return vector


def stage_b_family_balanced_ensemble_loss(
    ensemble_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, int]:
    """Family-balanced normalized MSE for posterior reweighting."""

    scales = ensemble_phi.new_tensor(ATOM_FAMILY_PPM_SCALES).reshape(1, -1)
    target = target_grid.to(device=ensemble_phi.device, dtype=ensemble_phi.dtype)
    mask = (
        observed_mask.to(device=ensemble_phi.device, dtype=torch.bool)
        & torch.isfinite(target)
        & torch.isfinite(ensemble_phi)
    )
    family_losses: list[tuple[torch.Tensor, float]] = []
    row_count = 0
    for family_index in range(ensemble_phi.shape[-1]):
        family_mask = mask[:, family_index]
        if not bool(torch.any(family_mask)):
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        diff = (
            ensemble_phi[:, family_index][family_mask]
            - target[:, family_index][family_mask]
        ) / scales[:, family_index].clamp_min(1.0e-3)
        family_losses.append((torch.mean(diff.square()), family_weight))
        row_count += int(torch.count_nonzero(family_mask).detach().cpu())
    if not family_losses:
        return _zero_loss_like(ensemble_phi), 0
    weighted_loss = ensemble_phi.new_tensor(0.0)
    weight_sum = 0.0
    for family_loss, family_weight in family_losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
    return weighted_loss / max(weight_sum, 1.0e-12), row_count


def _entity_uid_aliases(entity_uid: str) -> tuple[str, ...]:
    """Normalized entity aliases used by legacy replay configs."""

    entity = str(entity_uid).strip()
    if not entity:
        return ("",)
    aliases = [entity, entity.lower()]
    short_entity = entity.split(":")[-1]
    aliases.extend([short_entity, short_entity.lower()])
    if not entity.lower().startswith("bmrb:") and short_entity:
        aliases.extend([f"bmrb:{short_entity}", f"bmrb:{short_entity.lower()}"])
    deduped: list[str] = []
    for alias in aliases:
        normalized = str(alias).strip()
        if normalized and normalized not in deduped:
            deduped.append(normalized)
    return tuple(deduped)


def _split_entity_family_replay_key(key: str) -> tuple[str, str] | None:
    """Parse ``entity|family`` style keys while preserving ``bmrb:`` prefixes."""

    raw_key = str(key).strip()
    for separator in ("|", "::", "/", ":"):
        if separator not in raw_key:
            continue
        entity, family = raw_key.rsplit(separator, 1)
        entity = entity.strip()
        family = family.strip()
        if entity and family:
            return entity, family
    return None


def _canonical_entity_family_replay_family(
    family: str,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> str | None:
    """Map replay family aliases onto the configured canonical family names."""

    canonical_by_key: dict[str, str] = {}
    for configured_family in family_names:
        canonical = str(configured_family)
        normalized = canonical.lower().replace("_", "").replace("-", "").replace(" ", "")
        canonical_by_key[normalized] = canonical
    alias_lookup = {
        "h": "HN",
        "hn": "HN",
        "amideh": "HN",
        "n": "N",
        "amide15n": "N",
        "ca": "CA",
        "calpha": "CA",
        "cb": "CB",
        "cbeta": "CB",
        "c": "C'",
        "cp": "C'",
        "cprime": "C'",
        "c'": "C'",
        "carbonyl": "C'",
        "carbonylc": "C'",
    }
    raw = str(family).strip()
    key = raw.lower().replace("_", "").replace("-", "").replace(" ", "")
    candidate = alias_lookup.get(key, raw)
    candidate_key = str(candidate).lower().replace("_", "").replace("-", "").replace(" ", "")
    return canonical_by_key.get(candidate_key)


def _entity_weight_for_x0_replay(
    entity_uid: str,
    entity_weights: dict[str, float] | None,
) -> float:
    """Return the configured hard-entry weight for an x0 posterior example."""

    if not entity_weights:
        return 1.0
    aliases = set(_entity_uid_aliases(entity_uid))
    aliases.update(alias.lower() for alias in aliases)
    for key, value in entity_weights.items():
        key_aliases = set(_entity_uid_aliases(str(key)))
        key_aliases.update(alias.lower() for alias in key_aliases)
        if aliases & key_aliases:
            return max(float(value), 0.0)
    return 1.0


def _entity_family_weights_for_x0_replay(
    entity_uid: str,
    entity_family_weights: dict[str, float] | None,
    *,
    threshold: float = 1.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> dict[str, float]:
    """Select replay family weights for one entity without leaking to siblings."""

    if not entity_family_weights:
        return {}
    aliases = set(_entity_uid_aliases(entity_uid))
    aliases.update(alias.lower() for alias in aliases)
    selected: dict[str, float] = {}
    floor = float(threshold)
    for key, value in entity_family_weights.items():
        parsed = _split_entity_family_replay_key(str(key))
        if parsed is None:
            continue
        entity_part, family_part = parsed
        entity_aliases = set(_entity_uid_aliases(entity_part))
        entity_aliases.update(alias.lower() for alias in entity_aliases)
        if not (aliases & entity_aliases):
            continue
        family_name = _canonical_entity_family_replay_family(
            family_part,
            family_names=family_names,
        )
        if family_name is None:
            continue
        replay_weight = max(float(value) - floor, 0.0)
        if replay_weight <= 0.0:
            continue
        selected[family_name] = max(selected.get(family_name, 0.0), replay_weight)
    return selected


def _candidate_free_replay_ucbshift_residue_offset_contract_gate(
    config: StudentTrainingConfig,
) -> tuple[bool, dict[str, float]]:
    """Gate rejected-guard replay on an offline-verified UCBShift offset contract."""

    raw_contract = getattr(
        config,
        "candidate_free_replay_ucbshift_residue_offset_contract",
        {},
    )
    contract = raw_contract if isinstance(raw_contract, dict) else {}
    require_contract = bool(
        getattr(
            config,
            "candidate_free_replay_require_ucbshift_residue_offset_contract",
            False,
        )
    )
    ready = bool(contract.get("ready") is True)
    dominant_offset = float("nan")
    try:
        dominant_offset = float(contract.get("dominant_offset"))
    except (TypeError, ValueError):
        dominant_offset = float("nan")
    unique_offsets = contract.get("unique_offsets")
    entity_offsets = contract.get("entity_offsets")
    metrics = {
        "x0_entity_family_replay_ucbshift_residue_offset_contract_required": float(
            require_contract
        ),
        "x0_entity_family_replay_ucbshift_residue_offset_contract_ready": float(ready),
        "x0_entity_family_replay_ucbshift_residue_offset_contract_blocked": float(
            require_contract and not ready
        ),
        "x0_entity_family_replay_ucbshift_residue_offset_unique_count": float(
            len(unique_offsets) if isinstance(unique_offsets, list) else 0
        ),
        "x0_entity_family_replay_ucbshift_residue_offset_entity_count": float(
            len(entity_offsets) if isinstance(entity_offsets, dict) else 0
        ),
    }
    if math.isfinite(dominant_offset):
        metrics[
            "x0_entity_family_replay_ucbshift_residue_offset_dominant"
        ] = dominant_offset
    return (not require_contract or ready), metrics


_FAILED_ACTIVE_FACE_REPLAY_CACHE: dict[
    tuple[str, float, int],
    tuple[dict[str, str], ...],
] = {}


def _raise_failed_active_face_csv_field_limit() -> None:
    limit = sys.maxsize
    while True:
        try:
            csv.field_size_limit(limit)
            return
        except OverflowError:
            limit //= 10


def _failed_active_face_replay_float(
    value: Any,
    *,
    default: float = float("nan"),
) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return float(default)
    return parsed if math.isfinite(parsed) else float(default)


def _load_failed_active_face_replay_rows(
    bundle_path: str | Path,
) -> tuple[dict[str, str], ...]:
    """Load the async failed-active-face replay TSV without blocking training."""

    path_text = str(bundle_path or "").strip()
    if not path_text:
        return ()
    path = Path(os.path.expandvars(path_text)).expanduser()
    if not path.exists():
        return ()
    stat = path.stat()
    cache_key = (str(path), float(stat.st_mtime), int(stat.st_size))
    cached = _FAILED_ACTIVE_FACE_REPLAY_CACHE.get(cache_key)
    if cached is not None:
        return cached
    _raise_failed_active_face_csv_field_limit()
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        rows = tuple(
            {str(key): str(value) for key, value in dict(row).items()}
            for row in reader
        )
    _FAILED_ACTIVE_FACE_REPLAY_CACHE[cache_key] = rows
    return rows


def _failed_active_face_replay_residue_index(
    row: Mapping[str, str],
    *,
    residue_count: int,
) -> int | None:
    """Map replay residue/seq ids onto the zero-based model residue axis."""

    for key in (
        "residue_index",
        "aligned_residue_index",
        "seq_id",
        "residue_id",
        "residue_number",
    ):
        raw_value = row.get(key)
        if raw_value is None or str(raw_value).strip() == "":
            continue
        value = _failed_active_face_replay_float(raw_value)
        if not math.isfinite(value):
            continue
        rounded = int(round(value))
        if 1 <= rounded <= int(residue_count):
            return int(max(0, min(rounded - 1, int(residue_count) - 1)))
        return int(max(0, min(rounded, int(residue_count) - 1)))
    return None


def _failed_active_face_replay_row_family(
    row: Mapping[str, str],
    *,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> str | None:
    for key in ("atom_family", "family", "atom_type", "nucleus"):
        value = row.get(key)
        if value is None or str(value).strip() == "":
            continue
        return _canonical_entity_family_replay_family(value, family_names=family_names)
    return None


def _failed_active_face_replay_row_target(
    row: Mapping[str, str],
    *,
    target_source: str = "target_value",
) -> float:
    source_key = (
        str(target_source or "target_value")
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )
    source_keys: tuple[str, ...]
    if source_key in {"rowwise", "rowwise_prediction", "rowwise_oracle"}:
        source_keys = ("rowwise_prediction", "rowwise_value", "rowwise")
    elif source_key in {
        "shared_q",
        "shared_q_prediction",
        "shared_prediction",
    }:
        source_keys = ("shared_q_prediction", "shared_prediction")
    else:
        source_keys = (
            "target_value",
            "target",
            "observed_value",
            "chemical_shift",
            "shift",
        )
    fallback_keys = (
        "target_value",
        "target",
        "observed_value",
        "chemical_shift",
        "shift",
    )
    for key in (*source_keys, *fallback_keys):
        value = row.get(key)
        if value is None or str(value).strip() == "":
            continue
        parsed = _failed_active_face_replay_float(value)
        if math.isfinite(parsed):
            return parsed
    return float("nan")


def _failed_active_face_replay_rows_for_entity(
    bundle_path: str | Path,
    *,
    entity_uid: str,
) -> tuple[dict[str, str], ...]:
    aliases = set(_entity_uid_aliases(entity_uid))
    aliases.update(alias.lower() for alias in aliases)
    selected: list[dict[str, str]] = []
    for row in _load_failed_active_face_replay_rows(bundle_path):
        row_entity = str(
            row.get("entity_uid")
            or row.get("entity")
            or row.get("entry_id")
            or row.get("bmrb_id")
            or ""
        )
        if not row_entity.strip():
            continue
        row_aliases = set(_entity_uid_aliases(row_entity))
        row_aliases.update(alias.lower() for alias in row_aliases)
        if aliases & row_aliases:
            selected.append(dict(row))
    return tuple(selected)


def failed_active_face_support_center_loss(
    conformer_phi: torch.Tensor,
    *,
    entity_uid: str,
    replay_bundle_path: str | Path,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
    gap_focus_scale: float = 0.0,
    dual_weight_power: float = 1.0,
    response_deficit_weight_scale: float = 0.0,
    min_row_weight: float = 1.0,
    max_row_weight: float = 10.0,
    target_source: str = "target_value",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Place generated support around the exact failed active-face rows.

    The older entity-family replay objective only boosted whole families.  This
    loss consumes the async teacher's replay TSV directly, so a C'/HN/N failure
    at a specific residue becomes a sparse support-center target for
    ``phi_theta(X_k)`` without choosing a posterior ``q`` online.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_center_cells": 0.0
        }
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    residue_count = int(conformer_phi.shape[1])
    family_count = int(conformer_phi.shape[2])
    if residue_count <= 0 or family_count <= 0:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_center_cells": 0.0
        }

    rows = _failed_active_face_replay_rows_for_entity(
        replay_bundle_path,
        entity_uid=entity_uid,
    )
    if not rows:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_center_cells": 0.0,
            "failed_active_face_support_center_rows": 0.0,
        }

    family_to_index = {
        str(family): index
        for index, family in enumerate(family_names[:family_count])
    }
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    target_sum = torch.zeros(residue_count, family_count, dtype=dtype, device=device)
    cell_weights = torch.zeros_like(target_sum)
    rows_used = 0
    row_weight_values: list[float] = []
    family_row_counts: dict[str, int] = {}
    dual_power = max(float(dual_weight_power), 0.0)
    deficit_scale = max(float(response_deficit_weight_scale), 0.0)
    min_weight = max(float(min_row_weight), 0.0)
    max_weight = max(float(max_row_weight), min_weight if min_weight > 0.0 else 1.0)
    for row in rows:
        family_name = _failed_active_face_replay_row_family(
            row,
            family_names=family_names,
        )
        if family_name is None or family_name not in family_to_index:
            continue
        family_index = family_to_index[family_name]
        target_value = _failed_active_face_replay_row_target(
            row,
            target_source=target_source,
        )
        if not math.isfinite(target_value):
            continue
        residue_index = _failed_active_face_replay_residue_index(
            row,
            residue_count=residue_count,
        )
        if residue_index is None:
            continue
        dual = max(
            _failed_active_face_replay_float(
                row.get("dual_multiplier"),
                default=1.0,
            ),
            min_weight,
        )
        row_weight = dual**dual_power if dual_power > 0.0 else 1.0
        if deficit_scale > 0.0:
            deficit = max(
                _failed_active_face_replay_float(
                    row.get("response_deficit_abs_ppm"),
                    default=0.0,
                ),
                0.0,
            )
            row_weight *= 1.0 + deficit_scale * deficit
        row_weight = max(min(row_weight, max_weight), min_weight)
        row_weight_tensor = conformer_phi.new_tensor(row_weight)
        target_sum[residue_index, family_index] += (
            conformer_phi.new_tensor(float(target_value)) * row_weight_tensor
        )
        cell_weights[residue_index, family_index] += row_weight_tensor
        rows_used += 1
        row_weight_values.append(float(row_weight))
        family_row_counts[family_name] = family_row_counts.get(family_name, 0) + 1

    observed_mask = cell_weights > 0.0
    if rows_used <= 0 or not bool(torch.any(observed_mask)):
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_center_cells": 0.0,
            "failed_active_face_support_center_rows": 0.0,
        }
    target_grid = torch.where(
        observed_mask,
        target_sum / cell_weights.clamp_min(conformer_phi.new_tensor(1.0e-12)),
        target_sum,
    )

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[:family_count]
    ).reshape(1, 1, -1).clamp_min(1.0e-3)
    values = conformer_phi / scales
    target_norm = target_grid / scales.reshape(1, -1)
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(-values / smooth_tensor, dim=0)
        support_max = smooth_tensor * torch.logsumexp(values / smooth_tensor, dim=0)
    else:
        support_min = torch.amin(values, dim=0)
        support_max = torch.amax(values, dim=0)
    support_center = 0.5 * (support_min + support_max)
    gap_focus = max(float(gap_focus_scale), 0.0)

    losses: list[tuple[torch.Tensor, float, int]] = []
    active_counts: list[int] = []
    offset_values: list[float] = []
    metrics: dict[str, float] = {
        "failed_active_face_support_center_rows": float(rows_used),
        "failed_active_face_support_center_row_weight_mean": float(
            sum(row_weight_values) / max(len(row_weight_values), 1)
        ),
        "failed_active_face_support_center_target_source_code": float(
            {
                "target_value": 0,
                "target": 0,
                "rowwise": 1,
                "rowwise_prediction": 1,
                "rowwise_oracle": 1,
                "shared_q": 2,
                "shared_q_prediction": 2,
                "shared_prediction": 2,
            }.get(
                str(target_source or "target_value")
                .strip()
                .lower()
                .replace("-", "_")
                .replace(" ", "_"),
                0,
            )
        ),
    }
    for family_index in range(family_count):
        family_mask = observed_mask[:, family_index]
        point_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if point_count <= 0:
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        selected_center = support_center[:, family_index][family_mask]
        selected_target = target_norm[:, family_index][family_mask]
        selected_cell_weights = cell_weights[:, family_index][family_mask]
        offset = selected_center - selected_target
        low_gap = torch.relu(support_min[:, family_index][family_mask] - selected_target)
        high_gap = torch.relu(selected_target - support_max[:, family_index][family_mask])
        outside_gap = low_gap + high_gap
        cell_loss = offset.square()
        if gap_focus > 0.0:
            cell_loss = cell_loss * (1.0 + gap_focus * outside_gap.detach())
        weighted_cell_loss = (
            cell_loss * selected_cell_weights
        ).sum() / selected_cell_weights.sum().clamp_min(conformer_phi.new_tensor(1.0e-12))
        losses.append((weighted_cell_loss, family_weight, point_count))
        offset_abs = torch.abs(offset.detach())
        outside_active = int(torch.count_nonzero(outside_gap > 0.0).detach().cpu())
        offset_mean = float(torch.mean(offset_abs).cpu())
        offset_values.append(offset_mean)
        active_counts.append(outside_active)
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"failed_active_face_support_center_{safe_name}_rows"] = float(
            family_row_counts.get(family_name, 0)
        )
        metrics[
            f"failed_active_face_support_center_{safe_name}_offset_norm_mean"
        ] = offset_mean
        metrics[
            f"failed_active_face_support_center_{safe_name}_outside_fraction"
        ] = float(outside_active / max(point_count, 1))

    if not losses:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_center_cells": 0.0,
            "failed_active_face_support_center_rows": float(rows_used),
        }

    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    cell_count = 0
    for family_loss, family_weight, point_count in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
        cell_count += point_count
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics.update(
        {
            "failed_active_face_support_center_cells": float(cell_count),
            "failed_active_face_support_center_families": float(len(losses)),
            "failed_active_face_support_center_loss_value": float(loss.detach().cpu()),
            "failed_active_face_support_center_active_fraction": float(
                sum(active_counts) / max(cell_count, 1)
            ),
            "failed_active_face_support_center_offset_norm_mean": float(
                sum(offset_values) / max(len(offset_values), 1)
            ),
        }
    )
    return loss * weight, metrics


def failed_active_face_support_tail_loss(
    conformer_phi: torch.Tensor,
    *,
    entity_uid: str,
    replay_bundle_path: str | Path,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
    direction: str = "auto",
    target_source: str = "target_value",
    dual_weight_power: float = 1.0,
    response_deficit_weight_scale: float = 0.0,
    min_row_weight: float = 1.0,
    max_row_weight: float = 10.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Extend generated support toward failed active-face tail rows.

    Center matching can move an already useful support interval in the wrong
    direction.  This loss instead applies a one-sided hinge to the support
    boundary: if a failed C'/HN/N row needs lower support, only the smooth
    support minimum is pulled down; if it needs upper support, only the maximum
    is pushed up.  Rows already covered by the generated support stay quiet.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_tail_cells": 0.0
        }
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    residue_count = int(conformer_phi.shape[1])
    family_count = int(conformer_phi.shape[2])
    if residue_count <= 0 or family_count <= 0:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_tail_cells": 0.0
        }

    rows = _failed_active_face_replay_rows_for_entity(
        replay_bundle_path,
        entity_uid=entity_uid,
    )
    if not rows:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_tail_cells": 0.0,
            "failed_active_face_support_tail_rows": 0.0,
        }

    family_to_index = {
        str(family): index
        for index, family in enumerate(family_names[:family_count])
    }
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    target_sum = torch.zeros(residue_count, family_count, dtype=dtype, device=device)
    cell_weights = torch.zeros_like(target_sum)
    rows_used = 0
    row_weight_values: list[float] = []
    family_row_counts: dict[str, int] = {}
    dual_power = max(float(dual_weight_power), 0.0)
    deficit_scale = max(float(response_deficit_weight_scale), 0.0)
    min_weight = max(float(min_row_weight), 0.0)
    max_weight = max(float(max_row_weight), min_weight if min_weight > 0.0 else 1.0)
    for row in rows:
        family_name = _failed_active_face_replay_row_family(
            row,
            family_names=family_names,
        )
        if family_name is None or family_name not in family_to_index:
            continue
        family_index = family_to_index[family_name]
        target_value = _failed_active_face_replay_row_target(
            row,
            target_source=target_source,
        )
        if not math.isfinite(target_value):
            continue
        residue_index = _failed_active_face_replay_residue_index(
            row,
            residue_count=residue_count,
        )
        if residue_index is None:
            continue
        dual = max(
            _failed_active_face_replay_float(
                row.get("dual_multiplier"),
                default=1.0,
            ),
            min_weight,
        )
        row_weight = dual**dual_power if dual_power > 0.0 else 1.0
        if deficit_scale > 0.0:
            deficit = max(
                _failed_active_face_replay_float(
                    row.get("response_deficit_abs_ppm"),
                    default=0.0,
                ),
                0.0,
            )
            row_weight *= 1.0 + deficit_scale * deficit
        row_weight = max(min(row_weight, max_weight), min_weight)
        row_weight_tensor = conformer_phi.new_tensor(row_weight)
        target_sum[residue_index, family_index] += (
            conformer_phi.new_tensor(float(target_value)) * row_weight_tensor
        )
        cell_weights[residue_index, family_index] += row_weight_tensor
        rows_used += 1
        row_weight_values.append(float(row_weight))
        family_row_counts[family_name] = family_row_counts.get(family_name, 0) + 1

    observed_mask = cell_weights > 0.0
    if rows_used <= 0 or not bool(torch.any(observed_mask)):
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_tail_cells": 0.0,
            "failed_active_face_support_tail_rows": 0.0,
        }
    target_grid = torch.where(
        observed_mask,
        target_sum / cell_weights.clamp_min(conformer_phi.new_tensor(1.0e-12)),
        target_sum,
    )

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[:family_count]
    ).reshape(1, 1, -1).clamp_min(1.0e-3)
    values = conformer_phi / scales
    target_norm = target_grid / scales.reshape(1, -1)
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(-values / smooth_tensor, dim=0)
        support_max = smooth_tensor * torch.logsumexp(values / smooth_tensor, dim=0)
    else:
        support_min = torch.amin(values, dim=0)
        support_max = torch.amax(values, dim=0)
    support_center = 0.5 * (support_min + support_max)
    direction_key = (
        str(direction or "auto")
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )
    target_source_key = (
        str(target_source or "target_value")
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )

    losses: list[tuple[torch.Tensor, float, int]] = []
    active_counts: list[int] = []
    gap_values: list[float] = []
    lower_direction_count = 0
    upper_direction_count = 0
    metrics: dict[str, float] = {
        "failed_active_face_support_tail_rows": float(rows_used),
        "failed_active_face_support_tail_row_weight_mean": float(
            sum(row_weight_values) / max(len(row_weight_values), 1)
        ),
        "failed_active_face_support_tail_target_source_code": float(
            {
                "target_value": 0,
                "target": 0,
                "rowwise": 1,
                "rowwise_prediction": 1,
                "rowwise_oracle": 1,
                "shared_q": 2,
                "shared_q_prediction": 2,
                "shared_prediction": 2,
            }.get(target_source_key, 0)
        ),
        "failed_active_face_support_tail_direction_code": float(
            {"lower": -1, "down": -1, "upper": 1, "up": 1, "auto": 0}.get(
                direction_key,
                0,
            )
        ),
    }
    for family_index in range(family_count):
        family_mask = observed_mask[:, family_index]
        point_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if point_count <= 0:
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        selected_min = support_min[:, family_index][family_mask]
        selected_max = support_max[:, family_index][family_mask]
        selected_center = support_center[:, family_index][family_mask]
        selected_target = target_norm[:, family_index][family_mask]
        selected_cell_weights = cell_weights[:, family_index][family_mask]
        lower_gap = torch.relu(selected_min - selected_target)
        upper_gap = torch.relu(selected_target - selected_max)
        if direction_key in {"lower", "down"}:
            tail_gap = lower_gap
            lower_mask = torch.ones_like(tail_gap, dtype=torch.bool)
            upper_mask = torch.zeros_like(tail_gap, dtype=torch.bool)
        elif direction_key in {"upper", "up"}:
            tail_gap = upper_gap
            lower_mask = torch.zeros_like(tail_gap, dtype=torch.bool)
            upper_mask = torch.ones_like(tail_gap, dtype=torch.bool)
        else:
            lower_mask = selected_target <= selected_center.detach()
            upper_mask = ~lower_mask
            tail_gap = torch.where(lower_mask, lower_gap, upper_gap)

        weighted_cell_loss = (
            tail_gap.square() * selected_cell_weights
        ).sum() / selected_cell_weights.sum().clamp_min(conformer_phi.new_tensor(1.0e-12))
        losses.append((weighted_cell_loss, family_weight, point_count))
        active_count = int(torch.count_nonzero(tail_gap > 0.0).detach().cpu())
        active_counts.append(active_count)
        lower_count = int(torch.count_nonzero(lower_mask).detach().cpu())
        upper_count = int(torch.count_nonzero(upper_mask).detach().cpu())
        lower_direction_count += lower_count
        upper_direction_count += upper_count
        gap_mean = float(torch.mean(torch.abs(tail_gap.detach())).cpu())
        gap_values.append(gap_mean)
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"failed_active_face_support_tail_{safe_name}_rows"] = float(
            family_row_counts.get(family_name, 0)
        )
        metrics[
            f"failed_active_face_support_tail_{safe_name}_gap_norm_mean"
        ] = gap_mean
        metrics[
            f"failed_active_face_support_tail_{safe_name}_active_fraction"
        ] = float(active_count / max(point_count, 1))
        metrics[
            f"failed_active_face_support_tail_{safe_name}_lower_fraction"
        ] = float(lower_count / max(point_count, 1))
        metrics[
            f"failed_active_face_support_tail_{safe_name}_upper_fraction"
        ] = float(upper_count / max(point_count, 1))

    if not losses:
        return _zero_loss_like(conformer_phi), {
            "failed_active_face_support_tail_cells": 0.0,
            "failed_active_face_support_tail_rows": float(rows_used),
        }

    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    cell_count = 0
    for family_loss, family_weight, point_count in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
        cell_count += point_count
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics.update(
        {
            "failed_active_face_support_tail_cells": float(cell_count),
            "failed_active_face_support_tail_families": float(len(losses)),
            "failed_active_face_support_tail_loss_value": float(loss.detach().cpu()),
            "failed_active_face_support_tail_active_fraction": float(
                sum(active_counts) / max(cell_count, 1)
            ),
            "failed_active_face_support_tail_gap_norm_mean": float(
                sum(gap_values) / max(len(gap_values), 1)
            ),
            "failed_active_face_support_tail_lower_fraction": float(
                lower_direction_count / max(cell_count, 1)
            ),
            "failed_active_face_support_tail_upper_fraction": float(
                upper_direction_count / max(cell_count, 1)
            ),
        }
    )
    return loss * weight, metrics


def failed_active_face_energy_assignment_loss(
    conformer_phi: torch.Tensor,
    model_energy: torch.Tensor,
    *,
    entity_uid: str,
    replay_bundle_path: str | Path,
    prior_log_probs: torch.Tensor | None = None,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    target_source: str = "target_value",
    margin: float = 0.04,
    positive_fraction: float = 0.08,
    negative_fraction: float = 0.12,
    positive_mass_weight: float = 0.0,
    temperature: float = 1.0,
    dual_weight_power: float = 1.0,
    response_deficit_weight_scale: float = 0.0,
    min_row_weight: float = 1.0,
    max_row_weight: float = 10.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Rank posterior energy toward failed active-face conformers.

    Tail/center losses can create support without making one shared q use it.
    This loss keeps the failed replay target detached, selects the conformers
    whose generated chemical shift is closest to that target, and directly
    pushes their active posterior energy below far-away conformers.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(model_energy), {
            "failed_active_face_energy_assignment_rows": 0.0
        }
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if int(model_energy.numel()) != int(conformer_phi.shape[0]):
        raise ValueError("model_energy must have one value per conformer")
    support_count = int(conformer_phi.shape[0])
    residue_count = int(conformer_phi.shape[1])
    family_count = int(conformer_phi.shape[2])
    if support_count < 2 or residue_count <= 0 or family_count <= 0:
        return _zero_loss_like(model_energy), {
            "failed_active_face_energy_assignment_rows": 0.0
        }

    rows = _failed_active_face_replay_rows_for_entity(
        replay_bundle_path,
        entity_uid=entity_uid,
    )
    if not rows:
        return _zero_loss_like(model_energy), {
            "failed_active_face_energy_assignment_rows": 0.0
        }

    family_to_index = {
        str(family): index
        for index, family in enumerate(family_names[:family_count])
    }
    energy = model_energy.reshape(-1).to(
        device=conformer_phi.device,
        dtype=conformer_phi.dtype,
    )
    finite_energy = torch.isfinite(energy)
    temp = max(float(temperature), 1.0e-6)
    if prior_log_probs is not None and int(prior_log_probs.numel()) == support_count:
        prior_log = prior_log_probs.to(device=energy.device, dtype=energy.dtype).reshape(-1)
        prior_log = torch.nan_to_num(prior_log, nan=0.0, posinf=0.0, neginf=0.0)
    else:
        prior_log = torch.zeros_like(energy)
    effective_energy = energy - energy.new_tensor(temp) * prior_log
    if bool(torch.any(finite_energy)):
        effective_energy = effective_energy - effective_energy[finite_energy].mean()
    posterior_energy = torch.where(
        finite_energy,
        energy,
        energy.new_full(energy.shape, 1.0e6),
    )
    posterior_q = posterior_weights(
        prior_log_probs.to(device=energy.device, dtype=energy.dtype).reshape(-1)
        if prior_log_probs is not None and int(prior_log_probs.numel()) == support_count
        else None,
        posterior_energy,
        temperature=temp,
    )

    dual_power = max(float(dual_weight_power), 0.0)
    deficit_scale = max(float(response_deficit_weight_scale), 0.0)
    min_weight = max(float(min_row_weight), 0.0)
    max_weight = max(float(max_row_weight), min_weight if min_weight > 0.0 else 1.0)
    pos_fraction = min(max(float(positive_fraction), 0.0), 1.0)
    neg_fraction = min(max(float(negative_fraction), 0.0), 1.0)
    pair_margin = max(float(margin), 0.0)
    mass_weight = max(float(positive_mass_weight), 0.0)

    weighted_loss = energy.new_tensor(0.0)
    weighted_pair_loss = energy.new_tensor(0.0)
    weighted_mass_loss = energy.new_tensor(0.0)
    weight_sum = 0.0
    rows_used = 0
    positive_counts: list[int] = []
    negative_counts: list[int] = []
    gap_values: list[float] = []
    mass_values: list[float] = []
    residual_values: list[float] = []
    family_row_counts: dict[str, int] = {}
    for row in rows:
        family_name = _failed_active_face_replay_row_family(
            row,
            family_names=family_names,
        )
        if family_name is None or family_name not in family_to_index:
            continue
        family_index = family_to_index[family_name]
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        target_value = _failed_active_face_replay_row_target(
            row,
            target_source=target_source,
        )
        if not math.isfinite(target_value):
            continue
        residue_index = _failed_active_face_replay_residue_index(
            row,
            residue_count=residue_count,
        )
        if residue_index is None:
            continue
        row_values = conformer_phi[:, residue_index, family_index].detach()
        scale = conformer_phi.new_tensor(
            max(float(ATOM_FAMILY_PPM_SCALES[family_index]), 1.0e-3)
        )
        residual = torch.abs(
            (row_values - conformer_phi.new_tensor(float(target_value))) / scale
        )
        valid = finite_energy & torch.isfinite(row_values) & torch.isfinite(residual)
        valid_count = int(torch.count_nonzero(valid).detach().cpu())
        if valid_count < 2:
            continue
        valid_indices = torch.nonzero(valid, as_tuple=False).flatten()
        ordered = valid_indices[
            torch.argsort(residual.index_select(0, valid_indices), stable=True)
        ]
        positive_count = min(
            max(int(round(valid_count * pos_fraction)), 1),
            max(valid_count - 1, 1),
        )
        negative_count = min(
            max(int(round(valid_count * neg_fraction)), 1),
            max(valid_count - positive_count, 1),
        )
        positive_indices = ordered[:positive_count]
        negative_indices = ordered[-negative_count:]
        if int(positive_indices.numel()) <= 0 or int(negative_indices.numel()) <= 0:
            continue

        dual = max(
            _failed_active_face_replay_float(
                row.get("dual_multiplier"),
                default=1.0,
            ),
            min_weight,
        )
        row_weight = dual**dual_power if dual_power > 0.0 else 1.0
        if deficit_scale > 0.0:
            deficit = max(
                _failed_active_face_replay_float(
                    row.get("response_deficit_abs_ppm"),
                    default=0.0,
                ),
                0.0,
            )
            row_weight *= 1.0 + deficit_scale * deficit
        row_weight = max(min(row_weight, max_weight), min_weight) * family_weight
        row_weight_tensor = energy.new_tensor(row_weight)

        pos_energy = effective_energy.index_select(0, positive_indices)
        neg_energy = effective_energy.index_select(0, negative_indices)
        pair_gap = neg_energy[:, None] - pos_energy[None, :]
        pair_loss = torch.relu(energy.new_tensor(pair_margin) - pair_gap).mean()
        positive_mass = posterior_q.index_select(0, positive_indices).sum().clamp_min(
            1.0e-12
        )
        mass_loss = -torch.log(positive_mass)
        row_loss = pair_loss + energy.new_tensor(mass_weight) * mass_loss

        weighted_loss = weighted_loss + row_loss * row_weight_tensor
        weighted_pair_loss = weighted_pair_loss + pair_loss * row_weight_tensor
        weighted_mass_loss = weighted_mass_loss + mass_loss * row_weight_tensor
        weight_sum += float(row_weight)
        rows_used += 1
        positive_counts.append(int(positive_indices.numel()))
        negative_counts.append(int(negative_indices.numel()))
        gap_values.append(float(pair_gap.detach().mean().cpu()))
        mass_values.append(float(positive_mass.detach().cpu()))
        residual_values.append(
            float(residual.index_select(0, positive_indices).detach().mean().cpu())
        )
        family_row_counts[family_name] = family_row_counts.get(family_name, 0) + 1

    if rows_used <= 0 or weight_sum <= 0.0:
        return _zero_loss_like(model_energy), {
            "failed_active_face_energy_assignment_rows": 0.0
        }

    loss = weighted_loss / max(weight_sum, 1.0e-12)
    pair_component = weighted_pair_loss / max(weight_sum, 1.0e-12)
    mass_component = weighted_mass_loss / max(weight_sum, 1.0e-12)
    target_source_key = (
        str(target_source or "target_value")
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )
    metrics: dict[str, float] = {
        "failed_active_face_energy_assignment_rows": float(rows_used),
        "failed_active_face_energy_assignment_loss_value": float(loss.detach().cpu()),
        "failed_active_face_energy_assignment_pair_loss_value": float(
            pair_component.detach().cpu()
        ),
        "failed_active_face_energy_assignment_mass_loss_value": float(
            mass_component.detach().cpu()
        ),
        "failed_active_face_energy_assignment_positive_mass_weight": float(
            mass_weight
        ),
        "failed_active_face_energy_assignment_margin": float(pair_margin),
        "failed_active_face_energy_assignment_positive_count_mean": float(
            sum(positive_counts) / max(len(positive_counts), 1)
        ),
        "failed_active_face_energy_assignment_negative_count_mean": float(
            sum(negative_counts) / max(len(negative_counts), 1)
        ),
        "failed_active_face_energy_assignment_pair_gap_mean": float(
            sum(gap_values) / max(len(gap_values), 1)
        ),
        "failed_active_face_energy_assignment_positive_mass_mean": float(
            sum(mass_values) / max(len(mass_values), 1)
        ),
        "failed_active_face_energy_assignment_positive_residual_norm_mean": float(
            sum(residual_values) / max(len(residual_values), 1)
        ),
        "failed_active_face_energy_assignment_target_source_code": float(
            {
                "target_value": 0,
                "target": 0,
                "rowwise": 1,
                "rowwise_prediction": 1,
                "rowwise_oracle": 1,
                "shared_q": 2,
                "shared_q_prediction": 2,
                "shared_prediction": 2,
            }.get(target_source_key, 0)
        ),
    }
    for family_name, count in family_row_counts.items():
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"failed_active_face_energy_assignment_{safe_name}_rows"] = float(
            count
        )
    return loss * weight, metrics


def failed_active_face_shared_q_response_loss(
    conformer_phi: torch.Tensor,
    model_energy: torch.Tensor,
    *,
    entity_uid: str,
    replay_bundle_path: str | Path,
    prior_log_probs: torch.Tensor | None = None,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    target_source: str = "target_value",
    temperature: float = 1.0,
    huber_beta: float = 0.15,
    support_gap_weight: float = 0.0,
    dual_weight_power: float = 1.0,
    response_deficit_weight_scale: float = 0.0,
    min_row_weight: float = 1.0,
    max_row_weight: float = 10.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Constrain failed rows under the same support-level shared q.

    Energy assignment can prefer target-like conformers without improving the
    actual generated response.  This objective applies the failed replay rows
    directly to the one shared-q posterior mean, while still avoiding rowwise or
    family-specific q variables.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(model_energy), {
            "failed_active_face_shared_q_response_rows": 0.0
        }
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if int(model_energy.numel()) != int(conformer_phi.shape[0]):
        raise ValueError("model_energy must have one value per conformer")
    support_count = int(conformer_phi.shape[0])
    residue_count = int(conformer_phi.shape[1])
    family_count = int(conformer_phi.shape[2])
    if support_count < 1 or residue_count <= 0 or family_count <= 0:
        return _zero_loss_like(model_energy), {
            "failed_active_face_shared_q_response_rows": 0.0
        }

    rows = _failed_active_face_replay_rows_for_entity(
        replay_bundle_path,
        entity_uid=entity_uid,
    )
    if not rows:
        return _zero_loss_like(model_energy), {
            "failed_active_face_shared_q_response_rows": 0.0
        }

    energy = model_energy.reshape(-1).to(
        device=conformer_phi.device,
        dtype=conformer_phi.dtype,
    )
    finite_energy = torch.isfinite(energy)
    posterior_energy = torch.where(
        finite_energy,
        energy,
        energy.new_full(energy.shape, 1.0e6),
    )
    temp = max(float(temperature), 1.0e-6)
    prior_log: torch.Tensor | None = None
    if prior_log_probs is not None and int(prior_log_probs.numel()) == support_count:
        prior_log = prior_log_probs.to(device=energy.device, dtype=energy.dtype).reshape(-1)
        prior_log = torch.nan_to_num(prior_log, nan=0.0, posinf=0.0, neginf=0.0)
    posterior_q = posterior_weights(
        prior_log,
        posterior_energy,
        temperature=temp,
    )

    family_to_index = {
        str(family): index
        for index, family in enumerate(family_names[:family_count])
    }
    beta = max(float(huber_beta), 0.0)
    gap_weight = max(float(support_gap_weight), 0.0)
    dual_power = max(float(dual_weight_power), 0.0)
    deficit_scale = max(float(response_deficit_weight_scale), 0.0)
    min_weight = max(float(min_row_weight), 0.0)
    max_weight = max(float(max_row_weight), min_weight if min_weight > 0.0 else 1.0)

    weighted_loss = energy.new_tensor(0.0)
    weighted_response_loss = energy.new_tensor(0.0)
    weighted_gap_loss = energy.new_tensor(0.0)
    weight_sum = 0.0
    rows_used = 0
    response_norm_values: list[float] = []
    support_gap_values: list[float] = []
    posterior_mean_values: list[float] = []
    target_values: list[float] = []
    row_weight_values: list[float] = []
    family_row_counts: dict[str, int] = {}
    for row in rows:
        family_name = _failed_active_face_replay_row_family(
            row,
            family_names=family_names,
        )
        if family_name is None or family_name not in family_to_index:
            continue
        family_index = family_to_index[family_name]
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        target_value = _failed_active_face_replay_row_target(
            row,
            target_source=target_source,
        )
        if not math.isfinite(target_value):
            continue
        residue_index = _failed_active_face_replay_residue_index(
            row,
            residue_count=residue_count,
        )
        if residue_index is None:
            continue
        row_values = conformer_phi[:, residue_index, family_index]
        valid = finite_energy & torch.isfinite(row_values)
        if int(torch.count_nonzero(valid).detach().cpu()) <= 0:
            continue
        q = posterior_q * valid.to(dtype=posterior_q.dtype)
        q_sum = q.sum().clamp_min(1.0e-12)
        q = q / q_sum
        target_tensor = conformer_phi.new_tensor(float(target_value))
        scale = conformer_phi.new_tensor(
            max(float(ATOM_FAMILY_PPM_SCALES[family_index]), 1.0e-3)
        )
        posterior_mean = torch.sum(q * row_values)
        residual_norm = (posterior_mean - target_tensor) / scale
        abs_residual = torch.abs(residual_norm)
        if beta > 0.0:
            beta_tensor = energy.new_tensor(beta)
            response_loss = torch.where(
                abs_residual < beta_tensor,
                0.5 * residual_norm.square() / beta_tensor,
                abs_residual - 0.5 * beta_tensor,
            )
        else:
            response_loss = residual_norm.square()

        finite_values = row_values[valid]
        support_min = torch.amin(finite_values)
        support_max = torch.amax(finite_values)
        lower_gap = torch.relu(support_min - target_tensor) / scale
        upper_gap = torch.relu(target_tensor - support_max) / scale
        support_gap = lower_gap + upper_gap
        gap_loss = support_gap.square()

        dual = max(
            _failed_active_face_replay_float(
                row.get("dual_multiplier"),
                default=1.0,
            ),
            min_weight,
        )
        row_weight = dual**dual_power if dual_power > 0.0 else 1.0
        if deficit_scale > 0.0:
            deficit = max(
                _failed_active_face_replay_float(
                    row.get("response_deficit_abs_ppm"),
                    default=0.0,
                ),
                0.0,
            )
            row_weight *= 1.0 + deficit_scale * deficit
        row_weight = max(min(row_weight, max_weight), min_weight) * family_weight
        row_weight_tensor = energy.new_tensor(row_weight)
        row_loss = response_loss + energy.new_tensor(gap_weight) * gap_loss

        weighted_loss = weighted_loss + row_loss * row_weight_tensor
        weighted_response_loss = (
            weighted_response_loss + response_loss * row_weight_tensor
        )
        weighted_gap_loss = weighted_gap_loss + gap_loss * row_weight_tensor
        weight_sum += float(row_weight)
        rows_used += 1
        response_norm_values.append(float(abs_residual.detach().cpu()))
        support_gap_values.append(float(support_gap.detach().cpu()))
        posterior_mean_values.append(float(posterior_mean.detach().cpu()))
        target_values.append(float(target_value))
        row_weight_values.append(float(row_weight))
        family_row_counts[family_name] = family_row_counts.get(family_name, 0) + 1

    if rows_used <= 0 or weight_sum <= 0.0:
        return _zero_loss_like(model_energy), {
            "failed_active_face_shared_q_response_rows": 0.0
        }

    loss = weighted_loss / max(weight_sum, 1.0e-12)
    response_component = weighted_response_loss / max(weight_sum, 1.0e-12)
    gap_component = weighted_gap_loss / max(weight_sum, 1.0e-12)
    target_source_key = (
        str(target_source or "target_value")
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )
    metrics: dict[str, float] = {
        "failed_active_face_shared_q_response_rows": float(rows_used),
        "failed_active_face_shared_q_response_loss_value": float(loss.detach().cpu()),
        "failed_active_face_shared_q_response_response_loss_value": float(
            response_component.detach().cpu()
        ),
        "failed_active_face_shared_q_response_support_gap_loss_value": float(
            gap_component.detach().cpu()
        ),
        "failed_active_face_shared_q_response_abs_residual_norm_mean": float(
            sum(response_norm_values) / max(len(response_norm_values), 1)
        ),
        "failed_active_face_shared_q_response_support_gap_norm_mean": float(
            sum(support_gap_values) / max(len(support_gap_values), 1)
        ),
        "failed_active_face_shared_q_response_posterior_mean_mean": float(
            sum(posterior_mean_values) / max(len(posterior_mean_values), 1)
        ),
        "failed_active_face_shared_q_response_target_mean": float(
            sum(target_values) / max(len(target_values), 1)
        ),
        "failed_active_face_shared_q_response_row_weight_mean": float(
            sum(row_weight_values) / max(len(row_weight_values), 1)
        ),
        "failed_active_face_shared_q_response_support_gap_weight": float(gap_weight),
        "failed_active_face_shared_q_response_huber_beta": float(beta),
        "failed_active_face_shared_q_response_target_source_code": float(
            {
                "target_value": 0,
                "target": 0,
                "rowwise": 1,
                "rowwise_prediction": 1,
                "rowwise_oracle": 1,
                "shared_q": 2,
                "shared_q_prediction": 2,
                "shared_prediction": 2,
            }.get(target_source_key, 0)
        ),
    }
    for family_name, count in family_row_counts.items():
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"failed_active_face_shared_q_response_{safe_name}_rows"] = float(
            count
        )
    return loss * weight, metrics


def _load_phase_aware_co_support_report(
    config: StudentTrainingConfig,
) -> dict[str, Any] | None:
    path_text = str(
        getattr(config, "bioemu_x0_phase_aware_co_support_report_path", "") or ""
    ).strip()
    if not path_text:
        return _phase_aware_auto_co_support_report(config)
    path = Path(path_text)
    if not path.exists():
        raise ValueError(
            "Phase-aware co-support report is configured but missing: "
            f"{path}"
        )
    payload = _read_json(path)
    if not isinstance(payload, dict):
        raise ValueError(
            "Phase-aware co-support report must be a JSON object: "
            f"{path}"
        )
    entities: set[str] = set()
    for key in (
        "cprime_shared_q_phase_suspect_entities",
        "priority_entities",
        "cprime_rowwise_indexing_suspect_entities",
    ):
        value = payload.get(key)
        if isinstance(value, list):
            entities.update(str(item) for item in value if str(item).strip())
    global_fallback = False
    if not entities and _phase_aware_global_co_support_fallback(payload):
        # History-fallback diagnostics can identify a real HN/C'/N shared-q
        # support failure without per-entity rows.  Keep the pressure alive
        # globally instead of silently disabling the configured co-support term.
        entities.add("*")
        global_fallback = True
    return {
        "path": str(path),
        "payload": payload,
        "entities": sorted(entities),
        "global_fallback": global_fallback,
        "recommendation": str(payload.get("recommended_next_action") or ""),
    }


def _phase_aware_auto_co_support_report(
    config: StudentTrainingConfig,
) -> dict[str, Any] | None:
    if not bool(
        getattr(
            config,
            "bioemu_x0_phase_aware_co_support_auto_from_gap_enabled",
            False,
        )
    ):
        return None
    raw_gaps = dict(
        getattr(config, "bioemu_x0_phase_aware_co_support_auto_gap_by_family", {})
        or {}
    )
    if not raw_gaps:
        raw_gaps = dict(
            getattr(
                config,
                "bioemu_x0_no_oracle_response_envelope_gap_to_target",
                {},
            )
            or {}
        )
    gap_by_family: dict[str, float] = {}
    for family, raw_gap in raw_gaps.items():
        canonical = _x0_canonical_family_name(family)
        try:
            gap = float(raw_gap)
        except (TypeError, ValueError):
            continue
        if canonical and math.isfinite(gap):
            gap_by_family[canonical] = max(gap, 0.0)
    threshold = max(
        float(
            getattr(
                config,
                "bioemu_x0_phase_aware_co_support_auto_gap_threshold",
                0.05,
            )
        ),
        0.0,
    )
    pressure_families = [
        family for family in ("HN", "N", "C'") if gap_by_family.get(family, 0.0) >= threshold
    ]
    if len(pressure_families) < 2:
        return None
    payload = {
        "status": "config_auto_family_gap",
        "recommended_next_action": "auto_hn_n_cprime_cobalanced_support_from_family_gap",
        "support_pressure_families": pressure_families,
        "latest_target_gap_by_family": gap_by_family,
        "gap_threshold": float(threshold),
    }
    return {
        "path": "",
        "payload": payload,
        "entities": ["*"],
        "global_fallback": True,
        "auto_from_family_gap": True,
        "family_gaps": gap_by_family,
        "recommendation": str(payload["recommended_next_action"]),
    }


def _phase_aware_global_co_support_fallback(payload: dict[str, Any]) -> bool:
    action = str(payload.get("recommended_next_action") or "")
    if action in {
        "continue_hn_n_cprime_cobalanced_generated_support_from_best_epoch",
        "continue_hn_cprime_cobalanced_generated_support_from_best_epoch",
        "keep_hn_n_cprime_cobalanced_support_pressure",
        "keep_hn_cprime_cobalanced_support_pressure",
        "checkpoint_from_best_hn_n_cprime_focus_epoch",
        "train_edge_aware_shared_q_support_not_rowwise_shortcut",
        "train_cprime_phase_aware_shared_q_co_support",
    }:
        return True
    families = {
        str(item).upper().replace("CPRIME", "C'")
        for item in (payload.get("support_pressure_families") or [])
    }
    if not (families & {"HN", "C'", "N"}):
        return False
    gaps = payload.get("latest_target_gap_by_family")
    if not isinstance(gaps, dict):
        gaps = payload.get("recent_window_target_gap_by_family")
    if not isinstance(gaps, dict):
        return False
    for family in ("HN", "C'", "N"):
        try:
            if float(gaps.get(family, 0.0)) >= 0.05:
                return True
        except (TypeError, ValueError):
            continue
    return False


def _phase_aware_co_support_entity_matches(
    entity_uid: str,
    report: dict[str, Any] | None,
) -> bool:
    if not report:
        return False
    entities = report.get("entities")
    if not isinstance(entities, list) or not entities:
        return False
    if any(str(entity).strip() == "*" for entity in entities):
        return True
    aliases = set(_entity_uid_aliases(entity_uid))
    aliases.update(alias.lower() for alias in aliases)
    for entity in entities:
        entity_aliases = set(_entity_uid_aliases(str(entity)))
        entity_aliases.update(alias.lower() for alias in entity_aliases)
        if aliases & entity_aliases:
            return True
    return False


def _phase_aware_co_support_family_gaps(
    report: dict[str, Any] | None,
) -> dict[str, float]:
    if not isinstance(report, dict):
        return {}
    candidates: list[Any] = [report.get("family_gaps")]
    payload = report.get("payload")
    if isinstance(payload, dict):
        candidates.extend(
            [
                payload.get("latest_target_gap_by_family"),
                payload.get("recent_window_target_gap_by_family"),
            ]
        )
    for candidate in candidates:
        if not isinstance(candidate, dict):
            continue
        gaps: dict[str, float] = {}
        for family, raw_gap in candidate.items():
            canonical = _x0_canonical_family_name(family)
            try:
                gap = float(raw_gap)
            except (TypeError, ValueError):
                continue
            if canonical and math.isfinite(gap):
                gaps[canonical] = max(gap, 0.0)
        if gaps:
            return gaps
    return {}


