def _directional_support_expansion_family_gap_weights(
    config: StudentTrainingConfig,
    report: dict[str, Any] | None,
) -> tuple[dict[str, float], dict[str, float]]:
    """Gap source for support expansion, inheriting the strict goal floor gaps.

    Directional support expansion changes the generated conformer support, not
    just a posterior readout.  When no dedicated directional gap override is
    supplied, inherit the same goal-CCC floor family gap used by posterior and
    shared-oracle floor losses so HN/C'/N failures become support pressure.
    """

    explicit_raw = dict(
        getattr(
            config,
            "bioemu_x0_directional_support_expansion_auto_gap_by_family",
            {},
        )
        or {}
    )
    if explicit_raw:
        gaps = _support_rank_family_gap_weights(
            config,
            report,
            config_attr="bioemu_x0_directional_support_expansion_auto_gap_by_family",
        )
        return gaps, {
            "directional_support_expansion_explicit_gap_source": 1.0,
            "directional_support_expansion_inherits_goal_floor_gap_source": 0.0,
            "directional_support_expansion_gap_source_families": float(len(gaps)),
        }
    gaps = _x0_goal_ccc_floor_family_gap_weights(config, report)
    return gaps, {
        "directional_support_expansion_explicit_gap_source": 0.0,
        "directional_support_expansion_inherits_goal_floor_gap_source": float(
            bool(gaps)
        ),
        "directional_support_expansion_gap_source_families": float(len(gaps)),
        "directional_support_expansion_goal_floor_gap_source_max": float(
            max(gaps.values()) if gaps else 0.0
        ),
    }


def _gap_scaled_family_weights(
    base_weights: dict[str, float] | None,
    family_gap_weights: dict[str, float] | None,
    *,
    gap_weight_scale: float,
    gap_max_multiplier: float,
    metric_prefix: str,
) -> tuple[dict[str, float], dict[str, float]]:
    weights = {
        _x0_canonical_family_name(family): float(value)
        for family, value in dict(base_weights or {}).items()
    }
    gaps: dict[str, float] = {}
    for family, value in dict(family_gap_weights or {}).items():
        canonical = _x0_canonical_family_name(family)
        try:
            gap = float(value)
        except (TypeError, ValueError):
            continue
        if canonical and math.isfinite(gap) and gap > 0.0:
            gaps[canonical] = gap
    scale = max(float(gap_weight_scale), 0.0)
    max_multiplier = max(float(gap_max_multiplier), 1.0)
    metrics = {
        f"{metric_prefix}_gap_scaled_family_weights": 0.0,
        f"{metric_prefix}_gap_weight_scale": float(scale),
        f"{metric_prefix}_gap_max_multiplier": float(max_multiplier),
    }
    if not gaps or scale <= 0.0:
        return weights, metrics
    multipliers: dict[str, float] = {}
    for family, gap in gaps.items():
        if family not in CHEMICAL_SHIFT_FAMILIES:
            continue
        multiplier = min(max_multiplier, 1.0 + scale * max(float(gap), 0.0))
        base = max(float(weights.get(family, 1.0)), 0.0)
        weights[family] = base * multiplier
        multipliers[family] = float(multiplier)
    if not multipliers:
        return weights, metrics
    metrics[f"{metric_prefix}_gap_scaled_family_weights"] = 1.0
    metrics[f"{metric_prefix}_gap_multiplier_mean"] = float(
        sum(multipliers.values()) / max(len(multipliers), 1)
    )
    metrics[f"{metric_prefix}_gap_multiplier_max"] = float(max(multipliers.values()))
    for family, multiplier in multipliers.items():
        safe_family = family.replace("'", "prime").lower()
        metrics[f"{metric_prefix}_gap_multiplier_{safe_family}"] = float(multiplier)
        metrics[f"{metric_prefix}_weight_{safe_family}"] = float(weights[family])
    return weights, metrics


def _gap_scaled_family_floors(
    base_floors: dict[str, float] | None,
    family_gap_weights: dict[str, float] | None,
    *,
    gap_weight_scale: float,
    gap_max_multiplier: float,
    max_floors: dict[str, float] | None = None,
    metric_prefix: str,
) -> tuple[dict[str, float], dict[str, float]]:
    floors = {
        _x0_canonical_family_name(family): max(float(value), 0.0)
        for family, value in dict(base_floors or {}).items()
    }
    caps = {
        _x0_canonical_family_name(family): max(float(value), 0.0)
        for family, value in dict(max_floors or {}).items()
    }
    gaps: dict[str, float] = {}
    for family, value in dict(family_gap_weights or {}).items():
        canonical = _x0_canonical_family_name(family)
        try:
            gap = float(value)
        except (TypeError, ValueError):
            continue
        if canonical and math.isfinite(gap) and gap > 0.0:
            gaps[canonical] = gap
    scale = max(float(gap_weight_scale), 0.0)
    max_multiplier = max(float(gap_max_multiplier), 1.0)
    metrics = {
        f"{metric_prefix}_gap_scaled_family_floors": 0.0,
        f"{metric_prefix}_gap_weight_scale": float(scale),
        f"{metric_prefix}_gap_max_multiplier": float(max_multiplier),
    }
    if not gaps or scale <= 0.0:
        return floors, metrics
    multipliers: dict[str, float] = {}
    for family, gap in gaps.items():
        if family not in CHEMICAL_SHIFT_FAMILIES:
            continue
        base = max(float(floors.get(family, 0.0)), 0.0)
        if base <= 0.0:
            continue
        multiplier = min(max_multiplier, 1.0 + scale * max(float(gap), 0.0))
        scaled = base * multiplier
        cap = max(float(caps.get(family, 0.0)), 0.0)
        if cap > 0.0:
            scaled = min(scaled, cap)
        floors[family] = scaled
        multipliers[family] = float(multiplier)
    if not multipliers:
        return floors, metrics
    metrics[f"{metric_prefix}_gap_scaled_family_floors"] = 1.0
    metrics[f"{metric_prefix}_gap_multiplier_mean"] = float(
        sum(multipliers.values()) / max(len(multipliers), 1)
    )
    metrics[f"{metric_prefix}_gap_multiplier_max"] = float(max(multipliers.values()))
    for family, multiplier in multipliers.items():
        safe_family = family.replace("'", "prime").lower()
        metrics[f"{metric_prefix}_gap_multiplier_{safe_family}"] = float(multiplier)
        metrics[f"{metric_prefix}_floor_{safe_family}"] = float(floors[family])
    return floors, metrics


def _phase_aware_co_support_pair_weights(
    base_pair_weights: dict[str, float] | None,
    *,
    entity_uid: str,
    config: StudentTrainingConfig,
    report: dict[str, Any] | None,
    metric_prefix: str = "phase_aware_co_support",
) -> tuple[dict[str, float], dict[str, float]]:
    """Boost N/HN/C' co-support pairs only for phase-suspect entities."""

    prefix = str(metric_prefix or "phase_aware_co_support")
    weights = {str(key): float(value) for key, value in (base_pair_weights or {}).items()}
    metrics = {
        f"{prefix}_enabled": float(report is not None),
        f"{prefix}_active": 0.0,
        f"{prefix}_priority_entity_count": float(
            len(report.get("entities", [])) if isinstance(report, dict) else 0
        ),
    }
    if not _phase_aware_co_support_entity_matches(entity_uid, report):
        return weights, metrics

    multiplier = max(
        float(
            getattr(
                config,
                "bioemu_x0_phase_aware_co_support_pair_multiplier",
                1.75,
            )
        ),
        0.0,
    )
    if multiplier <= 0.0:
        metrics[f"{prefix}_active"] = 1.0
        metrics[f"{prefix}_pair_multiplier"] = 0.0
        metrics[f"{prefix}_pair_count"] = 0.0
        return weights, metrics
    configured_pairs = list(
        getattr(config, "bioemu_x0_phase_aware_co_support_pairs", []) or []
    )
    pairs = tuple(str(pair) for pair in configured_pairs if str(pair).strip())
    if not pairs:
        pairs = _PHASE_AWARE_CO_SUPPORT_DEFAULT_PAIRS

    family_gaps = _phase_aware_co_support_family_gaps(report)
    gap_scale = max(
        float(
            getattr(
                config,
                "bioemu_x0_phase_aware_co_support_auto_gap_scale",
                1.0,
            )
        ),
        0.0,
    )
    boosted = 0
    applied_gap_multipliers: list[float] = []
    for pair in pairs:
        parsed = _parse_cooccurrence_pair_key(pair)
        if parsed is None:
            continue
        source_index, target_index = parsed
        source_name = str(CHEMICAL_SHIFT_FAMILIES[source_index])
        target_name = str(CHEMICAL_SHIFT_FAMILIES[target_index])
        pair_gap = 0.5 * (
            float(family_gaps.get(source_name, 0.0))
            + float(family_gaps.get(target_name, 0.0))
        )
        gap_multiplier = 1.0 + gap_scale * max(pair_gap, 0.0)
        current = max(float(weights.get(pair, 1.0)), 0.0)
        weights[pair] = current * multiplier * gap_multiplier
        applied_gap_multipliers.append(float(gap_multiplier))
        boosted += 1

    metrics.update(
        {
            f"{prefix}_active": 1.0,
            f"{prefix}_pair_multiplier": float(multiplier),
            f"{prefix}_pair_count": float(boosted),
            f"{prefix}_gap_scaled_pair_weights": float(bool(family_gaps)),
            f"{prefix}_gap_multiplier_mean": float(
                sum(applied_gap_multipliers) / max(len(applied_gap_multipliers), 1)
            ),
            f"{prefix}_gap_multiplier_max": float(
                max(applied_gap_multipliers) if applied_gap_multipliers else 1.0
            ),
        }
    )
    return weights, metrics


def stage_b_entity_family_replay_loss(
    ensemble_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    entity_uid: str,
    entity_family_weights: dict[str, float] | None,
    replay_weight: float,
    threshold: float = 1.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Hard-entry replay loss focused on configured entity-family outliers."""

    global_weight = max(float(replay_weight), 0.0)
    if global_weight <= 0.0:
        return _zero_loss_like(ensemble_phi), {"x0_entity_family_replay_cells": 0.0}
    selected_weights = _entity_family_weights_for_x0_replay(
        entity_uid,
        entity_family_weights,
        threshold=threshold,
        family_names=family_names,
    )
    if not selected_weights:
        return _zero_loss_like(ensemble_phi), {"x0_entity_family_replay_cells": 0.0}
    replay_family_weights = {str(family): 0.0 for family in family_names}
    replay_family_weights.update(selected_weights)
    base_loss, replay_cells = stage_b_family_balanced_ensemble_loss(
        ensemble_phi,
        target_grid,
        observed_mask,
        family_weights=replay_family_weights,
        family_names=family_names,
    )
    if replay_cells <= 0:
        return _zero_loss_like(ensemble_phi), {
            "x0_entity_family_replay_cells": 0.0,
            "x0_entity_family_replay_configured_families": float(len(selected_weights)),
        }
    weight_mean = float(sum(selected_weights.values()) / max(len(selected_weights), 1))
    effective_weight = global_weight * max(weight_mean, 1.0e-12)
    metrics = {
        "x0_entity_family_replay_cells": float(replay_cells),
        "x0_entity_family_replay_configured_families": float(len(selected_weights)),
        "x0_entity_family_replay_loss_value": float(base_loss.detach().cpu()),
        "x0_entity_family_replay_global_weight": float(global_weight),
        "x0_entity_family_replay_weight_mean": float(weight_mean),
        "x0_entity_family_replay_effective_weight": float(effective_weight),
    }
    return base_loss * effective_weight, metrics


def stage_b_family_balanced_ccc_loss(
    ensemble_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    min_points: int = 3,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Differentiable family-balanced CCC loss on the ensemble observable."""

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(ensemble_phi), {"posterior_family_ccc_loss_families": 0.0}
    target = target_grid.to(device=ensemble_phi.device, dtype=ensemble_phi.dtype)
    mask = (
        observed_mask.to(device=ensemble_phi.device, dtype=torch.bool)
        & torch.isfinite(target)
        & torch.isfinite(ensemble_phi)
    )
    min_count = max(int(min_points), 2)
    losses: list[tuple[torch.Tensor, float]] = []
    ccc_values: list[float] = []
    for family_index in range(ensemble_phi.shape[-1]):
        family_mask = mask[:, family_index]
        point_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if point_count < min_count:
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        prediction = ensemble_phi[:, family_index][family_mask]
        observed = target[:, family_index][family_mask]
        pred_centered = prediction - prediction.mean()
        obs_centered = observed - observed.mean()
        pred_var = torch.mean(pred_centered.square())
        obs_var = torch.mean(obs_centered.square())
        covariance = torch.mean(pred_centered * obs_centered)
        mean_delta = (prediction.mean() - observed.mean()).square()
        ccc = (2.0 * covariance) / (
            pred_var + obs_var + mean_delta + ensemble_phi.new_tensor(1.0e-8)
        )
        losses.append((1.0 - ccc, family_weight))
        ccc_values.append(float(ccc.detach().cpu()))
    if not losses:
        return _zero_loss_like(ensemble_phi), {"posterior_family_ccc_loss_families": 0.0}
    weighted_loss = ensemble_phi.new_tensor(0.0)
    weight_sum = 0.0
    for family_loss, family_weight in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        "posterior_family_ccc_loss_families": float(len(losses)),
        "posterior_family_ccc_loss_value": float(loss.detach().cpu()),
        "posterior_family_ccc_proxy_mean": float(sum(ccc_values) / max(len(ccc_values), 1)),
        "posterior_family_ccc_proxy_min": float(min(ccc_values) if ccc_values else 0.0),
    }
    return loss * weight, metrics


def stage_b_family_ccc_floor_loss(
    ensemble_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    family_floors: dict[str, float] | None = None,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    min_points: int = 3,
    gap_power: float = 1.0,
    worst_family_mix: float = 0.0,
    macro_floor: float = 0.0,
    macro_floor_mix: float = 0.0,
    macro_floor_additive: bool = False,
    low_tail_floor: float = 0.0,
    low_tail_fraction: float = 0.4,
    low_tail_mix: float = 0.0,
    low_tail_additive: bool = True,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Hinge loss that prevents high-performing families from being traded away."""

    weight = max(float(loss_weight), 0.0)
    power = max(float(gap_power), 1.0e-6)
    worst_mix = min(max(float(worst_family_mix), 0.0), 1.0)
    macro_mix = min(max(float(macro_floor_mix), 0.0), 1.0)
    macro_floor_value = max(float(macro_floor), 0.0)
    macro_additive = bool(macro_floor_additive)
    tail_floor_value = max(float(low_tail_floor), 0.0)
    tail_mix = max(float(low_tail_mix), 0.0)
    tail_additive = bool(low_tail_additive)
    floors = dict(family_floors or {})
    if weight <= 0.0 or not floors:
        return _zero_loss_like(ensemble_phi), {"posterior_family_ccc_floor_loss_families": 0.0}
    target = target_grid.to(device=ensemble_phi.device, dtype=ensemble_phi.dtype)
    mask = observed_mask.to(device=ensemble_phi.device, dtype=torch.bool) & torch.isfinite(target)
    min_count = max(int(min_points), 2)
    penalties: list[tuple[torch.Tensor, float]] = []
    ccc_tensors: list[torch.Tensor] = []
    ccc_values: list[float] = []
    gaps: list[float] = []
    active_count = 0
    weighted_active_count = 0
    for family_index in range(ensemble_phi.shape[-1]):
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        if family_name not in floors:
            continue
        family_mask = mask[:, family_index]
        point_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if point_count < min_count:
            continue
        prediction = ensemble_phi[:, family_index][family_mask]
        observed = target[:, family_index][family_mask]
        pred_centered = prediction - prediction.mean()
        obs_centered = observed - observed.mean()
        pred_var = torch.mean(pred_centered.square())
        obs_var = torch.mean(obs_centered.square())
        covariance = torch.mean(pred_centered * obs_centered)
        mean_delta = (prediction.mean() - observed.mean()).square()
        ccc = (2.0 * covariance) / (
            pred_var + obs_var + mean_delta + ensemble_phi.new_tensor(1.0e-8)
        )
        floor_value = ensemble_phi.new_tensor(float(floors[family_name]))
        gap = torch.relu(floor_value - ccc)
        shaped_gap = torch.pow(gap.clamp_min(0.0), power)
        ccc_tensors.append(ccc)
        ccc_values.append(float(ccc.detach().cpu()))
        gap_float = float(gap.detach().cpu())
        gaps.append(gap_float)
        if gap_float > 0.0:
            active_count += 1
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        penalties.append((shaped_gap, family_weight))
        if gap_float > 0.0:
            weighted_active_count += 1
    macro_enabled = macro_floor_value > 0.0 and macro_mix > 0.0 and bool(ccc_tensors)
    tail_enabled = tail_floor_value > 0.0 and tail_mix > 0.0 and bool(ccc_tensors)
    if not penalties and not macro_enabled and not tail_enabled:
        return _zero_loss_like(ensemble_phi), {"posterior_family_ccc_floor_loss_families": 0.0}
    weighted_penalty = ensemble_phi.new_tensor(0.0)
    worst_penalty = ensemble_phi.new_tensor(0.0)
    weight_sum = 0.0
    for penalty, family_weight in penalties:
        weighted_penalty = weighted_penalty + penalty * family_weight
        worst_penalty = torch.maximum(worst_penalty, penalty)
        weight_sum += family_weight
    if penalties:
        mean_penalty = weighted_penalty / max(weight_sum, 1.0e-12)
        family_floor_loss = mean_penalty * (1.0 - worst_mix) + worst_penalty * worst_mix
    else:
        mean_penalty = ensemble_phi.new_tensor(0.0)
        family_floor_loss = ensemble_phi.new_tensor(0.0)
    macro_ccc = (
        torch.stack(ccc_tensors).mean()
        if ccc_tensors
        else ensemble_phi.new_tensor(0.0)
    )
    macro_gap = torch.relu(ensemble_phi.new_tensor(macro_floor_value) - macro_ccc)
    macro_penalty = torch.pow(macro_gap.clamp_min(0.0), power)
    tail_count = 0
    tail_ccc = ensemble_phi.new_tensor(0.0)
    tail_gap = ensemble_phi.new_tensor(0.0)
    tail_penalty = ensemble_phi.new_tensor(0.0)
    tail_fraction = 0.0
    if ccc_tensors:
        ccc_stack = torch.stack(ccc_tensors)
        family_n = int(ccc_stack.numel())
        tail_fraction = min(max(float(low_tail_fraction), 1.0 / max(family_n, 1)), 1.0)
        tail_count = max(1, min(family_n, int(math.ceil(family_n * tail_fraction))))
        tail_ccc = torch.sort(ccc_stack).values[:tail_count].mean()
        tail_gap = torch.relu(ensemble_phi.new_tensor(tail_floor_value) - tail_ccc)
        tail_penalty = torch.pow(tail_gap.clamp_min(0.0), power)
    loss = family_floor_loss
    if macro_enabled:
        if macro_additive:
            loss = family_floor_loss + macro_penalty * macro_mix
        else:
            loss = family_floor_loss * (1.0 - macro_mix) + macro_penalty * macro_mix
    if tail_enabled:
        if tail_additive:
            loss = loss + tail_penalty * tail_mix
        else:
            loss = loss * (1.0 - min(tail_mix, 1.0)) + tail_penalty * min(
                tail_mix,
                1.0,
            )
    metrics = {
        "posterior_family_ccc_floor_loss_families": float(len(ccc_tensors)),
        "posterior_family_ccc_floor_weighted_families": float(len(penalties)),
        "posterior_family_ccc_floor_loss_active": float(active_count),
        "posterior_family_ccc_floor_weighted_active": float(weighted_active_count),
        "posterior_family_ccc_floor_loss_value": float(loss.detach().cpu()),
        "posterior_family_ccc_floor_family_penalty": float(
            family_floor_loss.detach().cpu()
        ),
        "posterior_family_ccc_floor_mean_penalty": float(
            mean_penalty.detach().cpu()
        ),
        "posterior_family_ccc_floor_worst_penalty": float(
            worst_penalty.detach().cpu()
        ),
        "posterior_family_ccc_floor_gap_power": float(power),
        "posterior_family_ccc_floor_worst_family_mix": float(worst_mix),
        "posterior_family_ccc_floor_macro_ccc": float(macro_ccc.detach().cpu()),
        "posterior_family_ccc_floor_macro_floor": float(macro_floor_value),
        "posterior_family_ccc_floor_macro_floor_mix": float(macro_mix),
        "posterior_family_ccc_floor_macro_floor_additive": float(macro_additive),
        "posterior_family_ccc_floor_macro_gap": float(macro_gap.detach().cpu()),
        "posterior_family_ccc_floor_macro_penalty": float(
            macro_penalty.detach().cpu()
        ),
        "posterior_family_ccc_floor_low_tail_enabled": float(tail_enabled),
        "posterior_family_ccc_floor_low_tail_count": float(tail_count),
        "posterior_family_ccc_floor_low_tail_fraction": float(tail_fraction),
        "posterior_family_ccc_floor_low_tail_ccc": float(tail_ccc.detach().cpu()),
        "posterior_family_ccc_floor_low_tail_floor": float(tail_floor_value),
        "posterior_family_ccc_floor_low_tail_mix": float(tail_mix),
        "posterior_family_ccc_floor_low_tail_additive": float(tail_additive),
        "posterior_family_ccc_floor_low_tail_gap": float(tail_gap.detach().cpu()),
        "posterior_family_ccc_floor_low_tail_penalty": float(
            tail_penalty.detach().cpu()
        ),
        "posterior_family_ccc_floor_ccc_mean": float(
            sum(ccc_values) / max(len(ccc_values), 1)
        ),
        "posterior_family_ccc_floor_ccc_min": float(
            min(ccc_values) if ccc_values else 0.0
        ),
        "posterior_family_ccc_floor_gap_mean": float(sum(gaps) / max(len(gaps), 1)),
        "posterior_family_ccc_floor_gap_max": float(max(gaps) if gaps else 0.0),
    }
    return loss * weight, metrics


def _x0_canonical_family_name(family_name: Any) -> str:
    raw = str(family_name).strip()
    normalized = raw.lower().replace(" ", "").replace("_", "").replace("-", "")
    if normalized in {"c'", "cprime", "cprm", "carbonylc"}:
        return "C'"
    upper = raw.upper()
    if upper in {"HN", "N", "CA", "CB"}:
        return upper
    return raw


def _x0_target_ccc_family_floors(
    *,
    target_ccc: float,
    target_ccc_families: Sequence[str] | None,
) -> dict[str, float]:
    target = float(target_ccc)
    if not math.isfinite(target) or target <= 0.0:
        return {}
    families = list(target_ccc_families or CHEMICAL_SHIFT_FAMILIES)
    floors: dict[str, float] = {}
    for family in families:
        canonical = _x0_canonical_family_name(family)
        if canonical in CHEMICAL_SHIFT_FAMILIES:
            floors[canonical] = target
    return floors


def _x0_scheduled_goal_ccc_family_floors(
    config: StudentTrainingConfig,
    family_floors: Mapping[str, Any] | None,
    *,
    epoch: int,
    metric_prefix: str,
) -> tuple[dict[str, float], dict[str, float]]:
    """Ramp goal CCC floors without lowering the configured final target."""

    final_floors = {
        _x0_canonical_family_name(family): float(value)
        for family, value in dict(family_floors or {}).items()
        if _x0_canonical_family_name(family) in CHEMICAL_SHIFT_FAMILIES
    }
    final_floors = {
        family: value
        for family, value in final_floors.items()
        if math.isfinite(float(value)) and float(value) > 0.0
    }
    if not final_floors:
        return {}, {}
    enabled = bool(getattr(config, "bioemu_x0_goal_ccc_floor_schedule_contract", False))
    ramp_epochs = max(
        int(getattr(config, "bioemu_x0_goal_ccc_floor_schedule_ramp_epochs", 0) or 0),
        0,
    )
    start_epoch = int(
        getattr(config, "bioemu_x0_goal_ccc_floor_schedule_start_epoch", 0) or 0
    )
    if not enabled or ramp_epochs <= 0:
        return dict(final_floors), {
            f"{metric_prefix}_goal_ccc_floor_schedule_active": 0.0,
            f"{metric_prefix}_goal_ccc_floor_schedule_progress": 1.0,
        }
    raw_start_floors = dict(
        getattr(config, "bioemu_x0_goal_ccc_floor_schedule_start_floors", {}) or {}
    )
    start_floors = {
        _x0_canonical_family_name(family): float(value)
        for family, value in raw_start_floors.items()
        if _x0_canonical_family_name(family) in CHEMICAL_SHIFT_FAMILIES
    }
    progress = (float(epoch) - float(start_epoch)) / float(max(ramp_epochs, 1))
    progress = min(max(progress, 0.0), 1.0)
    scheduled: dict[str, float] = {}
    for family, final_floor in final_floors.items():
        start_floor = float(start_floors.get(family, final_floor))
        if not math.isfinite(start_floor):
            start_floor = final_floor
        if final_floor >= start_floor:
            scheduled_floor = start_floor + (final_floor - start_floor) * progress
            scheduled_floor = min(max(scheduled_floor, start_floor), final_floor)
        else:
            scheduled_floor = start_floor - (start_floor - final_floor) * progress
            scheduled_floor = max(min(scheduled_floor, start_floor), final_floor)
        scheduled[family] = float(scheduled_floor)
    metrics: dict[str, float] = {
        f"{metric_prefix}_goal_ccc_floor_schedule_active": 1.0,
        f"{metric_prefix}_goal_ccc_floor_schedule_start_epoch": float(start_epoch),
        f"{metric_prefix}_goal_ccc_floor_schedule_ramp_epochs": float(ramp_epochs),
        f"{metric_prefix}_goal_ccc_floor_schedule_progress": float(progress),
        f"{metric_prefix}_goal_ccc_floor_schedule_final_min": float(
            min(final_floors.values())
        ),
        f"{metric_prefix}_goal_ccc_floor_schedule_current_min": float(
            min(scheduled.values())
        ),
    }
    for family in CHEMICAL_SHIFT_FAMILIES:
        if family in scheduled:
            token = "Cprime" if family == "C'" else family
            metrics[f"{metric_prefix}_goal_ccc_floor_schedule_{token}"] = float(
                scheduled[family]
            )
    return scheduled, metrics


def _x0_goal_ccc_floor_shape_kwargs(
    config: StudentTrainingConfig,
) -> dict[str, Any]:
    """Return optional shape controls for strict goal CCC floor losses."""

    gap_power = max(
        float(getattr(config, "bioemu_x0_goal_ccc_floor_gap_power", 1.0) or 1.0),
        1.0e-6,
    )
    worst_family_mix = min(
        max(
            float(
                getattr(config, "bioemu_x0_goal_ccc_floor_worst_family_mix", 0.0)
                or 0.0
            ),
            0.0,
        ),
        1.0,
    )
    return {
        "gap_power": float(gap_power),
        "worst_family_mix": float(worst_family_mix),
        "macro_floor": float(
            max(
                float(getattr(config, "bioemu_x0_goal_ccc_macro_floor", 0.0) or 0.0),
                0.0,
            )
        ),
        "macro_floor_mix": float(
            min(
                max(
                    float(
                        getattr(config, "bioemu_x0_goal_ccc_macro_floor_mix", 0.0)
                        or 0.0
                    ),
                    0.0,
                ),
                1.0,
            )
        ),
        "macro_floor_additive": bool(
            getattr(config, "bioemu_x0_goal_ccc_macro_additive_contract", False)
        ),
        "low_tail_floor": float(
            max(
                float(getattr(config, "bioemu_x0_goal_ccc_low_tail_floor", 0.0) or 0.0),
                0.0,
            )
        ),
        "low_tail_fraction": float(
            min(
                max(
                    float(
                        getattr(config, "bioemu_x0_goal_ccc_low_tail_fraction", 0.4)
                        or 0.4
                    ),
                    0.0,
                ),
                1.0,
            )
        ),
        "low_tail_mix": float(
            max(
                float(getattr(config, "bioemu_x0_goal_ccc_low_tail_mix", 0.0) or 0.0),
                0.0,
            )
        ),
        "low_tail_additive": bool(
            getattr(config, "bioemu_x0_goal_ccc_low_tail_additive", True)
        ),
    }


def _x0_goal_ccc_floor_family_gap_weights(
    config: StudentTrainingConfig,
    report: dict[str, Any] | None,
) -> dict[str, float]:
    raw_gaps: dict[Any, Any] = dict(
        getattr(config, "bioemu_x0_goal_ccc_floor_auto_gap_by_family", {}) or {}
    )
    if not raw_gaps:
        raw_gaps = _phase_aware_co_support_family_gaps(report)
    if not raw_gaps:
        raw_gaps = dict(
            getattr(
                config,
                "bioemu_x0_no_oracle_response_envelope_gap_to_target",
                {},
            )
            or {}
        )
    gaps: dict[str, float] = {}
    for family, raw_gap in raw_gaps.items():
        canonical = _x0_canonical_family_name(family)
        try:
            gap = float(raw_gap)
        except (TypeError, ValueError):
            continue
        if canonical and math.isfinite(gap):
            gaps[canonical] = max(gap, 0.0)
    return gaps


def _x0_goal_ccc_floor_family_weights(
    config: StudentTrainingConfig,
    base_weights: dict[str, float] | None,
    report: dict[str, Any] | None,
    *,
    metric_prefix: str,
) -> tuple[dict[str, float], dict[str, float]]:
    return _gap_scaled_family_weights(
        base_weights,
        _x0_goal_ccc_floor_family_gap_weights(config, report),
        gap_weight_scale=float(
            getattr(config, "bioemu_x0_goal_ccc_floor_auto_gap_weight_scale", 0.0)
        ),
        gap_max_multiplier=float(
            getattr(config, "bioemu_x0_goal_ccc_floor_auto_gap_max_multiplier", 1.0)
        ),
        metric_prefix=metric_prefix,
    )


def multiseed_active_set_ccc_floor_loss(
    ensemble_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    seed_epoch: int,
    family_floors: dict[str, float] | None = None,
    seed_family_weights: dict[str, Any] | None = None,
    family_gap_weights: dict[str, float] | None = None,
    family_gap_weight_scale: float = 0.0,
    family_gap_max_multiplier: float = 3.0,
    loss_weight: float = 0.0,
    min_points: int = 3,
    gap_power: float = 1.0,
    worst_family_mix: float = 0.0,
    macro_floor: float = 0.0,
    macro_floor_mix: float = 0.0,
    macro_floor_additive: bool = False,
    low_tail_floor: float = 0.0,
    low_tail_fraction: float = 0.4,
    low_tail_mix: float = 0.0,
    low_tail_additive: bool = True,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Apply a seed-family active-set hinge to the current support face."""

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(ensemble_phi), {
            "multiseed_active_set_floor_loss_active": 0.0
        }
    floor_payload = {
        _x0_canonical_family_name(family): float(value)
        for family, value in dict(family_floors or {}).items()
    }
    if not floor_payload:
        return _zero_loss_like(ensemble_phi), {
            "multiseed_active_set_floor_loss_active": 0.0
        }
    seed_text = str(int(seed_epoch))
    raw_weight_payload = dict(seed_family_weights or {})
    active_payload: dict[str, float] = {}
    for key in ("*", "default", seed_text, f"epoch_{seed_text}"):
        payload = raw_weight_payload.get(key)
        if not isinstance(payload, Mapping):
            continue
        for family, family_weight in payload.items():
            canonical = _x0_canonical_family_name(family)
            try:
                parsed_weight = float(family_weight)
            except (TypeError, ValueError):
                continue
            if math.isfinite(parsed_weight) and parsed_weight > 0.0:
                active_payload[canonical] = parsed_weight
    if not active_payload:
        return _zero_loss_like(ensemble_phi), {
            "multiseed_active_set_seed_epoch": float(seed_epoch),
            "multiseed_active_set_floor_loss_active": 0.0,
            "multiseed_active_set_configured_families": 0.0,
        }
    canonical_gap_weights: dict[str, float] = {}
    for family, raw_gap in dict(family_gap_weights or {}).items():
        canonical = _x0_canonical_family_name(family)
        try:
            gap = float(raw_gap)
        except (TypeError, ValueError):
            continue
        if canonical and math.isfinite(gap) and gap > 0.0:
            canonical_gap_weights[canonical] = gap
    gap_scale = max(float(family_gap_weight_scale), 0.0)
    max_multiplier = max(float(family_gap_max_multiplier), 1.0)
    gap_multipliers: dict[str, float] = {}
    if canonical_gap_weights and gap_scale > 0.0:
        for family in list(active_payload):
            gap = canonical_gap_weights.get(family, 0.0)
            multiplier = min(max_multiplier, 1.0 + gap_scale * max(gap, 0.0))
            active_payload[family] = active_payload[family] * multiplier
            gap_multipliers[family] = float(multiplier)
    active_floors = {
        family: floor_payload[family]
        for family in active_payload
        if family in floor_payload
    }
    active_weights = {
        family: active_payload[family]
        for family in active_floors
    }
    if not active_floors:
        return _zero_loss_like(ensemble_phi), {
            "multiseed_active_set_seed_epoch": float(seed_epoch),
            "multiseed_active_set_floor_loss_active": 0.0,
            "multiseed_active_set_configured_families": 0.0,
        }
    floor_loss, floor_metrics = stage_b_family_ccc_floor_loss(
        ensemble_phi,
        target_grid,
        observed_mask,
        family_floors=active_floors,
        family_weights=active_weights,
        loss_weight=weight,
        min_points=min_points,
        gap_power=gap_power,
        worst_family_mix=worst_family_mix,
        macro_floor=macro_floor,
        macro_floor_mix=macro_floor_mix,
        macro_floor_additive=macro_floor_additive,
        low_tail_floor=low_tail_floor,
        low_tail_fraction=low_tail_fraction,
        low_tail_mix=low_tail_mix,
        low_tail_additive=low_tail_additive,
    )
    metrics = {
        "multiseed_active_set_seed_epoch": float(seed_epoch),
        "multiseed_active_set_configured_families": float(len(active_floors)),
        "multiseed_active_set_floor_loss_weight": float(weight),
        "multiseed_active_set_gap_scaled_weights": float(bool(gap_multipliers)),
        "multiseed_active_set_gap_weight_scale": float(gap_scale),
        "multiseed_active_set_gap_max_multiplier": float(max_multiplier),
    }
    if gap_multipliers:
        metrics["multiseed_active_set_gap_multiplier_mean"] = float(
            sum(gap_multipliers.values()) / max(len(gap_multipliers), 1)
        )
        metrics["multiseed_active_set_gap_multiplier_max"] = float(
            max(gap_multipliers.values())
        )
    for family, family_weight in active_weights.items():
        safe_family = family.replace("'", "prime").lower()
        metrics[f"multiseed_active_set_weight_{safe_family}"] = float(family_weight)
        if family in gap_multipliers:
            metrics[f"multiseed_active_set_gap_multiplier_{safe_family}"] = float(
                gap_multipliers[family]
            )
    metrics.update(
        {
            f"multiseed_active_set_{key}": value
            for key, value in floor_metrics.items()
        }
    )
    return floor_loss, metrics


def decoder_phi_trust_region_loss(
    conformer_phi: torch.Tensor,
    reference_phi: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    huber_beta: float = 0.05,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Keep the conformer observable close to the loaded checkpoint support.

    This is a train-only safety rail for structural experiments: it regularizes
    ``phi_theta(X_k)`` itself, not the observed CS target, so inference remains
    a UCBShift-through-conformer ensemble measure.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"decoder_phi_trust_region_families": 0.0}
    if conformer_phi.shape != reference_phi.shape:
        raise ValueError("conformer_phi and reference_phi must have matching shape")
    family_count = min(int(conformer_phi.shape[-1]), len(ATOM_FAMILY_PPM_SCALES))
    scales = conformer_phi.new_tensor(ATOM_FAMILY_PPM_SCALES[:family_count]).clamp_min(
        1.0e-3
    )
    beta = max(float(huber_beta), 1.0e-8)
    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    family_count_used = 0
    abs_ppm_values: list[float] = []
    max_abs_ppm = 0.0
    for family_index in range(family_count):
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        delta_ppm = (
            conformer_phi[..., family_index]
            - reference_phi[..., family_index].to(
                device=conformer_phi.device,
                dtype=conformer_phi.dtype,
            )
        )
        scaled_delta = delta_ppm / scales[family_index]
        abs_delta = scaled_delta.abs()
        beta_tensor = scaled_delta.new_tensor(beta)
        family_loss = torch.where(
            abs_delta <= beta_tensor,
            0.5 * scaled_delta.square() / beta_tensor,
            abs_delta - 0.5 * beta_tensor,
        ).mean()
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
        family_count_used += 1
        abs_ppm = delta_ppm.detach().abs()
        abs_ppm_values.append(float(abs_ppm.mean().cpu()))
        max_abs_ppm = max(max_abs_ppm, float(abs_ppm.max().cpu()))
    if family_count_used <= 0:
        return _zero_loss_like(conformer_phi), {"decoder_phi_trust_region_families": 0.0}
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        "decoder_phi_trust_region_families": float(family_count_used),
        "decoder_phi_trust_region_loss_value": float(loss.detach().cpu()),
        "decoder_phi_trust_region_abs_ppm_mean": float(
            sum(abs_ppm_values) / max(len(abs_ppm_values), 1)
        ),
        "decoder_phi_trust_region_abs_ppm_max": float(max_abs_ppm),
    }
    return loss * weight, metrics


def support_basis_delta_ceiling_loss(
    outputs: Mapping[str, Any],
    *,
    loss_weight: float = 0.0,
    ceiling_ppm: float = 0.0,
    huber_beta: float = 0.05,
    path_weights: Mapping[str, float] | None = None,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Penalize destructive support-basis moves while allowing small adaptation."""

    weight = max(float(loss_weight), 0.0)
    ceiling = max(float(ceiling_ppm), 0.0)
    first_tensor = next(
        (value for value in outputs.values() if isinstance(value, torch.Tensor)),
        None,
    )
    if first_tensor is None:
        return torch.tensor(0.0), {"support_basis_delta_ceiling_active_paths": 0.0}
    zero = _zero_loss_like(first_tensor)
    if weight <= 0.0 or ceiling <= 0.0:
        return zero, {"support_basis_delta_ceiling_active_paths": 0.0}

    path_to_key = {
        "mechanism": "mechanism_support_basis_delta_phi",
        "hn_signed": "hn_signed_support_basis_delta_phi",
        "hn_direct": "hn_direct_support_spread_delta_phi",
        "family_direct": "family_direct_support_spread_delta_phi",
        "cprime_isolated": "cprime_isolated_support_basis_delta_phi",
        "combined": "support_basis_delta_phi",
    }
    configured_path_weights = {
        str(key): max(float(value), 0.0)
        for key, value in dict(path_weights or {}).items()
    }
    beta = max(float(huber_beta), 1.0e-8)
    total = zero
    active_weight_sum = 0.0
    active_paths = 0
    max_abs_ppm = 0.0
    mean_abs_values: list[float] = []
    metrics: dict[str, float] = {
        "support_basis_delta_ceiling_ppm": float(ceiling),
        "support_basis_delta_ceiling_loss_weight": float(weight),
    }
    for path_name, output_key in path_to_key.items():
        path_weight = configured_path_weights.get(path_name, 1.0)
        if path_weight <= 0.0:
            continue
        delta = outputs.get(output_key)
        if not isinstance(delta, torch.Tensor) or delta.numel() <= 0:
            continue
        finite_delta = torch.where(torch.isfinite(delta), delta, torch.zeros_like(delta))
        abs_delta = finite_delta.abs()
        violation = torch.relu(abs_delta - ceiling)
        beta_tensor = violation.new_tensor(beta)
        path_loss = torch.where(
            violation <= beta_tensor,
            0.5 * violation.square() / beta_tensor,
            violation - 0.5 * beta_tensor,
        ).mean()
        total = total + path_loss * path_weight
        active_weight_sum += path_weight
        active_paths += 1
        detached_abs = abs_delta.detach()
        detached_violation = violation.detach()
        path_metric = path_name.replace("'", "prime").lower()
        metrics[f"support_basis_delta_ceiling_{path_metric}_weight"] = float(
            path_weight
        )
        metrics[f"support_basis_delta_ceiling_{path_metric}_abs_ppm_mean"] = float(
            detached_abs.mean().cpu()
        )
        metrics[f"support_basis_delta_ceiling_{path_metric}_abs_ppm_max"] = float(
            detached_abs.max().cpu()
        )
        metrics[
            f"support_basis_delta_ceiling_{path_metric}_violation_ppm_mean"
        ] = float(detached_violation.mean().cpu())
        max_abs_ppm = max(max_abs_ppm, float(detached_abs.max().cpu()))
        mean_abs_values.append(float(detached_abs.mean().cpu()))
    if active_paths <= 0:
        return zero, {"support_basis_delta_ceiling_active_paths": 0.0}

    unweighted_loss = total / max(active_weight_sum, 1.0e-12)
    metrics["support_basis_delta_ceiling_active_paths"] = float(active_paths)
    metrics["support_basis_delta_ceiling_loss_value"] = float(
        unweighted_loss.detach().cpu()
    )
    metrics["support_basis_delta_ceiling_abs_ppm_mean"] = float(
        sum(mean_abs_values) / max(len(mean_abs_values), 1)
    )
    metrics["support_basis_delta_ceiling_abs_ppm_max"] = float(max_abs_ppm)
    return unweighted_loss * weight, metrics


def x0_support_sample_seed(
    config: StudentTrainingConfig,
    *,
    epoch: int,
    example_index: int,
    training: bool,
) -> int:
    """Return the BioEmu support seed for staged x0 training/evaluation."""

    seed_epoch = x0_support_seed_epoch(
        config,
        epoch=epoch,
        example_index=example_index,
        training=training,
    )
    seed = int(config.seed) + seed_epoch * 1009 + int(example_index) * 9173
    if training:
        seed += int(getattr(config, "bioemu_x0_train_support_seed_offset", 0))
    return int(seed)


def x0_support_seed_epoch(
    config: StudentTrainingConfig,
    *,
    epoch: int,
    example_index: int,
    training: bool,
) -> int:
    """Return the support-face epoch used by deterministic x0 sampling."""

    if training and bool(getattr(config, "bioemu_x0_freeze_train_support_seed", False)):
        return int(getattr(config, "bioemu_x0_train_support_seed_epoch", epoch))
    if (not training) and bool(
        getattr(config, "bioemu_x0_freeze_eval_support_seed", False)
    ):
        return int(getattr(config, "bioemu_x0_eval_support_seed_epoch", epoch))
    if training:
        raw_seed_epochs = getattr(config, "bioemu_x0_train_support_seed_epochs", [])
        seed_epochs = [
            int(seed_epoch)
            for seed_epoch in raw_seed_epochs
            if int(seed_epoch) >= 0
        ]
        if seed_epochs:
            index = (int(epoch) + int(example_index)) % len(seed_epochs)
            return int(seed_epochs[index])
    return x0_effective_split_epoch(config, epoch=epoch, training=training)


def x0_effective_split_epoch(
    config: StudentTrainingConfig,
    *,
    epoch: int,
    training: bool,
) -> int:
    """Epoch used for deterministic support sampling and eval row splits."""

    if training and bool(getattr(config, "bioemu_x0_freeze_train_support_seed", False)):
        return int(getattr(config, "bioemu_x0_train_support_seed_epoch", epoch))
    if (not training) and bool(getattr(config, "bioemu_x0_freeze_eval_support_seed", False)):
        return int(getattr(config, "bioemu_x0_eval_support_seed_epoch", epoch))
    return int(epoch)


def supervised_support_envelope_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train conformer observables to contain supervised rows inside support.

    This is a decoder-side support loss, not a direct readout: it changes
    ``phi_theta(X_k)`` over the finite x0 support so a single posterior measure
    has a wider reachable set.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"support_envelope_cells": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(conformer_phi), {"support_envelope_cells": 0.0}

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1).clamp_min(1.0e-3)
    values = conformer_phi / scales
    target_norm = target / scales.reshape(1, -1)
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(-values / smooth_tensor, dim=0)
        support_max = smooth_tensor * torch.logsumexp(values / smooth_tensor, dim=0)
    else:
        support_min = torch.amin(values, dim=0)
        support_max = torch.amax(values, dim=0)

    losses: list[tuple[torch.Tensor, float, int]] = []
    active_counts: list[int] = []
    gap_values: list[float] = []
    for family_index in range(conformer_phi.shape[-1]):
        family_mask = mask[:, family_index]
        point_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if point_count <= 0:
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        low_gap = torch.relu(support_min[:, family_index][family_mask] - target_norm[:, family_index][family_mask])
        high_gap = torch.relu(target_norm[:, family_index][family_mask] - support_max[:, family_index][family_mask])
        gap = low_gap + high_gap
        losses.append((torch.mean(gap.square()), family_weight, point_count))
        active_counts.append(int(torch.count_nonzero(gap > 0.0).detach().cpu()))
        gap_values.append(float(torch.mean(gap.detach()).cpu()))
    if not losses:
        return _zero_loss_like(conformer_phi), {"support_envelope_cells": 0.0}

    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    cell_count = 0
    for family_loss, family_weight, point_count in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
        cell_count += point_count
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    active_total = sum(active_counts)
    metrics = {
        "support_envelope_cells": float(cell_count),
        "support_envelope_families": float(len(losses)),
        "support_envelope_loss_value": float(loss.detach().cpu()),
        "support_envelope_active_fraction": float(active_total / max(cell_count, 1)),
        "support_envelope_gap_norm_mean": float(sum(gap_values) / max(len(gap_values), 1)),
    }
    return loss * weight, metrics


def supervised_support_center_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
    gap_focus_scale: float = 0.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Move support centers toward supervised targets without choosing q.

    Envelope losses can widen a family support interval while leaving its
    center misplaced. C' failures often have exactly that shape, so this loss
    adds signed placement pressure on ``phi_theta(X_k)`` while still preserving
    one shared posterior measure at inference time.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"support_center_cells": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(conformer_phi), {"support_center_cells": 0.0}

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1).clamp_min(1.0e-3)
    values = conformer_phi / scales
    target_norm = target / scales.reshape(1, -1)
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(-values / smooth_tensor, dim=0)
        support_max = smooth_tensor * torch.logsumexp(values / smooth_tensor, dim=0)
    else:
        support_min = torch.amin(values, dim=0)
        support_max = torch.amax(values, dim=0)
    support_center = 0.5 * (support_min + support_max)
    gap_focus = max(float(gap_focus_scale), 0.0)

    losses: list[tuple[torch.Tensor, float, int]] = []
    offset_values: list[float] = []
    active_counts: list[int] = []
    metrics: dict[str, float] = {}
    for family_index in range(conformer_phi.shape[-1]):
        family_mask = mask[:, family_index]
        point_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if point_count <= 0:
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        selected_center = support_center[:, family_index][family_mask]
        selected_target = target_norm[:, family_index][family_mask]
        offset = selected_center - selected_target
        low_gap = torch.relu(support_min[:, family_index][family_mask] - selected_target)
        high_gap = torch.relu(selected_target - support_max[:, family_index][family_mask])
        outside_gap = low_gap + high_gap
        cell_loss = offset.square()
        if gap_focus > 0.0:
            cell_loss = cell_loss * (1.0 + gap_focus * outside_gap.detach())
        losses.append((torch.mean(cell_loss), family_weight, point_count))
        offset_abs = torch.abs(offset.detach())
        outside_active = int(torch.count_nonzero(outside_gap > 0.0).detach().cpu())
        offset_mean = float(torch.mean(offset_abs).cpu())
        offset_values.append(offset_mean)
        active_counts.append(outside_active)
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"support_center_{safe_name}_offset_norm_mean"] = offset_mean
        metrics[f"support_center_{safe_name}_outside_fraction"] = float(
            outside_active / max(point_count, 1)
        )
    if not losses:
        return _zero_loss_like(conformer_phi), {"support_center_cells": 0.0}

    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    cell_count = 0
    for family_loss, family_weight, point_count in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
        cell_count += point_count
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics.update(
        {
            "support_center_cells": float(cell_count),
            "support_center_families": float(len(losses)),
            "support_center_loss_value": float(loss.detach().cpu()),
            "support_center_active_fraction": float(
                sum(active_counts) / max(cell_count, 1)
            ),
            "support_center_offset_norm_mean": float(
                sum(offset_values) / max(len(offset_values), 1)
            ),
        }
    )
    return loss * weight, metrics


def raw_sample_support_width_floor_loss(
    conformer_phi: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    min_width_by_family: dict[str, float] | None = None,
    max_width_by_family: dict[str, float] | None = None,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    min_rows: int = 1,
    gap_scale: float = 0.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Keep generated conformer support from collapsing around observed rows.

    The floor is measured in ppm over the finite conformer-level support for
    each observed residue/family cell.  It does not choose a posterior q; it
    only makes the support broad enough that a shared q has something to select.
    """

    weight = max(float(loss_weight), 0.0)
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if observed_mask.ndim != 2 or observed_mask.shape != conformer_phi.shape[1:]:
        raise ValueError("observed_mask must match conformer_phi [L,F]")
    floors = {
        _x0_canonical_family_name(family): max(float(value), 0.0)
        for family, value in dict(min_width_by_family or {}).items()
    }
    if not any(value > 0.0 for value in floors.values()):
        return _zero_loss_like(conformer_phi), {
            "raw_sample_support_width_floor_cells": 0.0
        }
    caps = {
        _x0_canonical_family_name(family): max(float(value), 0.0)
        for family, value in dict(max_width_by_family or {}).items()
    }
    weights = {
        _x0_canonical_family_name(family): max(float(value), 0.0)
        for family, value in dict(family_weights or {}).items()
    }
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool)
    finite = torch.isfinite(conformer_phi)
    finite_rows = torch.count_nonzero(finite, dim=0)
    usable = mask & (finite_rows >= 2)
    if not bool(torch.any(usable)):
        return _zero_loss_like(conformer_phi), {
            "raw_sample_support_width_floor_cells": 0.0
        }

    family_count = min(int(conformer_phi.shape[-1]), len(family_names))
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[:family_count],
    ).clamp_min(1.0e-3)
    safe_values_for_min = torch.where(
        finite,
        conformer_phi,
        torch.full_like(conformer_phi, torch.inf),
    )
    safe_values_for_max = torch.where(
        finite,
        conformer_phi,
        torch.full_like(conformer_phi, -torch.inf),
    )
    support_min = torch.amin(safe_values_for_min, dim=0)
    support_max = torch.amax(safe_values_for_max, dim=0)
    support_width = (support_max - support_min).clamp_min(0.0)

    total = conformer_phi.new_tensor(0.0)
    total_weight = 0.0
    cell_count = 0
    active_count = 0
    active_families = 0
    width_means: list[float] = []
    gap_means: list[float] = []
    metrics: dict[str, float] = {}
    focus_scale = max(float(gap_scale), 0.0)
    for family_index in range(family_count):
        family_name = str(family_names[family_index])
        floor = max(float(floors.get(_x0_canonical_family_name(family_name), 0.0)), 0.0)
        if floor <= 0.0:
            continue
        cap = max(float(caps.get(_x0_canonical_family_name(family_name), 0.0)), 0.0)
        if cap > 0.0:
            floor = min(floor, cap)
        row_mask = usable[:, family_index]
        rows = int(torch.count_nonzero(row_mask).detach().cpu())
        if rows < max(int(min_rows), 1):
            continue
        family_weight = max(float(weights.get(_x0_canonical_family_name(family_name), 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        width = support_width[:, family_index][row_mask]
        gap_ppm = torch.relu(width.new_tensor(floor) - width)
        gap_norm = gap_ppm / scales[family_index]
        cell_loss = gap_norm.square()
        if focus_scale > 0.0:
            cell_loss = cell_loss * (1.0 + focus_scale * gap_norm.detach())
        family_loss = torch.mean(cell_loss)
        total = total + family_loss * family_weight
        total_weight += family_weight
        cell_count += rows
        family_active = int(torch.count_nonzero(gap_ppm > 0.0).detach().cpu())
        active_count += family_active
        active_families += int(family_active > 0)
        width_mean = float(torch.mean(width.detach()).cpu())
        gap_mean = float(torch.mean(gap_ppm.detach()).cpu())
        width_means.append(width_mean)
        gap_means.append(gap_mean)
        safe_family = family_name.replace("'", "prime").lower()
        metrics[f"raw_sample_support_width_floor_{safe_family}_rows"] = float(rows)
        metrics[f"raw_sample_support_width_floor_{safe_family}_floor_ppm"] = float(floor)
        metrics[f"raw_sample_support_width_floor_{safe_family}_width_mean_ppm"] = (
            width_mean
        )
        metrics[f"raw_sample_support_width_floor_{safe_family}_gap_mean_ppm"] = (
            gap_mean
        )
        metrics[f"raw_sample_support_width_floor_{safe_family}_active_fraction"] = float(
            family_active / max(rows, 1)
        )
    if total_weight <= 0.0 or cell_count <= 0:
        return _zero_loss_like(conformer_phi), {
            "raw_sample_support_width_floor_cells": 0.0
        }
    loss = total / max(total_weight, 1.0e-12)
    metrics.update(
        {
            "raw_sample_support_width_floor_cells": float(cell_count),
            "raw_sample_support_width_floor_families": float(active_families),
            "raw_sample_support_width_floor_loss_value": float(loss.detach().cpu()),
            "raw_sample_support_width_floor_active_fraction": float(
                active_count / max(cell_count, 1)
            ),
            "raw_sample_support_width_floor_width_mean_ppm": float(
                sum(width_means) / max(len(width_means), 1)
            ),
            "raw_sample_support_width_floor_gap_mean_ppm": float(
                sum(gap_means) / max(len(gap_means), 1)
            ),
        }
    )
    return loss * weight, metrics


def mechanism_support_envelope_loss(
    conformer_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
    risk_scale: float = 1.0,
    min_context_weight: float = 1.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Mechanism-aware decoder support loss for supervised target rows.

    This remains a support-side training objective: it only changes
    ``phi_theta(X_k)`` over the finite x0 conformer support.  Row-level
    HN/C' mechanism proxies decide how strongly a supervised row asks the
    support envelope to include the BMRB value, but no direct CS readout or
    rowwise inference-time posterior weight is created.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"mechanism_support_envelope_rows": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    families = family_indices.to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values.to(device=device, dtype=dtype)
    selected = row_mask.to(device=device, dtype=torch.bool) & torch.isfinite(values)
    usable_count = min(
        int(target_features.shape[0]),
        int(families.numel()),
        int(values.numel()),
        int(selected.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(conformer_phi), {"mechanism_support_envelope_rows": 0.0}
    target_features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = families[:usable_count]
    values = values[:usable_count]
    selected = selected[:usable_count]
    if not bool(torch.any(selected)):
        return _zero_loss_like(conformer_phi), {"mechanism_support_envelope_rows": 0.0}

    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi,
        target_features,
        families,
    )
    row_phi = row_phi[:, selected]
    row_targets = values[selected]
    row_families = families[selected]
    if row_phi.numel() == 0:
        return _zero_loss_like(conformer_phi), {"mechanism_support_envelope_rows": 0.0}

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    row_scales = scales[row_families].reshape(1, -1)
    normalized_phi = row_phi / row_scales
    normalized_targets = row_targets / scales[row_families]
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(-normalized_phi / smooth_tensor, dim=0)
        support_max = smooth_tensor * torch.logsumexp(normalized_phi / smooth_tensor, dim=0)
    else:
        support_min = torch.amin(normalized_phi, dim=0)
        support_max = torch.amax(normalized_phi, dim=0)
    low_gap = torch.relu(support_min - normalized_targets)
    high_gap = torch.relu(normalized_targets - support_max)
    gap = low_gap + high_gap

    row_family_weights = torch.ones_like(gap)
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        row_family_weights = torch.where(
            row_families == int(family_index),
            row_family_weights.new_full(row_family_weights.shape, family_weight),
            row_family_weights,
        )

    risks = _mechanism_support_row_risk(
        target_features[selected],
        row_families,
        family_names=family_names,
    )
    context_weights = max(float(min_context_weight), 0.0) + max(float(risk_scale), 0.0) * risks
    row_weights = row_family_weights * context_weights
    valid = row_weights > 0.0
    if not bool(torch.any(valid)):
        return _zero_loss_like(conformer_phi), {"mechanism_support_envelope_rows": 0.0}
    weighted_loss = torch.sum(gap[valid].square() * row_weights[valid]) / row_weights[
        valid
    ].sum().clamp_min(1.0e-12)
    active = gap[valid] > 0.0
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    n_index = family_names.index("N") if "N" in family_names else -1
    metrics = {
        "mechanism_support_envelope_rows": float(torch.count_nonzero(valid).detach().cpu()),
        "mechanism_support_envelope_families": float(
            torch.unique(row_families[valid]).numel()
        ),
        "mechanism_support_envelope_loss_value": float(weighted_loss.detach().cpu()),
        "mechanism_support_envelope_active_fraction": float(
            torch.count_nonzero(active).detach().cpu()
            / torch.count_nonzero(valid).detach().cpu().clamp_min(1)
        ),
        "mechanism_support_envelope_gap_norm_mean": float(gap[valid].mean().detach().cpu()),
        "mechanism_support_envelope_risk_mean": float(risks[valid].mean().detach().cpu()),
        "mechanism_support_envelope_weight_mean": float(row_weights[valid].mean().detach().cpu()),
        "mechanism_support_envelope_hn_rows": float(
            torch.count_nonzero(row_families[valid] == hn_index).detach().cpu()
            if hn_index >= 0
            else 0.0
        ),
        "mechanism_support_envelope_cprime_rows": float(
            torch.count_nonzero(row_families[valid] == cprime_index).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        "mechanism_support_envelope_n_rows": float(
            torch.count_nonzero(row_families[valid] == n_index).detach().cpu()
            if n_index >= 0
            else 0.0
        ),
    }
    return weighted_loss * weight, metrics


def conditional_family_support_envelope_loss(
    conformer_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
    risk_scale: float = 1.0,
    min_context_weight: float = 1.0,
    gap_margin: float = 0.0,
    gap_focus_scale: float = 0.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Row-conditional support envelope pressure for selected families.

    This is a narrower version of the support-envelope objective: it only acts
    on configured target rows whose current conformer-level support fails to
    cover the observed CS value.  It is useful when one family, e.g. C', needs
    support expansion without diluting HN rowwise oracle pressure.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"conditional_support_envelope_rows": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    usable_count = min(
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(target_values.numel()),
        int(row_mask.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(conformer_phi), {"conditional_support_envelope_rows": 0.0}
    features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = family_indices[:usable_count].to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values[:usable_count].to(device=device, dtype=dtype)
    selected = (
        row_mask[:usable_count].to(device=device, dtype=torch.bool)
        & torch.isfinite(values)
    )
    if not bool(torch.any(selected)):
        return _zero_loss_like(conformer_phi), {"conditional_support_envelope_rows": 0.0}

    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi,
        features,
        families,
    )[:, selected]
    row_targets = values[selected]
    row_families = families[selected]
    selected_features = features[selected]
    if row_phi.numel() == 0:
        return _zero_loss_like(conformer_phi), {"conditional_support_envelope_rows": 0.0}

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    row_scales = scales[row_families].reshape(1, -1)
    normalized_phi = row_phi / row_scales
    normalized_targets = row_targets / scales[row_families]
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(
            -normalized_phi / smooth_tensor,
            dim=0,
        )
        support_max = smooth_tensor * torch.logsumexp(
            normalized_phi / smooth_tensor,
            dim=0,
        )
    else:
        support_min = torch.amin(normalized_phi, dim=0)
        support_max = torch.amax(normalized_phi, dim=0)
    margin_tensor = conformer_phi.new_tensor(max(float(gap_margin), 0.0))
    low_gap = torch.relu(support_min - (normalized_targets - margin_tensor))
    high_gap = torch.relu((normalized_targets + margin_tensor) - support_max)
    raw_gap = low_gap + high_gap
    gap = raw_gap

    row_family_weights = torch.zeros_like(gap)
    configured_family_weights = family_weights or {}
    active_family_names: list[str] = []
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(float(configured_family_weights.get(family_name, 0.0)), 0.0)
        row_family_weights = torch.where(
            row_families == int(family_index),
            row_family_weights.new_full(row_family_weights.shape, family_weight),
            row_family_weights,
        )
        if family_weight > 0.0:
            active_family_names.append(family_name)

    risks = _mechanism_support_row_risk(
        selected_features,
        row_families,
        family_names=family_names,
    )
    context_weights = max(float(min_context_weight), 0.0) + max(float(risk_scale), 0.0) * risks
    gap_focus = 1.0 + max(float(gap_focus_scale), 0.0) * gap.detach()
    row_weights = row_family_weights * context_weights * gap_focus
    valid = (row_weights > 0.0) & (gap > 0.0)
    if not bool(torch.any(valid)):
        return _zero_loss_like(conformer_phi), {
            "conditional_support_envelope_rows": 0.0,
            "conditional_support_envelope_families": 0.0,
            "conditional_support_envelope_loss_value": 0.0,
        }
    weighted_loss = torch.sum(gap[valid].square() * row_weights[valid]) / row_weights[
        valid
    ].sum().clamp_min(1.0e-12)
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    n_index = family_names.index("N") if "N" in family_names else -1
    metrics = {
        "conditional_support_envelope_rows": float(torch.count_nonzero(valid).detach().cpu()),
        "conditional_support_envelope_families": float(
            len(
                {
                    str(
                        family_names[int(family_index)]
                        if int(family_index) < len(family_names)
                        else int(family_index)
                    )
                    for family_index in torch.unique(row_families[valid]).detach().cpu().tolist()
                }
                & set(active_family_names)
            )
        ),
        "conditional_support_envelope_loss_value": float(weighted_loss.detach().cpu()),
        "conditional_support_envelope_active_fraction": float(
            torch.count_nonzero(valid).detach().cpu()
            / max(int(torch.count_nonzero(row_family_weights > 0.0).detach().cpu()), 1)
        ),
        "conditional_support_envelope_gap_norm_mean": float(raw_gap[valid].mean().detach().cpu()),
        "conditional_support_envelope_risk_mean": float(risks[valid].mean().detach().cpu()),
        "conditional_support_envelope_weight_mean": float(row_weights[valid].mean().detach().cpu()),
        "conditional_support_envelope_hn_rows": float(
            torch.count_nonzero(row_families[valid] == hn_index).detach().cpu()
            if hn_index >= 0
            else 0.0
        ),
        "conditional_support_envelope_cprime_rows": float(
            torch.count_nonzero(row_families[valid] == cprime_index).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        "conditional_support_envelope_n_rows": float(
            torch.count_nonzero(row_families[valid] == n_index).detach().cpu()
            if n_index >= 0
            else 0.0
        ),
    }
    return weighted_loss * weight, metrics


def directional_mechanism_support_expansion_loss(
    conformer_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    loss_weight: float = 0.0,
    softness: float = 0.05,
    risk_scale: float = 1.0,
    min_context_weight: float = 1.0,
    margin: float = 0.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train-only directional support pressure for mechanism-risk rows.

    Unlike a direct row readout, this loss only changes the conformer-level
    observable support ``phi_theta(X_k)``.  Rows above the support center push
    the high endpoint toward the supervised value; rows below the center push
    the low endpoint.  The posterior weights still decide the final ensemble
    mean during inference.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"directional_support_expansion_rows": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    families = family_indices.to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values.to(device=device, dtype=dtype)
    selected = row_mask.to(device=device, dtype=torch.bool) & torch.isfinite(values)
    usable_count = min(
        int(target_features.shape[0]),
        int(families.numel()),
        int(values.numel()),
        int(selected.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(conformer_phi), {"directional_support_expansion_rows": 0.0}
    target_features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = families[:usable_count]
    values = values[:usable_count]
    selected = selected[:usable_count]
    if not bool(torch.any(selected)):
        return _zero_loss_like(conformer_phi), {"directional_support_expansion_rows": 0.0}

    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi,
        target_features,
        families,
    )
    row_phi = row_phi[:, selected]
    row_targets = values[selected]
    row_families = families[selected]
    if row_phi.numel() == 0:
        return _zero_loss_like(conformer_phi), {"directional_support_expansion_rows": 0.0}

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    row_scales = scales[row_families].reshape(1, -1)
    normalized_phi = row_phi / row_scales
    normalized_targets = row_targets / scales[row_families]
    smooth = max(float(softness), 0.0)
    if smooth > 0.0:
        smooth_tensor = conformer_phi.new_tensor(smooth)
        support_min = -smooth_tensor * torch.logsumexp(
            -normalized_phi / smooth_tensor,
            dim=0,
        )
        support_max = smooth_tensor * torch.logsumexp(
            normalized_phi / smooth_tensor,
            dim=0,
        )
    else:
        support_min = torch.amin(normalized_phi, dim=0)
        support_max = torch.amax(normalized_phi, dim=0)

    support_center = 0.5 * (support_min.detach() + support_max.detach())
    margin_tensor = conformer_phi.new_tensor(max(float(margin), 0.0))
    high_side = normalized_targets >= support_center
    high_gap = torch.relu(normalized_targets + margin_tensor - support_max)
    low_gap = torch.relu(support_min - (normalized_targets - margin_tensor))
    gap = torch.where(high_side, high_gap, low_gap)

    row_family_weights = torch.ones_like(gap)
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        row_family_weights = torch.where(
            row_families == int(family_index),
            row_family_weights.new_full(row_family_weights.shape, family_weight),
            row_family_weights,
        )

    risks = _mechanism_support_row_risk(
        target_features[selected],
        row_families,
        family_names=family_names,
    )
    context_weights = max(float(min_context_weight), 0.0) + max(float(risk_scale), 0.0) * risks
    row_weights = row_family_weights * context_weights
    valid = row_weights > 0.0
    if not bool(torch.any(valid)):
        return _zero_loss_like(conformer_phi), {"directional_support_expansion_rows": 0.0}
    weighted_loss = torch.sum(gap[valid].square() * row_weights[valid]) / row_weights[
        valid
    ].sum().clamp_min(1.0e-12)
    active = gap[valid] > 0.0
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    n_index = family_names.index("N") if "N" in family_names else -1
    metrics = {
        "directional_support_expansion_rows": float(torch.count_nonzero(valid).detach().cpu()),
        "directional_support_expansion_families": float(
            torch.unique(row_families[valid]).numel()
        ),
        "directional_support_expansion_loss_value": float(weighted_loss.detach().cpu()),
        "directional_support_expansion_active_fraction": float(
            torch.count_nonzero(active).detach().cpu()
            / torch.count_nonzero(valid).detach().cpu().clamp_min(1)
        ),
        "directional_support_expansion_gap_norm_mean": float(gap[valid].mean().detach().cpu()),
        "directional_support_expansion_risk_mean": float(risks[valid].mean().detach().cpu()),
        "directional_support_expansion_weight_mean": float(row_weights[valid].mean().detach().cpu()),
        "directional_support_expansion_high_side_fraction": float(
            high_side[valid].to(dtype=dtype).mean().detach().cpu()
        ),
        "directional_support_expansion_hn_rows": float(
            torch.count_nonzero(row_families[valid] == hn_index).detach().cpu()
            if hn_index >= 0
            else 0.0
        ),
        "directional_support_expansion_cprime_rows": float(
            torch.count_nonzero(row_families[valid] == cprime_index).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        "directional_support_expansion_n_rows": float(
            torch.count_nonzero(row_families[valid] == n_index).detach().cpu()
            if n_index >= 0
            else 0.0
        ),
    }
    return weighted_loss * weight, metrics


def _mechanism_support_row_risk(
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    *,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> torch.Tensor:
    """Return leakage-safe HN/C' mechanism risk weights for target rows."""

    row_count = int(family_indices.numel())
    if row_count <= 0:
        return family_indices.new_zeros(0, dtype=torch.float32)
    features = target_features.to(device=family_indices.device, dtype=torch.float32)
    risks = torch.zeros(row_count, dtype=torch.float32, device=family_indices.device)

    def max_columns(indices: tuple[int, ...]) -> torch.Tensor:
        values: list[torch.Tensor] = []
        for index in indices:
            if features.shape[1] <= index:
                continue
            values.append(torch.nan_to_num(features[:, index], nan=0.0).clamp(0.0, 1.0))
        if not values:
            return torch.zeros(row_count, dtype=torch.float32, device=family_indices.device)
        return torch.stack(values, dim=0).amax(dim=0)

    specs: dict[str, tuple[int, ...]] = {
        "HN": (
            FEATURE_EXCHANGE_RISK,
            FEATURE_RING_CURRENT_PROXY,
            FEATURE_HN_SEQUENCE_CONTEXT_RISK,
            FEATURE_SAMPLE_HN_EXCHANGE_PROXY,
            FEATURE_SAMPLE_CONDITION_RISK,
            FEATURE_DISORDER_PROXY,
            FEATURE_LOCAL_AROMATIC_DENSITY,
            FEATURE_LOCAL_CHARGED_DENSITY,
        ),
        "C'": (
            FEATURE_CPRIME_PLANE_PROXY,
            FEATURE_CPRIME_SEQUENCE_CONTEXT_RISK,
            FEATURE_PROLINE_NEIGHBOR,
            FEATURE_LOCAL_TURN_PROPENSITY,
            FEATURE_DISORDER_PROXY,
        ),
        "N": (
            FEATURE_SAMPLE_CONDITION_RISK,
            FEATURE_LOCAL_AROMATIC_DENSITY,
            FEATURE_LOCAL_CHARGED_DENSITY,
            FEATURE_ALIGNMENT_RISK,
        ),
        "CA": (
            FEATURE_LOCAL_TURN_PROPENSITY,
            FEATURE_PROLINE_NEIGHBOR,
            FEATURE_ALIGNMENT_RISK,
        ),
        "CB": (
            FEATURE_PROLINE_NEIGHBOR,
            FEATURE_LOCAL_TURN_PROPENSITY,
            FEATURE_ALIGNMENT_RISK,
        ),
    }
    for family_name, column_indices in specs.items():
        if family_name not in family_names:
            continue
        family_index = int(family_names.index(family_name))
        family_mask = family_indices == family_index
        if bool(torch.any(family_mask)):
            risks = torch.where(family_mask, max_columns(column_indices), risks)
    return risks.to(device=family_indices.device, dtype=target_features.dtype)


def scheduled_support_envelope_weight(
    base_weight: float,
    *,
    epoch: int,
    warmup_epochs: int = 0,
    start_scale: float = 1.0,
) -> tuple[float, float]:
    """Return an epoch-annealed support-envelope loss weight.

    Default config keeps the old constant behavior.  A warmup lets the decoder
    keep posterior alignment early while still reaching the requested support
    expansion pressure by the final warmup epoch.
    """

    weight = max(float(base_weight), 0.0)
    if weight <= 0.0:
        return 0.0, 0.0
    warmup = max(int(warmup_epochs), 0)
    if warmup <= 1:
        return weight, 1.0
    start = min(max(float(start_scale), 0.0), 1.0)
    progress = min(max((int(epoch) - 1) / max(warmup - 1, 1), 0.0), 1.0)
    scale = start + (1.0 - start) * progress
    return weight * scale, scale


def scheduled_generated_prior_alignment_weight(
    base_weight: float,
    *,
    example_index: int,
    ramp_examples: int = 0,
    start_scale: float = 1.0,
    ramp_power: float = 1.0,
) -> tuple[float, float, float]:
    """Return a within-epoch scheduled generated-prior loss weight."""

    weight = max(float(base_weight), 0.0)
    if weight <= 0.0:
        return 0.0, 0.0, 0.0
    ramp = max(int(ramp_examples), 0)
    if ramp <= 1:
        return weight, 1.0, 1.0
    start = min(max(float(start_scale), 0.0), 1.0)
    progress = min(max(float(max(int(example_index), 0)) / max(ramp - 1, 1), 0.0), 1.0)
    power = max(float(ramp_power), 0.0)
    if math.isfinite(power) and power != 1.0:
        progress = progress**power
    scale = start + (1.0 - start) * progress
    return weight * scale, scale, progress


def conformer_evidence_likelihood_energy(
    conformer_phi: torch.Tensor,
    evidence_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    energy_scale: float,
    family_weights: dict[str, float] | None = None,
    cell_count_power: float = 0.0,
    likelihood_kind: str = "gaussian",
    student_df: float = 4.0,
    good_bad_outlier_prob: float = 0.05,
    good_bad_bad_scale: float = 8.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Return a conformer-wise CS evidence compatibility energy.

    Only conditioning/evidence rows should be passed here.  Supervised rows
    stay masked for the primary posterior-mean loss, preserving the Stage-B/C
    evidence/supervision split while giving q_theta a real CS likelihood signal.
    The robust modes replace the quadratic BME chi-square term with an
    outlier-aware marginal likelihood while keeping the posterior on the
    BioEmu support simplex through the downstream softmax energy map.
    """

    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, family_count]")
    scale = max(float(energy_scale), 0.0)
    support_count = int(conformer_phi.shape[0])
    if scale <= 0.0:
        return conformer_phi.new_zeros(support_count), {"evidence_points": 0}
    target = evidence_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if not bool(torch.any(mask)):
        return conformer_phi.new_zeros(support_count), {"evidence_points": 0}
    ppm_scales = conformer_phi.new_tensor(ATOM_FAMILY_PPM_SCALES).clamp_min(1.0e-3)
    kind = str(likelihood_kind or "gaussian").strip().lower().replace("-", "_")
    if kind not in {"gaussian", "student", "student_t", "good_bad", "goodbad"}:
        raise ValueError(f"unsupported evidence likelihood kind: {likelihood_kind}")
    weighted_energy = conformer_phi.new_zeros(support_count)
    weight_sum = 0.0
    point_count = 0
    inlier_responsibility_sum = 0.0
    inlier_responsibility_count = 0
    for family_index in range(min(conformer_phi.shape[-1], target.shape[-1])):
        family_mask = mask[:, family_index]
        if not bool(torch.any(family_mask)):
            continue
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        family_weight = max(float((family_weights or {}).get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        residual = (
            conformer_phi[:, family_mask, family_index]
            - target[:, family_index][family_mask].reshape(1, -1)
        ) / ppm_scales[family_index]
        if kind in {"student", "student_t"}:
            df = max(float(student_df), 1.0)
            family_energy = 0.5 * (df + 1.0) * torch.log1p(
                residual.square() / df
            )
        elif kind in {"good_bad", "goodbad"}:
            pi = min(max(float(good_bad_outlier_prob), 1.0e-6), 1.0 - 1.0e-6)
            bad_scale = max(float(good_bad_bad_scale), 1.01)
            log_good = math.log1p(-pi) - 0.5 * residual.square()
            log_bad = (
                math.log(pi)
                - math.log(bad_scale)
                - 0.5 * (residual / bad_scale).square()
            )
            stacked = torch.stack([log_good, log_bad], dim=0)
            family_energy = -torch.logsumexp(stacked, dim=0)
            responsibility = torch.softmax(stacked.detach(), dim=0)[0]
            inlier_responsibility_sum += float(torch.mean(responsibility).cpu())
            inlier_responsibility_count += 1
        else:
            family_energy = residual.square()
        weighted_energy = weighted_energy + family_weight * family_energy.mean(dim=1)
        weight_sum += family_weight
        point_count += int(torch.count_nonzero(family_mask).detach().cpu())
    if weight_sum <= 0.0:
        return conformer_phi.new_zeros(support_count), {"evidence_points": 0}
    count_power = max(float(cell_count_power), 0.0)
    count_scale = float(max(point_count, 1)) ** count_power
    metrics: dict[str, float] = {
        "evidence_points": float(point_count),
        "likelihood_kind": 1.0
        if kind in {"student", "student_t"}
        else (2.0 if kind in {"good_bad", "goodbad"} else 0.0),
    }
    if inlier_responsibility_count > 0:
        metrics["inlier_responsibility_mean"] = (
            inlier_responsibility_sum / inlier_responsibility_count
        )
    return scale * count_scale * weighted_energy / weight_sum, metrics


def aggregate_family_expert_energies(
    expert_terms: list[tuple[str, torch.Tensor, int]],
    *,
    mode: str = "sum",
    residual_cap: float = 0.0,
) -> tuple[torch.Tensor | None, dict[str, float]]:
    """Reconcile family expert energies into one shared posterior energy."""

    valid_terms = [
        (name, energy, int(count))
        for name, energy, count in expert_terms
        if int(count) > 0 and isinstance(energy, torch.Tensor)
    ]
    if not valid_terms:
        return None, {"family_expert_energy_terms": 0.0}
    energies = [energy for _, energy, _ in valid_terms]
    stacked = torch.stack(energies, dim=0)
    mode_key = str(mode or "sum").strip().lower()
    if mode_key in {"mean", "average"}:
        aggregate = torch.mean(stacked, dim=0)
    else:
        aggregate = torch.sum(stacked, dim=0)
        if mode_key in {"bounded_sum", "capped_sum", "centered_bounded_sum"}:
            centered = aggregate - torch.mean(aggregate)
            cap = max(float(residual_cap), 0.0)
            if cap > 0.0:
                aggregate = centered.new_tensor(cap) * torch.tanh(centered / cap)
            else:
                aggregate = centered
    centered_terms = stacked - torch.mean(stacked, dim=1, keepdim=True)
    dispersion = torch.var(centered_terms, dim=0, unbiased=False).mean()
    metrics = {
        "family_expert_energy_terms": float(len(valid_terms)),
        "family_expert_energy_cells": float(sum(count for _, _, count in valid_terms)),
        "family_expert_energy_mean_abs": float(torch.mean(torch.abs(aggregate.detach())).cpu()),
        "family_expert_energy_std": float(torch.std(aggregate.detach(), unbiased=False).cpu()),
        "family_expert_energy_conflict_var": float(dispersion.detach().cpu()),
    }
    return aggregate, metrics


def family_expert_energy_conflict_loss(
    expert_terms: list[tuple[str, torch.Tensor, int]],
    *,
    loss_weight: float = 0.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Penalize disagreement between family expert energy proposals."""

    valid_terms = [
        energy
        for _, energy, count in expert_terms
        if int(count) > 0 and isinstance(energy, torch.Tensor)
    ]
    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0 or len(valid_terms) < 2:
        if valid_terms:
            return _zero_loss_like(valid_terms[0]), {"family_expert_conflict_loss_terms": float(len(valid_terms))}
        return torch.tensor(0.0), {"family_expert_conflict_loss_terms": 0.0}
    stacked = torch.stack(valid_terms, dim=0)
    centered = stacked - torch.mean(stacked, dim=1, keepdim=True)
    loss = torch.var(centered, dim=0, unbiased=False).mean()
    metrics = {
        "family_expert_conflict_loss_terms": float(len(valid_terms)),
        "family_expert_conflict_loss_value": float(loss.detach().cpu()),
    }
    return loss * weight, metrics


def support_phi_family_variance_diagnostics(
    conformer_phi: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    weights: torch.Tensor | None = None,
    family_index: int = 0,
) -> dict[str, float | int]:
    """Summarize whether x0 support can move a family observable."""

    if conformer_phi.ndim != 3 or observed_mask.ndim != 2:
        return {"cell_count": 0}
    if family_index < 0 or family_index >= conformer_phi.shape[-1] or family_index >= observed_mask.shape[-1]:
        return {"cell_count": 0}
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool)[:, family_index]
    if not bool(torch.any(mask)):
        return {"cell_count": 0}
    values = conformer_phi[:, mask, family_index]
    finite_columns = torch.all(torch.isfinite(values), dim=0)
    if not bool(torch.any(finite_columns)):
        return {"cell_count": 0}
    values = values[:, finite_columns]
    support_std = torch.std(values, dim=0, unbiased=False)
    support_range = torch.amax(values, dim=0) - torch.amin(values, dim=0)
    result: dict[str, float | int] = {
        "cell_count": int(values.shape[1]),
        "support_std": float(torch.mean(support_std).detach().cpu()),
        "support_range": float(torch.mean(support_range).detach().cpu()),
    }
    if weights is not None:
        normalized_weights = weights.to(device=values.device, dtype=values.dtype)
        normalized_weights = normalized_weights / normalized_weights.sum().clamp_min(1.0e-12)
        mean = torch.sum(values * normalized_weights.reshape(-1, 1), dim=0)
        variance = torch.sum(
            (values - mean.reshape(1, -1)).square() * normalized_weights.reshape(-1, 1),
            dim=0,
        )
        result["posterior_std"] = float(torch.mean(torch.sqrt(variance.clamp_min(0.0))).detach().cpu())
    return result


def _bme_mirror_shared_q_weights(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    family_weights: torch.Tensor | None = None,
    steps: int = 64,
    learning_rate: float = 0.20,
    kl_weight: float = 0.01,
    likelihood_kind: str = "gaussian",
    student_df: float = 4.0,
    good_bad_outlier_prob: float = 0.05,
    good_bad_bad_scale: float = 8.0,
    reference_offset_l2: float = 0.0,
    reference_offset_learning_rate: float = 0.05,
    reference_offset_max_abs_ppm: float = 0.0,
    restart_count: int = 0,
    restart_noise: float = 0.0,
    restart_seed: int = 0,
    energy_warmstart_scales: Sequence[float] | None = None,
    ccc_loss_weight: float = 0.0,
    ccc_floor: float = 0.95,
    ccc_min_points: int = 3,
    ccc_family_weight_mode: str = "cell",
    ccc_dual_gap_learning_rate: float = 0.0,
    ccc_dual_gap_max_multiplier: float = 1.0,
    ccc_dual_gap_update_every: int = 1,
    ccc_dual_gap_warmup_steps: int = 0,
    ccc_dual_gap_loss_kind: str = "quadratic",
    selection_metric: str = "objective",
    ess_floor: float = 0.0,
    ess_loss_weight: float = 0.0,
    top_mass_cap: float = 0.0,
    top_mass_loss_weight: float = 0.0,
    local_residual_weights: torch.Tensor | None = None,
    local_residual_loss_weight: float = 0.0,
    local_residual_target_norm: float = 0.50,
    local_residual_dual_learning_rate: float = 0.0,
    local_residual_dual_max_multiplier: float = 1.0,
    local_residual_dual_update_every: int = 1,
    local_residual_dual_warmup_steps: int = 0,
    shape_dual_weights: torch.Tensor | None = None,
    shape_dual_loss_weight: float = 0.0,
    shape_dual_target_rmse: float = 0.35,
    shape_dual_min_points: int = 4,
    shape_dual_dual_learning_rate: float = 0.0,
    shape_dual_dual_max_multiplier: float = 1.0,
    shape_dual_dual_update_every: int = 1,
    shape_dual_dual_warmup_steps: int = 0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Solve a finite-support BME teacher on the probability simplex.

    The energy-softmax oracle asks which individual conformers have low
    residual.  This mirror-descent solver optimizes the ensemble mean directly
    while preserving the BioEmu prior through a KL term and one shared q.
    """

    support_count = int(conformer_phi.shape[0])
    if support_count <= 0:
        return conformer_phi.new_zeros((0,)), {"shared_q_oracle_bme_cells": 0.0}
    if prior_log_probs is None:
        prior = conformer_phi.new_full((support_count,), 1.0 / support_count)
    else:
        prior = torch.softmax(
            prior_log_probs.to(device=conformer_phi.device, dtype=conformer_phi.dtype),
            dim=-1,
        )
    prior = prior.clamp_min(1.0e-12)
    prior = prior / prior.sum().clamp_min(1.0e-12)

    target_device_grid = target_grid.to(
        device=conformer_phi.device,
        dtype=conformer_phi.dtype,
    )
    finite_by_cell = torch.any(torch.isfinite(conformer_phi), dim=0)
    mask = (
        observed_mask.to(device=conformer_phi.device, dtype=torch.bool)
        & torch.isfinite(target_device_grid)
        & finite_by_cell
    )
    if not bool(torch.any(mask)):
        return prior, {"shared_q_oracle_bme_cells": 0.0}

    raw_values = conformer_phi[:, mask]
    finite_values = torch.isfinite(raw_values)
    finite_value_weights = finite_values.to(dtype=conformer_phi.dtype)
    values = torch.where(finite_values, raw_values, torch.zeros_like(raw_values))
    target = target_device_grid[mask]
    family_indices = torch.nonzero(mask, as_tuple=False)[:, 1]
    family_count = int(conformer_phi.shape[-1])
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).index_select(0, family_indices).clamp_min(1.0e-3)
    if family_weights is None:
        cell_weights = torch.ones_like(target)
    else:
        cell_weights = family_weights.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        ).index_select(0, family_indices)
    cell_weights = cell_weights.clamp_min(0.0)
    if not bool(torch.any(cell_weights > 0.0)):
        cell_weights = torch.ones_like(target)
    normalizer = cell_weights.sum().clamp_min(1.0e-12)
    if local_residual_weights is None:
        local_cell_weights = torch.zeros_like(target)
    else:
        if tuple(local_residual_weights.shape) != tuple(target_grid.shape):
            raise ValueError("local_residual_weights must match target_grid [L,F]")
        local_grid = local_residual_weights.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        )
        local_cell_weights = local_grid[mask].clamp_min(0.0)
    if shape_dual_weights is None:
        shape_cell_weights = torch.zeros_like(target)
    else:
        if tuple(shape_dual_weights.shape) != tuple(target_grid.shape):
            raise ValueError("shape_dual_weights must match target_grid [L,F]")
        shape_grid = shape_dual_weights.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        )
        shape_cell_weights = shape_grid[mask].clamp_min(0.0)

    step_count = max(int(steps), 0)
    lr = max(float(learning_rate), 0.0)
    theta = max(float(kl_weight), 0.0)
    kind = str(likelihood_kind or "gaussian").lower()
    df = max(float(student_df), 1.0)
    pi = min(max(float(good_bad_outlier_prob), 1.0e-6), 1.0 - 1.0e-6)
    bad_scale = max(float(good_bad_bad_scale), 1.01)
    offset_l2 = max(float(reference_offset_l2), 0.0)
    offset_lr = max(float(reference_offset_learning_rate), 0.0)
    offset_cap = max(float(reference_offset_max_abs_ppm), 0.0)
    offset_enabled = bool(offset_cap > 0.0 and (offset_lr > 0.0 or offset_l2 > 0.0))
    ccc_weight = max(float(ccc_loss_weight), 0.0)
    ccc_target_floor = float(ccc_floor)
    ccc_point_floor = max(int(ccc_min_points), 2)
    ccc_weight_mode = str(ccc_family_weight_mode or "cell").strip().lower()
    dual_gap_lr = max(float(ccc_dual_gap_learning_rate), 0.0)
    dual_gap_max_multiplier = max(float(ccc_dual_gap_max_multiplier), 1.0)
    dual_gap_update_every = max(int(ccc_dual_gap_update_every), 1)
    dual_gap_warmup_steps = max(int(ccc_dual_gap_warmup_steps), 0)
    dual_gap_loss_key = str(ccc_dual_gap_loss_kind or "quadratic").strip().lower()
    dual_gap_augmented = dual_gap_loss_key in {
        "augmented",
        "augmented_lagrangian",
        "al",
        "linear_quadratic",
        "lagrangian_quadratic",
    }
    selection_mode = str(selection_metric or "objective").strip().lower()
    selection_mode = selection_mode.replace("-", "_")
    dual_gap_enabled = bool(
        ccc_weight > 0.0
        and dual_gap_lr > 0.0
        and dual_gap_max_multiplier > 1.0
    )
    safety_ess_floor = min(max(float(ess_floor), 0.0), float(support_count))
    safety_ess_weight = max(float(ess_loss_weight), 0.0)
    safety_top_cap = min(max(float(top_mass_cap), 0.0), 1.0)
    safety_top_weight = max(float(top_mass_loss_weight), 0.0)
    safety_enabled = bool(
        (safety_ess_weight > 0.0 and safety_ess_floor > 1.0)
        or (safety_top_weight > 0.0 and safety_top_cap > 0.0)
    )
    local_weight = max(float(local_residual_loss_weight), 0.0)
    local_target_norm = max(float(local_residual_target_norm), 0.0)
    local_dual_lr = max(float(local_residual_dual_learning_rate), 0.0)
    local_dual_max = max(float(local_residual_dual_max_multiplier), 1.0)
    local_dual_update_every = max(int(local_residual_dual_update_every), 1)
    local_dual_warmup_steps = max(int(local_residual_dual_warmup_steps), 0)
    local_active = local_cell_weights > 0.0
    local_active_count = int(torch.count_nonzero(local_active).detach().cpu())
    local_enabled = bool(local_weight > 0.0 and local_active_count > 0)
    local_dual_enabled = bool(local_enabled and local_dual_lr > 0.0 and local_dual_max > 1.0)
    local_normalizer = local_cell_weights.sum().clamp_min(1.0e-12)
    shape_weight = max(float(shape_dual_loss_weight), 0.0)
    shape_target_rmse = max(float(shape_dual_target_rmse), 0.0)
    shape_point_floor = max(int(shape_dual_min_points), 2)
    shape_dual_lr = max(float(shape_dual_dual_learning_rate), 0.0)
    shape_dual_max = max(float(shape_dual_dual_max_multiplier), 1.0)
    shape_dual_update_every = max(int(shape_dual_dual_update_every), 1)
    shape_dual_warmup_steps = max(int(shape_dual_dual_warmup_steps), 0)
    shape_active = shape_cell_weights > 0.0
    shape_active_count = int(torch.count_nonzero(shape_active).detach().cpu())
    shape_enabled = bool(shape_weight > 0.0 and shape_active_count > 0)
    shape_dual_enabled = bool(
        shape_enabled and shape_dual_lr > 0.0 and shape_dual_max > 1.0
    )
    configured_restart_count = max(int(restart_count), 0)
    noise_scale = max(float(restart_noise), 0.0)
    seed = int(restart_seed)
    warmstart_scales = [
        max(float(scale), 0.0)
        for scale in (energy_warmstart_scales or [])
        if max(float(scale), 0.0) > 0.0
    ]
    effective_restart_count = configured_restart_count if noise_scale > 0.0 else 0
    total_candidates = 1 + len(warmstart_scales) + effective_restart_count
    progress_enabled = total_candidates >= 16 or step_count >= 512
    progress_every = max(1, total_candidates // 10)
    progress_start = time.monotonic()
    candidate_index = 0
    goal_safe_selection_modes = {
        "goal",
        "goal_safe",
        "ccc_gap_macro",
        "macro_gap",
        "min_macro",
        "min_macro_ccc",
        "family_gate_then_min_macro_ccc",
        "family_gate_then_min_ccc_then_macro_ccc",
    }
    ccc_gap_selection_modes = {"ccc_gap", "gap", "floor_gap"} | goal_safe_selection_modes

    def _emit_candidate_progress(
        label: str,
        *,
        objective: float,
        best_objective: float,
        force: bool = False,
    ) -> None:
        if not progress_enabled:
            return
        if (
            not force
            and candidate_index < total_candidates
            and candidate_index % progress_every != 0
        ):
            return
        elapsed = time.monotonic() - progress_start
        print(
            "[bioemu-x0-bme] "
            f"candidate={candidate_index}/{total_candidates} "
            f"label={label} objective={objective:.8g} "
            f"best={best_objective:.8g} elapsed_s={elapsed:.1f}",
            flush=True,
        )

    def _candidate_selection_score(
        diagnostics: dict[str, float],
        objective: float,
    ) -> float:
        shape_gap_max = float(
            diagnostics.get("shared_q_oracle_bme_shape_dual_gap_max", 0.0)
        )
        shape_gap_mean = float(
            diagnostics.get("shared_q_oracle_bme_shape_dual_gap_mean", 0.0)
        )
        ccc_macro = float(
            diagnostics.get("shared_q_oracle_bme_ccc_macro", float("-inf"))
        )
        ccc_macro_gap = (
            max(0.0, ccc_target_floor - ccc_macro)
            if math.isfinite(ccc_macro)
            else float("inf")
        )
        if selection_mode in {"ccc_gap", "gap", "floor_gap"}:
            gap_max = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_max", float("inf"))
            )
            gap_mean = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_mean", float("inf"))
            )
            ccc_min = float(
                diagnostics.get("shared_q_oracle_bme_ccc_min", float("-inf"))
            )
            return (
                gap_max
                + 1.0e-3 * gap_mean
                + 1.0e-4 * ccc_macro_gap
                - 1.0e-3 * ccc_min
                - 1.0e-5 * ccc_macro
                + 1.0e-6 * float(objective)
            )
        if selection_mode in goal_safe_selection_modes:
            gap_max = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_max", float("inf"))
            )
            gap_mean = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_mean", float("inf"))
            )
            ccc_min = float(
                diagnostics.get("shared_q_oracle_bme_ccc_min", float("-inf"))
            )
            return (
                gap_max
                + 1.0e-2 * ccc_macro_gap
                + 1.0e-3 * gap_mean
                - 1.0e-3 * ccc_min
                - 1.0e-4 * ccc_macro
                + 1.0e-6 * float(objective)
            )
        if selection_mode in {"ccc_min", "min_ccc", "maximin"}:
            ccc_min = float(
                diagnostics.get("shared_q_oracle_bme_ccc_min", float("-inf"))
            )
            gap_max = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_max", float("inf"))
            )
            return -ccc_min + 1.0e-3 * gap_max + 1.0e-6 * float(objective)
        if selection_mode in {"feasible_objective", "constraint", "constrained"}:
            gap_max = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_max", float("inf"))
            )
            ccc_min = float(
                diagnostics.get("shared_q_oracle_bme_ccc_min", float("-inf"))
            )
            if math.isfinite(gap_max) and gap_max <= 1.0e-5:
                return float(objective)
            return 1.0e6 + gap_max - 1.0e-3 * ccc_min + 1.0e-6 * float(objective)
        if selection_mode in {"shape_gap", "shape", "shape_dual"}:
            return (
                shape_gap_max
                + 1.0e-3 * shape_gap_mean
                + 1.0e-6 * float(objective)
            )
        if selection_mode in {
            "ccc_shape_gap",
            "joint_gap",
            "cosatisfaction",
            "co_satisfaction",
        }:
            gap_max = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_max", float("inf"))
            )
            gap_mean = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_mean", float("inf"))
            )
            return (
                max(gap_max, shape_gap_max)
                + 0.25 * (gap_max + shape_gap_max)
                + 1.0e-3 * (gap_mean + shape_gap_mean)
                + 1.0e-6 * float(objective)
            )
        if selection_mode in {
            "shape_feasible_objective",
            "joint_feasible_objective",
            "cosatisfaction_feasible_objective",
        }:
            gap_max = float(
                diagnostics.get("shared_q_oracle_bme_ccc_gap_max", float("inf"))
            )
            ccc_min = float(
                diagnostics.get("shared_q_oracle_bme_ccc_min", float("-inf"))
            )
            if (
                math.isfinite(gap_max)
                and gap_max <= 1.0e-5
                and math.isfinite(shape_gap_max)
                and shape_gap_max <= 1.0e-5
            ):
                return float(objective)
            return (
                1.0e6
                + max(gap_max, shape_gap_max)
                + 0.25 * (gap_max + shape_gap_max)
                - 1.0e-3 * ccc_min
                + 1.0e-6 * float(objective)
            )
        return float(objective)

    def _weighted_prediction_for_weights(
        weights: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        denominator = torch.matmul(weights, finite_value_weights).clamp_min(1.0e-12)
        numerator = torch.matmul(weights, values)
        return numerator / denominator, denominator

    def _local_residual_dual_loss_for_cells(
        prediction_cells: torch.Tensor,
        dual_multipliers: torch.Tensor | None,
    ) -> tuple[torch.Tensor, dict[str, float]]:
        if not local_enabled:
            return prediction_cells.sum() * 0.0, {
                "shared_q_oracle_bme_local_residual_cells": 0.0,
            }
        normalized_residual = (prediction_cells - target) / scales
        gap = torch.relu(normalized_residual.abs() - prediction_cells.new_tensor(local_target_norm))
        active_gap = torch.where(local_active, gap, torch.zeros_like(gap))
        if dual_multipliers is not None:
            multiplier = dual_multipliers.to(
                device=prediction_cells.device,
                dtype=prediction_cells.dtype,
            ).clamp_min(0.0)
            raw_loss = multiplier * active_gap + 0.5 * active_gap.square()
        else:
            raw_loss = active_gap.square()
        loss = (raw_loss * local_cell_weights).sum() / local_normalizer
        active_values = active_gap[local_active]
        diagnostics = {
            "shared_q_oracle_bme_local_residual_cells": float(local_active_count),
            "shared_q_oracle_bme_local_residual_loss": float(loss.detach().cpu()),
            "shared_q_oracle_bme_local_residual_gap_max": float(
                active_values.max().detach().cpu()
                if int(active_values.numel()) > 0
                else 0.0
            ),
            "shared_q_oracle_bme_local_residual_gap_mean": float(
                (
                    (active_gap * local_cell_weights).sum()
                    / local_normalizer
                )
                .detach()
                .cpu()
            ),
        }
        return loss, diagnostics

    def _shape_dual_family_stats_for_cells(
        prediction_cells: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        rmse_values = prediction_cells.new_full((family_count,), float("nan"))
        gaps = prediction_cells.new_zeros((family_count,))
        valid = torch.zeros(
            (family_count,), device=prediction_cells.device, dtype=torch.bool
        )
        if not shape_enabled:
            return rmse_values, gaps, valid
        target_rmse = prediction_cells.new_tensor(float(shape_target_rmse))
        eps = prediction_cells.new_tensor(1.0e-8)
        for family_index in range(family_count):
            family_mask = shape_active & (family_indices == int(family_index))
            if int(torch.count_nonzero(family_mask).detach().cpu()) < shape_point_floor:
                continue
            pred = prediction_cells[family_mask]
            truth = target[family_mask]
            weights_for_group = shape_cell_weights[family_mask]
            finite = (
                torch.isfinite(pred)
                & torch.isfinite(truth)
                & torch.isfinite(weights_for_group)
                & (weights_for_group > 0.0)
            )
            if int(torch.count_nonzero(finite).detach().cpu()) < shape_point_floor:
                continue
            pred = pred[finite]
            truth = truth[finite]
            weights_for_group = weights_for_group[finite].clamp_min(0.0)
            weights_for_group = weights_for_group / weights_for_group.sum().clamp_min(
                1.0e-12
            )
            pred_mean = torch.sum(weights_for_group * pred)
            truth_mean = torch.sum(weights_for_group * truth)
            pred_centered = pred - pred_mean
            truth_centered = truth - truth_mean
            pred_std = torch.sqrt(
                torch.sum(weights_for_group * pred_centered.square()) + eps
            )
            truth_std = torch.sqrt(
                torch.sum(weights_for_group * truth_centered.square()) + eps
            )
            pred_z = pred_centered / pred_std
            truth_z = truth_centered / truth_std
            rmse = torch.sqrt(
                torch.sum(weights_for_group * (pred_z - truth_z).square()) + eps
            )
            rmse_values[family_index] = rmse
            gaps[family_index] = torch.relu(rmse - target_rmse)
            valid[family_index] = True
        return rmse_values, gaps, valid

    def _shape_dual_loss_for_cells(
        prediction_cells: torch.Tensor,
        dual_multipliers: torch.Tensor | None,
    ) -> tuple[torch.Tensor, dict[str, float]]:
        if not shape_enabled:
            return prediction_cells.sum() * 0.0, {
                "shared_q_oracle_bme_shape_dual_cells": 0.0,
                "shared_q_oracle_bme_shape_dual_family_count": 0.0,
            }
        rmse_values, gaps, valid = _shape_dual_family_stats_for_cells(
            prediction_cells
        )
        if not bool(torch.any(valid)):
            return prediction_cells.sum() * 0.0, {
                "shared_q_oracle_bme_shape_dual_cells": float(shape_active_count),
                "shared_q_oracle_bme_shape_dual_family_count": 0.0,
            }
        family_losses: list[torch.Tensor] = []
        family_loss_weights: list[torch.Tensor] = []
        for family_index in range(family_count):
            if not bool(valid[family_index].detach().cpu()):
                continue
            gap = gaps[family_index]
            multiplier = prediction_cells.new_tensor(1.0)
            if dual_multipliers is not None and family_index < int(
                dual_multipliers.numel()
            ):
                multiplier = dual_multipliers[family_index].to(
                    device=prediction_cells.device,
                    dtype=prediction_cells.dtype,
                ).clamp_min(0.0)
                family_loss = multiplier * gap + 0.5 * gap.square()
            else:
                family_loss = gap.square()
            family_losses.append(family_loss)
            family_mask = shape_active & (family_indices == int(family_index))
            weight_values = (
                shape_cell_weights[family_mask] * cell_weights[family_mask]
            )
            family_loss_weights.append(weight_values.mean().clamp_min(0.0))
        stacked_loss = torch.stack(family_losses)
        stacked_weights = torch.stack(family_loss_weights).to(
            device=prediction_cells.device,
            dtype=prediction_cells.dtype,
        )
        if not bool(torch.any(stacked_weights > 0.0)):
            stacked_weights = torch.ones_like(stacked_weights)
        loss = (
            stacked_loss * stacked_weights
        ).sum() / stacked_weights.sum().clamp_min(1.0e-12)
        valid_rmse = rmse_values[valid]
        valid_gaps = gaps[valid]
        diagnostics = {
            "shared_q_oracle_bme_shape_dual_cells": float(shape_active_count),
            "shared_q_oracle_bme_shape_dual_family_count": float(
                int(torch.count_nonzero(valid).detach().cpu())
            ),
            "shared_q_oracle_bme_shape_dual_loss": float(loss.detach().cpu()),
            "shared_q_oracle_bme_shape_dual_rmse_max": float(
                valid_rmse.max().detach().cpu()
            ),
            "shared_q_oracle_bme_shape_dual_rmse_mean": float(
                valid_rmse.mean().detach().cpu()
            ),
            "shared_q_oracle_bme_shape_dual_gap_max": float(
                valid_gaps.max().detach().cpu()
            ),
            "shared_q_oracle_bme_shape_dual_gap_mean": float(
                valid_gaps.mean().detach().cpu()
            ),
        }
        return loss, diagnostics

    if progress_enabled:
        print(
            "[bioemu-x0-bme] "
            f"start candidates={total_candidates} steps={step_count} "
            f"warmstarts={len(warmstart_scales)} restarts={effective_restart_count} "
            f"support={support_count} cells={int(torch.count_nonzero(mask).detach().cpu())}",
            flush=True,
        )

    def _run_candidate(
        initial_weights: torch.Tensor,
    ) -> tuple[torch.Tensor, dict[str, float], float]:
        weights = initial_weights.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
        weights = weights.clamp_min(1.0e-12)
        weights = weights / weights.sum().clamp_min(1.0e-12)
        offsets = conformer_phi.new_zeros((family_count,))
        dual_lambda = conformer_phi.new_zeros((family_count,))
        local_dual_lambda = torch.zeros_like(target)
        shape_dual_lambda = conformer_phi.new_zeros((family_count,))
        dual_update_count = 0
        local_dual_update_count = 0
        shape_dual_update_count = 0
        responsibility_mean = conformer_phi.new_tensor(float("nan"))
        for step_index in range(step_count):
            prediction, prediction_denominator = _weighted_prediction_for_weights(weights)
            offset_by_cell = offsets.index_select(0, family_indices)
            residual = (prediction + offset_by_cell - target) / scales
            if kind in {"student", "student_t"}:
                influence = ((df + 1.0) * residual) / (df + residual.square())
            elif kind in {"good_bad", "goodbad"}:
                log_good = math.log(1.0 - pi) - 0.5 * residual.square()
                log_bad = (
                    math.log(pi)
                    - math.log(bad_scale)
                    - 0.5 * (residual / bad_scale).square()
                )
                stacked = torch.stack([log_good, log_bad], dim=0)
                responsibility = torch.softmax(stacked.detach(), dim=0)[0]
                responsibility_mean = responsibility.mean()
                influence = (
                    responsibility * residual
                    + (1.0 - responsibility) * residual / (bad_scale * bad_scale)
                )
            else:
                influence = residual
            dloss_dprediction = cell_weights * influence / scales / normalizer
            ccc_loss_value = conformer_phi.new_tensor(0.0)
            if ccc_weight > 0.0:
                ccc_prediction = (prediction + offset_by_cell).detach().clone()
                ccc_prediction.requires_grad_(True)
                ccc_family_multipliers = None
                if dual_gap_enabled:
                    ccc_family_multipliers = dual_lambda.detach()
                    if not dual_gap_augmented:
                        ccc_family_multipliers = 1.0 + ccc_family_multipliers
                ccc_loss_value, _ = _ccc_floor_loss_for_cells(
                    ccc_prediction,
                    target,
                    family_indices,
                    family_count=family_count,
                    family_cell_weights=cell_weights,
                    floor=ccc_target_floor,
                    min_points=ccc_point_floor,
                    family_weight_mode=ccc_weight_mode,
                    family_loss_multipliers=ccc_family_multipliers,
                    loss_kind=dual_gap_loss_key,
                )
                if ccc_loss_value.requires_grad:
                    ccc_grad = torch.autograd.grad(
                        ccc_loss_value,
                        ccc_prediction,
                        retain_graph=False,
                        create_graph=False,
                        allow_unused=True,
                    )[0]
                    if ccc_grad is None:
                        ccc_grad = torch.zeros_like(ccc_prediction)
                else:
                    ccc_grad = torch.zeros_like(ccc_prediction)
                dloss_dprediction = dloss_dprediction + ccc_weight * ccc_grad
                if (
                    dual_gap_enabled
                    and step_index + 1 >= dual_gap_warmup_steps
                    and (step_index + 1) % dual_gap_update_every == 0
                ):
                    with torch.no_grad():
                        _, ccc_gaps, ccc_valid = _ccc_floor_family_stats_for_cells(
                            prediction + offset_by_cell,
                            target,
                            family_indices,
                            family_count=family_count,
                            floor=ccc_target_floor,
                            min_points=ccc_point_floor,
                        )
                        gap_update = torch.where(
                            ccc_valid,
                            ccc_gaps,
                            torch.zeros_like(ccc_gaps),
                        )
                        dual_lambda = torch.clamp(
                            dual_lambda + dual_gap_lr * gap_update,
                            min=0.0,
                            max=(
                                dual_gap_max_multiplier
                                if dual_gap_augmented
                                else dual_gap_max_multiplier - 1.0
                            ),
                        )
                        dual_update_count += 1
            if local_enabled:
                local_prediction = (prediction + offset_by_cell).detach().clone()
                local_prediction.requires_grad_(True)
                local_loss_value, _ = _local_residual_dual_loss_for_cells(
                    local_prediction,
                    local_dual_lambda.detach() if local_dual_enabled else None,
                )
                if local_loss_value.requires_grad:
                    local_grad = torch.autograd.grad(
                        local_loss_value,
                        local_prediction,
                        retain_graph=False,
                        create_graph=False,
                        allow_unused=True,
                    )[0]
                    if local_grad is None:
                        local_grad = torch.zeros_like(local_prediction)
                else:
                    local_grad = torch.zeros_like(local_prediction)
                dloss_dprediction = dloss_dprediction + local_weight * local_grad
                if (
                    local_dual_enabled
                    and step_index + 1 >= local_dual_warmup_steps
                    and (step_index + 1) % local_dual_update_every == 0
                ):
                    with torch.no_grad():
                        local_residual = (prediction + offset_by_cell - target) / scales
                        local_gap = torch.relu(local_residual.abs() - local_target_norm)
                        local_gap = torch.where(
                            local_active,
                            local_gap,
                            torch.zeros_like(local_gap),
                        )
                        local_dual_lambda = torch.clamp(
                            local_dual_lambda + local_dual_lr * local_gap,
                            min=0.0,
                            max=local_dual_max,
                        )
                        local_dual_update_count += 1
            if shape_enabled:
                shape_prediction = (prediction + offset_by_cell).detach().clone()
                shape_prediction.requires_grad_(True)
                shape_loss_value, _ = _shape_dual_loss_for_cells(
                    shape_prediction,
                    shape_dual_lambda.detach() if shape_dual_enabled else None,
                )
                if shape_loss_value.requires_grad:
                    shape_grad = torch.autograd.grad(
                        shape_loss_value,
                        shape_prediction,
                        retain_graph=False,
                        create_graph=False,
                        allow_unused=True,
                    )[0]
                    if shape_grad is None:
                        shape_grad = torch.zeros_like(shape_prediction)
                else:
                    shape_grad = torch.zeros_like(shape_prediction)
                dloss_dprediction = dloss_dprediction + shape_weight * shape_grad
                if (
                    shape_dual_enabled
                    and step_index + 1 >= shape_dual_warmup_steps
                    and (step_index + 1) % shape_dual_update_every == 0
                ):
                    with torch.no_grad():
                        _, shape_gaps, shape_valid = _shape_dual_family_stats_for_cells(
                            prediction + offset_by_cell
                        )
                        shape_gap_update = torch.where(
                            shape_valid,
                            shape_gaps,
                            torch.zeros_like(shape_gaps),
                        )
                        shape_dual_lambda = torch.clamp(
                            shape_dual_lambda + shape_dual_lr * shape_gap_update,
                            min=0.0,
                            max=shape_dual_max,
                        )
                        shape_dual_update_count += 1
            prediction_jacobian = (
                finite_value_weights
                * (values - prediction.reshape(1, -1))
                / prediction_denominator.reshape(1, -1).clamp_min(1.0e-12)
            )
            gradient = torch.matmul(prediction_jacobian, dloss_dprediction)
            if theta > 0.0:
                kl_gradient = torch.log(weights.clamp_min(1.0e-12) / prior) + 1.0
                gradient = gradient + theta * kl_gradient
            if safety_enabled:
                safety_weights = weights.detach().clone().requires_grad_(True)
                safety_loss, _ = _simplex_safety_loss_for_weights(
                    safety_weights,
                    ess_floor=safety_ess_floor,
                    ess_loss_weight=safety_ess_weight,
                    top_mass_cap=safety_top_cap,
                    top_mass_loss_weight=safety_top_weight,
                )
                if safety_loss.requires_grad:
                    safety_grad = torch.autograd.grad(
                        safety_loss,
                        safety_weights,
                        retain_graph=False,
                        create_graph=False,
                        allow_unused=True,
                    )[0]
                    if safety_grad is None:
                        safety_grad = torch.zeros_like(safety_weights)
                else:
                    safety_grad = torch.zeros_like(safety_weights)
                gradient = gradient + safety_grad
            if offset_enabled:
                offset_gradient = torch.zeros_like(offsets)
                offset_gradient.scatter_add_(0, family_indices, dloss_dprediction)
                if offset_l2 > 0.0:
                    offset_gradient = offset_gradient + offset_l2 * offsets
                offsets = offsets - offset_lr * offset_gradient
                offsets = offsets.clamp(min=-offset_cap, max=offset_cap)
            gradient = gradient - gradient.mean()
            update = torch.exp((-lr * gradient).clamp(min=-30.0, max=30.0))
            weights = weights * update
            weights = weights / weights.sum().clamp_min(1.0e-12)

        prediction, _ = _weighted_prediction_for_weights(weights)
        offset_by_cell = offsets.index_select(0, family_indices)
        residual = (prediction + offset_by_cell - target) / scales
        data_loss = 0.5 * (cell_weights * residual.square()).sum() / normalizer
        final_dual_multipliers = None
        if dual_gap_enabled:
            final_dual_multipliers = dual_lambda.detach()
            if not dual_gap_augmented:
                final_dual_multipliers = 1.0 + final_dual_multipliers
        ccc_loss, ccc_diagnostics = _ccc_floor_loss_for_cells(
            prediction + offset_by_cell,
            target,
            family_indices,
            family_count=family_count,
            family_cell_weights=cell_weights,
            floor=ccc_target_floor,
            min_points=ccc_point_floor,
            family_weight_mode=ccc_weight_mode,
            family_loss_multipliers=final_dual_multipliers,
            loss_kind=dual_gap_loss_key,
        )
        final_ccc_values, final_ccc_gaps, final_ccc_valid = (
            _ccc_floor_family_stats_for_cells(
                prediction + offset_by_cell,
                target,
                family_indices,
                family_count=family_count,
                floor=ccc_target_floor,
                min_points=ccc_point_floor,
            )
        )
        kl = torch.sum(
            weights
            * (torch.log(weights.clamp_min(1.0e-12)) - torch.log(prior))
        )
        safety_loss, safety_diagnostics = _simplex_safety_loss_for_weights(
            weights,
            ess_floor=safety_ess_floor,
            ess_loss_weight=safety_ess_weight,
            top_mass_cap=safety_top_cap,
            top_mass_loss_weight=safety_top_weight,
        )
        local_loss, local_diagnostics = _local_residual_dual_loss_for_cells(
            prediction + offset_by_cell,
            local_dual_lambda.detach() if local_dual_enabled else None,
        )
        shape_loss, shape_diagnostics = _shape_dual_loss_for_cells(
            prediction + offset_by_cell,
            shape_dual_lambda.detach() if shape_dual_enabled else None,
        )
        offset_penalty = 0.5 * offset_l2 * offsets.square().mean()
        objective = (
            data_loss
            + theta * kl
            + offset_penalty
            + ccc_weight * ccc_loss
            + safety_loss
            + local_weight * local_loss
            + shape_weight * shape_loss
        )
        diagnostics = {
            "shared_q_oracle_bme_cells": float(
                int(torch.count_nonzero(mask).detach().cpu())
            ),
            "shared_q_oracle_bme_steps": float(step_count),
            "shared_q_oracle_bme_learning_rate": float(lr),
            "shared_q_oracle_bme_kl_weight": float(theta),
            "shared_q_oracle_bme_data_loss": float(data_loss.detach().cpu()),
            "shared_q_oracle_bme_kl": float(kl.detach().cpu()),
            "shared_q_oracle_bme_reference_offset_l2": float(offset_l2),
            "shared_q_oracle_bme_reference_offset_learning_rate": float(offset_lr),
            "shared_q_oracle_bme_reference_offset_max_abs_ppm": float(offset_cap),
            "shared_q_oracle_bme_reference_offset_abs_max": float(
                offsets.detach().abs().max().cpu()
            ),
            "shared_q_oracle_bme_reference_offset_rms": float(
                torch.sqrt(offsets.detach().square().mean()).cpu()
            ),
            "shared_q_oracle_bme_reference_offset_penalty": float(
                offset_penalty.detach().cpu()
            ),
            "shared_q_oracle_bme_ccc_loss_weight": float(ccc_weight),
            "shared_q_oracle_bme_ccc_floor": float(ccc_target_floor),
            "shared_q_oracle_bme_ccc_min_points": float(ccc_point_floor),
            "shared_q_oracle_bme_ccc_family_weight_mode_is_uniform": float(
                ccc_weight_mode in {"uniform", "equal", "constraint", "constraints"}
            ),
            "shared_q_oracle_bme_ccc_dual_gap_learning_rate": float(dual_gap_lr),
            "shared_q_oracle_bme_ccc_dual_gap_max_multiplier": float(
                dual_gap_max_multiplier
            ),
            "shared_q_oracle_bme_ccc_dual_gap_update_every": float(
                dual_gap_update_every
            ),
            "shared_q_oracle_bme_ccc_dual_gap_warmup_steps": float(
                dual_gap_warmup_steps
            ),
            "shared_q_oracle_bme_ccc_dual_gap_loss_kind_is_augmented_lagrangian": float(
                dual_gap_augmented
            ),
            "shared_q_oracle_bme_ccc_dual_gap_enabled": float(dual_gap_enabled),
            "shared_q_oracle_bme_ccc_dual_gap_update_count": float(
                dual_update_count
            ),
            "shared_q_oracle_bme_ccc_floor_loss": float(ccc_loss.detach().cpu()),
            "shared_q_oracle_bme_ess_floor": float(safety_ess_floor),
            "shared_q_oracle_bme_ess_loss_weight": float(safety_ess_weight),
            "shared_q_oracle_bme_top_mass_cap": float(safety_top_cap),
            "shared_q_oracle_bme_top_mass_loss_weight": float(safety_top_weight),
            "shared_q_oracle_bme_simplex_safety_loss": float(
                safety_loss.detach().cpu()
            ),
            "shared_q_oracle_bme_local_residual_loss_weight": float(local_weight),
            "shared_q_oracle_bme_local_residual_target_norm": float(local_target_norm),
            "shared_q_oracle_bme_local_residual_dual_learning_rate": float(local_dual_lr),
            "shared_q_oracle_bme_local_residual_dual_max_multiplier": float(local_dual_max),
            "shared_q_oracle_bme_local_residual_dual_update_every": float(
                local_dual_update_every
            ),
            "shared_q_oracle_bme_local_residual_dual_warmup_steps": float(
                local_dual_warmup_steps
            ),
            "shared_q_oracle_bme_local_residual_dual_enabled": float(local_dual_enabled),
            "shared_q_oracle_bme_local_residual_dual_update_count": float(
                local_dual_update_count
            ),
            "shared_q_oracle_bme_shape_dual_loss_weight": float(shape_weight),
            "shared_q_oracle_bme_shape_dual_target_rmse": float(shape_target_rmse),
            "shared_q_oracle_bme_shape_dual_min_points": float(shape_point_floor),
            "shared_q_oracle_bme_shape_dual_dual_learning_rate": float(
                shape_dual_lr
            ),
            "shared_q_oracle_bme_shape_dual_dual_max_multiplier": float(
                shape_dual_max
            ),
            "shared_q_oracle_bme_shape_dual_dual_update_every": float(
                shape_dual_update_every
            ),
            "shared_q_oracle_bme_shape_dual_dual_warmup_steps": float(
                shape_dual_warmup_steps
            ),
            "shared_q_oracle_bme_shape_dual_dual_enabled": float(
                shape_dual_enabled
            ),
            "shared_q_oracle_bme_shape_dual_dual_update_count": float(
                shape_dual_update_count
            ),
            "shared_q_oracle_bme_objective": float(objective.detach().cpu()),
        }
        diagnostics.update(ccc_diagnostics)
        diagnostics.update(safety_diagnostics)
        diagnostics.update(local_diagnostics)
        diagnostics.update(shape_diagnostics)
        if local_dual_enabled:
            active_dual = local_dual_lambda.detach()[local_active]
            diagnostics["shared_q_oracle_bme_local_residual_dual_multiplier_mean"] = float(
                active_dual.mean().detach().cpu()
                if int(active_dual.numel()) > 0
                else 0.0
            )
            diagnostics["shared_q_oracle_bme_local_residual_dual_multiplier_max"] = float(
                active_dual.max().detach().cpu()
                if int(active_dual.numel()) > 0
                else 0.0
            )
        if shape_enabled:
            shape_rmse_values, shape_gaps, shape_valid = (
                _shape_dual_family_stats_for_cells(prediction + offset_by_cell)
            )
            active_shape_dual = shape_dual_lambda.detach()[shape_valid]
            if shape_dual_enabled:
                diagnostics["shared_q_oracle_bme_shape_dual_dual_multiplier_mean"] = float(
                    active_shape_dual.mean().detach().cpu()
                    if int(active_shape_dual.numel()) > 0
                    else 0.0
                )
                diagnostics["shared_q_oracle_bme_shape_dual_dual_multiplier_max"] = float(
                    active_shape_dual.max().detach().cpu()
                    if int(active_shape_dual.numel()) > 0
                    else 0.0
                )
            for family_index in range(family_count):
                family_name = (
                    str(family_names[family_index])
                    if family_index < len(family_names)
                    else str(family_index)
                )
                family_key = _metric_family_key(family_name)
                if bool(shape_valid[family_index].detach().cpu()):
                    diagnostics[
                        f"shared_q_oracle_bme_shape_dual_rmse_{family_key}"
                    ] = float(shape_rmse_values[family_index].detach().cpu())
                    diagnostics[
                        f"shared_q_oracle_bme_shape_dual_gap_{family_key}"
                    ] = float(shape_gaps[family_index].detach().cpu())
                diagnostics[
                    f"shared_q_oracle_bme_shape_dual_multiplier_{family_key}"
                ] = float(shape_dual_lambda.detach()[family_index].cpu())
        reported_dual_multipliers = None
        if dual_gap_enabled:
            dual_multipliers = 1.0 + dual_lambda.detach()
            reported_dual_multipliers = dual_multipliers
            diagnostics["shared_q_oracle_bme_ccc_dual_multiplier_mean"] = float(
                dual_multipliers.mean().detach().cpu()
            )
            diagnostics["shared_q_oracle_bme_ccc_dual_multiplier_max"] = float(
                dual_multipliers.max().detach().cpu()
            )
            diagnostics["shared_q_oracle_bme_ccc_dual_gap_max"] = float(
                torch.max(
                    torch.where(
                        final_ccc_valid,
                        final_ccc_gaps,
                        torch.zeros_like(final_ccc_gaps),
                    )
                )
                .detach()
                .cpu()
            )
            for family_index in range(family_count):
                family_name = (
                    str(family_names[family_index])
                    if family_index < len(family_names)
                    else str(family_index)
                )
                family_key = _metric_family_key(family_name)
                if bool(final_ccc_valid[family_index].detach().cpu()):
                    diagnostics[
                        f"shared_q_oracle_bme_ccc_{family_key}"
                    ] = float(final_ccc_values[family_index].detach().cpu())
                    diagnostics[
                        f"shared_q_oracle_bme_ccc_gap_{family_key}"
                    ] = float(final_ccc_gaps[family_index].detach().cpu())
                diagnostics[
                    f"shared_q_oracle_bme_ccc_dual_multiplier_{family_key}"
                ] = float(dual_multipliers[family_index].detach().cpu())
        _add_hn_n_cprime_bme_ccc_diagnostics(
            diagnostics,
            final_ccc_values,
            final_ccc_gaps,
            final_ccc_valid,
            family_names=family_names,
            family_count=family_count,
            dual_multipliers=reported_dual_multipliers,
        )
        if torch.isfinite(responsibility_mean):
            diagnostics["shared_q_oracle_bme_inlier_responsibility_mean"] = float(
                responsibility_mean.detach().cpu()
            )
        return weights, diagnostics, float(objective.detach().cpu())

    best_weights, best_diagnostics, best_objective = _run_candidate(prior)
    best_selection_score = _candidate_selection_score(best_diagnostics, best_objective)
    candidate_index += 1
    first_objective = best_objective
    first_selection_score = best_selection_score
    selected_restart = 0
    selected_energy_warmstart = 0
    _emit_candidate_progress(
        "prior",
        objective=best_objective,
        best_objective=best_objective,
        force=True,
    )
    if warmstart_scales:
        residual_by_conformer = (values - target.reshape(1, -1)) / scales.reshape(1, -1)
        finite_cell_weights = cell_weights.reshape(1, -1) * finite_value_weights
        energy_normalizer_by_conformer = finite_cell_weights.sum(dim=1)
        energy_by_conformer = (
            0.5
            * (finite_cell_weights * residual_by_conformer.square()).sum(dim=1)
            / energy_normalizer_by_conformer.clamp_min(1.0e-12)
        )
        energy_by_conformer = torch.where(
            energy_normalizer_by_conformer > 0.0,
            energy_by_conformer,
            torch.full_like(energy_by_conformer, 1.0e6),
        )
        log_prior = torch.log(prior.clamp_min(1.0e-12))
        for warmstart_index, warmstart_scale in enumerate(warmstart_scales, start=1):
            initial_weights = torch.softmax(
                log_prior - warmstart_scale * energy_by_conformer,
                dim=-1,
            )
            weights, diagnostics, objective = _run_candidate(initial_weights)
            selection_score = _candidate_selection_score(diagnostics, objective)
            if selection_score < best_selection_score:
                best_weights = weights
                best_diagnostics = diagnostics
                best_objective = objective
                best_selection_score = selection_score
                selected_restart = 0
                selected_energy_warmstart = warmstart_index
            candidate_index += 1
            _emit_candidate_progress(
                f"warmstart:{warmstart_index}",
                objective=objective,
                best_objective=best_objective,
            )
    if effective_restart_count > 0:
        generator = torch.Generator(device="cpu")
        generator.manual_seed(seed)
        restart_noise_cpu = torch.randn(
            (effective_restart_count, support_count),
            generator=generator,
            dtype=torch.float32,
        )
        log_prior = torch.log(prior.clamp_min(1.0e-12))
        for restart_index in range(effective_restart_count):
            perturbation = restart_noise_cpu[restart_index].to(
                device=conformer_phi.device,
                dtype=conformer_phi.dtype,
            )
            initial_weights = torch.softmax(
                log_prior + noise_scale * perturbation,
                dim=-1,
            )
            weights, diagnostics, objective = _run_candidate(initial_weights)
            selection_score = _candidate_selection_score(diagnostics, objective)
            if selection_score < best_selection_score:
                best_weights = weights
                best_diagnostics = diagnostics
                best_objective = objective
                best_selection_score = selection_score
                selected_restart = restart_index + 1
                selected_energy_warmstart = 0
            candidate_index += 1
            _emit_candidate_progress(
                f"restart:{restart_index + 1}",
                objective=objective,
                best_objective=best_objective,
                force=candidate_index >= total_candidates,
            )

    best_diagnostics.update(
        {
            "shared_q_oracle_bme_energy_warmstart_count": float(
                len(warmstart_scales)
            ),
            "shared_q_oracle_bme_energy_warmstart_selected": float(
                selected_energy_warmstart
            ),
            "shared_q_oracle_bme_restart_count": float(effective_restart_count),
            "shared_q_oracle_bme_restart_noise": float(noise_scale),
            "shared_q_oracle_bme_restart_seed": float(seed),
            "shared_q_oracle_bme_candidate_count": float(
                1 + len(warmstart_scales) + effective_restart_count
            ),
            "shared_q_oracle_bme_selected_restart": float(selected_restart),
            "shared_q_oracle_bme_first_objective": float(first_objective),
            "shared_q_oracle_bme_best_objective": float(best_objective),
            "shared_q_oracle_bme_selection_metric_is_ccc_gap": float(
                selection_mode in ccc_gap_selection_modes
            ),
            "shared_q_oracle_bme_selection_metric_is_ccc_min": float(
                selection_mode in {"ccc_min", "min_ccc", "maximin"}
            ),
            "shared_q_oracle_bme_selection_metric_is_goal_safe": float(
                selection_mode in goal_safe_selection_modes
            ),
            "shared_q_oracle_bme_selection_metric_is_cosatisfaction": float(
                selection_mode
                in {
                    "ccc_shape_gap",
                    "joint_gap",
                    "cosatisfaction",
                    "co_satisfaction",
                    "shape_feasible_objective",
                    "joint_feasible_objective",
                    "cosatisfaction_feasible_objective",
                }
            ),
            "shared_q_oracle_bme_first_selection_score": float(first_selection_score),
            "shared_q_oracle_bme_best_selection_score": float(best_selection_score),
            "shared_q_oracle_bme_restart_improved": float(
                selected_restart > 0 or selected_energy_warmstart > 0
            ),
        }
    )
    return best_weights, best_diagnostics


def _metric_family_key(family_name: str) -> str:
    normalized = str(family_name).strip().lower()
    if normalized in {"c'", "cprime", "c_prime"}:
        return "cprime"
    return "".join(ch if ch.isalnum() else "_" for ch in normalized).strip("_")


def _canonical_shared_q_family_name(family_name: str) -> str:
    normalized = (
        str(family_name)
        .strip()
        .lower()
        .replace("_", "")
        .replace("-", "")
        .replace(" ", "")
    )
    if normalized in {"c'", "cprime"}:
        return "C'"
    if normalized == "hn":
        return "HN"
    if normalized == "n":
        return "N"
    return str(family_name).strip().upper()


def _hn_n_cprime_family_indices(
    family_names: tuple[str, ...] | list[str],
    family_count: int,
) -> list[int]:
    target_names = {"HN", "N", "C'"}
    indices: list[int] = []
    seen: set[str] = set()
    for family_index in range(max(int(family_count), 0)):
        family_name = (
            str(family_names[family_index])
            if family_index < len(family_names)
            else str(family_index)
        )
        canonical = _canonical_shared_q_family_name(family_name)
        if canonical in target_names and canonical not in seen:
            indices.append(family_index)
            seen.add(canonical)
    return indices


def _add_hn_n_cprime_bme_ccc_diagnostics(
    diagnostics: dict[str, float],
    ccc_values: torch.Tensor,
    ccc_gaps: torch.Tensor,
    ccc_valid: torch.Tensor,
    *,
    family_names: tuple[str, ...] | list[str],
    family_count: int,
    dual_multipliers: torch.Tensor | None = None,
) -> None:
    """Record the HN/N/Cprime triad as the shared-q active-face bottleneck."""

    triad_indices = _hn_n_cprime_family_indices(family_names, family_count)
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_configured_family_count"] = float(
        len(triad_indices)
    )
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_missing_family_count"] = float(
        max(3 - len(triad_indices), 0)
    )
    if not triad_indices:
        diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_family_count"] = 0.0
        diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_all_valid"] = 0.0
        return

    index_tensor = torch.as_tensor(
        triad_indices,
        device=ccc_values.device,
        dtype=torch.long,
    )
    triad_valid = ccc_valid.index_select(0, index_tensor).to(dtype=torch.bool)
    valid_count = int(torch.count_nonzero(triad_valid).detach().cpu())
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_family_count"] = float(
        valid_count
    )
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_all_valid"] = float(
        len(triad_indices) == 3 and valid_count == 3
    )
    if valid_count <= 0:
        return

    valid_indices = index_tensor[triad_valid]
    triad_ccc = ccc_values.index_select(0, valid_indices)
    triad_gaps = ccc_gaps.index_select(0, valid_indices)
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_min"] = float(
        torch.amin(triad_ccc.detach()).cpu()
    )
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_macro"] = float(
        torch.mean(triad_ccc.detach()).cpu()
    )
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_gap_max"] = float(
        torch.amax(triad_gaps.detach()).cpu()
    )
    diagnostics["shared_q_oracle_bme_ccc_hn_n_cprime_gap_mean"] = float(
        torch.mean(triad_gaps.detach()).cpu()
    )
    if dual_multipliers is not None and int(dual_multipliers.numel()) >= int(
        max(triad_indices) + 1
    ):
        triad_dual = dual_multipliers.to(
            device=ccc_values.device,
            dtype=ccc_values.dtype,
        ).index_select(0, valid_indices)
        diagnostics["shared_q_oracle_bme_ccc_dual_multiplier_hn_n_cprime_max"] = float(
            torch.amax(triad_dual.detach()).cpu()
        )
        diagnostics["shared_q_oracle_bme_ccc_dual_multiplier_hn_n_cprime_mean"] = float(
            torch.mean(triad_dual.detach()).cpu()
        )


def _ccc_floor_family_stats_for_cells(
    prediction: torch.Tensor,
    target: torch.Tensor,
    family_indices: torch.Tensor,
    *,
    family_count: int,
    floor: float,
    min_points: int,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Return per-family CCC, positive floor gaps, and validity mask."""

    count = max(int(family_count), 0)
    ccc_values = prediction.new_full((count,), float("nan"))
    gaps = prediction.new_zeros((count,))
    valid = torch.zeros((count,), device=prediction.device, dtype=torch.bool)
    if prediction.numel() == 0 or count == 0:
        return ccc_values, gaps, valid
    point_floor = max(int(min_points), 2)
    floor_value = prediction.new_tensor(float(floor))
    for family_index in range(count):
        family_mask = family_indices == int(family_index)
        if int(torch.count_nonzero(family_mask).detach().cpu()) < point_floor:
            continue
        pred = prediction[family_mask]
        truth = target[family_mask]
        finite = torch.isfinite(pred) & torch.isfinite(truth)
        if int(torch.count_nonzero(finite).detach().cpu()) < point_floor:
            continue
        pred = pred[finite]
        truth = truth[finite]
        pred_centered = pred - pred.mean()
        truth_centered = truth - truth.mean()
        covariance = torch.mean(pred_centered * truth_centered)
        pred_var = torch.mean(pred_centered.square())
        truth_var = torch.mean(truth_centered.square())
        mean_delta = pred.mean() - truth.mean()
        denominator = pred_var + truth_var + mean_delta.square()
        ccc = 2.0 * covariance / denominator.clamp_min(1.0e-8)
        ccc_values[family_index] = ccc
        gaps[family_index] = torch.relu(floor_value - ccc)
        valid[family_index] = True
    return ccc_values, gaps, valid


def _simplex_safety_loss_for_weights(
    weights: torch.Tensor,
    *,
    ess_floor: float,
    ess_loss_weight: float,
    top_mass_cap: float,
    top_mass_loss_weight: float,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Penalty that keeps a shared-q solution from collapsing to a few states."""

    if weights.numel() == 0:
        return weights.new_tensor(0.0), {
            "shared_q_oracle_bme_safety_ess": 0.0,
            "shared_q_oracle_bme_safety_top_mass": 0.0,
        }
    normalized = weights.clamp_min(0.0)
    normalized = normalized / normalized.sum().clamp_min(1.0e-12)
    sum_square = normalized.square().sum().clamp_min(1.0e-12)
    ess = 1.0 / sum_square
    top_mass = torch.amax(normalized)

    loss = weights.sum() * 0.0
    ess_gap = weights.new_tensor(0.0)
    top_gap = weights.new_tensor(0.0)
    ess_floor_value = min(max(float(ess_floor), 0.0), float(weights.numel()))
    ess_weight = max(float(ess_loss_weight), 0.0)
    if ess_weight > 0.0 and ess_floor_value > 1.0:
        # Equivalent to relu(log(ESS_floor / ESS)); stable over large supports.
        ess_gap = torch.relu(
            torch.log(
                sum_square * normalized.new_tensor(float(ess_floor_value))
            )
        )
        loss = loss + normalized.new_tensor(ess_weight) * ess_gap.square()
    top_cap_value = min(max(float(top_mass_cap), 0.0), 1.0)
    top_weight = max(float(top_mass_loss_weight), 0.0)
    if top_weight > 0.0 and top_cap_value > 0.0:
        top_gap = torch.relu(
            (top_mass - normalized.new_tensor(top_cap_value))
            / normalized.new_tensor(top_cap_value).clamp_min(1.0e-12)
        )
        loss = loss + normalized.new_tensor(top_weight) * top_gap.square()

    diagnostics = {
        "shared_q_oracle_bme_safety_ess": float(ess.detach().cpu()),
        "shared_q_oracle_bme_safety_top_mass": float(top_mass.detach().cpu()),
        "shared_q_oracle_bme_safety_ess_gap": float(ess_gap.detach().cpu()),
        "shared_q_oracle_bme_safety_top_mass_gap": float(top_gap.detach().cpu()),
    }
    return loss, diagnostics


def _ccc_floor_loss_for_cells(
    prediction: torch.Tensor,
    target: torch.Tensor,
    family_indices: torch.Tensor,
    *,
    family_count: int,
    family_cell_weights: torch.Tensor,
    floor: float,
    min_points: int,
    family_weight_mode: str = "cell",
    family_loss_multipliers: torch.Tensor | None = None,
    loss_kind: str = "quadratic",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Differentiable CCC floor penalty over observed cells grouped by family."""

    if prediction.numel() == 0:
        return prediction.sum() * 0.0, {
            "shared_q_oracle_bme_ccc_family_count": 0.0,
        }
    loss_key = str(loss_kind or "quadratic").strip().lower()
    augmented = loss_key in {
        "augmented",
        "augmented_lagrangian",
        "al",
        "linear_quadratic",
        "lagrangian_quadratic",
    }
    losses: list[torch.Tensor] = []
    weights: list[torch.Tensor] = []
    ccc_values: list[torch.Tensor] = []
    gap_values: list[torch.Tensor] = []
    for family_index in range(max(int(family_count), 0)):
        family_mask = family_indices == int(family_index)
        if int(torch.count_nonzero(family_mask).detach().cpu()) < int(min_points):
            continue
        pred = prediction[family_mask]
        truth = target[family_mask]
        finite = torch.isfinite(pred) & torch.isfinite(truth)
        if int(torch.count_nonzero(finite).detach().cpu()) < int(min_points):
            continue
        pred = pred[finite]
        truth = truth[finite]
        pred_centered = pred - pred.mean()
        truth_centered = truth - truth.mean()
        covariance = torch.mean(pred_centered * truth_centered)
        pred_var = torch.mean(pred_centered.square())
        truth_var = torch.mean(truth_centered.square())
        mean_delta = pred.mean() - truth.mean()
        denominator = pred_var + truth_var + mean_delta.square()
        ccc = 2.0 * covariance / denominator.clamp_min(1.0e-8)
        ccc_values.append(ccc)
        gap = torch.relu(pred.new_tensor(float(floor)) - ccc)
        gap_values.append(gap)
        family_loss = gap.square()
        multiplier = pred.new_tensor(1.0)
        if (
            family_loss_multipliers is not None
            and family_index < int(family_loss_multipliers.numel())
        ):
            multiplier = family_loss_multipliers[family_index].to(
                device=prediction.device,
                dtype=prediction.dtype,
            ).clamp_min(0.0)
        if augmented:
            family_loss = multiplier * gap + 0.5 * gap.square()
        else:
            family_loss = gap.square()
        losses.append(family_loss)
        weight_mode = str(family_weight_mode or "cell").strip().lower()
        if weight_mode in {"uniform", "equal", "constraint", "constraints"}:
            family_weight = pred.new_tensor(1.0)
        else:
            family_weight = family_cell_weights[family_mask][finite].mean().clamp_min(0.0)
        if not augmented:
            family_weight = family_weight * multiplier
        weights.append(family_weight)
    if not losses:
        return prediction.sum() * 0.0, {
            "shared_q_oracle_bme_ccc_family_count": 0.0,
        }
    stacked_loss = torch.stack(losses)
    stacked_weights = torch.stack(weights).to(dtype=prediction.dtype, device=prediction.device)
    if not bool(torch.any(stacked_weights > 0.0)):
        stacked_weights = torch.ones_like(stacked_weights)
    loss = (stacked_loss * stacked_weights).sum() / stacked_weights.sum().clamp_min(1.0e-12)
    ccc_stack = torch.stack(ccc_values)
    gap_stack = torch.stack(gap_values)
    ccc_macro = torch.mean(ccc_stack)
    ccc_macro_gap = torch.relu(prediction.new_tensor(float(floor)) - ccc_macro)
    weighted_gap_mean = (
        (gap_stack * stacked_weights).sum()
        / stacked_weights.sum().clamp_min(1.0e-12)
    )
    weighted_gap_square = (
        (gap_stack.square() * stacked_weights).sum()
        / stacked_weights.sum().clamp_min(1.0e-12)
    )
    diagnostics = {
        "shared_q_oracle_bme_ccc_family_count": float(len(losses)),
        "shared_q_oracle_bme_ccc_min": float(torch.amin(ccc_stack.detach()).cpu()),
        "shared_q_oracle_bme_ccc_macro": float(ccc_macro.detach().cpu()),
        "shared_q_oracle_bme_ccc_macro_gap": float(
            ccc_macro_gap.detach().cpu()
        ),
        "shared_q_oracle_bme_ccc_gap_max": float(torch.amax(gap_stack.detach()).cpu()),
        "shared_q_oracle_bme_ccc_gap_mean": float(weighted_gap_mean.detach().cpu()),
        "shared_q_oracle_bme_ccc_gap_quadratic": float(
            weighted_gap_square.detach().cpu()
        ),
        "shared_q_oracle_bme_ccc_loss_kind_is_augmented_lagrangian": float(
            augmented
        ),
    }
    return loss, diagnostics


def support_reachability_oracle_predictions(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    energy_family_weights: dict[str, float] | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    oracle_solver: str = "energy_softmax",
    bme_steps: int = 64,
    bme_learning_rate: float = 0.20,
    bme_kl_weight: float = 0.01,
    bme_likelihood_kind: str = "gaussian",
    bme_student_df: float = 4.0,
    bme_good_bad_outlier_prob: float = 0.05,
    bme_good_bad_bad_scale: float = 8.0,
    bme_reference_offset_l2: float = 0.0,
    bme_reference_offset_learning_rate: float = 0.05,
    bme_reference_offset_max_abs_ppm: float = 0.0,
    bme_restart_count: int = 0,
    bme_restart_noise: float = 0.0,
    bme_restart_seed: int = 0,
    bme_energy_warmstart_scales: Sequence[float] | None = None,
    bme_ccc_loss_weight: float = 0.0,
    bme_ccc_floor: float = 0.95,
    bme_ccc_min_points: int = 3,
    bme_ccc_family_weight_mode: str = "cell",
    bme_ccc_dual_gap_learning_rate: float = 0.0,
    bme_ccc_dual_gap_max_multiplier: float = 1.0,
    bme_ccc_dual_gap_update_every: int = 1,
    bme_ccc_dual_gap_warmup_steps: int = 0,
    bme_ccc_dual_gap_loss_kind: str = "quadratic",
    bme_selection_metric: str = "objective",
    bme_ess_floor: float = 0.0,
    bme_ess_loss_weight: float = 0.0,
    bme_top_mass_cap: float = 0.0,
    bme_top_mass_loss_weight: float = 0.0,
    bme_local_residual_weights: torch.Tensor | None = None,
    bme_local_residual_loss_weight: float = 0.0,
    bme_local_residual_target_norm: float = 0.50,
    bme_local_residual_dual_learning_rate: float = 0.0,
    bme_local_residual_dual_max_multiplier: float = 1.0,
    bme_local_residual_dual_update_every: int = 1,
    bme_local_residual_dual_warmup_steps: int = 0,
    bme_shape_dual_weights: torch.Tensor | None = None,
    bme_shape_dual_loss_weight: float = 0.0,
    bme_shape_dual_target_rmse: float = 0.35,
    bme_shape_dual_min_points: int = 4,
    bme_shape_dual_dual_learning_rate: float = 0.0,
    bme_shape_dual_dual_max_multiplier: float = 1.0,
    bme_shape_dual_dual_update_every: int = 1,
    bme_shape_dual_dual_warmup_steps: int = 0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> dict[str, torch.Tensor | dict[str, float]]:
    """Return leakage-diagnostic support upper bounds for supervised rows.

    These predictions are never used as conditioning inputs or training targets
    for q_theta.  They answer a narrower question for the viewer: whether the
    current x0 support and decoder phi contain conformers that could explain
    held-out BMRB cells if an oracle posterior knew the supervised rows.
    """

    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    oracle_phi = conformer_phi if oracle_conformer_phi is None else oracle_conformer_phi
    if oracle_phi.shape != conformer_phi.shape:
        raise ValueError("oracle_conformer_phi must match conformer_phi")
    oracle_phi = oracle_phi.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    phi_finite = torch.isfinite(conformer_phi)
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    support_available = torch.any(phi_finite, dim=0)
    mask = mask & support_available
    support_count = int(conformer_phi.shape[0])
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1)
    if not bool(torch.any(mask)):
        zeros = torch.zeros_like(target)
        return {
            "shared_q_prediction": zeros,
            "single_prediction": zeros,
            "rowwise_prediction": zeros,
            "clipped_prediction": zeros,
            "mask": mask,
            "weights": conformer_phi.new_full((support_count,), 1.0 / max(support_count, 1)),
            "diagnostics": {"cell_count": 0},
        }

    residual = (oracle_phi - target.reshape(1, *target.shape)) / scales.clamp_min(1.0e-3)
    family_energy_weights = conformer_phi.new_ones(int(conformer_phi.shape[-1]))
    configured_energy_weights = energy_family_weights or {}
    if configured_energy_weights:
        for family_index in range(int(conformer_phi.shape[-1])):
            family_name = (
                str(family_names[family_index])
                if family_index < len(family_names)
                else str(family_index)
            )
            if family_name in configured_energy_weights:
                family_energy_weights[family_index] = max(
                    float(configured_energy_weights[family_name]),
                    0.0,
                )
    mask_float = mask.to(dtype=conformer_phi.dtype)
    weighted_mask = mask_float * family_energy_weights.reshape(1, -1)
    if not bool(torch.any(weighted_mask > 0.0)):
        weighted_mask = mask_float
        family_energy_weights = conformer_phi.new_ones(int(conformer_phi.shape[-1]))
    oracle_finite = torch.isfinite(oracle_phi)
    support_mask = mask.reshape(1, *mask.shape) & oracle_finite
    masked_residual = torch.where(
        support_mask,
        residual,
        torch.zeros_like(residual),
    )
    energy_weight_grid = (
        weighted_mask.reshape(1, *weighted_mask.shape)
        * support_mask.to(dtype=conformer_phi.dtype)
    )
    energy_normalizer = energy_weight_grid.sum(dim=(1, 2))
    energy = (
        (masked_residual.square() * energy_weight_grid).sum(dim=(1, 2))
        / energy_normalizer.clamp_min(1.0e-12)
    )
    energy = torch.where(
        energy_normalizer > 0.0,
        energy,
        torch.full_like(energy, 1.0e6),
    )
    solver = str(oracle_solver or "energy_softmax").lower()
    bme_diagnostics: dict[str, float] = {}
    bme_solver_aliases = {
        "bme",
        "bme_mirror",
        "mirror",
        "mirror_descent",
        "maxent",
        "bme_stochastic",
        "stochastic_bme",
        "stochastic_simplex",
        "maxent_stochastic",
    }
    if solver in bme_solver_aliases:
        weights, bme_diagnostics = _bme_mirror_shared_q_weights(
            oracle_phi,
            target,
            mask,
            prior_log_probs=prior_log_probs,
            family_weights=family_energy_weights,
            steps=int(bme_steps),
            learning_rate=float(bme_learning_rate),
            kl_weight=float(bme_kl_weight),
            likelihood_kind=str(bme_likelihood_kind),
            student_df=float(bme_student_df),
            good_bad_outlier_prob=float(bme_good_bad_outlier_prob),
            good_bad_bad_scale=float(bme_good_bad_bad_scale),
            reference_offset_l2=float(bme_reference_offset_l2),
            reference_offset_learning_rate=float(bme_reference_offset_learning_rate),
            reference_offset_max_abs_ppm=float(bme_reference_offset_max_abs_ppm),
            restart_count=int(bme_restart_count),
            restart_noise=float(bme_restart_noise),
            restart_seed=int(bme_restart_seed),
            energy_warmstart_scales=bme_energy_warmstart_scales,
            ccc_loss_weight=float(bme_ccc_loss_weight),
            ccc_floor=float(bme_ccc_floor),
            ccc_min_points=int(bme_ccc_min_points),
            ccc_family_weight_mode=str(bme_ccc_family_weight_mode),
            ccc_dual_gap_learning_rate=float(bme_ccc_dual_gap_learning_rate),
            ccc_dual_gap_max_multiplier=float(bme_ccc_dual_gap_max_multiplier),
            ccc_dual_gap_update_every=int(bme_ccc_dual_gap_update_every),
            ccc_dual_gap_warmup_steps=int(bme_ccc_dual_gap_warmup_steps),
            ccc_dual_gap_loss_kind=str(bme_ccc_dual_gap_loss_kind),
            selection_metric=str(bme_selection_metric),
            ess_floor=float(bme_ess_floor),
            ess_loss_weight=float(bme_ess_loss_weight),
            top_mass_cap=float(bme_top_mass_cap),
            top_mass_loss_weight=float(bme_top_mass_loss_weight),
            local_residual_weights=bme_local_residual_weights,
            local_residual_loss_weight=float(bme_local_residual_loss_weight),
            local_residual_target_norm=float(bme_local_residual_target_norm),
            local_residual_dual_learning_rate=float(
                bme_local_residual_dual_learning_rate
            ),
            local_residual_dual_max_multiplier=float(
                bme_local_residual_dual_max_multiplier
            ),
            local_residual_dual_update_every=int(
                bme_local_residual_dual_update_every
            ),
            local_residual_dual_warmup_steps=int(
                bme_local_residual_dual_warmup_steps
            ),
            shape_dual_weights=bme_shape_dual_weights,
            shape_dual_loss_weight=float(bme_shape_dual_loss_weight),
            shape_dual_target_rmse=float(bme_shape_dual_target_rmse),
            shape_dual_min_points=int(bme_shape_dual_min_points),
            shape_dual_dual_learning_rate=float(
                bme_shape_dual_dual_learning_rate
            ),
            shape_dual_dual_max_multiplier=float(
                bme_shape_dual_dual_max_multiplier
            ),
            shape_dual_dual_update_every=int(bme_shape_dual_dual_update_every),
            shape_dual_dual_warmup_steps=int(
                bme_shape_dual_dual_warmup_steps
            ),
            family_names=family_names,
        )
    else:
        weights = posterior_weights(
            prior_log_probs,
            max(float(oracle_energy_scale), 0.0) * energy,
        )
    weight_view = weights.reshape(weights.shape[0], 1, 1)
    weighted_finite = weight_view * phi_finite.to(dtype=conformer_phi.dtype)
    weighted_denominator = weighted_finite.sum(dim=0).clamp_min(1.0e-12)
    shared_q_prediction = (
        torch.where(phi_finite, conformer_phi, torch.zeros_like(conformer_phi))
        * weight_view
    ).sum(dim=0) / weighted_denominator
    single_index = int(torch.argmin(energy).detach().cpu())
    single_prediction = torch.where(
        phi_finite[single_index],
        conformer_phi[single_index],
        torch.zeros_like(conformer_phi[single_index]),
    )

    support_min = torch.amin(
        torch.where(phi_finite, conformer_phi, torch.full_like(conformer_phi, torch.inf)),
        dim=0,
    )
    support_max = torch.amax(
        torch.where(phi_finite, conformer_phi, torch.full_like(conformer_phi, -torch.inf)),
        dim=0,
    )
    clipped_prediction = torch.where(
        support_available,
        torch.minimum(torch.maximum(target, support_min), support_max),
        torch.zeros_like(target),
    )
    nearest_distance = torch.where(
        phi_finite,
        torch.abs(conformer_phi - target.reshape(1, *target.shape)),
        torch.full_like(conformer_phi, torch.inf),
    )
    nearest_indices = torch.argmin(nearest_distance, dim=0)
    rowwise_prediction = torch.gather(
        torch.where(phi_finite, conformer_phi, torch.zeros_like(conformer_phi)),
        dim=0,
        index=nearest_indices.reshape(1, *nearest_indices.shape),
    ).squeeze(0)

    inside = (target >= support_min) & (target <= support_max) & mask
    outside_gap = torch.where(
        target < support_min,
        support_min - target,
        torch.where(target > support_max, target - support_max, torch.zeros_like(target)),
    )
    normalized_gap = outside_gap / scales.reshape(1, -1).clamp_min(1.0e-3)
    diagnostics = {
        "cell_count": int(torch.count_nonzero(mask).detach().cpu()),
        "within_support_fraction": float(
            torch.count_nonzero(inside).detach().cpu()
            / torch.count_nonzero(mask).detach().cpu().clamp_min(1)
        ),
        "outside_gap_norm_mean": float(normalized_gap[mask].mean().detach().cpu()),
        "shared_q_oracle_ess": float((1.0 / weights.square().sum().clamp_min(1.0e-12)).detach().cpu()),
        "shared_q_oracle_top_mass": float(torch.max(weights).detach().cpu()),
        "shared_q_oracle_energy_weight_mean": float(
            weighted_mask[mask].mean().detach().cpu()
        ),
        "shared_q_oracle_energy_weight_max": float(
            weighted_mask[mask].max().detach().cpu()
        ),
        "shared_q_oracle_source_is_sidecar": float(
            oracle_conformer_phi is not None
        ),
        "shared_q_oracle_support_coverage_mean": float(
            (
                energy_normalizer
                / weighted_mask.sum().clamp_min(1.0e-12)
            )
            .clamp(min=0.0, max=1.0)
            .mean()
            .detach()
            .cpu()
        ),
        "shared_q_oracle_solver_is_bme": float(bool(bme_diagnostics)),
    }
    diagnostics.update(bme_diagnostics)
    return {
        "shared_q_prediction": shared_q_prediction,
        "single_prediction": single_prediction,
        "rowwise_prediction": rowwise_prediction,
        "clipped_prediction": clipped_prediction,
        "mask": mask,
        "weights": weights,
        "diagnostics": diagnostics,
    }


def shared_q_oracle_distillation_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    weights: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    oracle_energy_family_weights: dict[str, float] | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    oracle_solver: str = "energy_softmax",
    bme_steps: int = 64,
    bme_learning_rate: float = 0.20,
    bme_kl_weight: float = 0.01,
    bme_likelihood_kind: str = "gaussian",
    bme_student_df: float = 4.0,
    bme_good_bad_outlier_prob: float = 0.05,
    bme_good_bad_bad_scale: float = 8.0,
    bme_reference_offset_l2: float = 0.0,
    bme_reference_offset_learning_rate: float = 0.05,
    bme_reference_offset_max_abs_ppm: float = 0.0,
    bme_restart_count: int = 0,
    bme_restart_noise: float = 0.0,
    bme_restart_seed: int = 0,
    bme_energy_warmstart_scales: Sequence[float] | None = None,
    bme_ccc_loss_weight: float = 0.0,
    bme_ccc_floor: float = 0.95,
    bme_ccc_min_points: int = 3,
    bme_ccc_family_weight_mode: str = "cell",
    bme_ccc_dual_gap_learning_rate: float = 0.0,
    bme_ccc_dual_gap_max_multiplier: float = 1.0,
    bme_ccc_dual_gap_update_every: int = 1,
    bme_ccc_dual_gap_warmup_steps: int = 0,
    bme_ccc_dual_gap_loss_kind: str = "quadratic",
    bme_selection_metric: str = "objective",
    bme_ess_floor: float = 0.0,
    bme_ess_loss_weight: float = 0.0,
    bme_top_mass_cap: float = 0.0,
    bme_top_mass_loss_weight: float = 0.0,
    precomputed_oracle: dict[str, Any] | None = None,
    metric_prefix: str = "oracle_distill",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Distill a supervised-row oracle into one shared posterior q.

    This loss is intended for train splits only.  It uses the same supervised
    rows as the CS loss to form a detached shared-q oracle, then nudges the
    learned single population distribution toward that oracle without creating
    atom-family-specific posterior weights.
    """

    scale = max(float(oracle_energy_scale), 0.0)
    weight = max(float(loss_weight), 0.0)
    prefix = str(metric_prefix or "oracle_distill")
    if weight <= 0.0:
        return _zero_loss_like(weights), {f"{prefix}_cells": 0.0}
    oracle_reused = precomputed_oracle is not None
    if precomputed_oracle is None:
        oracle = support_reachability_oracle_predictions(
            conformer_phi.detach(),
            target_grid.detach(),
            observed_mask.detach(),
            prior_log_probs=(
                prior_log_probs.detach() if prior_log_probs is not None else None
            ),
            oracle_energy_scale=scale,
            energy_family_weights=oracle_energy_family_weights,
            oracle_conformer_phi=(
                oracle_conformer_phi.detach()
                if oracle_conformer_phi is not None
                else None
            ),
            oracle_solver=oracle_solver,
            bme_steps=bme_steps,
            bme_learning_rate=bme_learning_rate,
            bme_kl_weight=bme_kl_weight,
            bme_likelihood_kind=bme_likelihood_kind,
            bme_student_df=bme_student_df,
            bme_good_bad_outlier_prob=bme_good_bad_outlier_prob,
            bme_good_bad_bad_scale=bme_good_bad_bad_scale,
            bme_reference_offset_l2=bme_reference_offset_l2,
            bme_reference_offset_learning_rate=bme_reference_offset_learning_rate,
            bme_reference_offset_max_abs_ppm=bme_reference_offset_max_abs_ppm,
            bme_restart_count=bme_restart_count,
            bme_restart_noise=bme_restart_noise,
            bme_restart_seed=bme_restart_seed,
            bme_energy_warmstart_scales=bme_energy_warmstart_scales,
            bme_ccc_loss_weight=bme_ccc_loss_weight,
            bme_ccc_floor=bme_ccc_floor,
            bme_ccc_min_points=bme_ccc_min_points,
            bme_ccc_family_weight_mode=bme_ccc_family_weight_mode,
            bme_ccc_dual_gap_learning_rate=bme_ccc_dual_gap_learning_rate,
            bme_ccc_dual_gap_max_multiplier=bme_ccc_dual_gap_max_multiplier,
            bme_ccc_dual_gap_update_every=bme_ccc_dual_gap_update_every,
            bme_ccc_dual_gap_warmup_steps=bme_ccc_dual_gap_warmup_steps,
            bme_ccc_dual_gap_loss_kind=bme_ccc_dual_gap_loss_kind,
            bme_selection_metric=bme_selection_metric,
            bme_ess_floor=bme_ess_floor,
            bme_ess_loss_weight=bme_ess_loss_weight,
            bme_top_mass_cap=bme_top_mass_cap,
            bme_top_mass_loss_weight=bme_top_mass_loss_weight,
        )
    else:
        oracle = precomputed_oracle
    diagnostics = dict(oracle.get("diagnostics", {}))
    cell_count = int(diagnostics.get("cell_count", 0))
    if cell_count <= 0:
        return _zero_loss_like(weights), {f"{prefix}_cells": 0.0}
    teacher_weights = oracle["weights"]
    if not isinstance(teacher_weights, torch.Tensor):
        return _zero_loss_like(weights), {f"{prefix}_cells": 0.0}
    teacher = teacher_weights.to(device=weights.device, dtype=weights.dtype).detach()
    student = weights.clamp_min(1.0e-12)
    teacher = teacher.clamp_min(1.0e-12)
    kl = torch.sum(teacher * (torch.log(teacher) - torch.log(student)))
    metrics = {
        f"{prefix}_cells": float(cell_count),
        f"{prefix}_kl": float(kl.detach().cpu()),
        f"{prefix}_ess": float(diagnostics.get("shared_q_oracle_ess", 0.0)),
        f"{prefix}_top_mass": float(diagnostics.get("shared_q_oracle_top_mass", 0.0)),
        f"{prefix}_energy_weight_mean": float(
            diagnostics.get("shared_q_oracle_energy_weight_mean", 1.0)
        ),
        f"{prefix}_energy_weight_max": float(
            diagnostics.get("shared_q_oracle_energy_weight_max", 1.0)
        ),
        f"{prefix}_source_is_sidecar": float(
            diagnostics.get("shared_q_oracle_source_is_sidecar", 0.0)
        ),
        f"{prefix}_support_coverage_mean": float(
            diagnostics.get("shared_q_oracle_support_coverage_mean", 1.0)
        ),
        f"{prefix}_solver_is_bme": float(
            diagnostics.get("shared_q_oracle_solver_is_bme", 0.0)
        ),
        f"{prefix}_oracle_reused": float(oracle_reused),
    }
    for key, value in diagnostics.items():
        key_text = str(key)
        if key_text.startswith("shared_q_oracle_bme"):
            metrics[f"{prefix}_{key.replace('shared_q_oracle_', '')}"] = float(value)
        if key_text.startswith("external_global_family_teacher"):
            metrics[f"{prefix}_{key_text}"] = float(value)
    return kl * weight, metrics


def shared_q_witness_ccc_floor_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_ccc_floors: dict[str, float] | None = None,
    family_weights: dict[str, float] | None = None,
    oracle_energy_family_weights: dict[str, float] | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    oracle_solver: str = "energy_softmax",
    bme_steps: int = 64,
    bme_learning_rate: float = 0.20,
    bme_kl_weight: float = 0.01,
    bme_likelihood_kind: str = "gaussian",
    bme_student_df: float = 4.0,
    bme_good_bad_outlier_prob: float = 0.05,
    bme_good_bad_bad_scale: float = 8.0,
    bme_reference_offset_l2: float = 0.0,
    bme_reference_offset_learning_rate: float = 0.05,
    bme_reference_offset_max_abs_ppm: float = 0.0,
    bme_restart_count: int = 0,
    bme_restart_noise: float = 0.0,
    bme_restart_seed: int = 0,
    bme_energy_warmstart_scales: Sequence[float] | None = None,
    bme_ccc_loss_weight: float = 0.0,
    bme_ccc_floor: float = 0.95,
    bme_ccc_min_points: int = 3,
    bme_ccc_family_weight_mode: str = "cell",
    bme_ccc_dual_gap_learning_rate: float = 0.0,
    bme_ccc_dual_gap_max_multiplier: float = 1.0,
    bme_ccc_dual_gap_update_every: int = 1,
    bme_ccc_dual_gap_warmup_steps: int = 0,
    bme_ccc_dual_gap_loss_kind: str = "quadratic",
    bme_selection_metric: str = "objective",
    bme_ess_floor: float = 0.0,
    bme_ess_loss_weight: float = 0.0,
    bme_top_mass_cap: float = 0.0,
    bme_top_mass_loss_weight: float = 0.0,
    precomputed_oracle: dict[str, Any] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    min_points: int = 3,
    gap_power: float = 1.0,
    worst_family_mix: float = 0.0,
    macro_floor: float = 0.0,
    macro_floor_mix: float = 0.0,
    macro_floor_additive: bool = False,
    low_tail_floor: float = 0.0,
    low_tail_fraction: float = 0.4,
    low_tail_mix: float = 0.0,
    low_tail_additive: bool = True,
    metric_prefix: str = "shared_q_witness",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Apply a stop-gradient one-shared-q witness to trainable conformer phi.

    The oracle chooses a single q on detached support observables, optionally
    UCBShift sidecars.  The floor loss then recomputes the posterior mean from
    the current ``conformer_phi`` under that fixed q, so gradients point toward
    preserving the official shared-q face instead of a row-wise proxy.
    """

    prefix = str(metric_prefix or "shared_q_witness")
    weight = max(float(loss_weight), 0.0)
    floors = dict(family_ccc_floors or {})
    if weight <= 0.0 or not floors:
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    oracle_reused = precomputed_oracle is not None
    if precomputed_oracle is None:
        oracle = support_reachability_oracle_predictions(
            conformer_phi.detach(),
            target_grid.detach(),
            observed_mask.detach(),
            prior_log_probs=(
                prior_log_probs.detach() if prior_log_probs is not None else None
            ),
            oracle_energy_scale=max(float(oracle_energy_scale), 0.0),
            energy_family_weights=oracle_energy_family_weights,
            oracle_conformer_phi=(
                oracle_conformer_phi.detach()
                if oracle_conformer_phi is not None
                else None
            ),
            oracle_solver=oracle_solver,
            bme_steps=bme_steps,
            bme_learning_rate=bme_learning_rate,
            bme_kl_weight=bme_kl_weight,
            bme_likelihood_kind=bme_likelihood_kind,
            bme_student_df=bme_student_df,
            bme_good_bad_outlier_prob=bme_good_bad_outlier_prob,
            bme_good_bad_bad_scale=bme_good_bad_bad_scale,
            bme_reference_offset_l2=bme_reference_offset_l2,
            bme_reference_offset_learning_rate=bme_reference_offset_learning_rate,
            bme_reference_offset_max_abs_ppm=bme_reference_offset_max_abs_ppm,
            bme_restart_count=bme_restart_count,
            bme_restart_noise=bme_restart_noise,
            bme_restart_seed=bme_restart_seed,
            bme_energy_warmstart_scales=bme_energy_warmstart_scales,
            bme_ccc_loss_weight=bme_ccc_loss_weight,
            bme_ccc_floor=bme_ccc_floor,
            bme_ccc_min_points=bme_ccc_min_points,
            bme_ccc_family_weight_mode=bme_ccc_family_weight_mode,
            bme_ccc_dual_gap_learning_rate=bme_ccc_dual_gap_learning_rate,
            bme_ccc_dual_gap_max_multiplier=bme_ccc_dual_gap_max_multiplier,
            bme_ccc_dual_gap_update_every=bme_ccc_dual_gap_update_every,
            bme_ccc_dual_gap_warmup_steps=bme_ccc_dual_gap_warmup_steps,
            bme_ccc_dual_gap_loss_kind=bme_ccc_dual_gap_loss_kind,
            bme_selection_metric=bme_selection_metric,
            bme_ess_floor=bme_ess_floor,
            bme_ess_loss_weight=bme_ess_loss_weight,
            bme_top_mass_cap=bme_top_mass_cap,
            bme_top_mass_loss_weight=bme_top_mass_loss_weight,
            family_names=family_names,
        )
    else:
        oracle = precomputed_oracle
    mask = oracle.get("mask")
    weights = oracle.get("weights")
    diagnostics = dict(oracle.get("diagnostics", {}))
    cell_count = int(diagnostics.get("cell_count", 0))
    if (
        cell_count <= 0
        or not isinstance(mask, torch.Tensor)
        or not isinstance(weights, torch.Tensor)
    ):
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    q = weights.to(device=conformer_phi.device, dtype=conformer_phi.dtype).detach()
    q = q.clamp_min(0.0)
    q = q / q.sum().clamp_min(1.0e-12)
    q_view = q.reshape(q.shape[0], 1, 1)
    finite = torch.isfinite(conformer_phi)
    numerator = (
        torch.where(finite, conformer_phi, torch.zeros_like(conformer_phi)) * q_view
    ).sum(dim=0)
    denominator = (finite.to(dtype=conformer_phi.dtype) * q_view).sum(dim=0)
    witness_prediction = numerator / denominator.clamp_min(1.0e-12)
    floor_loss, floor_metrics = stage_b_family_ccc_floor_loss(
        witness_prediction,
        target_grid,
        mask.to(device=conformer_phi.device, dtype=torch.bool),
        family_floors=floors,
        family_weights=family_weights,
        family_names=family_names,
        loss_weight=weight,
        min_points=min_points,
        gap_power=gap_power,
        worst_family_mix=worst_family_mix,
        macro_floor=macro_floor,
        macro_floor_mix=macro_floor_mix,
        macro_floor_additive=macro_floor_additive,
        low_tail_floor=low_tail_floor,
        low_tail_fraction=low_tail_fraction,
        low_tail_mix=low_tail_mix,
        low_tail_additive=low_tail_additive,
    )
    metrics = {
        f"{prefix}_cells": float(cell_count),
        f"{prefix}_oracle_reused": float(oracle_reused),
        f"{prefix}_ess": float(diagnostics.get("shared_q_oracle_ess", 0.0)),
        f"{prefix}_top_mass": float(
            diagnostics.get("shared_q_oracle_top_mass", 0.0)
        ),
        f"{prefix}_solver_is_bme": float(
            diagnostics.get("shared_q_oracle_solver_is_bme", 0.0)
        ),
        f"{prefix}_loss_weight": float(weight),
        f"{prefix}_floor_family_count": float(
            floor_metrics.get("posterior_family_ccc_floor_loss_families", 0.0)
        ),
        f"{prefix}_floor_active": float(
            floor_metrics.get("posterior_family_ccc_floor_loss_active", 0.0)
        ),
        f"{prefix}_floor_loss_value": float(
            floor_metrics.get("posterior_family_ccc_floor_loss_value", 0.0)
        ),
        f"{prefix}_floor_gap_mean": float(
            floor_metrics.get("posterior_family_ccc_floor_gap_mean", 0.0)
        ),
        f"{prefix}_floor_gap_max": float(
            floor_metrics.get("posterior_family_ccc_floor_gap_max", 0.0)
        ),
    }
    return floor_loss, metrics


def shared_q_oracle_energy_target_loss(
    model_energy: torch.Tensor,
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    oracle_energy_family_weights: dict[str, float] | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    oracle_solver: str = "energy_softmax",
    bme_steps: int = 64,
    bme_learning_rate: float = 0.20,
    bme_kl_weight: float = 0.01,
    bme_likelihood_kind: str = "gaussian",
    bme_student_df: float = 4.0,
    bme_good_bad_outlier_prob: float = 0.05,
    bme_good_bad_bad_scale: float = 8.0,
    bme_reference_offset_l2: float = 0.0,
    bme_reference_offset_learning_rate: float = 0.05,
    bme_reference_offset_max_abs_ppm: float = 0.0,
    bme_restart_count: int = 0,
    bme_restart_noise: float = 0.0,
    bme_restart_seed: int = 0,
    bme_energy_warmstart_scales: Sequence[float] | None = None,
    bme_ccc_loss_weight: float = 0.0,
    bme_ccc_floor: float = 0.95,
    bme_ccc_min_points: int = 3,
    bme_ccc_family_weight_mode: str = "cell",
    bme_ccc_dual_gap_learning_rate: float = 0.0,
    bme_ccc_dual_gap_max_multiplier: float = 1.0,
    bme_ccc_dual_gap_update_every: int = 1,
    bme_ccc_dual_gap_warmup_steps: int = 0,
    bme_ccc_dual_gap_loss_kind: str = "quadratic",
    bme_selection_metric: str = "objective",
    bme_ess_floor: float = 0.0,
    bme_ess_loss_weight: float = 0.0,
    bme_top_mass_cap: float = 0.0,
    bme_top_mass_loss_weight: float = 0.0,
    target_clip: float = 6.0,
    huber_beta: float = 0.5,
    std_loss_weight: float = 0.0,
    shape_loss_weight: float = 0.0,
    rank_loss_weight: float = 0.0,
    corr_loss_weight: float = 0.0,
    std_huber_beta: float = 0.25,
    shape_huber_beta: float = 0.5,
    rank_margin: float = 0.25,
    rank_top_fraction: float = 0.10,
    temperature: float = 1.0,
    precomputed_oracle: dict[str, Any] | None = None,
    metric_prefix: str = "oracle_energy_target",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Fit ``E_theta`` directly to the oracle posterior log-ratio.

    If the posterior is ``q(k) = softmax(log p(k) - E(k) / T)``, then an oracle
    posterior ``q*`` corresponds to ``E*(k) = T * (log p(k) - log q*(k))`` up
    to an additive constant.  Centering both sides preserves the posterior
    measure while giving the energy head a much stronger learning signal than
    a KL through a nearly-uniform softmax.
    """

    weight = max(float(loss_weight), 0.0)
    prefix = str(metric_prefix or "oracle_energy_target")
    if weight <= 0.0:
        return _zero_loss_like(model_energy), {f"{prefix}_cells": 0.0}
    oracle_reused = precomputed_oracle is not None
    if precomputed_oracle is None:
        oracle = support_reachability_oracle_predictions(
            conformer_phi.detach(),
            target_grid.detach(),
            observed_mask.detach(),
            prior_log_probs=(
                prior_log_probs.detach() if prior_log_probs is not None else None
            ),
            oracle_energy_scale=max(float(oracle_energy_scale), 0.0),
            energy_family_weights=oracle_energy_family_weights,
            oracle_conformer_phi=(
                oracle_conformer_phi.detach()
                if oracle_conformer_phi is not None
                else None
            ),
            oracle_solver=oracle_solver,
            bme_steps=bme_steps,
            bme_learning_rate=bme_learning_rate,
            bme_kl_weight=bme_kl_weight,
            bme_likelihood_kind=bme_likelihood_kind,
            bme_student_df=bme_student_df,
            bme_good_bad_outlier_prob=bme_good_bad_outlier_prob,
            bme_good_bad_bad_scale=bme_good_bad_bad_scale,
            bme_reference_offset_l2=bme_reference_offset_l2,
            bme_reference_offset_learning_rate=bme_reference_offset_learning_rate,
            bme_reference_offset_max_abs_ppm=bme_reference_offset_max_abs_ppm,
            bme_restart_count=bme_restart_count,
            bme_restart_noise=bme_restart_noise,
            bme_restart_seed=bme_restart_seed,
            bme_energy_warmstart_scales=bme_energy_warmstart_scales,
            bme_ccc_loss_weight=bme_ccc_loss_weight,
            bme_ccc_floor=bme_ccc_floor,
            bme_ccc_min_points=bme_ccc_min_points,
            bme_ccc_family_weight_mode=bme_ccc_family_weight_mode,
            bme_ccc_dual_gap_learning_rate=bme_ccc_dual_gap_learning_rate,
            bme_ccc_dual_gap_max_multiplier=bme_ccc_dual_gap_max_multiplier,
            bme_ccc_dual_gap_update_every=bme_ccc_dual_gap_update_every,
            bme_ccc_dual_gap_warmup_steps=bme_ccc_dual_gap_warmup_steps,
            bme_ccc_dual_gap_loss_kind=bme_ccc_dual_gap_loss_kind,
            bme_selection_metric=bme_selection_metric,
            bme_ess_floor=bme_ess_floor,
            bme_ess_loss_weight=bme_ess_loss_weight,
            bme_top_mass_cap=bme_top_mass_cap,
            bme_top_mass_loss_weight=bme_top_mass_loss_weight,
        )
    else:
        oracle = precomputed_oracle
    diagnostics = dict(oracle.get("diagnostics", {}))
    cell_count = int(diagnostics.get("cell_count", 0))
    teacher_weights = oracle.get("weights")
    if cell_count <= 0 or not isinstance(teacher_weights, torch.Tensor):
        return _zero_loss_like(model_energy), {f"{prefix}_cells": 0.0}
    teacher = teacher_weights.to(device=model_energy.device, dtype=model_energy.dtype)
    teacher = teacher.clamp_min(1.0e-10)
    if prior_log_probs is None:
        prior_log = torch.zeros_like(model_energy)
    else:
        prior_log = prior_log_probs.to(device=model_energy.device, dtype=model_energy.dtype)
    target_energy = max(float(temperature), 1.0e-6) * (prior_log - torch.log(teacher))
    target_energy = target_energy - target_energy.mean()
    clip_value = max(float(target_clip), 0.0)
    if clip_value > 0.0:
        target_energy = target_energy.clamp(min=-clip_value, max=clip_value)
    predicted_energy = model_energy - model_energy.mean()
    beta = max(float(huber_beta), 1.0e-6)
    base_loss = F.smooth_l1_loss(
        predicted_energy,
        target_energy.detach(),
        beta=beta,
        reduction="mean",
    )
    predicted_std = predicted_energy.std(unbiased=False)
    target_std = target_energy.detach().std(unbiased=False)
    std_loss = _zero_loss_like(predicted_energy)
    std_weight = max(float(std_loss_weight), 0.0)
    if std_weight > 0.0:
        eps = predicted_energy.new_tensor(1.0e-6)
        std_loss = F.smooth_l1_loss(
            torch.log(predicted_std.clamp_min(eps)),
            torch.log(target_std.clamp_min(eps)),
            beta=max(float(std_huber_beta), 1.0e-6),
            reduction="mean",
        )
    shape_loss = _zero_loss_like(predicted_energy)
    shape_weight = max(float(shape_loss_weight), 0.0)
    target_z = target_energy.detach() / target_std.clamp_min(1.0e-6)
    predicted_z = predicted_energy / predicted_std.clamp_min(1.0e-6)
    corr = torch.mean(predicted_z * target_z.detach())
    corr_loss = _zero_loss_like(predicted_energy)
    corr_weight = max(float(corr_loss_weight), 0.0)
    if corr_weight > 0.0:
        corr_loss = (1.0 - corr).clamp_min(0.0)
    if shape_weight > 0.0:
        shape_loss = F.smooth_l1_loss(
            predicted_z,
            target_z,
            beta=max(float(shape_huber_beta), 1.0e-6),
            reduction="mean",
        )
    rank_loss = _zero_loss_like(predicted_energy)
    rank_gap = predicted_energy.new_tensor(0.0)
    rank_weight = max(float(rank_loss_weight), 0.0)
    if rank_weight > 0.0 and int(predicted_energy.numel()) >= 2:
        support_count = int(predicted_energy.numel())
        rank_count = min(
            max(int(round(support_count * max(float(rank_top_fraction), 0.0))), 1),
            support_count // 2,
        )
        if rank_count > 0:
            high_q_indices = torch.topk(-target_energy.detach(), rank_count).indices
            low_q_indices = torch.topk(target_energy.detach(), rank_count).indices
            high_q_energy = predicted_energy.index_select(0, high_q_indices)
            low_q_energy = predicted_energy.index_select(0, low_q_indices)
            pair_gap = low_q_energy[:, None] - high_q_energy[None, :]
            rank_gap = pair_gap.detach().mean()
            rank_loss = torch.relu(
                predicted_energy.new_tensor(max(float(rank_margin), 0.0)) - pair_gap
            ).mean()
    loss = (
        base_loss
        + std_weight * std_loss
        + shape_weight * shape_loss
        + rank_weight * rank_loss
        + corr_weight * corr_loss
    )
    energy_mae = torch.mean(torch.abs(predicted_energy.detach() - target_energy.detach()))
    metrics = {
        f"{prefix}_cells": float(cell_count),
        f"{prefix}_loss_value": float(loss.detach().cpu()),
        f"{prefix}_base_loss_value": float(base_loss.detach().cpu()),
        f"{prefix}_std_loss_value": float(std_loss.detach().cpu()),
        f"{prefix}_std_loss_weight": float(std_weight),
        f"{prefix}_shape_loss_value": float(shape_loss.detach().cpu()),
        f"{prefix}_shape_loss_weight": float(shape_weight),
        f"{prefix}_corr_loss_value": float(corr_loss.detach().cpu()),
        f"{prefix}_corr_loss_weight": float(corr_weight),
        f"{prefix}_corr": float(corr.detach().cpu()),
        f"{prefix}_rank_loss_value": float(rank_loss.detach().cpu()),
        f"{prefix}_rank_loss_weight": float(rank_weight),
        f"{prefix}_rank_gap": float(rank_gap.detach().cpu()),
        f"{prefix}_energy_mae": float(energy_mae.detach().cpu()),
        f"{prefix}_target_std": float(target_std.detach().cpu()),
        f"{prefix}_target_range": float(
            (target_energy.detach().max() - target_energy.detach().min()).cpu()
        ),
        f"{prefix}_predicted_std": float(predicted_std.detach().cpu()),
        f"{prefix}_teacher_ess": float(diagnostics.get("shared_q_oracle_ess", 0.0)),
        f"{prefix}_teacher_top_mass": float(
            diagnostics.get("shared_q_oracle_top_mass", 0.0)
        ),
        f"{prefix}_source_is_sidecar": float(
            diagnostics.get("shared_q_oracle_source_is_sidecar", 0.0)
        ),
        f"{prefix}_support_coverage_mean": float(
            diagnostics.get("shared_q_oracle_support_coverage_mean", 1.0)
        ),
        f"{prefix}_solver_is_bme": float(
            diagnostics.get("shared_q_oracle_solver_is_bme", 0.0)
        ),
        f"{prefix}_oracle_reused": float(oracle_reused),
    }
    for key, value in diagnostics.items():
        key_text = str(key)
        if key_text.startswith("shared_q_oracle_bme"):
            metrics[f"{prefix}_{key.replace('shared_q_oracle_', '')}"] = float(value)
        if key_text.startswith("external_global_family_teacher"):
            metrics[f"{prefix}_{key_text}"] = float(value)
    return loss * weight, metrics


def shared_q_oracle_contrastive_energy_loss(
    model_energy: torch.Tensor,
    student_weights: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    loss_weight: float = 0.0,
    margin: float = 0.04,
    hard_negative_fraction: float = 0.02,
    positive_mass_weight: float = 0.0,
    temperature: float = 1.0,
    precomputed_oracle: dict[str, Any] | None = None,
    metric_prefix: str = "oracle_contrastive_energy",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Push external shared-q positives below hard negative conformers.

    A sparse exported teacher can put nonzero mass on only a few candidates in a
    large BioEmu support.  KL still sees the positives, but the negative side of
    the simplex is diffuse.  This loss adds a direct dual-margin pressure on
    the energy landscape while keeping one shared posterior q.
    """

    weight = max(float(loss_weight), 0.0)
    prefix = str(metric_prefix or "oracle_contrastive_energy")
    if weight <= 0.0 or precomputed_oracle is None:
        return _zero_loss_like(model_energy), {f"{prefix}_positive_count": 0.0}
    teacher_weights = precomputed_oracle.get("weights")
    if not isinstance(teacher_weights, torch.Tensor):
        return _zero_loss_like(model_energy), {f"{prefix}_positive_count": 0.0}
    teacher = teacher_weights.to(device=model_energy.device, dtype=model_energy.dtype)
    if teacher.shape != model_energy.shape:
        return _zero_loss_like(model_energy), {f"{prefix}_positive_count": 0.0}
    positive_mask = teacher > 0.0
    positive_count = int(torch.count_nonzero(positive_mask).detach().cpu())
    negative_count = int(model_energy.numel()) - positive_count
    if positive_count <= 0 or negative_count <= 0:
        return _zero_loss_like(model_energy), {
            f"{prefix}_positive_count": float(positive_count),
            f"{prefix}_negative_count": float(max(negative_count, 0)),
        }

    if prior_log_probs is None:
        prior_log = torch.zeros_like(model_energy)
    else:
        prior_log = prior_log_probs.to(device=model_energy.device, dtype=model_energy.dtype)
    temp = max(float(temperature), 1.0e-6)
    effective_energy = model_energy - temp * prior_log
    effective_energy = effective_energy - effective_energy.mean()

    pos_energy = effective_energy[positive_mask]
    neg_energy = effective_energy[~positive_mask]
    pos_teacher = teacher[positive_mask].clamp_min(0.0)
    pos_teacher = pos_teacher / pos_teacher.sum().clamp_min(1.0e-12)
    hard_fraction = min(max(float(hard_negative_fraction), 0.0), 1.0)
    hard_count = min(
        max(int(round(float(negative_count) * hard_fraction)), 1),
        int(negative_count),
    )
    hard_indices = torch.topk(-neg_energy.detach(), hard_count).indices
    hard_neg_energy = neg_energy.index_select(0, hard_indices)

    gap = hard_neg_energy[:, None] - pos_energy[None, :]
    pair_loss = torch.relu(model_energy.new_tensor(max(float(margin), 0.0)) - gap)
    weighted_pair_loss = torch.sum(
        pair_loss * pos_teacher.reshape(1, -1), dim=1
    ).mean()

    student = student_weights.to(device=model_energy.device, dtype=model_energy.dtype)
    positive_mass = student[positive_mask].sum().clamp_min(1.0e-12)
    mass_weight = max(float(positive_mass_weight), 0.0)
    positive_mass_loss = -torch.log(positive_mass)
    loss = weighted_pair_loss + mass_weight * positive_mass_loss

    weighted_positive_energy = torch.sum(pos_energy.detach() * pos_teacher.detach())
    hard_negative_energy_mean = hard_neg_energy.detach().mean()
    metrics = {
        f"{prefix}_loss_value": float(loss.detach().cpu()),
        f"{prefix}_pair_loss_value": float(weighted_pair_loss.detach().cpu()),
        f"{prefix}_positive_mass_loss_value": float(
            positive_mass_loss.detach().cpu()
        ),
        f"{prefix}_positive_mass_loss_weight": float(mass_weight),
        f"{prefix}_positive_mass": float(positive_mass.detach().cpu()),
        f"{prefix}_positive_count": float(positive_count),
        f"{prefix}_negative_count": float(negative_count),
        f"{prefix}_hard_negative_count": float(hard_count),
        f"{prefix}_margin": float(max(float(margin), 0.0)),
        f"{prefix}_hard_negative_fraction": float(hard_fraction),
        f"{prefix}_weighted_positive_energy": float(weighted_positive_energy.cpu()),
        f"{prefix}_hard_negative_energy_mean": float(
            hard_negative_energy_mean.cpu()
        ),
        f"{prefix}_mean_gap": float(gap.detach().mean().cpu()),
        f"{prefix}_min_gap": float(gap.detach().min().cpu()),
    }
    diagnostics = precomputed_oracle.get("diagnostics", {})
    if isinstance(diagnostics, dict):
        metrics[f"{prefix}_teacher_ess"] = float(
            diagnostics.get("shared_q_oracle_ess", 0.0)
        )
        metrics[f"{prefix}_teacher_top_mass"] = float(
            diagnostics.get("shared_q_oracle_top_mass", 0.0)
        )
        metrics[f"{prefix}_support_coverage_mean"] = float(
            diagnostics.get("shared_q_oracle_support_coverage_mean", 0.0)
        )
    return loss * weight, metrics


def sidecar_pair_rank_energy_target_loss(
    model_energy: torch.Tensor,
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    loss_weight: float = 0.0,
    pair_weights: dict[str, float] | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    rank_top_fraction: float = 0.10,
    rank_margin: float = 0.15,
    imbalance_weight: float = 0.25,
    min_cells_per_family: int = 1,
    metric_prefix: str = "sidecar_pair_rank_energy_target",
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Rank energy by C'/HN co-satisfaction without exporting pair-specific q.

    The shared-q energy target can become nearly flat when the BME posterior is
    broad.  This auxiliary target instead builds a rank-normalized Pareto score
    from UCBShift-passed sidecar residuals for configured family pairs.  It only
    updates the scalar conformer energy, so inference still emits one shared
    posterior population.
    """

    weight = max(float(loss_weight), 0.0)
    prefix = str(metric_prefix or "sidecar_pair_rank_energy_target")
    if weight <= 0.0:
        return _zero_loss_like(model_energy), {f"{prefix}_pairs": 0.0}
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    if int(model_energy.numel()) != int(conformer_phi.shape[0]):
        raise ValueError("model_energy must have one value per conformer")
    teacher_phi = conformer_phi.detach()
    if oracle_conformer_phi is not None:
        if oracle_conformer_phi.shape != conformer_phi.shape:
            raise ValueError("oracle_conformer_phi must match conformer_phi")
        teacher_phi = oracle_conformer_phi.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        ).detach()
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")

    configured_pairs = pair_weights or {"C'->HN": 1.0, "HN->C'": 1.0}
    family_count = min(int(conformer_phi.shape[-1]), len(family_names))
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: int(conformer_phi.shape[-1])]
    ).clamp_min(1.0e-3)
    support_count = int(conformer_phi.shape[0])

    def _family_residual_energy(family_index: int) -> torch.Tensor:
        family_mask = mask[:, family_index]
        finite_cells = int(torch.count_nonzero(family_mask).detach().cpu())
        if finite_cells < max(int(min_cells_per_family), 1):
            return conformer_phi.new_full((support_count,), float("nan"))
        values = teacher_phi[:, :, family_index]
        targets = target[:, family_index].reshape(1, -1)
        finite = torch.isfinite(values) & family_mask.reshape(1, -1)
        counts = finite.to(dtype=conformer_phi.dtype).sum(dim=1)
        residual = (values - targets) / scales[family_index]
        energy = torch.sum(
            torch.where(finite, residual.square(), torch.zeros_like(residual)),
            dim=1,
        ) / counts.clamp_min(1.0)
        enough = counts >= max(int(min_cells_per_family), 1)
        return torch.where(
            enough,
            energy,
            conformer_phi.new_full((support_count,), float("nan")),
        )

    def _rank01(values: torch.Tensor, valid: torch.Tensor) -> torch.Tensor:
        ranks = torch.zeros_like(values)
        count = int(torch.count_nonzero(valid).detach().cpu())
        if count <= 1:
            return ranks
        valid_indices = torch.nonzero(valid, as_tuple=False).flatten()
        ordered = valid_indices[
            torch.argsort(values.index_select(0, valid_indices), stable=True)
        ]
        rank_values = torch.arange(count, device=values.device, dtype=values.dtype)
        ranks = ranks.scatter(0, ordered, rank_values / float(count - 1))
        return ranks

    predicted = model_energy.reshape(-1).to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    finite_pred = torch.isfinite(predicted)
    weighted_loss = model_energy.new_tensor(0.0)
    weight_sum = 0.0
    pair_total = 0
    conformer_total = 0
    gap_values: list[torch.Tensor] = []
    target_std_values: list[torch.Tensor] = []
    active_labels: list[str] = []
    hn_pair_count = 0
    cprime_pair_count = 0

    for pair_key, raw_pair_weight in configured_pairs.items():
        pair_weight = max(float(raw_pair_weight), 0.0)
        if pair_weight <= 0.0:
            continue
        parsed = _parse_cooccurrence_pair_key(str(pair_key), family_names=family_names)
        if parsed is None:
            continue
        source_index, target_index = parsed
        if source_index >= family_count or target_index >= family_count:
            continue
        source_energy = _family_residual_energy(source_index)
        target_energy = _family_residual_energy(target_index)
        valid = finite_pred & torch.isfinite(source_energy) & torch.isfinite(target_energy)
        valid_count = int(torch.count_nonzero(valid).detach().cpu())
        if valid_count < 4:
            continue
        source_rank = _rank01(source_energy.detach(), valid)
        target_rank = _rank01(target_energy.detach(), valid)
        pair_target = torch.maximum(source_rank, target_rank)
        pair_target = pair_target + max(float(imbalance_weight), 0.0) * torch.abs(
            source_rank - target_rank
        )
        pair_target = torch.where(valid, pair_target, torch.zeros_like(pair_target))
        rank_count = min(
            max(int(round(valid_count * max(float(rank_top_fraction), 0.0))), 1),
            valid_count // 2,
        )
        if rank_count <= 0:
            continue
        valid_indices = torch.nonzero(valid, as_tuple=False).flatten()
        valid_targets = pair_target.index_select(0, valid_indices)
        good_indices = valid_indices[torch.topk(-valid_targets, rank_count).indices]
        bad_indices = valid_indices[torch.topk(valid_targets, rank_count).indices]
        centered_pred = predicted - predicted[valid].mean()
        good_energy = centered_pred.index_select(0, good_indices)
        bad_energy = centered_pred.index_select(0, bad_indices)
        pair_gap = bad_energy[:, None] - good_energy[None, :]
        pair_loss = torch.relu(
            predicted.new_tensor(max(float(rank_margin), 0.0)) - pair_gap
        ).mean()
        weighted_loss = weighted_loss + pair_loss * pair_weight
        weight_sum += pair_weight
        pair_total += 1
        conformer_total += valid_count
        gap_values.append(pair_gap.detach().mean())
        target_std_values.append(pair_target[valid].detach().std(unbiased=False))
        source_name = str(family_names[source_index])
        target_name = str(family_names[target_index])
        active_labels.append(f"{source_name}->{target_name}")
        if source_name == "HN" or target_name == "HN":
            hn_pair_count += 1
        if source_name == "C'" or target_name == "C'":
            cprime_pair_count += 1

    if pair_total <= 0 or weight_sum <= 0.0:
        return _zero_loss_like(model_energy), {f"{prefix}_pairs": 0.0}
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        f"{prefix}_pairs": float(pair_total),
        f"{prefix}_active_pair_count": float(len(set(active_labels))),
        f"{prefix}_conformers": float(conformer_total),
        f"{prefix}_loss_value": float(loss.detach().cpu()),
        f"{prefix}_rank_gap": float(torch.mean(torch.stack(gap_values)).detach().cpu()),
        f"{prefix}_target_std": float(
            torch.mean(torch.stack(target_std_values)).detach().cpu()
        ),
        f"{prefix}_rank_top_fraction": float(max(float(rank_top_fraction), 0.0)),
        f"{prefix}_rank_margin": float(max(float(rank_margin), 0.0)),
        f"{prefix}_imbalance_weight": float(max(float(imbalance_weight), 0.0)),
        f"{prefix}_hn_pair_count": float(hn_pair_count),
        f"{prefix}_cprime_pair_count": float(cprime_pair_count),
        f"{prefix}_source_is_sidecar": float(oracle_conformer_phi is not None),
    }
    return loss * weight, metrics


def sidecar_weighted_observable_loss(
    sidecar_phi: torch.Tensor,
    weights: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    loss_weight: float = 0.0,
    ccc_loss_weight: float = 0.0,
    ccc_floor_loss_weight: float = 0.0,
    family_ccc_floors: dict[str, float] | None = None,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    min_points: int = 3,
    metric_prefix: str = "sidecar_weighted_observable",
    detach_sidecar: bool = True,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train q through the actual UCBShift-sidecar ensemble observable."""

    prefix = str(metric_prefix or "sidecar_weighted_observable")
    mse_weight = max(float(loss_weight), 0.0)
    ccc_weight = max(float(ccc_loss_weight), 0.0)
    floor_weight = max(float(ccc_floor_loss_weight), 0.0)
    if sidecar_phi.ndim != 3:
        return _zero_loss_like(weights), {f"{prefix}_cells": 0.0}
    sidecar = sidecar_phi.to(device=weights.device, dtype=weights.dtype)
    if detach_sidecar:
        sidecar = sidecar.detach()
    sidecar_ensemble = finite_weighted_ensemble_observable(sidecar, weights)
    total = _zero_loss_like(sidecar_ensemble)
    metrics: dict[str, float] = {}
    if mse_weight > 0.0:
        mse_loss, cells = stage_b_family_balanced_ensemble_loss(
            sidecar_ensemble,
            target_grid,
            observed_mask,
            family_weights=family_weights,
            family_names=family_names,
        )
        total = total + mse_loss * mse_weight
        metrics.update(
            {
                f"{prefix}_cells": float(cells),
                f"{prefix}_mse_loss_value": float(mse_loss.detach().cpu()),
                f"{prefix}_mse_loss_weight": float(mse_weight),
            }
        )
    if ccc_weight > 0.0:
        ccc_loss, ccc_metrics = stage_b_family_balanced_ccc_loss(
            sidecar_ensemble,
            target_grid,
            observed_mask,
            family_weights=family_weights,
            family_names=family_names,
            loss_weight=ccc_weight,
            min_points=min_points,
        )
        total = total + ccc_loss
        metrics.update(
            {
                f"{prefix}_ccc_loss_value": float(
                    ccc_metrics.get("posterior_family_ccc_loss_value", 0.0)
                ),
                f"{prefix}_ccc_proxy_mean": float(
                    ccc_metrics.get("posterior_family_ccc_proxy_mean", 0.0)
                ),
                f"{prefix}_ccc_proxy_min": float(
                    ccc_metrics.get("posterior_family_ccc_proxy_min", 0.0)
                ),
                f"{prefix}_ccc_loss_weight": float(ccc_weight),
            }
        )
    if floor_weight > 0.0 and family_ccc_floors:
        floor_loss, floor_metrics = stage_b_family_ccc_floor_loss(
            sidecar_ensemble,
            target_grid,
            observed_mask,
            family_floors=family_ccc_floors,
            family_weights=family_weights,
            family_names=family_names,
            loss_weight=floor_weight,
            min_points=min_points,
        )
        total = total + floor_loss
        metrics.update(
            {
                f"{prefix}_ccc_floor_loss_value": float(
                    floor_metrics.get("posterior_family_ccc_floor_loss_value", 0.0)
                ),
                f"{prefix}_ccc_floor_gap_mean": float(
                    floor_metrics.get("posterior_family_ccc_floor_gap_mean", 0.0)
                ),
                f"{prefix}_ccc_floor_gap_max": float(
                    floor_metrics.get("posterior_family_ccc_floor_gap_max", 0.0)
                ),
                f"{prefix}_ccc_floor_loss_active": float(
                    floor_metrics.get("posterior_family_ccc_floor_loss_active", 0.0)
                ),
                f"{prefix}_ccc_floor_loss_weight": float(floor_weight),
            }
        )
    if not metrics:
        metrics[f"{prefix}_cells"] = 0.0
    return total, metrics


def sidecar_family_affine_calibrated_grid(
    sidecar_phi: torch.Tensor,
    model: nn.Module,
    *,
    metric_prefix: str = "sidecar_family_affine_calibration",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Apply the decoder family affine chart to a UCBShift sidecar grid.

    The operation is intentionally tiny: one bounded scale and shift per atom
    family. It gives the shared-q objective a trainable observable calibration
    path without adding decoder capacity or changing the BioEmu support.
    """

    prefix = str(metric_prefix or "sidecar_family_affine_calibration")
    decoder = getattr(model, "decoder", None)
    required = (
        "family_affine_scale_delta",
        "family_affine_shift_delta",
        "family_ppm_centers",
        "family_affine_family_scale",
    )
    if decoder is None or not all(hasattr(decoder, name) for name in required):
        return sidecar_phi, {f"{prefix}_enabled": 0.0, f"{prefix}_active": 0.0}

    scale_cap = float(getattr(decoder, "family_affine_scale_cap", 0.0))
    shift_cap = float(getattr(decoder, "family_affine_shift_cap_ppm", 0.0))
    if scale_cap <= 0.0 and shift_cap <= 0.0:
        return sidecar_phi, {f"{prefix}_enabled": 1.0, f"{prefix}_active": 0.0}

    dtype = sidecar_phi.dtype
    device = sidecar_phi.device
    raw_scale = decoder.family_affine_scale_delta.to(device=device, dtype=dtype)
    raw_shift = decoder.family_affine_shift_delta.to(device=device, dtype=dtype)
    family_scale = decoder.family_affine_family_scale.to(device=device, dtype=dtype)
    centers = decoder.family_ppm_centers.to(device=device, dtype=dtype)
    view_shape = (1,) * (sidecar_phi.ndim - 1) + (sidecar_phi.shape[-1],)
    scale = 1.0 + torch.tanh(raw_scale) * scale_cap * family_scale
    shift = torch.tanh(raw_shift) * shift_cap * family_scale
    calibrated = centers.reshape(view_shape) + (
        sidecar_phi - centers.reshape(view_shape)
    ) * scale.reshape(view_shape) + shift.reshape(view_shape)

    metrics = {
        f"{prefix}_enabled": 1.0,
        f"{prefix}_active": 1.0,
        f"{prefix}_scale_delta_abs_mean": float(raw_scale.detach().abs().mean().cpu()),
        f"{prefix}_scale_delta_abs_max": float(raw_scale.detach().abs().max().cpu()),
        f"{prefix}_scale_deviation_abs_mean": float(
            (scale.detach() - 1.0).abs().mean().cpu()
        ),
        f"{prefix}_shift_delta_abs_mean": float(raw_shift.detach().abs().mean().cpu()),
        f"{prefix}_shift_delta_abs_max": float(raw_shift.detach().abs().max().cpu()),
        f"{prefix}_shift_abs_mean": float(shift.detach().abs().mean().cpu()),
    }
    return calibrated, metrics


def sidecar_evidence_reference_offset_calibrated_grid(
    sidecar_phi: torch.Tensor,
    weights: torch.Tensor,
    evidence_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    max_abs_ppm: float,
    family_scales: dict[str, float] | None = None,
    strength: float = 1.0,
    min_rows: int = 2,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    metric_prefix: str = "sidecar_evidence_reference_offset",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Apply an evidence-only family reference offset to a sidecar grid.

    Chemical shifts are experiment-level ensemble observables; a small
    entry/family referencing correction should be inferred from conditioning
    rows only, never from the masked supervised rows used to score CCC.
    """

    prefix = str(metric_prefix or "sidecar_evidence_reference_offset")
    max_abs = max(float(max_abs_ppm), 0.0)
    if (
        sidecar_phi.ndim != 3
        or weights.ndim != 1
        or evidence_grid.ndim != 2
        or observed_mask.ndim != 2
        or max_abs <= 0.0
    ):
        return sidecar_phi, {f"{prefix}_enabled": float(max_abs > 0.0), f"{prefix}_active": 0.0}
    if sidecar_phi.shape[0] != weights.shape[0]:
        return sidecar_phi, {f"{prefix}_enabled": 1.0, f"{prefix}_active": 0.0}
    if evidence_grid.shape != observed_mask.shape or evidence_grid.shape != sidecar_phi.shape[1:]:
        raise ValueError("evidence_grid and observed_mask must match sidecar_phi [L,F]")

    dtype = sidecar_phi.dtype
    device = sidecar_phi.device
    sidecar_detached = sidecar_phi.detach()
    weights_detached = weights.detach().to(device=device, dtype=dtype)
    evidence = evidence_grid.to(device=device, dtype=dtype)
    observed = observed_mask.to(device=device, dtype=torch.bool)
    ensemble = finite_weighted_ensemble_observable(sidecar_detached, weights_detached)

    offset = torch.zeros(sidecar_phi.shape[-1], device=device, dtype=dtype)
    family_scales = dict(family_scales or {})
    active_families = 0
    total_cells = 0
    offsets_for_metrics: list[torch.Tensor] = []
    min_required = max(int(min_rows), 1)
    for family_index, family_name in enumerate(tuple(family_names)):
        if family_index >= sidecar_phi.shape[-1]:
            break
        mask = observed[:, family_index] & torch.isfinite(evidence[:, family_index])
        mask = mask & torch.isfinite(ensemble[:, family_index])
        cells = int(mask.sum().detach().cpu())
        if cells < min_required:
            continue
        scale = max(float(family_scales.get(str(family_name), 1.0)), 0.0)
        family_cap = max_abs * scale
        if family_cap <= 0.0:
            continue
        raw_offset = (evidence[:, family_index][mask] - ensemble[:, family_index][mask]).mean()
        family_offset = torch.clamp(raw_offset * float(strength), -family_cap, family_cap)
        offset[family_index] = family_offset
        active_families += 1
        total_cells += cells
        offsets_for_metrics.append(family_offset.detach())

    if active_families <= 0:
        return sidecar_phi, {
            f"{prefix}_enabled": 1.0,
            f"{prefix}_active": 0.0,
            f"{prefix}_family_count": 0.0,
            f"{prefix}_cells": 0.0,
        }

    view_shape = (1,) * (sidecar_phi.ndim - 1) + (sidecar_phi.shape[-1],)
    calibrated = sidecar_phi + offset.reshape(view_shape)
    stacked_offsets = torch.stack(offsets_for_metrics)
    metrics = {
        f"{prefix}_enabled": 1.0,
        f"{prefix}_active": 1.0,
        f"{prefix}_family_count": float(active_families),
        f"{prefix}_cells": float(total_cells),
        f"{prefix}_strength": float(strength),
        f"{prefix}_max_abs_ppm": float(max_abs),
        f"{prefix}_offset_abs_mean": float(stacked_offsets.abs().mean().cpu()),
        f"{prefix}_offset_abs_max": float(stacked_offsets.abs().max().cpu()),
    }
    for family_index, family_name in enumerate(tuple(family_names)):
        if family_index >= offset.shape[0]:
            break
        safe_name = str(family_name).lower().replace("'", "prime")
        metrics[f"{prefix}_{safe_name}_offset_ppm"] = float(offset[family_index].detach().cpu())
    return calibrated, metrics


def finite_weighted_ensemble_observable(
    conformer_observable: torch.Tensor,
    weights: torch.Tensor,
) -> torch.Tensor:
    """Weighted support mean that ignores missing conformer-level sidecar slots."""

    if weights.ndim != 1 or conformer_observable.ndim < 2:
        return weighted_ensemble_observable(conformer_observable, weights)
    if conformer_observable.shape[0] != weights.shape[0]:
        return weighted_ensemble_observable(conformer_observable, weights)
    finite = torch.isfinite(conformer_observable)
    view_shape = (weights.shape[0],) + (1,) * (conformer_observable.ndim - 1)
    weight_view = weights.reshape(view_shape)
    denominator = (weight_view * finite.to(dtype=weights.dtype)).sum(dim=0)
    numerator = (
        torch.where(
            finite,
            conformer_observable,
            torch.zeros_like(conformer_observable),
        )
        * weight_view
    ).sum(dim=0)
    return torch.where(
        denominator > 0.0,
        numerator / denominator.clamp_min(1.0e-12),
        torch.full_like(numerator, float("nan")),
    )


def family_mode_weighted_ensemble_observable(
    conformer_observable: torch.Tensor,
    shared_weights: torch.Tensor,
    mode_component_weights: torch.Tensor | None,
    *,
    family_mode_map: dict[str, int] | None = None,
    blend: float = 1.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Use family-assigned posterior-mode components for observable means.

    The conformer support and conformer-level observable stay unchanged.  Only
    the empirical measure used for each atom-family chart is swapped from the
    exported shared q to the corresponding internal component q.
    """

    base = finite_weighted_ensemble_observable(conformer_observable, shared_weights)
    metrics = {"family_mode_observable_active_families": 0.0}
    if (
        mode_component_weights is None
        or mode_component_weights.ndim != 2
        or conformer_observable.ndim != 3
    ):
        return base, metrics
    if int(mode_component_weights.shape[-1]) != int(shared_weights.numel()):
        return base, metrics
    family_map = family_mode_map or {}
    if not family_map:
        return base, metrics
    alpha = min(max(float(blend), 0.0), 1.0)
    if alpha <= 0.0:
        return base, metrics

    output = base.clone()
    active_count = 0
    ess_values: list[float] = []
    for family_index, family_name in enumerate(family_names):
        if family_index >= output.shape[-1]:
            break
        if family_name not in family_map:
            continue
        mode_index = int(family_map[family_name])
        if mode_index < 0 or mode_index >= int(mode_component_weights.shape[0]):
            continue
        component = mode_component_weights[mode_index].to(
            device=shared_weights.device,
            dtype=shared_weights.dtype,
        )
        component = component / component.sum().clamp_min(1.0e-12)
        component_observable = finite_weighted_ensemble_observable(
            conformer_observable,
            component,
        )
        output[:, family_index] = (
            (1.0 - alpha) * output[:, family_index]
            + alpha * component_observable[:, family_index]
        )
        ess = 1.0 / component.square().sum().clamp_min(1.0e-12)
        ess_values.append(float(ess.detach().cpu()))
        prefix = "cprime" if family_name == "C'" else family_name.lower()
        metrics[f"family_mode_observable_{prefix}_mode"] = float(mode_index)
        metrics[f"family_mode_observable_{prefix}_ess"] = float(ess.detach().cpu())
        metrics[f"family_mode_observable_{prefix}_top_mass"] = float(
            torch.max(component.detach()).cpu()
        )
        active_count += 1
    metrics["family_mode_observable_active_families"] = float(active_count)
    metrics["family_mode_observable_blend"] = float(alpha)
    if ess_values:
        metrics["family_mode_observable_ess_mean"] = float(
            sum(ess_values) / len(ess_values)
        )
    return output, metrics


def residue_local_family_mode_weighted_ensemble_observable(
    conformer_observable: torch.Tensor,
    shared_weights: torch.Tensor,
    mode_component_weights: torch.Tensor | None,
    residue_mode_weights: torch.Tensor | None,
    *,
    family_mode_map: dict[str, int] | None = None,
    blend: float = 1.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Use residue/family-local mixtures over posterior-mode components.

    The component measures remain global ``q_m(k)`` distributions, but each
    residue/family chart can learn a local mixture over those components.  This
    is a compact approximation to ``q(k | residue, family, D)`` without storing
    or training a full ``L x F x K`` posterior tensor.
    """

    base = finite_weighted_ensemble_observable(conformer_observable, shared_weights)
    metrics = {"residue_local_mode_observable_active_families": 0.0}
    if (
        mode_component_weights is None
        or residue_mode_weights is None
        or mode_component_weights.ndim != 2
        or residue_mode_weights.ndim != 3
        or conformer_observable.ndim != 3
    ):
        return base, metrics
    mode_count, support_count = int(mode_component_weights.shape[0]), int(
        mode_component_weights.shape[1]
    )
    residue_count = int(conformer_observable.shape[1])
    family_count = min(int(conformer_observable.shape[2]), len(family_names))
    if int(shared_weights.numel()) != support_count:
        return base, metrics
    if int(residue_mode_weights.shape[0]) != residue_count:
        return base, metrics
    if int(residue_mode_weights.shape[1]) < family_count:
        return base, metrics
    if int(residue_mode_weights.shape[2]) != mode_count:
        return base, metrics
    family_map = family_mode_map or {}
    if not family_map:
        return base, metrics
    alpha = min(max(float(blend), 0.0), 1.0)
    if alpha <= 0.0:
        return base, metrics

    components = mode_component_weights.to(
        device=shared_weights.device,
        dtype=shared_weights.dtype,
    )
    components = components / components.sum(dim=-1, keepdim=True).clamp_min(1.0e-12)
    component_observables = torch.stack(
        [
            finite_weighted_ensemble_observable(conformer_observable, components[index])
            for index in range(mode_count)
        ],
        dim=0,
    )
    local_mode_weights = residue_mode_weights.to(
        device=shared_weights.device,
        dtype=shared_weights.dtype,
    )
    local_mode_weights = local_mode_weights / local_mode_weights.sum(
        dim=-1,
        keepdim=True,
    ).clamp_min(1.0e-12)

    output = base.clone()
    active_count = 0
    entropy_values: list[float] = []
    ess_values: list[float] = []
    top_mass_values: list[float] = []
    for family_index, family_name in enumerate(family_names):
        if family_index >= family_count or family_name not in family_map:
            continue
        component_values = component_observables[:, :, family_index].transpose(0, 1)
        local_mix = local_mode_weights[:, family_index, :]
        local_observable = torch.sum(local_mix * component_values, dim=-1)
        output[:, family_index] = (
            (1.0 - alpha) * output[:, family_index]
            + alpha * local_observable
        )
        with torch.no_grad():
            local_support_weights = torch.matmul(local_mix.detach(), components.detach())
            local_ess = 1.0 / local_support_weights.square().sum(dim=-1).clamp_min(
                1.0e-12
            )
            local_top = local_support_weights.max(dim=-1).values
            local_entropy = -torch.sum(
                local_mix.detach().clamp_min(1.0e-12)
                * local_mix.detach().clamp_min(1.0e-12).log(),
                dim=-1,
            )
            prefix = "cprime" if family_name == "C'" else family_name.lower()
            metrics[f"residue_local_mode_observable_{prefix}_mode_entropy"] = float(
                local_entropy.mean().cpu()
            )
            metrics[f"residue_local_mode_observable_{prefix}_ess"] = float(
                local_ess.mean().cpu()
            )
            metrics[f"residue_local_mode_observable_{prefix}_top_mass"] = float(
                local_top.mean().cpu()
            )
            entropy_values.append(float(local_entropy.mean().cpu()))
            ess_values.append(float(local_ess.mean().cpu()))
            top_mass_values.append(float(local_top.mean().cpu()))
        active_count += 1
    metrics["residue_local_mode_observable_active_families"] = float(active_count)
    metrics["residue_local_mode_observable_blend"] = float(alpha)
    if entropy_values:
        metrics["residue_local_mode_observable_mode_entropy_mean"] = float(
            sum(entropy_values) / len(entropy_values)
        )
        metrics["residue_local_mode_observable_ess_mean"] = float(
            sum(ess_values) / len(ess_values)
        )
        metrics["residue_local_mode_observable_top_mass_mean"] = float(
            sum(top_mass_values) / len(top_mass_values)
        )
    return output, metrics


def residue_local_mode_gate_teacher_loss(
    conformer_observable: torch.Tensor,
    mode_component_weights: torch.Tensor | None,
    residue_mode_logits: torch.Tensor | None,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    family_mode_map: dict[str, int] | None = None,
    oracle_scale: float = 256.0,
    gate_temperature: float = 1.0,
    loss_weight: float = 0.0,
    hard_loss_weight: float = 0.0,
    entropy_loss_weight: float = 0.0,
    entropy_target: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_oracle_scales: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    metric_prefix: str = "residue_local_mode_gate_teacher",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Teach local residue/family gates which posterior mode explains a row.

    The teacher is a compact per-row distribution over existing mode components.
    It closes part of the rowwise-oracle gap without increasing decoder width or
    materializing a full ``L x F x K`` posterior.
    """

    prefix = str(metric_prefix or "residue_local_mode_gate_teacher")
    zero_source = (
        residue_mode_logits
        if isinstance(residue_mode_logits, torch.Tensor)
        else conformer_observable
    )
    weight = max(float(loss_weight), 0.0)
    hard_weight = max(float(hard_loss_weight), 0.0)
    entropy_weight = max(float(entropy_loss_weight), 0.0)
    if weight <= 0.0 and hard_weight <= 0.0 and entropy_weight <= 0.0:
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}
    if (
        mode_component_weights is None
        or residue_mode_logits is None
        or conformer_observable.ndim != 3
        or mode_component_weights.ndim != 2
        or residue_mode_logits.ndim != 3
    ):
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}

    mode_count, support_count = int(mode_component_weights.shape[0]), int(
        mode_component_weights.shape[1]
    )
    residue_count = int(conformer_observable.shape[1])
    family_count = min(int(conformer_observable.shape[2]), len(family_names))
    if (
        int(conformer_observable.shape[0]) != support_count
        or int(residue_mode_logits.shape[0]) != residue_count
        or int(residue_mode_logits.shape[1]) < family_count
        or int(residue_mode_logits.shape[2]) != mode_count
    ):
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}

    family_map = dict(family_mode_map or {})
    if not family_map:
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}
    usable_count = min(
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(target_values.numel()),
        int(row_mask.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}

    device = residue_mode_logits.device
    dtype = residue_mode_logits.dtype
    features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = family_indices[:usable_count].to(device=device).long().clamp(
        min=0,
        max=max(family_count - 1, 0),
    )
    values = target_values[:usable_count].to(device=device, dtype=dtype)
    selected = (
        row_mask[:usable_count].to(device=device, dtype=torch.bool)
        & torch.isfinite(values)
    )
    configured_family_weights = family_weights or {}
    for family_index in torch.unique(families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(
            float(configured_family_weights.get(family_name, 1.0)),
            0.0,
        )
        if family_name not in family_map or family_weight <= 0.0:
            selected = selected & (families != int(family_index))
    if not bool(torch.any(selected)):
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}

    features = features[selected]
    families = families[selected]
    values = values[selected]
    residue_indices = _aligned_residue_indices_from_target_features(
        features,
        residue_count=residue_count,
    )

    components = mode_component_weights.to(device=device, dtype=dtype)
    components = components / components.sum(dim=-1, keepdim=True).clamp_min(1.0e-12)
    component_observables = torch.stack(
        [
            finite_weighted_ensemble_observable(
                conformer_observable.detach().to(device=device, dtype=dtype),
                components[index].detach(),
            )
            for index in range(mode_count)
        ],
        dim=0,
    )
    mode_row_phi = target_aligned_phi_from_residue_family(
        component_observables,
        features,
        families,
    )
    scales = conformer_observable.new_tensor(
        ATOM_FAMILY_PPM_SCALES[:family_count],
        device=device,
        dtype=dtype,
    ).clamp_min(1.0e-3)
    row_scales = scales[families].reshape(1, -1)
    base_oracle_scale = max(float(oracle_scale), 0.0)
    row_oracle_scales = torch.full_like(values, base_oracle_scale)
    configured_family_scales = family_oracle_scales or {}
    row_weights = torch.ones_like(values)
    active_family_names: list[str] = []
    for family_index in torch.unique(families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_scale = max(
            float(configured_family_scales.get(family_name, base_oracle_scale)),
            0.0,
        )
        family_weight = max(
            float(configured_family_weights.get(family_name, 1.0)),
            0.0,
        )
        row_oracle_scales = torch.where(
            families == int(family_index),
            row_oracle_scales.new_full(row_oracle_scales.shape, family_scale),
            row_oracle_scales,
        )
        row_weights = torch.where(
            families == int(family_index),
            row_weights.new_full(row_weights.shape, family_weight),
            row_weights,
        )
        if family_weight > 0.0:
            active_family_names.append(family_name)

    teacher_logits = -row_oracle_scales.reshape(1, -1) * (
        (mode_row_phi.detach() - values.reshape(1, -1)) / row_scales
    ).square()
    teacher = torch.softmax(teacher_logits, dim=0).transpose(0, 1).detach()
    gate_logits = residue_mode_logits[residue_indices, families, :]
    gate_temp = max(float(gate_temperature), 1.0e-3)
    scaled_gate_logits = gate_logits / gate_temp
    gate_log_probs = torch.log_softmax(scaled_gate_logits, dim=-1)
    per_row_loss = -torch.sum(teacher * gate_log_probs, dim=-1)
    valid = row_weights > 0.0
    if not bool(torch.any(valid)):
        return _zero_loss_like(zero_source), {f"{prefix}_cells": 0.0}
    soft_loss = (
        torch.sum(per_row_loss[valid] * row_weights[valid])
        / row_weights[valid].sum().clamp_min(1.0e-12)
    )
    teacher_mode = torch.argmax(teacher, dim=-1)
    hard_row_loss = F.cross_entropy(
        scaled_gate_logits,
        teacher_mode,
        reduction="none",
    )
    hard_loss = (
        torch.sum(hard_row_loss[valid] * row_weights[valid])
        / row_weights[valid].sum().clamp_min(1.0e-12)
    )
    gate_probs_train = torch.softmax(scaled_gate_logits, dim=-1)
    gate_entropy_train = -torch.sum(
        gate_probs_train.clamp_min(1.0e-12)
        * gate_probs_train.clamp_min(1.0e-12).log(),
        dim=-1,
    )
    entropy_target_value = max(float(entropy_target), 0.0)
    entropy_loss = (
        torch.sum(
            F.relu(gate_entropy_train[valid] - entropy_target_value)
            * row_weights[valid]
        )
        / row_weights[valid].sum().clamp_min(1.0e-12)
        if entropy_weight > 0.0 and entropy_target_value > 0.0
        else scaled_gate_logits.new_zeros(())
    )
    total_loss = (
        soft_loss * weight
        + hard_loss * hard_weight
        + entropy_loss * entropy_weight
    )
    gate_probs = gate_probs_train.detach()
    teacher_entropy = -torch.sum(
        teacher.clamp_min(1.0e-12) * teacher.clamp_min(1.0e-12).log(),
        dim=-1,
    )
    gate_entropy = -torch.sum(
        gate_probs.clamp_min(1.0e-12) * gate_probs.clamp_min(1.0e-12).log(),
        dim=-1,
    )
    gate_mode = torch.argmax(gate_probs, dim=-1)
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    hn_valid = valid & (families == hn_index) if hn_index >= 0 else valid & False
    cprime_valid = (
        valid & (families == cprime_index) if cprime_index >= 0 else valid & False
    )
    metrics = {
        f"{prefix}_cells": float(torch.count_nonzero(valid).detach().cpu()),
        f"{prefix}_families": float(len(set(active_family_names))),
        f"{prefix}_loss_value": float(total_loss.detach().cpu()),
        f"{prefix}_soft_loss_value": float(soft_loss.detach().cpu()),
        f"{prefix}_hard_loss_value": float(hard_loss.detach().cpu()),
        f"{prefix}_entropy_loss_value": float(entropy_loss.detach().cpu()),
        f"{prefix}_effective_loss_weight": float(weight),
        f"{prefix}_hard_loss_weight": float(hard_weight),
        f"{prefix}_entropy_loss_weight": float(entropy_weight),
        f"{prefix}_gate_temperature": float(gate_temp),
        f"{prefix}_entropy_target": float(entropy_target_value),
        f"{prefix}_teacher_entropy_mean": float(
            teacher_entropy[valid].mean().detach().cpu()
        ),
        f"{prefix}_gate_entropy_mean": float(gate_entropy[valid].mean().detach().cpu()),
        f"{prefix}_teacher_top_mass_mean": float(
            torch.amax(teacher[valid], dim=-1).mean().detach().cpu()
        ),
        f"{prefix}_gate_top_mass_mean": float(
            torch.amax(gate_probs[valid], dim=-1).mean().detach().cpu()
        ),
        f"{prefix}_mode_accuracy": float(
            torch.mean((teacher_mode[valid] == gate_mode[valid]).float()).detach().cpu()
        ),
        f"{prefix}_scale_mean": float(row_oracle_scales[valid].mean().detach().cpu()),
        f"{prefix}_hn_rows": float(
            torch.count_nonzero(hn_valid).detach().cpu() if hn_index >= 0 else 0.0
        ),
        f"{prefix}_cprime_rows": float(
            torch.count_nonzero(cprime_valid).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        f"{prefix}_hn_mode_accuracy": float(
            torch.mean((teacher_mode[hn_valid] == gate_mode[hn_valid]).float()).detach().cpu()
            if bool(torch.any(hn_valid))
            else 0.0
        ),
        f"{prefix}_cprime_mode_accuracy": float(
            torch.mean(
                (teacher_mode[cprime_valid] == gate_mode[cprime_valid]).float()
            ).detach().cpu()
            if bool(torch.any(cprime_valid))
            else 0.0
        ),
    }
    return total_loss, metrics


def shared_q_oracle_decoder_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    oracle_solver: str = "energy_softmax",
    bme_steps: int = 64,
    bme_learning_rate: float = 0.20,
    bme_kl_weight: float = 0.01,
    bme_likelihood_kind: str = "gaussian",
    bme_student_df: float = 4.0,
    bme_good_bad_outlier_prob: float = 0.05,
    bme_good_bad_bad_scale: float = 8.0,
    bme_reference_offset_l2: float = 0.0,
    bme_reference_offset_learning_rate: float = 0.05,
    bme_reference_offset_max_abs_ppm: float = 0.0,
    bme_restart_count: int = 0,
    bme_restart_noise: float = 0.0,
    bme_restart_seed: int = 0,
    bme_energy_warmstart_scales: Sequence[float] | None = None,
    bme_ccc_loss_weight: float = 0.0,
    bme_ccc_floor: float = 0.95,
    bme_ccc_min_points: int = 3,
    bme_ccc_family_weight_mode: str = "cell",
    bme_ccc_dual_gap_learning_rate: float = 0.0,
    bme_ccc_dual_gap_max_multiplier: float = 1.0,
    bme_ccc_dual_gap_update_every: int = 1,
    bme_ccc_dual_gap_warmup_steps: int = 0,
    bme_ccc_dual_gap_loss_kind: str = "quadratic",
    bme_selection_metric: str = "objective",
    bme_ess_floor: float = 0.0,
    bme_ess_loss_weight: float = 0.0,
    bme_top_mass_cap: float = 0.0,
    bme_top_mass_loss_weight: float = 0.0,
    loss_weight: float = 0.0,
    ccc_loss_weight: float = 0.0,
    ccc_floor_loss_weight: float = 0.0,
    family_ccc_floors: dict[str, float] | None = None,
    family_weights: dict[str, float] | None = None,
    oracle_energy_family_weights: dict[str, float] | None = None,
    min_points: int = 3,
    gap_power: float = 1.0,
    worst_family_mix: float = 0.0,
    macro_floor: float = 0.0,
    macro_floor_mix: float = 0.0,
    macro_floor_additive: bool = False,
    low_tail_floor: float = 0.0,
    low_tail_fraction: float = 0.4,
    low_tail_mix: float = 0.0,
    low_tail_additive: bool = True,
    metric_prefix: str = "shared_oracle_decoder",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Use a detached shared-q oracle to train conformer CS observables.

    Unlike ``shared_q_oracle_distillation_loss``, this loss does not train q
    directly.  It asks the decoder to make ``sum_k q_oracle(k) phi_theta(X_k)``
    match supervised rows, raising the ceiling for one physically shared
    posterior measure while keeping inference free of rowwise oracle weights.
    """

    mse_weight = max(float(loss_weight), 0.0)
    ccc_weight = max(float(ccc_loss_weight), 0.0)
    floor_weight = max(float(ccc_floor_loss_weight), 0.0)
    prefix = str(metric_prefix or "shared_oracle_decoder")
    if mse_weight <= 0.0 and ccc_weight <= 0.0 and floor_weight <= 0.0:
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    oracle = support_reachability_oracle_predictions(
        conformer_phi.detach(),
        target_grid.detach(),
        observed_mask.detach(),
        prior_log_probs=prior_log_probs.detach() if prior_log_probs is not None else None,
        oracle_energy_scale=max(float(oracle_energy_scale), 0.0),
        energy_family_weights=oracle_energy_family_weights,
        oracle_conformer_phi=(
            oracle_conformer_phi.detach() if oracle_conformer_phi is not None else None
        ),
        oracle_solver=oracle_solver,
        bme_steps=bme_steps,
        bme_learning_rate=bme_learning_rate,
        bme_kl_weight=bme_kl_weight,
        bme_likelihood_kind=bme_likelihood_kind,
        bme_student_df=bme_student_df,
        bme_good_bad_outlier_prob=bme_good_bad_outlier_prob,
        bme_good_bad_bad_scale=bme_good_bad_bad_scale,
        bme_reference_offset_l2=bme_reference_offset_l2,
        bme_reference_offset_learning_rate=bme_reference_offset_learning_rate,
        bme_reference_offset_max_abs_ppm=bme_reference_offset_max_abs_ppm,
        bme_restart_count=bme_restart_count,
        bme_restart_noise=bme_restart_noise,
        bme_restart_seed=bme_restart_seed,
        bme_energy_warmstart_scales=bme_energy_warmstart_scales,
        bme_ccc_loss_weight=bme_ccc_loss_weight,
        bme_ccc_floor=bme_ccc_floor,
        bme_ccc_min_points=bme_ccc_min_points,
        bme_ccc_family_weight_mode=bme_ccc_family_weight_mode,
        bme_ccc_dual_gap_learning_rate=bme_ccc_dual_gap_learning_rate,
        bme_ccc_dual_gap_max_multiplier=bme_ccc_dual_gap_max_multiplier,
        bme_ccc_dual_gap_update_every=bme_ccc_dual_gap_update_every,
        bme_ccc_dual_gap_warmup_steps=bme_ccc_dual_gap_warmup_steps,
        bme_ccc_dual_gap_loss_kind=bme_ccc_dual_gap_loss_kind,
        bme_selection_metric=bme_selection_metric,
        bme_ess_floor=bme_ess_floor,
        bme_ess_loss_weight=bme_ess_loss_weight,
        bme_top_mass_cap=bme_top_mass_cap,
        bme_top_mass_loss_weight=bme_top_mass_loss_weight,
    )
    diagnostics = dict(oracle.get("diagnostics", {}))
    cell_count = int(diagnostics.get("cell_count", 0))
    teacher_weights = oracle.get("weights")
    if cell_count <= 0 or not isinstance(teacher_weights, torch.Tensor):
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    teacher_weights = teacher_weights.to(
        device=conformer_phi.device,
        dtype=conformer_phi.dtype,
    ).detach()
    oracle_ensemble_phi = weighted_ensemble_observable(conformer_phi, teacher_weights)
    base_loss, supervised_points = stage_b_family_balanced_ensemble_loss(
        oracle_ensemble_phi,
        target_grid,
        observed_mask,
        family_weights=family_weights,
    )
    total = base_loss * mse_weight
    metrics = {
        f"{prefix}_cells": float(supervised_points),
        f"{prefix}_loss_value": float(base_loss.detach().cpu()),
        f"{prefix}_loss_weight": float(mse_weight),
        f"{prefix}_ess": float(diagnostics.get("shared_q_oracle_ess", 0.0)),
        f"{prefix}_top_mass": float(
            diagnostics.get("shared_q_oracle_top_mass", 0.0)
        ),
        f"{prefix}_energy_weight_mean": float(
            diagnostics.get("shared_q_oracle_energy_weight_mean", 1.0)
        ),
        f"{prefix}_energy_weight_max": float(
            diagnostics.get("shared_q_oracle_energy_weight_max", 1.0)
        ),
        f"{prefix}_source_is_sidecar": float(
            diagnostics.get("shared_q_oracle_source_is_sidecar", 0.0)
        ),
        f"{prefix}_support_coverage_mean": float(
            diagnostics.get("shared_q_oracle_support_coverage_mean", 1.0)
        ),
        f"{prefix}_solver_is_bme": float(
            diagnostics.get("shared_q_oracle_solver_is_bme", 0.0)
        ),
    }
    for key, value in diagnostics.items():
        if str(key).startswith("shared_q_oracle_bme"):
            metrics[f"{prefix}_{key.replace('shared_q_oracle_', '')}"] = float(value)
    if ccc_weight > 0.0:
        ccc_loss, ccc_metrics = stage_b_family_balanced_ccc_loss(
            oracle_ensemble_phi,
            target_grid,
            observed_mask,
            family_weights=family_weights,
            loss_weight=ccc_weight,
            min_points=min_points,
        )
        total = total + ccc_loss
        metrics.update(
            {
                f"{prefix}_ccc_loss_value": float(
                    ccc_metrics.get("posterior_family_ccc_loss_value", 0.0)
                ),
                f"{prefix}_ccc_proxy_mean": float(
                    ccc_metrics.get("posterior_family_ccc_proxy_mean", 0.0)
                ),
                f"{prefix}_ccc_proxy_min": float(
                    ccc_metrics.get("posterior_family_ccc_proxy_min", 0.0)
                ),
                f"{prefix}_ccc_loss_weight": float(ccc_weight),
            }
        )
    if floor_weight > 0.0 and family_ccc_floors:
        floor_loss, floor_metrics = stage_b_family_ccc_floor_loss(
            oracle_ensemble_phi,
            target_grid,
            observed_mask,
            family_floors=family_ccc_floors,
            family_weights=family_weights,
            loss_weight=floor_weight,
            min_points=min_points,
            gap_power=gap_power,
            worst_family_mix=worst_family_mix,
            macro_floor=macro_floor,
            macro_floor_mix=macro_floor_mix,
            macro_floor_additive=macro_floor_additive,
            low_tail_floor=low_tail_floor,
            low_tail_fraction=low_tail_fraction,
            low_tail_mix=low_tail_mix,
            low_tail_additive=low_tail_additive,
        )
        total = total + floor_loss
        metrics.update(
            {
                f"{prefix}_ccc_floor_loss_value": float(
                    floor_metrics.get("posterior_family_ccc_floor_loss_value", 0.0)
                ),
                f"{prefix}_ccc_floor_gap_mean": float(
                    floor_metrics.get("posterior_family_ccc_floor_gap_mean", 0.0)
                ),
                f"{prefix}_ccc_floor_gap_max": float(
                    floor_metrics.get("posterior_family_ccc_floor_gap_max", 0.0)
                ),
                f"{prefix}_ccc_floor_loss_active": float(
                    floor_metrics.get("posterior_family_ccc_floor_loss_active", 0.0)
                ),
                f"{prefix}_ccc_floor_loss_weight": float(floor_weight),
            }
        )
    return total, metrics


def rowwise_oracle_decoder_loss(
    conformer_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_oracle_energy_scales: dict[str, float] | None = None,
    min_teacher_ess: float = 0.0,
    max_teacher_prior_blend: float = 0.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train conformer CS support with detached per-row oracle weights.

    This is a train-only decoder objective.  It builds a detached oracle over
    the fixed x0 support for each supervised row, then updates
    ``phi_theta(X_k)`` so the oracle-weighted conformer observable matches the
    target.  Inference still exports a single shared posterior population and
    predicts only through ``sum_k q_k phi_theta(X_k)``.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"rowwise_oracle_decoder_cells": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    usable_count = min(
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(target_values.numel()),
        int(row_mask.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(conformer_phi), {"rowwise_oracle_decoder_cells": 0.0}
    features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = family_indices[:usable_count].to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values[:usable_count].to(device=device, dtype=dtype)
    selected = (
        row_mask[:usable_count].to(device=device, dtype=torch.bool)
        & torch.isfinite(values)
    )
    if not bool(torch.any(selected)):
        return _zero_loss_like(conformer_phi), {"rowwise_oracle_decoder_cells": 0.0}

    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi,
        features,
        families,
    )[:, selected]
    row_targets = values[selected]
    row_families = families[selected]
    if row_phi.numel() == 0:
        return _zero_loss_like(conformer_phi), {"rowwise_oracle_decoder_cells": 0.0}

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    row_scales = scales[row_families].reshape(1, -1)
    residual = (row_phi.detach() - row_targets.reshape(1, -1)) / row_scales
    base_oracle_scale = max(float(oracle_energy_scale), 0.0)
    row_oracle_scales = torch.full_like(row_targets, base_oracle_scale)
    configured_family_scales = family_oracle_energy_scales or {}
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_scale = max(
            float(configured_family_scales.get(family_name, base_oracle_scale)),
            0.0,
        )
        row_oracle_scales = torch.where(
            row_families == int(family_index),
            row_oracle_scales.new_full(row_oracle_scales.shape, family_scale),
            row_oracle_scales,
        )
    energy = row_oracle_scales.reshape(1, -1) * residual.square()
    logits = -energy
    if prior_log_probs is not None and int(prior_log_probs.numel()) == int(row_phi.shape[0]):
        logits = logits + prior_log_probs.to(device=device, dtype=dtype).reshape(-1, 1)
    raw_teacher_weights = torch.softmax(logits, dim=0).detach()
    raw_ess = 1.0 / raw_teacher_weights.square().sum(dim=0).clamp_min(1.0e-12)
    teacher_weights = raw_teacher_weights
    blend_coefficients = torch.zeros_like(row_targets)
    ess_floor = min(max(float(min_teacher_ess), 0.0), float(row_phi.shape[0]))
    max_prior_blend = max(float(max_teacher_prior_blend), 0.0)
    if ess_floor > 1.0 and max_prior_blend > 0.0:
        if prior_log_probs is not None and int(prior_log_probs.numel()) == int(row_phi.shape[0]):
            base_weights = torch.softmax(
                prior_log_probs.to(device=device, dtype=dtype).reshape(-1, 1),
                dim=0,
            )
        else:
            base_weights = torch.full(
                (int(row_phi.shape[0]), 1),
                1.0 / max(float(row_phi.shape[0]), 1.0),
                device=device,
                dtype=dtype,
            )
        ess_deficit = ((ess_floor - raw_ess) / max(ess_floor - 1.0, 1.0e-6)).clamp(
            min=0.0,
            max=1.0,
        )
        blend_coefficients = (ess_deficit * max_prior_blend).clamp(
            min=0.0,
            max=max_prior_blend,
        )
        teacher_weights = (
            raw_teacher_weights * (1.0 - blend_coefficients.reshape(1, -1))
            + base_weights * blend_coefficients.reshape(1, -1)
        )
        teacher_weights = (
            teacher_weights
            / teacher_weights.sum(dim=0, keepdim=True).clamp_min(1.0e-12)
        ).detach()
    prediction = torch.sum(row_phi * teacher_weights, dim=0)
    normalized_error = (prediction - row_targets) / scales[row_families]

    row_weights = torch.ones_like(normalized_error)
    configured_family_weights = family_weights or {}
    active_family_names: list[str] = []
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        row_weights = torch.where(
            row_families == int(family_index),
            row_weights.new_full(row_weights.shape, family_weight),
            row_weights,
        )
        if family_weight > 0.0:
            active_family_names.append(family_name)
    valid = row_weights > 0.0
    if not bool(torch.any(valid)):
        return _zero_loss_like(conformer_phi), {"rowwise_oracle_decoder_cells": 0.0}
    base_loss = torch.sum(normalized_error[valid].square() * row_weights[valid]) / row_weights[
        valid
    ].sum().clamp_min(1.0e-12)
    ess = 1.0 / teacher_weights.square().sum(dim=0).clamp_min(1.0e-12)
    top_mass = torch.amax(teacher_weights, dim=0)
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    hn_valid = valid & (row_families == hn_index) if hn_index >= 0 else valid & False
    cprime_valid = (
        valid & (row_families == cprime_index) if cprime_index >= 0 else valid & False
    )
    metrics = {
        "rowwise_oracle_decoder_cells": float(torch.count_nonzero(valid).detach().cpu()),
        "rowwise_oracle_decoder_families": float(len(set(active_family_names))),
        "rowwise_oracle_decoder_loss_value": float(base_loss.detach().cpu()),
        "rowwise_oracle_decoder_ess_mean": float(ess[valid].mean().detach().cpu()),
        "rowwise_oracle_decoder_raw_ess_mean": float(
            raw_ess[valid].mean().detach().cpu()
        ),
        "rowwise_oracle_decoder_top_mass_mean": float(top_mass[valid].mean().detach().cpu()),
        "rowwise_oracle_decoder_teacher_blend_mean": float(
            blend_coefficients[valid].mean().detach().cpu()
        ),
        "rowwise_oracle_decoder_scale_mean": float(
            row_oracle_scales[valid].mean().detach().cpu()
        ),
        "rowwise_oracle_decoder_hn_rows": float(
            torch.count_nonzero(row_families[valid] == hn_index).detach().cpu()
            if hn_index >= 0
            else 0.0
        ),
        "rowwise_oracle_decoder_cprime_rows": float(
            torch.count_nonzero(row_families[valid] == cprime_index).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        "rowwise_oracle_decoder_hn_scale": float(
            row_oracle_scales[hn_valid].mean().detach().cpu()
            if bool(torch.any(hn_valid))
            else 0.0
        ),
        "rowwise_oracle_decoder_cprime_scale": float(
            row_oracle_scales[cprime_valid].mean().detach().cpu()
            if bool(torch.any(cprime_valid))
            else 0.0
        ),
        "rowwise_oracle_decoder_hn_ess_mean": float(
            ess[hn_valid].mean().detach().cpu() if bool(torch.any(hn_valid)) else 0.0
        ),
        "rowwise_oracle_decoder_cprime_ess_mean": float(
            ess[cprime_valid].mean().detach().cpu()
            if bool(torch.any(cprime_valid))
            else 0.0
        ),
        "rowwise_oracle_decoder_hn_blend_mean": float(
            blend_coefficients[hn_valid].mean().detach().cpu()
            if bool(torch.any(hn_valid))
            else 0.0
        ),
        "rowwise_oracle_decoder_cprime_blend_mean": float(
            blend_coefficients[cprime_valid].mean().detach().cpu()
            if bool(torch.any(cprime_valid))
            else 0.0
        ),
    }
    return base_loss * weight, metrics


def capacity_adapter_residual_oracle_loss(
    conformer_phi: torch.Tensor,
    adapter_delta_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_oracle_energy_scales: dict[str, float] | None = None,
    target_clip_ppm: float = 0.0,
    min_teacher_ess: float = 0.0,
    max_teacher_prior_blend: float = 0.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
    metric_prefix: str = "capacity_adapter_residual_oracle",
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train only the capacity adapter to explain BMRB-aligned residuals.

    The teacher posterior is detached and train-only.  The supervised target is
    the residual left by the non-adapter conformer observable under that teacher,
    so the adapter learns a conformer-level correction while inference still
    predicts through the single ensemble observable ``sum_k q_k phi_theta(X_k)``.
    """

    weight = max(float(loss_weight), 0.0)
    prefix = str(metric_prefix or "capacity_adapter_residual_oracle")
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_cells": 0.0,
        }
    if conformer_phi.ndim != 3 or adapter_delta_phi.shape != conformer_phi.shape:
        raise ValueError("conformer_phi and adapter_delta_phi must both be [K, L, F]")
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")

    device = conformer_phi.device
    dtype = conformer_phi.dtype
    usable_count = min(
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(target_values.numel()),
        int(row_mask.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_cells": 0.0,
        }

    features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = family_indices[:usable_count].to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values[:usable_count].to(device=device, dtype=dtype)
    selected = (
        row_mask[:usable_count].to(device=device, dtype=torch.bool)
        & torch.isfinite(values)
    )
    if not bool(torch.any(selected)):
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_cells": 0.0,
        }

    baseline_phi = (conformer_phi - adapter_delta_phi).detach()
    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi,
        features,
        families,
    )[:, selected]
    row_baseline = target_aligned_phi_from_residue_family(
        baseline_phi,
        features,
        families,
    )[:, selected]
    row_delta = target_aligned_phi_from_residue_family(
        adapter_delta_phi,
        features,
        families,
    )[:, selected]
    row_targets = values[selected]
    row_families = families[selected]
    if row_delta.numel() == 0:
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_cells": 0.0,
        }

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    row_scales = scales[row_families].reshape(1, -1)
    detached_error = (row_phi.detach() - row_targets.reshape(1, -1)) / row_scales
    base_oracle_scale = max(float(oracle_energy_scale), 0.0)
    row_oracle_scales = torch.full_like(row_targets, base_oracle_scale)
    configured_family_scales = family_oracle_energy_scales or {}
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_scale = max(
            float(configured_family_scales.get(family_name, base_oracle_scale)),
            0.0,
        )
        row_oracle_scales = torch.where(
            row_families == int(family_index),
            row_oracle_scales.new_full(row_oracle_scales.shape, family_scale),
            row_oracle_scales,
        )

    energy = row_oracle_scales.reshape(1, -1) * detached_error.square()
    logits = -energy
    if prior_log_probs is not None and int(prior_log_probs.numel()) == int(row_phi.shape[0]):
        prior_weights = torch.softmax(
            prior_log_probs.to(device=device, dtype=dtype).reshape(-1, 1),
            dim=0,
        )
        logits = logits + prior_log_probs.to(device=device, dtype=dtype).reshape(-1, 1)
    else:
        prior_weights = torch.full(
            (int(row_phi.shape[0]), 1),
            1.0 / max(float(row_phi.shape[0]), 1.0),
            device=device,
            dtype=dtype,
        )
    raw_teacher_weights = torch.softmax(logits, dim=0).detach()
    raw_ess = 1.0 / raw_teacher_weights.square().sum(dim=0).clamp_min(1.0e-12)
    teacher_weights = raw_teacher_weights
    blend_coefficients = torch.zeros_like(row_targets)
    ess_floor = min(max(float(min_teacher_ess), 0.0), float(row_phi.shape[0]))
    max_prior_blend = max(float(max_teacher_prior_blend), 0.0)
    if ess_floor > 1.0 and max_prior_blend > 0.0:
        ess_deficit = ((ess_floor - raw_ess) / max(ess_floor - 1.0, 1.0e-6)).clamp(
            min=0.0,
            max=1.0,
        )
        blend_coefficients = (ess_deficit * max_prior_blend).clamp(
            min=0.0,
            max=max_prior_blend,
        )
        teacher_weights = (
            raw_teacher_weights * (1.0 - blend_coefficients.reshape(1, -1))
            + prior_weights * blend_coefficients.reshape(1, -1)
        )
        teacher_weights = (
            teacher_weights
            / teacher_weights.sum(dim=0, keepdim=True).clamp_min(1.0e-12)
        ).detach()

    baseline_prediction = torch.sum(row_baseline * teacher_weights, dim=0).detach()
    adapter_prediction = torch.sum(row_delta * teacher_weights, dim=0)
    target_delta = row_targets - baseline_prediction
    clip_ppm = max(float(target_clip_ppm), 0.0)
    if clip_ppm > 0.0:
        target_delta = target_delta.clamp(min=-clip_ppm, max=clip_ppm)
    normalized_error = (adapter_prediction - target_delta) / scales[row_families]

    row_weights = torch.ones_like(normalized_error)
    configured_family_weights = family_weights or {}
    active_family_names: list[str] = []
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        row_weights = torch.where(
            row_families == int(family_index),
            row_weights.new_full(row_weights.shape, family_weight),
            row_weights,
        )
        if family_weight > 0.0:
            active_family_names.append(family_name)
    valid = row_weights > 0.0
    if not bool(torch.any(valid)):
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_cells": 0.0,
        }

    base_loss = torch.sum(normalized_error[valid].square() * row_weights[valid]) / row_weights[
        valid
    ].sum().clamp_min(1.0e-12)
    ess = 1.0 / teacher_weights.square().sum(dim=0).clamp_min(1.0e-12)
    top_mass = torch.amax(teacher_weights, dim=0)
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    hn_valid = valid & (row_families == hn_index) if hn_index >= 0 else valid & False
    cprime_valid = (
        valid & (row_families == cprime_index) if cprime_index >= 0 else valid & False
    )
    metrics = {
        f"{prefix}_cells": float(
            torch.count_nonzero(valid).detach().cpu()
        ),
        f"{prefix}_families": float(
            len(set(active_family_names))
        ),
        f"{prefix}_loss_value": float(base_loss.detach().cpu()),
        f"{prefix}_ess_mean": float(
            ess[valid].mean().detach().cpu()
        ),
        f"{prefix}_raw_ess_mean": float(
            raw_ess[valid].mean().detach().cpu()
        ),
        f"{prefix}_top_mass_mean": float(
            top_mass[valid].mean().detach().cpu()
        ),
        f"{prefix}_teacher_blend_mean": float(
            blend_coefficients[valid].mean().detach().cpu()
        ),
        f"{prefix}_target_delta_abs_mean": float(
            target_delta[valid].abs().mean().detach().cpu()
        ),
        f"{prefix}_adapter_delta_abs_mean": float(
            adapter_prediction[valid].abs().mean().detach().cpu()
        ),
        f"{prefix}_hn_rows": float(
            torch.count_nonzero(row_families[valid] == hn_index).detach().cpu()
            if hn_index >= 0
            else 0.0
        ),
        f"{prefix}_cprime_rows": float(
            torch.count_nonzero(row_families[valid] == cprime_index).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        f"{prefix}_hn_target_delta_abs_mean": float(
            target_delta[hn_valid].abs().mean().detach().cpu()
            if bool(torch.any(hn_valid))
            else 0.0
        ),
        f"{prefix}_cprime_target_delta_abs_mean": float(
            target_delta[cprime_valid].abs().mean().detach().cpu()
            if bool(torch.any(cprime_valid))
            else 0.0
        ),
    }
    return base_loss * weight, metrics


def rowwise_support_rank_margin_loss(
    conformer_phi: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_oracle_energy_scales: dict[str, float] | None = None,
    margin: float = 0.05,
    min_teacher_ess: float = 0.0,
    max_teacher_prior_blend: float = 0.0,
    risk_scale: float = 0.0,
    min_context_weight: float = 1.0,
    gap_focus_scale: float = 0.0,
    oracle_conformer_phi: torch.Tensor | None = None,
    metric_prefix: str = "rowwise_support_rank",
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Separate good and bad conformer-level CS support for each target row.

    The detached oracle defines which conformers are currently target-compatible.
    The loss updates only ``phi_theta(X_k)`` so oracle-good conformers become
    closer to the supervised shift than oracle-bad conformers by a small margin.
    No rowwise or family-specific posterior is exported at inference time.
    """

    weight = max(float(loss_weight), 0.0)
    prefix = str(metric_prefix or "rowwise_support_rank")
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    oracle_phi = conformer_phi if oracle_conformer_phi is None else oracle_conformer_phi
    if oracle_phi.shape != conformer_phi.shape:
        raise ValueError("oracle_conformer_phi must match conformer_phi")
    if target_features.ndim != 2:
        raise ValueError("target_features must have shape [T, D]")
    device = conformer_phi.device
    dtype = conformer_phi.dtype
    usable_count = min(
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(target_values.numel()),
        int(row_mask.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = family_indices[:usable_count].to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values[:usable_count].to(device=device, dtype=dtype)
    selected = (
        row_mask[:usable_count].to(device=device, dtype=torch.bool)
        & torch.isfinite(values)
    )
    if not bool(torch.any(selected)):
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}

    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi,
        features,
        families,
    )[:, selected]
    oracle_row_phi = target_aligned_phi_from_residue_family(
        oracle_phi.to(device=device, dtype=dtype),
        features,
        families,
    )[:, selected]
    row_targets = values[selected]
    row_families = families[selected]
    selected_features = features[selected]
    if row_phi.numel() == 0:
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}
    oracle_finite = torch.isfinite(oracle_row_phi)
    if oracle_conformer_phi is not None:
        teacher_supported = torch.count_nonzero(oracle_finite, dim=0) >= 2
        if not bool(torch.any(teacher_supported)):
            return _zero_loss_like(conformer_phi), {
                f"{prefix}_cells": 0.0,
                f"{prefix}_teacher_supported_rows": 0.0,
            }
        row_phi = row_phi[:, teacher_supported]
        oracle_row_phi = oracle_row_phi[:, teacher_supported]
        oracle_finite = oracle_finite[:, teacher_supported]
        row_targets = row_targets[teacher_supported]
        row_families = row_families[teacher_supported]
        selected_features = selected_features[teacher_supported]
    else:
        oracle_finite = torch.ones_like(row_phi, dtype=torch.bool)

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    row_scales = scales[row_families].reshape(1, -1)
    detached_error = (
        oracle_row_phi.detach() - row_targets.reshape(1, -1)
    ) / row_scales
    base_oracle_scale = max(float(oracle_energy_scale), 0.0)
    row_oracle_scales = torch.full_like(row_targets, base_oracle_scale)
    configured_family_scales = family_oracle_energy_scales or {}
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_scale = max(
            float(configured_family_scales.get(family_name, base_oracle_scale)),
            0.0,
        )
        row_oracle_scales = torch.where(
            row_families == int(family_index),
            row_oracle_scales.new_full(row_oracle_scales.shape, family_scale),
            row_oracle_scales,
        )
    energy = row_oracle_scales.reshape(1, -1) * detached_error.square()
    energy = torch.where(
        oracle_finite,
        energy,
        torch.full_like(energy, 1.0e6),
    )
    good_logits = torch.where(
        oracle_finite,
        -energy,
        torch.full_like(energy, -1.0e6),
    )
    if prior_log_probs is not None and int(prior_log_probs.numel()) == int(row_phi.shape[0]):
        prior_logits = prior_log_probs.to(device=device, dtype=dtype).reshape(-1, 1)
        prior_logits = prior_logits.expand_as(good_logits)
        prior_logits = torch.where(
            oracle_finite,
            prior_logits,
            torch.full_like(prior_logits, -1.0e6),
        )
        prior_weights = torch.softmax(prior_logits, dim=0)
        good_logits = good_logits + prior_logits
    else:
        uniform_logits = torch.zeros_like(good_logits)
        uniform_logits = torch.where(
            oracle_finite,
            uniform_logits,
            torch.full_like(uniform_logits, -1.0e6),
        )
        prior_weights = torch.softmax(uniform_logits, dim=0)
    good_weights_raw = torch.softmax(good_logits, dim=0).detach()
    raw_good_ess = 1.0 / good_weights_raw.square().sum(dim=0).clamp_min(1.0e-12)
    good_weights = good_weights_raw
    blend_coefficients = torch.zeros_like(row_targets)
    ess_floor = min(max(float(min_teacher_ess), 0.0), float(row_phi.shape[0]))
    max_prior_blend = max(float(max_teacher_prior_blend), 0.0)
    if ess_floor > 1.0 and max_prior_blend > 0.0:
        ess_deficit = (
            (ess_floor - raw_good_ess) / max(ess_floor - 1.0, 1.0e-6)
        ).clamp(min=0.0, max=1.0)
        blend_coefficients = (ess_deficit * max_prior_blend).clamp(
            min=0.0,
            max=max_prior_blend,
        )
        good_weights = (
            good_weights_raw * (1.0 - blend_coefficients.reshape(1, -1))
            + prior_weights * blend_coefficients.reshape(1, -1)
        )
        good_weights = (
            good_weights
            / good_weights.sum(dim=0, keepdim=True).clamp_min(1.0e-12)
        ).detach()
    bad_logits = torch.where(
        oracle_finite,
        energy.clamp(max=80.0),
        torch.full_like(energy, -1.0e6),
    )
    bad_weights = torch.softmax(bad_logits, dim=0).detach()

    normalized_abs_error = (
        (row_phi - row_targets.reshape(1, -1)) / row_scales
    ).abs()
    good_error = torch.sum(good_weights * normalized_abs_error, dim=0)
    bad_error = torch.sum(bad_weights * normalized_abs_error, dim=0).detach()
    hinge = torch.relu(good_error - bad_error + max(float(margin), 0.0))

    row_weights = torch.ones_like(hinge)
    configured_family_weights = family_weights or {}
    active_family_names: list[str] = []
    for family_index in torch.unique(row_families).detach().cpu().tolist():
        family_name = (
            str(family_names[int(family_index)])
            if int(family_index) < len(family_names)
            else str(int(family_index))
        )
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        row_weights = torch.where(
            row_families == int(family_index),
            row_weights.new_full(row_weights.shape, family_weight),
            row_weights,
        )
        if family_weight > 0.0:
            active_family_names.append(family_name)
    risks = _mechanism_support_row_risk(
        selected_features,
        row_families,
        family_names=family_names,
    )
    context_weights = max(float(min_context_weight), 0.0) + max(float(risk_scale), 0.0) * risks
    gap_focus = 1.0 + max(float(gap_focus_scale), 0.0) * hinge.detach()
    row_weights = row_weights * context_weights * gap_focus
    valid = row_weights > 0.0
    if not bool(torch.any(valid)):
        return _zero_loss_like(conformer_phi), {f"{prefix}_cells": 0.0}

    base_loss = torch.sum(hinge[valid].square() * row_weights[valid]) / row_weights[
        valid
    ].sum().clamp_min(1.0e-12)
    good_ess = 1.0 / good_weights.square().sum(dim=0).clamp_min(1.0e-12)
    bad_ess = 1.0 / bad_weights.square().sum(dim=0).clamp_min(1.0e-12)
    hn_index = family_names.index("HN") if "HN" in family_names else -1
    cprime_index = family_names.index("C'") if "C'" in family_names else -1
    hn_valid = valid & (row_families == hn_index) if hn_index >= 0 else valid & False
    cprime_valid = (
        valid & (row_families == cprime_index) if cprime_index >= 0 else valid & False
    )
    metrics = {
        f"{prefix}_cells": float(torch.count_nonzero(valid).detach().cpu()),
        f"{prefix}_families": float(len(set(active_family_names))),
        f"{prefix}_loss_value": float(base_loss.detach().cpu()),
        f"{prefix}_active_fraction": float(
            (hinge[valid] > 0.0).to(dtype=dtype).mean().detach().cpu()
        ),
        f"{prefix}_gap_mean": float(
            (bad_error[valid] - good_error[valid]).mean().detach().cpu()
        ),
        f"{prefix}_good_error_mean": float(
            good_error[valid].mean().detach().cpu()
        ),
        f"{prefix}_bad_error_mean": float(
            bad_error[valid].mean().detach().cpu()
        ),
        f"{prefix}_good_ess_mean": float(
            good_ess[valid].mean().detach().cpu()
        ),
        f"{prefix}_bad_ess_mean": float(
            bad_ess[valid].mean().detach().cpu()
        ),
        f"{prefix}_raw_good_ess_mean": float(
            raw_good_ess[valid].mean().detach().cpu()
        ),
        f"{prefix}_blend_mean": float(
            blend_coefficients[valid].mean().detach().cpu()
        ),
        f"{prefix}_risk_mean": float(risks[valid].mean().detach().cpu()),
        f"{prefix}_weight_mean": float(
            row_weights[valid].mean().detach().cpu()
        ),
        f"{prefix}_hn_rows": float(
            torch.count_nonzero(row_families[valid] == hn_index).detach().cpu()
            if hn_index >= 0
            else 0.0
        ),
        f"{prefix}_cprime_rows": float(
            torch.count_nonzero(row_families[valid] == cprime_index).detach().cpu()
            if cprime_index >= 0
            else 0.0
        ),
        f"{prefix}_hn_good_ess_mean": float(
            good_ess[hn_valid].mean().detach().cpu() if bool(torch.any(hn_valid)) else 0.0
        ),
        f"{prefix}_cprime_good_ess_mean": float(
            good_ess[cprime_valid].mean().detach().cpu()
            if bool(torch.any(cprime_valid))
            else 0.0
        ),
        f"{prefix}_teacher_supported_rows": float(row_targets.numel()),
        f"{prefix}_oracle_source_is_sidecar": float(oracle_conformer_phi is not None),
    }
    return base_loss * weight, metrics


def hn_shared_q_energy_assignment_loss(
    conformer_phi: torch.Tensor,
    model_energy: torch.Tensor,
    target_features: torch.Tensor,
    family_indices: torch.Tensor,
    target_values: torch.Tensor,
    row_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    loss_weight: float = 0.0,
    oracle_energy_scale: float = 256.0,
    temperature: float = 1.0,
    target_clip_ppm: float = 0.0,
    min_residual_ppm: float = 0.0,
    residual_power: float = 1.0,
    min_teacher_ess: float = 0.0,
    max_teacher_prior_blend: float = 0.0,
    positive_mass_weight: float = 0.0,
    target_side_margin_ppm: float = 0.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Distill HN target-side support into the one shared posterior energy.

    This trains only the support-level energy assignment.  The detached teacher
    is a single K-way distribution built from HN rows, not a rowwise posterior
    exported at inference time.
    """

    prefix = "hn_shared_q_energy_assignment"
    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}
    if conformer_phi.ndim != 3:
        raise ValueError("conformer_phi must have shape [K, L, F]")
    support_count = int(conformer_phi.shape[0])
    if int(model_energy.numel()) != support_count:
        raise ValueError("model_energy must have one value per conformer")
    if support_count < 2:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}
    if "HN" not in family_names:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}

    usable_count = min(
        int(target_features.shape[0]),
        int(family_indices.numel()),
        int(target_values.numel()),
        int(row_mask.numel()),
    )
    if usable_count <= 0:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}

    device = conformer_phi.device
    dtype = conformer_phi.dtype
    hn_index = int(list(family_names).index("HN"))
    features = target_features[:usable_count].to(device=device, dtype=dtype)
    families = family_indices[:usable_count].to(device=device).long().clamp(
        min=0,
        max=max(int(conformer_phi.shape[-1]) - 1, 0),
    )
    values = target_values[:usable_count].to(device=device, dtype=dtype)
    selected = (
        row_mask[:usable_count].to(device=device, dtype=torch.bool)
        & (families == hn_index)
        & torch.isfinite(values)
    )
    if not bool(torch.any(selected)):
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}

    row_phi = target_aligned_phi_from_residue_family(
        conformer_phi.detach(),
        features,
        families,
    )[:, selected]
    row_targets = values[selected]
    if row_phi.numel() == 0:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}

    energy = model_energy.reshape(-1).to(device=device, dtype=dtype)
    finite_energy = torch.isfinite(energy)
    if not bool(torch.any(finite_energy)):
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}
    posterior_energy = torch.where(
        finite_energy,
        energy,
        energy.new_full(energy.shape, 1.0e6),
    )
    temp = max(float(temperature), 1.0e-6)
    if prior_log_probs is not None and int(prior_log_probs.numel()) == support_count:
        prior_log = prior_log_probs.to(device=device, dtype=dtype).reshape(-1)
        prior_log = torch.nan_to_num(prior_log, nan=0.0, posinf=0.0, neginf=0.0)
    else:
        prior_log = torch.zeros_like(energy)
    student_q = posterior_weights(prior_log, posterior_energy, temperature=temp)
    student_q = student_q.to(device=device, dtype=dtype)

    row_finite = torch.isfinite(row_phi)
    row_valid = row_finite & finite_energy.reshape(-1, 1)
    supported = torch.count_nonzero(row_valid, dim=0) >= 2
    if not bool(torch.any(supported)):
        return _zero_loss_like(model_energy), {
            f"{prefix}_rows": 0.0,
            f"{prefix}_teacher_supported_rows": 0.0,
        }
    row_phi = row_phi[:, supported]
    row_targets = row_targets[supported]
    row_valid = row_valid[:, supported]

    q_for_teacher = student_q.detach().reshape(-1, 1)
    valid_q = q_for_teacher * row_valid.to(dtype=dtype)
    valid_q_sum = valid_q.sum(dim=0).clamp_min(1.0e-12)
    posterior_mean = (
        torch.where(row_valid, row_phi, torch.zeros_like(row_phi)) * q_for_teacher
    ).sum(dim=0) / valid_q_sum
    residual_ppm = row_targets - posterior_mean
    residual_abs_ppm = torch.abs(residual_ppm)
    row_active = residual_abs_ppm >= max(float(min_residual_ppm), 0.0)
    if not bool(torch.any(row_active)):
        return _zero_loss_like(model_energy), {
            f"{prefix}_rows": 0.0,
            f"{prefix}_teacher_supported_rows": float(row_targets.numel()),
            f"{prefix}_posterior_hn_residual_abs_ppm_mean": float(
                residual_abs_ppm.mean().detach().cpu()
            ),
        }

    row_phi = row_phi[:, row_active]
    row_targets = row_targets[row_active]
    row_valid = row_valid[:, row_active]
    posterior_mean = posterior_mean[row_active]
    residual_ppm = residual_ppm[row_active]
    residual_abs_ppm = residual_abs_ppm[row_active]

    family_scale = conformer_phi.new_tensor(
        max(float(ATOM_FAMILY_PPM_SCALES[hn_index]), 1.0e-3)
    )
    diff_ppm = row_phi - row_targets.reshape(1, -1)
    clip_ppm = max(float(target_clip_ppm), 0.0)
    if clip_ppm > 0.0:
        diff_ppm = diff_ppm.clamp(min=-clip_ppm, max=clip_ppm)
    row_energy = max(float(oracle_energy_scale), 0.0) * (diff_ppm / family_scale).square()
    row_energy = torch.where(
        row_valid,
        row_energy,
        torch.full_like(row_energy, 1.0e6),
    )

    residual_norm = residual_abs_ppm / family_scale
    power = max(float(residual_power), 0.0)
    if power > 0.0:
        row_weights = residual_norm.clamp_min(1.0e-6).pow(power)
    else:
        row_weights = torch.ones_like(residual_norm)
    aggregate_energy = (
        row_energy * row_weights.reshape(1, -1)
    ).sum(dim=1) / row_weights.sum().clamp_min(1.0e-12)
    teacher_logits = -aggregate_energy
    teacher_logits = torch.where(
        finite_energy,
        teacher_logits + prior_log,
        torch.full_like(teacher_logits, -1.0e6),
    )
    teacher_raw = torch.softmax(teacher_logits, dim=0)
    raw_teacher_ess = 1.0 / teacher_raw.square().sum().clamp_min(1.0e-12)

    prior_logits = torch.where(
        finite_energy,
        prior_log,
        torch.full_like(prior_log, -1.0e6),
    )
    prior_weights = torch.softmax(prior_logits, dim=0)
    ess_floor = min(max(float(min_teacher_ess), 0.0), float(support_count))
    max_blend = max(float(max_teacher_prior_blend), 0.0)
    blend = 0.0
    teacher = teacher_raw
    if ess_floor > 1.0 and max_blend > 0.0:
        raw_ess_value = float(raw_teacher_ess.detach().cpu())
        blend = min(
            max((ess_floor - raw_ess_value) / max(ess_floor - 1.0, 1.0e-6), 0.0)
            * max_blend,
            max_blend,
        )
        blend_tensor = teacher_raw.new_tensor(blend)
        teacher = teacher_raw * (1.0 - blend_tensor) + prior_weights * blend_tensor
        teacher = teacher / teacher.sum().clamp_min(1.0e-12)
    teacher = teacher.detach()

    student_safe = student_q.clamp_min(1.0e-12)
    teacher_safe = teacher.clamp_min(1.0e-12)
    kl = torch.sum(teacher_safe * (torch.log(teacher_safe) - torch.log(student_safe)))

    mass_component = energy.new_tensor(0.0)
    target_side_rows = 0
    target_side_mass_mean = 0.0
    target_side_gap_mean = 0.0
    mass_weight = max(float(positive_mass_weight), 0.0)
    margin_ppm = max(float(target_side_margin_ppm), 0.0)
    if mass_weight > 0.0:
        direction = torch.sign(residual_ppm.detach())
        side_score = direction.reshape(1, -1) * (row_phi - posterior_mean.reshape(1, -1))
        target_side = row_valid & (side_score >= margin_ppm)
        rows_with_side = torch.any(target_side, dim=0) & (direction != 0.0)
        if bool(torch.any(rows_with_side)):
            side_mass = (student_q.reshape(-1, 1) * target_side.to(dtype=dtype)).sum(dim=0)
            active_mass = side_mass[rows_with_side].clamp_min(1.0e-12)
            active_weights = row_weights[rows_with_side]
            mass_component = (
                -torch.log(active_mass) * active_weights
            ).sum() / active_weights.sum().clamp_min(1.0e-12)
            target_side_rows = int(torch.count_nonzero(rows_with_side).detach().cpu())
            target_side_mass_mean = float(active_mass.detach().mean().cpu())
            metric_side_score = side_score[:, rows_with_side]
            metric_valid = row_valid[:, rows_with_side]
            metric_denominator = metric_valid.to(dtype=dtype).sum().clamp_min(1.0)
            target_side_gap_mean = float(
                (
                    torch.where(
                        metric_valid,
                        metric_side_score,
                        torch.zeros_like(metric_side_score),
                    ).sum()
                    / metric_denominator
                )
                .detach()
                .cpu()
            )

    total = kl + energy.new_tensor(mass_weight) * mass_component
    rows_used = int(row_targets.numel())
    metrics = {
        f"{prefix}_rows": float(rows_used),
        f"{prefix}_teacher_supported_rows": float(rows_used),
        f"{prefix}_loss_value": float(total.detach().cpu()),
        f"{prefix}_kl_value": float(kl.detach().cpu()),
        f"{prefix}_positive_mass_loss_value": float(mass_component.detach().cpu()),
        f"{prefix}_positive_mass_weight": float(mass_weight),
        f"{prefix}_target_side_rows": float(target_side_rows),
        f"{prefix}_target_side_mass_mean": float(target_side_mass_mean),
        f"{prefix}_target_side_gap_ppm_mean": float(target_side_gap_mean),
        f"{prefix}_posterior_hn_residual_abs_ppm_mean": float(
            residual_abs_ppm.detach().mean().cpu()
        ),
        f"{prefix}_row_weight_mean": float(row_weights.detach().mean().cpu()),
        f"{prefix}_teacher_ess": float(
            (1.0 / teacher_safe.square().sum().clamp_min(1.0e-12)).detach().cpu()
        ),
        f"{prefix}_raw_teacher_ess": float(raw_teacher_ess.detach().cpu()),
        f"{prefix}_teacher_prior_blend": float(blend),
        f"{prefix}_teacher_top_mass": float(teacher_safe.detach().max().cpu()),
        f"{prefix}_student_top_mass": float(student_safe.detach().max().cpu()),
        f"{prefix}_teacher_student_dot": float(
            torch.sum(teacher * student_q.detach()).detach().cpu()
        ),
        f"{prefix}_target_side_margin_ppm": float(margin_ppm),
    }
    return total * weight, metrics


def leave_family_out_oracle_decoder_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train family observables to agree with q selected by other families.

    For a family such as HN or C', the detached teacher posterior is formed
    from all supervised families except that family.  The decoder is then
    trained so the excluded family's conformer observable matches the target
    under this cross-family q.  This raises the ceiling for one shared
    posterior measure without exporting family-specific q at inference.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {"leave_family_out_oracle_decoder_cells": 0.0}
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(conformer_phi), {"leave_family_out_oracle_decoder_cells": 0.0}

    family_count = min(conformer_phi.shape[-1], len(family_names))
    configured_family_weights = family_weights or {}
    family_terms: list[tuple[torch.Tensor, float, int]] = []
    ess_values: list[float] = []
    top_mass_values: list[float] = []
    active_family_names: list[str] = []
    for family_index in range(family_count):
        family_name = str(family_names[family_index])
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        teacher_mask = mask.clone()
        teacher_mask[:, family_index] = False
        if not bool(torch.any(teacher_mask)):
            continue
        oracle = support_reachability_oracle_predictions(
            conformer_phi.detach(),
            target.detach(),
            teacher_mask.detach(),
            prior_log_probs=prior_log_probs.detach() if prior_log_probs is not None else None,
            oracle_energy_scale=max(float(oracle_energy_scale), 0.0),
        )
        teacher_weights = oracle.get("weights")
        if not isinstance(teacher_weights, torch.Tensor):
            continue
        teacher_weights = teacher_weights.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        ).detach()
        prediction = torch.sum(
            conformer_phi[:, :, family_index] * teacher_weights.reshape(-1, 1),
            dim=0,
        )
        scale = conformer_phi.new_tensor(
            max(float(ATOM_FAMILY_PPM_SCALES[family_index]), 1.0e-3)
        )
        diff = (prediction[family_mask] - target[:, family_index][family_mask]) / scale
        family_terms.append((torch.mean(diff.square()), family_weight, cell_count))
        diagnostics = oracle.get("diagnostics", {})
        if isinstance(diagnostics, dict):
            ess_values.append(float(diagnostics.get("shared_q_oracle_ess", 0.0)))
            top_mass_values.append(float(diagnostics.get("shared_q_oracle_top_mass", 0.0)))
        active_family_names.append(family_name)

    if not family_terms:
        return _zero_loss_like(conformer_phi), {"leave_family_out_oracle_decoder_cells": 0.0}
    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    cell_total = 0
    for family_loss, family_weight, cell_count in family_terms:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
        cell_total += cell_count
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    hn_rows = 0
    cprime_rows = 0
    for family_name, (_, _, cell_count) in zip(active_family_names, family_terms):
        if family_name == "HN":
            hn_rows += cell_count
        if family_name == "C'":
            cprime_rows += cell_count
    metrics = {
        "leave_family_out_oracle_decoder_cells": float(cell_total),
        "leave_family_out_oracle_decoder_families": float(len(family_terms)),
        "leave_family_out_oracle_decoder_loss_value": float(loss.detach().cpu()),
        "leave_family_out_oracle_decoder_ess_mean": float(
            sum(ess_values) / max(len(ess_values), 1)
        ),
        "leave_family_out_oracle_decoder_top_mass_mean": float(
            sum(top_mass_values) / max(len(top_mass_values), 1)
        ),
        "leave_family_out_oracle_decoder_hn_rows": float(hn_rows),
        "leave_family_out_oracle_decoder_cprime_rows": float(cprime_rows),
    }
    return loss * weight, metrics


def _parse_cooccurrence_pair_key(
    pair_key: str,
    *,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[int, int] | None:
    """Parse ``source->target`` family-pair config keys."""

    text = str(pair_key).strip()
    for separator in ("->", "|", ":", ","):
        if separator in text:
            source_name, target_name = [part.strip() for part in text.split(separator, 1)]
            break
    else:
        return None
    family_to_index = {str(name): index for index, name in enumerate(family_names)}
    if source_name not in family_to_index or target_name not in family_to_index:
        return None
    source_index = int(family_to_index[source_name])
    target_index = int(family_to_index[target_name])
    if source_index == target_index:
        return None
    return source_index, target_index


def pairwise_cooccurrence_decoder_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    pair_weights: dict[str, float] | None = None,
    oracle_conformer_phi: torch.Tensor | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Align HN/C' rowwise-good conformers into one shared population support.

    The shared-q ceiling drops when HN and C' are each reachable rowwise but
    prefer different conformers.  This train-only loss forms a detached
    source-family oracle q, then teaches the target-family decoder observable
    under that same q.  Inference still exports one posterior population.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {
            "pairwise_cooccurrence_decoder_cells": 0.0
        }
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(conformer_phi), {
            "pairwise_cooccurrence_decoder_cells": 0.0
        }
    oracle_phi = conformer_phi.detach()
    if oracle_conformer_phi is not None:
        if oracle_conformer_phi.shape != conformer_phi.shape:
            raise ValueError("oracle_conformer_phi must match conformer_phi")
        oracle_phi = oracle_conformer_phi.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        ).detach()

    configured_pairs = pair_weights or {"HN->C'": 1.0, "C'->HN": 1.0}
    family_count = min(int(conformer_phi.shape[-1]), len(family_names))
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: int(conformer_phi.shape[-1])]
    ).clamp_min(1.0e-3)
    weighted_loss = conformer_phi.new_tensor(0.0)
    weight_sum = 0.0
    cell_total = 0
    pair_total = 0
    hn_target_rows = 0
    cprime_target_rows = 0
    ess_values: list[float] = []
    top_mass_values: list[float] = []
    active_pair_labels: list[str] = []

    for pair_key, raw_pair_weight in configured_pairs.items():
        pair_weight = max(float(raw_pair_weight), 0.0)
        if pair_weight <= 0.0:
            continue
        parsed = _parse_cooccurrence_pair_key(
            str(pair_key),
            family_names=family_names,
        )
        if parsed is None:
            continue
        source_index, target_index = parsed
        if source_index >= family_count or target_index >= family_count:
            continue
        source_mask = mask[:, source_index]
        target_mask = mask[:, target_index]
        source_cells = int(torch.count_nonzero(source_mask).detach().cpu())
        target_cells = int(torch.count_nonzero(target_mask).detach().cpu())
        if source_cells <= 0 or target_cells <= 0:
            continue
        teacher_mask = torch.zeros_like(mask)
        teacher_mask[:, source_index] = source_mask
        oracle = support_reachability_oracle_predictions(
            conformer_phi.detach(),
            target.detach(),
            teacher_mask.detach(),
            prior_log_probs=prior_log_probs.detach() if prior_log_probs is not None else None,
            oracle_energy_scale=max(float(oracle_energy_scale), 0.0),
            oracle_conformer_phi=oracle_phi,
        )
        teacher_weights = oracle.get("weights")
        if not isinstance(teacher_weights, torch.Tensor):
            continue
        teacher_weights = teacher_weights.to(
            device=conformer_phi.device,
            dtype=conformer_phi.dtype,
        ).detach()
        target_phi = conformer_phi[:, :, target_index]
        finite = torch.isfinite(target_phi)
        weighted_finite = teacher_weights.reshape(-1, 1) * finite.to(dtype=conformer_phi.dtype)
        denominator = weighted_finite.sum(dim=0).clamp_min(1.0e-12)
        prediction = (
            torch.where(finite, target_phi, torch.zeros_like(target_phi))
            * teacher_weights.reshape(-1, 1)
        ).sum(dim=0) / denominator
        target_values = target[:, target_index]
        valid = target_mask & torch.isfinite(prediction)
        if not bool(torch.any(valid)):
            continue
        scale = scales[target_index]
        diff = (prediction[valid] - target_values[valid]) / scale
        pair_loss = torch.mean(diff.square())
        weighted_loss = weighted_loss + pair_loss * pair_weight
        weight_sum += pair_weight
        target_cell_count = int(torch.count_nonzero(valid).detach().cpu())
        cell_total += target_cell_count
        pair_total += 1
        target_family_name = str(family_names[target_index])
        source_family_name = str(family_names[source_index])
        active_pair_labels.append(f"{source_family_name}->{target_family_name}")
        if target_family_name == "HN":
            hn_target_rows += target_cell_count
        if target_family_name == "C'":
            cprime_target_rows += target_cell_count
        diagnostics = oracle.get("diagnostics", {})
        if isinstance(diagnostics, dict):
            ess_values.append(float(diagnostics.get("shared_q_oracle_ess", 0.0)))
            top_mass_values.append(float(diagnostics.get("shared_q_oracle_top_mass", 0.0)))

    if pair_total <= 0 or weight_sum <= 0.0:
        return _zero_loss_like(conformer_phi), {
            "pairwise_cooccurrence_decoder_cells": 0.0
        }
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        "pairwise_cooccurrence_decoder_cells": float(cell_total),
        "pairwise_cooccurrence_decoder_pairs": float(pair_total),
        "pairwise_cooccurrence_decoder_loss_value": float(loss.detach().cpu()),
        "pairwise_cooccurrence_decoder_ess_mean": float(
            sum(ess_values) / max(len(ess_values), 1)
        ),
        "pairwise_cooccurrence_decoder_top_mass_mean": float(
            sum(top_mass_values) / max(len(top_mass_values), 1)
        ),
        "pairwise_cooccurrence_decoder_hn_target_rows": float(hn_target_rows),
        "pairwise_cooccurrence_decoder_cprime_target_rows": float(cprime_target_rows),
        "pairwise_cooccurrence_decoder_sidecar_source": float(
            oracle_conformer_phi is not None
        ),
        "pairwise_cooccurrence_decoder_active_pair_count": float(
            len(set(active_pair_labels))
        ),
    }
    return loss * weight, metrics


def same_conformer_cosatisfaction_decoder_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    focus_families: Sequence[str] | None = None,
    required_families: Sequence[str] | None = None,
    fallback_required_families: Sequence[str] | None = None,
    fallback_min_rows: int = 0,
    family_weights: dict[str, float] | None = None,
    min_family_count: int = 2,
    gap_focus_scale: float = 0.0,
    worst_family_error_mix: float = 0.0,
    family_balanced_error_mix: float = 0.0,
    coverage_weight_power: float = 0.0,
    coverage_fallback_enabled: bool = False,
    coverage_fallback_min_family_count: int = 0,
    coverage_fallback_row_min_family_count: int = 1,
    coverage_fallback_min_rows: int = 1,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train one conformer subset to co-satisfy multiple atom families.

    Pairwise co-occurrence can transfer HN-good support to C' or CA one edge at
    a time.  This loss is stricter: for residue rows with multiple observed
    focus families, it builds a detached K-way teacher from the joint
    same-conformer error and updates ``phi_theta(X_k)`` under that same teacher.
    No rowwise or family-specific posterior is exported at inference time.
    """

    prefix = "same_conformer_cosatisfaction_decoder"
    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(conformer_phi), {f"{prefix}_rows": 0.0}
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    if conformer_phi.shape[1:] != target_grid.shape:
        raise ValueError("target_grid must match conformer_phi [L,F]")
    if target_grid.shape != observed_mask.shape:
        raise ValueError("observed_mask must match target_grid")

    device = conformer_phi.device
    dtype = conformer_phi.dtype
    family_count = min(int(conformer_phi.shape[-1]), len(family_names))
    if family_count <= 0:
        return _zero_loss_like(conformer_phi), {f"{prefix}_rows": 0.0}

    family_to_index = {
        _x0_canonical_family_name(name): index
        for index, name in enumerate(family_names[:family_count])
    }
    requested_families = list(focus_families or ("HN", "C'", "CA"))
    focus_indices: list[int] = []
    focus_names: list[str] = []
    for raw_family in requested_families:
        canonical = _x0_canonical_family_name(raw_family)
        family_index = family_to_index.get(canonical)
        if family_index is None or family_index in focus_indices:
            continue
        focus_indices.append(int(family_index))
        focus_names.append(canonical)
    required_indices: list[int] = []
    for raw_family in required_families or ():
        canonical = _x0_canonical_family_name(raw_family)
        family_index = family_to_index.get(canonical)
        if family_index is None:
            continue
        if family_index not in focus_indices:
            focus_indices.append(int(family_index))
            focus_names.append(canonical)
        if family_index not in required_indices:
            required_indices.append(int(family_index))
    fallback_required_indices: list[int] = []
    for raw_family in fallback_required_families or ():
        canonical = _x0_canonical_family_name(raw_family)
        family_index = family_to_index.get(canonical)
        if family_index is None:
            continue
        if family_index not in focus_indices:
            focus_indices.append(int(family_index))
            focus_names.append(canonical)
        if family_index not in fallback_required_indices:
            fallback_required_indices.append(int(family_index))
    if len(focus_indices) < max(int(min_family_count), 1):
        return _zero_loss_like(conformer_phi), {f"{prefix}_rows": 0.0}

    target = target_grid.to(device=device, dtype=dtype)[:, :family_count]
    mask = (
        observed_mask.to(device=device, dtype=torch.bool)[:, :family_count]
        & torch.isfinite(target)
    )
    focus_mask = torch.zeros_like(mask)
    focus_mask[:, focus_indices] = mask[:, focus_indices]
    row_family_counts = torch.count_nonzero(focus_mask, dim=1)
    required_count = max(int(min_family_count), 1)
    def _select_for_required(
        indices: Sequence[int],
    ) -> tuple[torch.Tensor, torch.Tensor]:
        if indices:
            observed = torch.all(focus_mask[:, list(indices)], dim=1)
        else:
            observed = torch.ones_like(row_family_counts, dtype=torch.bool)
        return observed, (row_family_counts >= required_count) & observed

    primary_required_observed, selected_rows = _select_for_required(required_indices)
    primary_candidate_rows = float(torch.count_nonzero(selected_rows).detach().cpu())
    fallback_candidate_rows = 0.0
    fallback_used = False
    fallback_threshold = max(int(fallback_min_rows), 0)
    required_observed = primary_required_observed
    if fallback_required_indices and (
        primary_candidate_rows <= 0.0
        or (fallback_threshold > 0 and primary_candidate_rows < float(fallback_threshold))
    ):
        fallback_observed, fallback_rows = _select_for_required(fallback_required_indices)
        fallback_candidate_rows = float(torch.count_nonzero(fallback_rows).detach().cpu())
        if fallback_candidate_rows > primary_candidate_rows:
            required_indices = fallback_required_indices
            required_observed = fallback_observed
            selected_rows = fallback_rows
            fallback_used = True
    coverage_fallback_used = False
    coverage_fallback_family_count = 0
    coverage_fallback_rows = 0.0
    coverage_fallback_required_count = max(
        int(coverage_fallback_min_family_count),
        len(focus_indices) if required_count > 1 else 1,
    )
    coverage_fallback_row_count = max(
        int(coverage_fallback_row_min_family_count),
        1,
    )
    coverage_fallback_min_row_count = max(int(coverage_fallback_min_rows), 0)
    if coverage_fallback_enabled and not bool(torch.any(selected_rows)):
        focus_family_covered = torch.any(focus_mask[:, focus_indices], dim=0)
        coverage_fallback_family_count = int(
            torch.count_nonzero(focus_family_covered).detach().cpu()
        )
        coverage_candidate_rows = row_family_counts >= coverage_fallback_row_count
        coverage_fallback_rows = float(
            torch.count_nonzero(coverage_candidate_rows).detach().cpu()
        )
        if (
            coverage_fallback_family_count >= coverage_fallback_required_count
            and coverage_fallback_rows >= float(coverage_fallback_min_row_count)
            and bool(torch.any(coverage_candidate_rows))
        ):
            selected_rows = coverage_candidate_rows
            required_observed = torch.any(focus_mask[:, focus_indices], dim=1)
            required_indices = []
            coverage_fallback_used = True
    if not bool(torch.any(selected_rows)):
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_rows": 0.0,
            f"{prefix}_required_family_count": float(len(required_indices)),
            f"{prefix}_required_family_rows": float(
                torch.count_nonzero(required_observed).detach().cpu()
            ),
            f"{prefix}_required_family_fallback_used": float(fallback_used),
            f"{prefix}_primary_candidate_rows": float(primary_candidate_rows),
            f"{prefix}_fallback_candidate_rows": float(fallback_candidate_rows),
            f"{prefix}_fallback_min_rows": float(fallback_threshold),
            f"{prefix}_coverage_fallback_enabled": float(
                bool(coverage_fallback_enabled)
            ),
            f"{prefix}_coverage_fallback_used": float(coverage_fallback_used),
            f"{prefix}_coverage_fallback_family_count": float(
                coverage_fallback_family_count
            ),
            f"{prefix}_coverage_fallback_min_family_count": float(
                coverage_fallback_required_count
            ),
            f"{prefix}_coverage_fallback_rows": float(coverage_fallback_rows),
            f"{prefix}_coverage_fallback_row_min_family_count": float(
                coverage_fallback_row_count
            ),
            f"{prefix}_coverage_fallback_min_rows": float(
                coverage_fallback_min_row_count
            ),
        }

    phi = conformer_phi[:, :, :family_count]
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[:family_count],
    ).clamp_min(1.0e-3)
    diff = (phi - target.reshape(1, target.shape[0], family_count)) / scales.reshape(
        1,
        1,
        family_count,
    )
    finite = torch.isfinite(diff)
    cell_mask = focus_mask.reshape(1, target.shape[0], family_count) & finite

    configured_family_weights = family_weights or {}
    per_family_weights = conformer_phi.new_zeros(family_count)
    for family_index in focus_indices:
        family_name = _x0_canonical_family_name(family_names[family_index])
        per_family_weights[family_index] = max(
            float(configured_family_weights.get(family_name, 1.0)),
            0.0,
        )
    weighted_focus_mask = focus_mask.to(dtype=dtype) * per_family_weights.reshape(
        1,
        family_count,
    )
    row_weight_sum = weighted_focus_mask.sum(dim=1)
    selected_rows = selected_rows & (row_weight_sum > 0.0)
    if not bool(torch.any(selected_rows)):
        return _zero_loss_like(conformer_phi), {f"{prefix}_rows": 0.0}

    selected_indices = torch.nonzero(selected_rows, as_tuple=False).reshape(-1)
    row_required_counts = row_family_counts[selected_indices].reshape(1, -1)
    valid_support = (
        torch.count_nonzero(cell_mask[:, selected_indices, :], dim=2)
        >= row_required_counts
    )
    supported_rows = torch.any(valid_support, dim=0)
    if not bool(torch.any(supported_rows)):
        return _zero_loss_like(conformer_phi), {
            f"{prefix}_rows": 0.0,
            f"{prefix}_candidate_rows": float(selected_indices.numel()),
        }

    selected_indices = selected_indices[supported_rows]
    valid_support = valid_support[:, supported_rows]
    selected_family_counts = row_family_counts[selected_indices].to(dtype=dtype)
    coverage_fraction = (
        selected_family_counts / max(float(len(focus_indices)), 1.0)
    ).clamp(min=0.0, max=1.0)
    coverage_power = max(float(coverage_weight_power), 0.0)
    coverage_weight = (
        torch.pow(coverage_fraction.clamp_min(1.0e-6), coverage_power)
        if coverage_power > 0.0
        else torch.ones_like(coverage_fraction)
    )
    selected_row_weights = row_weight_sum[selected_indices].clamp_min(1.0e-12)
    safe_sq = torch.where(
        torch.isfinite(diff),
        diff.square(),
        torch.zeros_like(diff),
    )
    weighted_sq = safe_sq * weighted_focus_mask.reshape(1, target.shape[0], family_count)
    weighted_mean_error = (
        weighted_sq[:, selected_indices, :].sum(dim=2) / selected_row_weights
    )
    worst_mix = min(max(float(worst_family_error_mix), 0.0), 1.0)
    selected_cell_mask = cell_mask[:, selected_indices, :]
    worst_family_error = torch.where(
        selected_cell_mask,
        safe_sq[:, selected_indices, :],
        torch.full_like(safe_sq[:, selected_indices, :], -1.0),
    ).max(dim=2).values.clamp_min(0.0)
    row_error = (
        weighted_mean_error * (1.0 - worst_mix) + worst_family_error * worst_mix
    )
    teacher_energy = torch.where(
        valid_support,
        row_error.detach(),
        torch.full_like(row_error, 1.0e6),
    )
    teacher_logits = -max(float(oracle_energy_scale), 0.0) * teacher_energy
    if prior_log_probs is not None and int(prior_log_probs.numel()) == int(phi.shape[0]):
        prior_log = prior_log_probs.to(device=device, dtype=dtype).reshape(-1, 1)
        prior_log = torch.nan_to_num(prior_log, nan=0.0, posinf=0.0, neginf=0.0)
        teacher_logits = teacher_logits + prior_log
    teacher_logits = torch.where(
        valid_support,
        teacher_logits,
        torch.full_like(teacher_logits, -1.0e6),
    )
    teacher_weights = torch.softmax(teacher_logits, dim=0).detach()
    per_row_loss = torch.sum(teacher_weights * row_error, dim=0)
    row_focus = (
        1.0 + max(float(gap_focus_scale), 0.0) * per_row_loss.detach()
    ) * coverage_weight
    row_balanced_loss = torch.sum(per_row_loss * row_focus) / row_focus.sum().clamp_min(
        1.0e-12
    )
    selected_focus_mask = focus_mask[selected_indices, :]
    selected_focus_float = selected_focus_mask.to(dtype=dtype)
    selected_safe_sq = safe_sq[:, selected_indices, :]
    expected_cell_error = torch.sum(
        teacher_weights.reshape(teacher_weights.shape[0], teacher_weights.shape[1], 1)
        * selected_safe_sq,
        dim=0,
    )
    focus_error = expected_cell_error[:, focus_indices]
    focus_observed = selected_focus_float[:, focus_indices]
    family_count_by_focus = focus_observed.sum(dim=0)
    safe_family_count_by_focus = family_count_by_focus.clamp_min(1.0e-12)
    family_error_mean = (
        (focus_error * focus_observed).sum(dim=0) / safe_family_count_by_focus
    )
    family_balance_weights = per_family_weights[focus_indices].clamp_min(0.0)
    family_available = (family_count_by_focus > 0.0) & (family_balance_weights > 0.0)
    if bool(torch.any(family_available)):
        active_family_weights = family_balance_weights[family_available]
        family_balanced_error = (
            family_error_mean[family_available] * active_family_weights
        ).sum() / active_family_weights.sum().clamp_min(1.0e-12)
    else:
        family_balanced_error = row_balanced_loss
    family_mix = min(max(float(family_balanced_error_mix), 0.0), 1.0)
    base_loss = (
        row_balanced_loss * (1.0 - family_mix)
        + family_balanced_error * family_mix
    )

    teacher_ess = 1.0 / teacher_weights.square().sum(dim=0).clamp_min(1.0e-12)
    teacher_top_mass = teacher_weights.max(dim=0).values
    family_row_counts = {
        _x0_canonical_family_name(family_names[family_index]): float(
            torch.count_nonzero(selected_focus_mask[:, family_index]).detach().cpu()
        )
        for family_index in focus_indices
    }
    best_error = torch.min(teacher_energy, dim=0).values
    metrics = {
        f"{prefix}_rows": float(selected_indices.numel()),
        f"{prefix}_candidate_rows": float(torch.count_nonzero(selected_rows).detach().cpu()),
        f"{prefix}_cells": float(torch.count_nonzero(selected_focus_mask).detach().cpu()),
        f"{prefix}_families": float(len(focus_indices)),
        f"{prefix}_required_family_count": float(len(required_indices)),
        f"{prefix}_required_family_rows": float(
            torch.count_nonzero(required_observed).detach().cpu()
        ),
        f"{prefix}_required_family_fallback_used": float(fallback_used),
        f"{prefix}_primary_candidate_rows": float(primary_candidate_rows),
        f"{prefix}_fallback_candidate_rows": float(fallback_candidate_rows),
        f"{prefix}_fallback_min_rows": float(fallback_threshold),
        f"{prefix}_coverage_fallback_enabled": float(
            bool(coverage_fallback_enabled)
        ),
        f"{prefix}_coverage_fallback_used": float(coverage_fallback_used),
        f"{prefix}_coverage_fallback_family_count": float(
            coverage_fallback_family_count
        ),
        f"{prefix}_coverage_fallback_min_family_count": float(
            coverage_fallback_required_count
        ),
        f"{prefix}_coverage_fallback_rows": float(coverage_fallback_rows),
        f"{prefix}_coverage_fallback_row_min_family_count": float(
            coverage_fallback_row_count
        ),
        f"{prefix}_coverage_fallback_min_rows": float(
            coverage_fallback_min_row_count
        ),
        f"{prefix}_loss_value": float(base_loss.detach().cpu()),
        f"{prefix}_teacher_ess_mean": float(teacher_ess.mean().detach().cpu()),
        f"{prefix}_teacher_ess_min": float(teacher_ess.min().detach().cpu()),
        f"{prefix}_teacher_top_mass_mean": float(
            teacher_top_mass.mean().detach().cpu()
        ),
        f"{prefix}_teacher_top_mass_max": float(teacher_top_mass.max().detach().cpu()),
        f"{prefix}_teacher_weighted_error_mean": float(
            per_row_loss.detach().mean().cpu()
        ),
        f"{prefix}_weighted_mean_error_mean": float(
            weighted_mean_error.detach().mean().cpu()
        ),
        f"{prefix}_worst_family_error_mean": float(
            worst_family_error.detach().mean().cpu()
        ),
        f"{prefix}_worst_family_error_mix": float(worst_mix),
        f"{prefix}_family_balanced_error_mean": float(
            family_balanced_error.detach().cpu()
        ),
        f"{prefix}_family_balanced_error_mix": float(family_mix),
        f"{prefix}_row_balanced_loss_value": float(
            row_balanced_loss.detach().cpu()
        ),
        f"{prefix}_best_error_mean": float(best_error.detach().mean().cpu()),
        f"{prefix}_row_focus_mean": float(row_focus.detach().mean().cpu()),
        f"{prefix}_min_family_count": float(required_count),
        f"{prefix}_coverage_weight_power": float(coverage_power),
        f"{prefix}_coverage_fraction_mean": float(
            coverage_fraction.detach().mean().cpu()
        ),
        f"{prefix}_coverage_fraction_min": float(
            coverage_fraction.detach().min().cpu()
        ),
        f"{prefix}_coverage_weight_mean": float(
            coverage_weight.detach().mean().cpu()
        ),
        f"{prefix}_train_only": 1.0,
    }
    for family_name, row_count in family_row_counts.items():
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"{prefix}_{safe_name}_rows"] = float(row_count)
    return base_loss * weight, metrics


def same_conformer_cosatisfaction_energy_assignment_loss(
    conformer_phi: torch.Tensor,
    model_energy: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    temperature: float = 1.0,
    loss_weight: float = 0.0,
    focus_families: Sequence[str] | None = None,
    required_families: Sequence[str] | None = None,
    fallback_required_families: Sequence[str] | None = None,
    fallback_min_rows: int = 0,
    family_weights: dict[str, float] | None = None,
    min_family_count: int = 2,
    min_teacher_ess: float = 0.0,
    max_teacher_prior_blend: float = 0.0,
    max_teacher_top_mass: float = 0.0,
    gap_focus_scale: float = 0.0,
    worst_family_error_mix: float = 0.0,
    family_balanced_error_mix: float = 0.0,
    coverage_weight_power: float = 0.0,
    coverage_fallback_enabled: bool = False,
    coverage_fallback_min_family_count: int = 0,
    coverage_fallback_row_min_family_count: int = 1,
    coverage_fallback_min_rows: int = 1,
    topk_mass_loss_weight: float = 0.0,
    topk_fraction: float = 0.125,
    topk_min_count: int = 1,
    topk_target_mass_scale: float = 1.0,
    topk_listwise_weight: float = 0.0,
    top1_nll_weight: float = 0.0,
    student_ess_floor: float = 0.0,
    student_ess_floor_loss_weight: float = 0.0,
    student_top_mass_cap: float = 0.0,
    student_top_mass_cap_loss_weight: float = 0.0,
    student_health_anchor_loss_weight: float = 0.0,
    student_health_anchor_prior_blend: float = 0.0,
    student_health_anchor_gap_power: float = 1.0,
    student_logit_std_cap: float = 0.0,
    student_logit_std_cap_loss_weight: float = 0.0,
    student_logit_range_cap: float = 0.0,
    student_logit_range_cap_loss_weight: float = 0.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train the shared-q energy toward same-conformer co-satisfaction.

    The teacher is one K-way support distribution per example, built from the
    aggregate HN/C'/CA same-conformer error across eligible rows.  This keeps
    the final interface as one support-level q while giving the energy head a
    direct target for multi-family co-satisfaction.
    """

    prefix = "same_conformer_cosatisfaction_energy_assignment"
    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    support_count = int(conformer_phi.shape[0])
    if int(model_energy.numel()) != support_count:
        raise ValueError("model_energy must have one value per conformer")
    if support_count < 2:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}
    if conformer_phi.shape[1:] != target_grid.shape:
        raise ValueError("target_grid must match conformer_phi [L,F]")
    if target_grid.shape != observed_mask.shape:
        raise ValueError("observed_mask must match target_grid")

    device = conformer_phi.device
    dtype = conformer_phi.dtype
    family_count = min(int(conformer_phi.shape[-1]), len(family_names))
    family_to_index = {
        _x0_canonical_family_name(name): index
        for index, name in enumerate(family_names[:family_count])
    }
    requested_families = list(focus_families or ("HN", "C'", "CA"))
    focus_indices: list[int] = []
    for raw_family in requested_families:
        family_index = family_to_index.get(_x0_canonical_family_name(raw_family))
        if family_index is not None and family_index not in focus_indices:
            focus_indices.append(int(family_index))
    required_indices: list[int] = []
    for raw_family in required_families or ():
        family_index = family_to_index.get(_x0_canonical_family_name(raw_family))
        if family_index is None:
            continue
        if family_index not in focus_indices:
            focus_indices.append(int(family_index))
        if family_index not in required_indices:
            required_indices.append(int(family_index))
    fallback_required_indices: list[int] = []
    for raw_family in fallback_required_families or ():
        family_index = family_to_index.get(_x0_canonical_family_name(raw_family))
        if family_index is None:
            continue
        if family_index not in focus_indices:
            focus_indices.append(int(family_index))
        if family_index not in fallback_required_indices:
            fallback_required_indices.append(int(family_index))
    required_count = max(int(min_family_count), 1)
    if len(focus_indices) < required_count:
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}

    target = target_grid.to(device=device, dtype=dtype)[:, :family_count]
    mask = (
        observed_mask.to(device=device, dtype=torch.bool)[:, :family_count]
        & torch.isfinite(target)
    )
    focus_mask = torch.zeros_like(mask)
    focus_mask[:, focus_indices] = mask[:, focus_indices]
    row_family_counts = torch.count_nonzero(focus_mask, dim=1)

    def _select_for_required(
        indices: Sequence[int],
    ) -> tuple[torch.Tensor, torch.Tensor]:
        if indices:
            observed = torch.all(focus_mask[:, list(indices)], dim=1)
        else:
            observed = torch.ones_like(row_family_counts, dtype=torch.bool)
        return observed, (row_family_counts >= required_count) & observed

    primary_required_observed, selected_rows = _select_for_required(required_indices)
    primary_candidate_rows = float(torch.count_nonzero(selected_rows).detach().cpu())
    fallback_candidate_rows = 0.0
    fallback_used = False
    fallback_threshold = max(int(fallback_min_rows), 0)
    required_observed = primary_required_observed
    if fallback_required_indices and (
        primary_candidate_rows <= 0.0
        or (fallback_threshold > 0 and primary_candidate_rows < float(fallback_threshold))
    ):
        fallback_observed, fallback_rows = _select_for_required(fallback_required_indices)
        fallback_candidate_rows = float(torch.count_nonzero(fallback_rows).detach().cpu())
        if fallback_candidate_rows > primary_candidate_rows:
            required_indices = fallback_required_indices
            required_observed = fallback_observed
            selected_rows = fallback_rows
            fallback_used = True
    coverage_fallback_used = False
    coverage_fallback_family_count = 0
    coverage_fallback_rows = 0.0
    coverage_fallback_required_count = max(
        int(coverage_fallback_min_family_count),
        len(focus_indices) if required_count > 1 else 1,
    )
    coverage_fallback_row_count = max(
        int(coverage_fallback_row_min_family_count),
        1,
    )
    coverage_fallback_min_row_count = max(int(coverage_fallback_min_rows), 0)
    if coverage_fallback_enabled and not bool(torch.any(selected_rows)):
        focus_family_covered = torch.any(focus_mask[:, focus_indices], dim=0)
        coverage_fallback_family_count = int(
            torch.count_nonzero(focus_family_covered).detach().cpu()
        )
        coverage_candidate_rows = row_family_counts >= coverage_fallback_row_count
        coverage_fallback_rows = float(
            torch.count_nonzero(coverage_candidate_rows).detach().cpu()
        )
        if (
            coverage_fallback_family_count >= coverage_fallback_required_count
            and coverage_fallback_rows >= float(coverage_fallback_min_row_count)
            and bool(torch.any(coverage_candidate_rows))
        ):
            selected_rows = coverage_candidate_rows
            required_observed = torch.any(focus_mask[:, focus_indices], dim=1)
            required_indices = []
            coverage_fallback_used = True
    if not bool(torch.any(selected_rows)):
        return _zero_loss_like(model_energy), {
            f"{prefix}_rows": 0.0,
            f"{prefix}_required_family_count": float(len(required_indices)),
            f"{prefix}_required_family_rows": float(
                torch.count_nonzero(required_observed).detach().cpu()
            ),
            f"{prefix}_required_family_fallback_used": float(fallback_used),
            f"{prefix}_primary_candidate_rows": float(primary_candidate_rows),
            f"{prefix}_fallback_candidate_rows": float(fallback_candidate_rows),
            f"{prefix}_fallback_min_rows": float(fallback_threshold),
            f"{prefix}_coverage_fallback_enabled": float(
                bool(coverage_fallback_enabled)
            ),
            f"{prefix}_coverage_fallback_used": float(coverage_fallback_used),
            f"{prefix}_coverage_fallback_family_count": float(
                coverage_fallback_family_count
            ),
            f"{prefix}_coverage_fallback_min_family_count": float(
                coverage_fallback_required_count
            ),
            f"{prefix}_coverage_fallback_rows": float(coverage_fallback_rows),
            f"{prefix}_coverage_fallback_row_min_family_count": float(
                coverage_fallback_row_count
            ),
            f"{prefix}_coverage_fallback_min_rows": float(
                coverage_fallback_min_row_count
            ),
        }

    configured_family_weights = family_weights or {}
    per_family_weights = conformer_phi.new_zeros(family_count)
    for family_index in focus_indices:
        family_name = _x0_canonical_family_name(family_names[family_index])
        per_family_weights[family_index] = max(
            float(configured_family_weights.get(family_name, 1.0)),
            0.0,
        )
    weighted_focus_mask = focus_mask.to(dtype=dtype) * per_family_weights.reshape(
        1,
        family_count,
    )
    row_weight_sum = weighted_focus_mask.sum(dim=1)
    selected_rows = selected_rows & (row_weight_sum > 0.0)
    if not bool(torch.any(selected_rows)):
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}

    phi = conformer_phi.detach()[:, :, :family_count]
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[:family_count],
    ).clamp_min(1.0e-3)
    diff = (phi - target.reshape(1, target.shape[0], family_count)) / scales.reshape(
        1,
        1,
        family_count,
    )
    finite = torch.isfinite(diff)
    cell_mask = focus_mask.reshape(1, target.shape[0], family_count) & finite
    selected_indices = torch.nonzero(selected_rows, as_tuple=False).reshape(-1)
    row_required_counts = row_family_counts[selected_indices].reshape(1, -1)
    valid_support = (
        torch.count_nonzero(cell_mask[:, selected_indices, :], dim=2)
        >= row_required_counts
    )
    supported_rows = torch.any(valid_support, dim=0)
    if not bool(torch.any(supported_rows)):
        return _zero_loss_like(model_energy), {
            f"{prefix}_rows": 0.0,
            f"{prefix}_candidate_rows": float(selected_indices.numel()),
        }

    selected_indices = selected_indices[supported_rows]
    valid_support = valid_support[:, supported_rows]
    selected_family_counts = row_family_counts[selected_indices].to(dtype=dtype)
    coverage_fraction = (
        selected_family_counts / max(float(len(focus_indices)), 1.0)
    ).clamp(min=0.0, max=1.0)
    coverage_power = max(float(coverage_weight_power), 0.0)
    coverage_weight = (
        torch.pow(coverage_fraction.clamp_min(1.0e-6), coverage_power)
        if coverage_power > 0.0
        else torch.ones_like(coverage_fraction)
    )
    selected_row_weights = row_weight_sum[selected_indices].clamp_min(1.0e-12)
    safe_sq = torch.where(
        torch.isfinite(diff),
        diff.square(),
        torch.zeros_like(diff),
    )
    weighted_sq = safe_sq * weighted_focus_mask.reshape(1, target.shape[0], family_count)
    weighted_mean_error = (
        weighted_sq[:, selected_indices, :].sum(dim=2) / selected_row_weights
    )
    worst_mix = min(max(float(worst_family_error_mix), 0.0), 1.0)
    selected_cell_mask = cell_mask[:, selected_indices, :]
    worst_family_error = torch.where(
        selected_cell_mask,
        safe_sq[:, selected_indices, :],
        torch.full_like(safe_sq[:, selected_indices, :], -1.0),
    ).max(dim=2).values.clamp_min(0.0)
    row_error = (
        weighted_mean_error * (1.0 - worst_mix) + worst_family_error * worst_mix
    )
    row_error = torch.where(
        valid_support,
        row_error.detach(),
        torch.full_like(row_error, 1.0e6),
    )
    best_error = torch.min(row_error, dim=0).values
    row_focus = (
        1.0 + max(float(gap_focus_scale), 0.0) * best_error.detach()
    ) * coverage_weight
    row_aggregate_energy = (row_error * row_focus.reshape(1, -1)).sum(dim=1) / row_focus.sum().clamp_min(
        1.0e-12
    )
    selected_focus_mask = focus_mask[selected_indices, :]
    selected_focus_float = selected_focus_mask.to(dtype=dtype)
    selected_safe_sq = safe_sq[:, selected_indices, :]
    focus_safe_sq = selected_safe_sq[:, :, focus_indices]
    focus_observed = selected_focus_float[:, focus_indices]
    family_count_by_focus = focus_observed.sum(dim=0)
    safe_family_count_by_focus = family_count_by_focus.clamp_min(1.0e-12)
    family_error_mean = (
        (focus_safe_sq * focus_observed.reshape(1, focus_observed.shape[0], -1)).sum(
            dim=1
        )
        / safe_family_count_by_focus.reshape(1, -1)
    )
    family_balance_weights = per_family_weights[focus_indices].clamp_min(0.0)
    family_available = (family_count_by_focus > 0.0) & (family_balance_weights > 0.0)
    if bool(torch.any(family_available)):
        active_family_weights = family_balance_weights[family_available]
        family_balanced_energy = (
            family_error_mean[:, family_available] * active_family_weights.reshape(
                1,
                -1,
            )
        ).sum(dim=1) / active_family_weights.sum().clamp_min(1.0e-12)
    else:
        family_balanced_energy = row_aggregate_energy
    family_mix = min(max(float(family_balanced_error_mix), 0.0), 1.0)
    aggregate_energy = (
        row_aggregate_energy * (1.0 - family_mix)
        + family_balanced_energy * family_mix
    )

    energy = model_energy.reshape(-1).to(device=device, dtype=dtype)
    finite_energy = torch.isfinite(energy)
    if not bool(torch.any(finite_energy)):
        return _zero_loss_like(model_energy), {f"{prefix}_rows": 0.0}
    posterior_energy = torch.where(
        finite_energy,
        energy,
        energy.new_full(energy.shape, 1.0e6),
    )
    if prior_log_probs is not None and int(prior_log_probs.numel()) == support_count:
        prior_log = prior_log_probs.to(device=device, dtype=dtype).reshape(-1)
        prior_log = torch.nan_to_num(prior_log, nan=0.0, posinf=0.0, neginf=0.0)
    else:
        prior_log = torch.zeros_like(energy)
    posterior_temperature = max(float(temperature), 1.0e-6)
    student_logits = prior_log - posterior_energy / posterior_temperature
    finite_student_logits = torch.where(
        finite_energy,
        student_logits,
        torch.zeros_like(student_logits),
    )
    finite_count_for_logits = torch.count_nonzero(finite_energy).clamp_min(1)
    logit_mean = finite_student_logits.sum() / finite_count_for_logits.to(dtype=dtype)
    centered_logits = torch.where(
        finite_energy,
        student_logits - logit_mean,
        torch.zeros_like(student_logits),
    )
    logit_var = centered_logits.square().sum() / finite_count_for_logits.to(
        dtype=dtype
    )
    student_logit_std = torch.sqrt(logit_var.clamp_min(0.0))
    finite_logit_values = student_logits[finite_energy]
    if int(finite_logit_values.numel()) > 0:
        student_logit_range = finite_logit_values.max() - finite_logit_values.min()
    else:
        student_logit_range = student_logits.new_tensor(0.0)
    student_q = posterior_weights(
        prior_log,
        posterior_energy,
        temperature=posterior_temperature,
    ).to(device=device, dtype=dtype)

    teacher_logits = -max(float(oracle_energy_scale), 0.0) * aggregate_energy
    teacher_logits = torch.where(
        finite_energy,
        teacher_logits + prior_log,
        torch.full_like(teacher_logits, -1.0e6),
    )
    teacher_raw = torch.softmax(teacher_logits, dim=0)
    raw_teacher_ess = 1.0 / teacher_raw.square().sum().clamp_min(1.0e-12)
    raw_teacher_top_mass = teacher_raw.max()

    prior_logits = torch.where(
        finite_energy,
        prior_log,
        torch.full_like(prior_log, -1.0e6),
    )
    prior_weights = torch.softmax(prior_logits, dim=0)
    ess_floor = min(max(float(min_teacher_ess), 0.0), float(support_count))
    max_blend = max(float(max_teacher_prior_blend), 0.0)
    blend = 0.0
    teacher = teacher_raw
    if ess_floor > 1.0 and max_blend > 0.0:
        raw_ess_value = float(raw_teacher_ess.detach().cpu())
        blend = min(
            max((ess_floor - raw_ess_value) / max(ess_floor - 1.0, 1.0e-6), 0.0)
            * max_blend,
            max_blend,
        )
    top_mass_cap = min(max(float(max_teacher_top_mass), 0.0), 1.0)
    if top_mass_cap > 0.0 and max_blend > 0.0:
        raw_top_mass_value = float(raw_teacher_top_mass.detach().cpu())
        if raw_top_mass_value > top_mass_cap:
            low = blend
            high = max_blend
            for _ in range(24):
                mid = 0.5 * (low + high)
                mid_tensor = teacher_raw.new_tensor(mid)
                candidate = (
                    teacher_raw * (1.0 - mid_tensor)
                    + prior_weights * mid_tensor
                )
                candidate = candidate / candidate.sum().clamp_min(1.0e-12)
                candidate_top = float(candidate.detach().max().cpu())
                if candidate_top > top_mass_cap:
                    low = mid
                else:
                    high = mid
            blend = max(blend, high)
    if blend > 0.0:
        blend_tensor = teacher_raw.new_tensor(blend)
        teacher = teacher_raw * (1.0 - blend_tensor) + prior_weights * blend_tensor
        teacher = teacher / teacher.sum().clamp_min(1.0e-12)
    teacher = teacher.detach()

    teacher_safe = teacher.clamp_min(1.0e-12)
    student_safe = student_q.clamp_min(1.0e-12)
    kl = torch.sum(teacher_safe * (torch.log(teacher_safe) - torch.log(student_safe)))
    objective = kl
    student_ess = 1.0 / student_safe.square().sum().clamp_min(1.0e-12)
    student_top_mass_value = student_safe.max()
    student_ess_floor_value = min(
        max(float(student_ess_floor), 0.0),
        float(support_count),
    )
    student_ess_weight = max(float(student_ess_floor_loss_weight), 0.0)
    student_ess_floor_loss = kl.new_tensor(0.0)
    if student_ess_weight > 0.0 and student_ess_floor_value > 1.0:
        ess_gap = (
            kl.new_tensor(student_ess_floor_value) - student_ess
        ).clamp_min(0.0) / max(student_ess_floor_value, 1.0e-12)
        student_ess_floor_loss = ess_gap.square()
        objective = objective + student_ess_weight * student_ess_floor_loss
    student_top_cap_value = min(max(float(student_top_mass_cap), 0.0), 1.0)
    student_top_cap_weight = max(float(student_top_mass_cap_loss_weight), 0.0)
    student_top_mass_cap_loss = kl.new_tensor(0.0)
    if student_top_cap_weight > 0.0 and student_top_cap_value > 0.0:
        top_gap = (
            student_top_mass_value - kl.new_tensor(student_top_cap_value)
        ).clamp_min(0.0)
        student_top_mass_cap_loss = top_gap.square()
        objective = objective + student_top_cap_weight * student_top_mass_cap_loss
    health_anchor_weight = max(float(student_health_anchor_loss_weight), 0.0)
    health_anchor_prior_blend = min(
        max(float(student_health_anchor_prior_blend), 0.0),
        1.0,
    )
    health_anchor_gap_power = max(float(student_health_anchor_gap_power), 0.0)
    health_anchor_kl = kl.new_tensor(0.0)
    health_anchor_gap = kl.new_tensor(0.0)
    health_anchor_scale = kl.new_tensor(0.0)
    if health_anchor_weight > 0.0:
        finite_count = torch.count_nonzero(finite_energy).clamp_min(1)
        uniform_anchor = torch.where(
            finite_energy,
            torch.full_like(student_safe, 1.0 / float(finite_count.detach().cpu())),
            torch.zeros_like(student_safe),
        )
        anchor = (
            uniform_anchor * (1.0 - health_anchor_prior_blend)
            + prior_weights.detach() * health_anchor_prior_blend
        )
        anchor = anchor / anchor.sum().clamp_min(1.0e-12)
        anchor_safe = anchor.clamp_min(1.0e-12)
        gap_terms: list[torch.Tensor] = []
        if student_ess_floor_value > 1.0:
            gap_terms.append(
                (
                    kl.new_tensor(student_ess_floor_value) - student_ess.detach()
                ).clamp_min(0.0)
                / max(student_ess_floor_value, 1.0e-12)
            )
        if student_top_cap_value > 0.0:
            gap_terms.append(
                (
                    student_top_mass_value.detach()
                    - kl.new_tensor(student_top_cap_value)
                ).clamp_min(0.0)
                / max(1.0 - student_top_cap_value, 1.0e-12)
            )
        if gap_terms:
            health_anchor_gap = torch.stack(gap_terms).max()
        else:
            health_anchor_gap = kl.new_tensor(1.0)
        health_anchor_scale = (
            torch.pow(health_anchor_gap.clamp_min(0.0), health_anchor_gap_power)
            if health_anchor_gap_power > 0.0
            else torch.where(
                health_anchor_gap > 0.0,
                torch.ones_like(health_anchor_gap),
                torch.zeros_like(health_anchor_gap),
            )
        )
        health_anchor_kl = torch.sum(
            student_safe * (torch.log(student_safe) - torch.log(anchor_safe))
        )
        objective = objective + health_anchor_weight * health_anchor_scale * health_anchor_kl
    logit_std_cap_value = max(float(student_logit_std_cap), 0.0)
    logit_std_weight = max(float(student_logit_std_cap_loss_weight), 0.0)
    logit_std_cap_loss = kl.new_tensor(0.0)
    if logit_std_weight > 0.0 and logit_std_cap_value > 0.0:
        std_gap = (
            student_logit_std - kl.new_tensor(logit_std_cap_value)
        ).clamp_min(0.0) / max(logit_std_cap_value, 1.0e-12)
        logit_std_cap_loss = std_gap.square()
        objective = objective + logit_std_weight * logit_std_cap_loss
    logit_range_cap_value = max(float(student_logit_range_cap), 0.0)
    logit_range_weight = max(float(student_logit_range_cap_loss_weight), 0.0)
    logit_range_cap_loss = kl.new_tensor(0.0)
    if logit_range_weight > 0.0 and logit_range_cap_value > 0.0:
        range_gap = (
            student_logit_range - kl.new_tensor(logit_range_cap_value)
        ).clamp_min(0.0) / max(logit_range_cap_value, 1.0e-12)
        logit_range_cap_loss = range_gap.square()
        objective = objective + logit_range_weight * logit_range_cap_loss
    topk_weight = max(float(topk_mass_loss_weight), 0.0)
    topk_loss = kl.new_tensor(0.0)
    topk_mass_loss = kl.new_tensor(0.0)
    topk_listwise_kl = kl.new_tensor(0.0)
    top1_nll = kl.new_tensor(0.0)
    top_count = 0
    teacher_topk_mass = kl.new_tensor(0.0)
    student_topk_mass = kl.new_tensor(0.0)
    target_topk_mass = kl.new_tensor(0.0)
    teacher_top1_mass = kl.new_tensor(0.0)
    student_top1_mass = kl.new_tensor(0.0)
    if topk_weight > 0.0:
        positive_teacher = finite_energy & torch.isfinite(teacher) & (teacher > 0.0)
        positive_count = int(torch.count_nonzero(positive_teacher).detach().cpu())
        if positive_count > 0:
            requested_top = max(
                int(topk_min_count),
                int(math.ceil(float(support_count) * max(float(topk_fraction), 0.0))),
            )
            top_count = min(max(requested_top, 1), positive_count, support_count)
            masked_teacher = torch.where(
                positive_teacher,
                teacher,
                torch.full_like(teacher, -1.0),
            )
            top_values, top_indices = torch.topk(masked_teacher, k=top_count, dim=0)
            teacher_topk_mass = top_values.sum().clamp_min(1.0e-12)
            student_topk_mass = student_safe[top_indices].sum().clamp_min(1.0e-12)
            target_topk_mass = (
                teacher_topk_mass * max(float(topk_target_mass_scale), 0.0)
            ).clamp(min=1.0e-12, max=1.0)
            topk_mass_loss = -target_topk_mass.detach() * torch.log(student_topk_mass)

            top_student_log_q = torch.log(
                student_safe[top_indices] / student_topk_mass.clamp_min(1.0e-12)
            )
            top_teacher = top_values / teacher_topk_mass
            top_teacher_safe = top_teacher.clamp_min(1.0e-12)
            topk_listwise_kl = torch.sum(
                top_teacher_safe * (torch.log(top_teacher_safe) - top_student_log_q)
            )
            teacher_top1_mass = top_values[0].clamp_min(1.0e-12)
            student_top1_mass = student_safe[top_indices[0]].clamp_min(1.0e-12)
            top1_nll = -teacher_top1_mass.detach() * torch.log(student_top1_mass)
            topk_loss = (
                topk_mass_loss
                + max(float(topk_listwise_weight), 0.0) * topk_listwise_kl
                + max(float(top1_nll_weight), 0.0) * top1_nll
            )
            objective = objective + topk_weight * topk_loss
    metrics = {
        f"{prefix}_rows": float(selected_indices.numel()),
        f"{prefix}_candidate_rows": float(torch.count_nonzero(selected_rows).detach().cpu()),
        f"{prefix}_cells": float(torch.count_nonzero(selected_focus_mask).detach().cpu()),
        f"{prefix}_families": float(len(focus_indices)),
        f"{prefix}_required_family_count": float(len(required_indices)),
        f"{prefix}_required_family_rows": float(
            torch.count_nonzero(required_observed).detach().cpu()
        ),
        f"{prefix}_required_family_fallback_used": float(fallback_used),
        f"{prefix}_primary_candidate_rows": float(primary_candidate_rows),
        f"{prefix}_fallback_candidate_rows": float(fallback_candidate_rows),
        f"{prefix}_fallback_min_rows": float(fallback_threshold),
        f"{prefix}_coverage_fallback_enabled": float(
            bool(coverage_fallback_enabled)
        ),
        f"{prefix}_coverage_fallback_used": float(coverage_fallback_used),
        f"{prefix}_coverage_fallback_family_count": float(
            coverage_fallback_family_count
        ),
        f"{prefix}_coverage_fallback_min_family_count": float(
            coverage_fallback_required_count
        ),
        f"{prefix}_coverage_fallback_rows": float(coverage_fallback_rows),
        f"{prefix}_coverage_fallback_row_min_family_count": float(
            coverage_fallback_row_count
        ),
        f"{prefix}_coverage_fallback_min_rows": float(
            coverage_fallback_min_row_count
        ),
        f"{prefix}_loss_value": float(objective.detach().cpu()),
        f"{prefix}_kl_value": float(kl.detach().cpu()),
        f"{prefix}_topk_mass_loss_weight": float(topk_weight),
        f"{prefix}_topk_loss_value": float(topk_loss.detach().cpu()),
        f"{prefix}_topk_mass_loss_value": float(topk_mass_loss.detach().cpu()),
        f"{prefix}_topk_listwise_kl_value": float(topk_listwise_kl.detach().cpu()),
        f"{prefix}_topk_listwise_weight": float(max(float(topk_listwise_weight), 0.0)),
        f"{prefix}_top1_nll_value": float(top1_nll.detach().cpu()),
        f"{prefix}_top1_nll_weight": float(max(float(top1_nll_weight), 0.0)),
        f"{prefix}_topk_fraction": float(max(float(topk_fraction), 0.0)),
        f"{prefix}_topk_min_count": float(max(int(topk_min_count), 0)),
        f"{prefix}_topk_count": float(top_count),
        f"{prefix}_teacher_topk_mass": float(teacher_topk_mass.detach().cpu()),
        f"{prefix}_student_topk_mass": float(student_topk_mass.detach().cpu()),
        f"{prefix}_target_topk_mass": float(target_topk_mass.detach().cpu()),
        f"{prefix}_topk_mass_gap": float(
            (target_topk_mass.detach() - student_topk_mass.detach()).cpu()
        ),
        f"{prefix}_teacher_top1_mass": float(teacher_top1_mass.detach().cpu()),
        f"{prefix}_student_top1_mass": float(student_top1_mass.detach().cpu()),
        f"{prefix}_teacher_ess": float(
            (1.0 / teacher_safe.square().sum().clamp_min(1.0e-12)).detach().cpu()
        ),
        f"{prefix}_raw_teacher_ess": float(raw_teacher_ess.detach().cpu()),
        f"{prefix}_teacher_top_mass": float(teacher_safe.detach().max().cpu()),
        f"{prefix}_raw_teacher_top_mass": float(raw_teacher_top_mass.detach().cpu()),
        f"{prefix}_teacher_top_mass_cap": float(top_mass_cap),
        f"{prefix}_student_top_mass": float(student_safe.detach().max().cpu()),
        f"{prefix}_student_ess": float(student_ess.detach().cpu()),
        f"{prefix}_student_ess_floor": float(student_ess_floor_value),
        f"{prefix}_student_ess_floor_loss_weight": float(student_ess_weight),
        f"{prefix}_student_ess_floor_loss_value": float(
            student_ess_floor_loss.detach().cpu()
        ),
        f"{prefix}_student_top_mass_cap": float(student_top_cap_value),
        f"{prefix}_student_top_mass_cap_loss_weight": float(student_top_cap_weight),
        f"{prefix}_student_top_mass_cap_loss_value": float(
            student_top_mass_cap_loss.detach().cpu()
        ),
        f"{prefix}_student_health_anchor_loss_weight": float(health_anchor_weight),
        f"{prefix}_student_health_anchor_prior_blend": float(
            health_anchor_prior_blend
        ),
        f"{prefix}_student_health_anchor_gap_power": float(health_anchor_gap_power),
        f"{prefix}_student_health_anchor_gap": float(
            health_anchor_gap.detach().cpu()
        ),
        f"{prefix}_student_health_anchor_scale": float(
            health_anchor_scale.detach().cpu()
        ),
        f"{prefix}_student_health_anchor_kl_value": float(
            health_anchor_kl.detach().cpu()
        ),
        f"{prefix}_student_logit_std": float(student_logit_std.detach().cpu()),
        f"{prefix}_student_logit_std_cap": float(logit_std_cap_value),
        f"{prefix}_student_logit_std_cap_loss_weight": float(logit_std_weight),
        f"{prefix}_student_logit_std_cap_loss_value": float(
            logit_std_cap_loss.detach().cpu()
        ),
        f"{prefix}_student_logit_range": float(
            student_logit_range.detach().cpu()
        ),
        f"{prefix}_student_logit_range_cap": float(logit_range_cap_value),
        f"{prefix}_student_logit_range_cap_loss_weight": float(
            logit_range_weight
        ),
        f"{prefix}_student_logit_range_cap_loss_value": float(
            logit_range_cap_loss.detach().cpu()
        ),
        f"{prefix}_teacher_prior_blend": float(blend),
        f"{prefix}_teacher_student_dot": float(
            torch.sum(teacher * student_q.detach()).detach().cpu()
        ),
        f"{prefix}_aggregate_error_mean": float(aggregate_energy.detach().mean().cpu()),
        f"{prefix}_row_aggregate_error_mean": float(
            row_aggregate_energy.detach().mean().cpu()
        ),
        f"{prefix}_family_balanced_error_mean": float(
            family_balanced_energy.detach().mean().cpu()
        ),
        f"{prefix}_family_balanced_error_mix": float(family_mix),
        f"{prefix}_weighted_mean_error_mean": float(
            weighted_mean_error.detach().mean().cpu()
        ),
        f"{prefix}_worst_family_error_mean": float(
            worst_family_error.detach().mean().cpu()
        ),
        f"{prefix}_worst_family_error_mix": float(worst_mix),
        f"{prefix}_best_error_mean": float(best_error.detach().mean().cpu()),
        f"{prefix}_row_focus_mean": float(row_focus.detach().mean().cpu()),
        f"{prefix}_min_family_count": float(required_count),
        f"{prefix}_coverage_weight_power": float(coverage_power),
        f"{prefix}_coverage_fraction_mean": float(
            coverage_fraction.detach().mean().cpu()
        ),
        f"{prefix}_coverage_fraction_min": float(
            coverage_fraction.detach().min().cpu()
        ),
        f"{prefix}_coverage_weight_mean": float(
            coverage_weight.detach().mean().cpu()
        ),
        f"{prefix}_train_only": 1.0,
    }
    for family_index in focus_indices:
        family_name = _x0_canonical_family_name(family_names[family_index])
        safe_name = family_name.replace("'", "prime").lower()
        metrics[f"{prefix}_{safe_name}_rows"] = float(
            torch.count_nonzero(selected_focus_mask[:, family_index]).detach().cpu()
        )
    return objective * weight, metrics


def consensus_oracle_distillation_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    weights: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    conflict_kl_threshold: float = 0.75,
    family_weights: dict[str, float] | None = None,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Distill only the family-oracle signal that agrees on a shared q.

    The rowwise support oracle can be nearly perfect for HN/C' while N/CA/CB
    prefer a different conformer mixture.  This train-only loss forms one
    oracle per atom family, downweights family oracles that strongly disagree
    with the all-family shared-q oracle, and distills the geometric consensus
    into the single population distribution used by inference.
    """

    scale = max(float(oracle_energy_scale), 0.0)
    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(weights), {"consensus_oracle_distill_cells": 0.0}
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(weights), {"consensus_oracle_distill_cells": 0.0}

    prior = prior_log_probs.detach() if prior_log_probs is not None else None
    all_oracle = support_reachability_oracle_predictions(
        conformer_phi.detach(),
        target.detach(),
        mask.detach(),
        prior_log_probs=prior,
        oracle_energy_scale=scale,
    )
    global_teacher = all_oracle.get("weights")
    if not isinstance(global_teacher, torch.Tensor):
        return _zero_loss_like(weights), {"consensus_oracle_distill_cells": 0.0}
    global_teacher = global_teacher.to(device=weights.device, dtype=weights.dtype).detach()
    global_log = torch.log(global_teacher.clamp_min(1.0e-12))

    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1)
    residual = (conformer_phi.detach() - target.reshape(1, *target.shape)) / scales.clamp_min(1.0e-3)
    configured_family_weights = family_weights or {}
    threshold = max(float(conflict_kl_threshold), 0.0)
    weighted_log_terms: list[torch.Tensor] = []
    family_kl_values: list[float] = []
    family_agreements: list[float] = []
    family_cell_total = 0
    effective_weight_sum = 0.0
    raw_weight_sum = 0.0
    family_count = min(conformer_phi.shape[-1], len(CHEMICAL_SHIFT_FAMILIES))
    for family_index in range(family_count):
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        family_name = str(CHEMICAL_SHIFT_FAMILIES[family_index])
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        family_residual = residual[:, family_mask, family_index]
        family_energy = family_residual.square().mean(dim=1)
        family_teacher = posterior_weights(prior, scale * family_energy)
        family_teacher = family_teacher.to(device=weights.device, dtype=weights.dtype).detach()
        family_log = torch.log(family_teacher.clamp_min(1.0e-12))
        family_kl = torch.sum(
            family_teacher.clamp_min(1.0e-12) * (family_log - global_log)
        )
        family_kl_value = float(family_kl.detach().cpu())
        if threshold > 0.0:
            agreement = float(torch.exp((-family_kl.detach() / threshold).clamp(min=-50.0)).cpu())
        else:
            agreement = 1.0
        effective_weight = family_weight * max(agreement, 0.0)
        if effective_weight <= 0.0:
            continue
        weighted_log_terms.append(family_log * effective_weight)
        family_kl_values.append(family_kl_value)
        family_agreements.append(float(agreement))
        family_cell_total += cell_count
        effective_weight_sum += effective_weight
        raw_weight_sum += family_weight

    if not weighted_log_terms or effective_weight_sum <= 0.0:
        return _zero_loss_like(weights), {
            "consensus_oracle_distill_cells": float(family_cell_total),
            "consensus_oracle_distill_families": 0.0,
        }
    consensus_log = torch.stack(weighted_log_terms, dim=0).sum(dim=0) / float(effective_weight_sum)
    teacher = torch.softmax(consensus_log, dim=-1).detach()
    student = weights.clamp_min(1.0e-12)
    teacher_safe = teacher.clamp_min(1.0e-12)
    kl = torch.sum(teacher_safe * (torch.log(teacher_safe) - torch.log(student)))
    agreement_mean = effective_weight_sum / max(raw_weight_sum, 1.0e-12)
    ess = 1.0 / teacher_safe.square().sum().clamp_min(1.0e-12)
    metrics = {
        "consensus_oracle_distill_cells": float(family_cell_total),
        "consensus_oracle_distill_families": float(len(family_kl_values)),
        "consensus_oracle_distill_kl": float(kl.detach().cpu()),
        "consensus_oracle_distill_family_kl_mean": float(sum(family_kl_values) / max(len(family_kl_values), 1)),
        "consensus_oracle_distill_family_kl_max": float(max(family_kl_values) if family_kl_values else 0.0),
        "consensus_oracle_distill_agreement_mean": float(agreement_mean),
        "consensus_oracle_distill_family_agreement_min": float(min(family_agreements) if family_agreements else 0.0),
        "consensus_oracle_distill_ess": float(ess.detach().cpu()),
        "consensus_oracle_distill_top_mass": float(torch.max(teacher_safe).detach().cpu()),
    }
    return kl * weight * float(agreement_mean), metrics


def posterior_mode_component_diversity_loss(
    mode_component_weights: torch.Tensor,
    *,
    loss_weight: float = 0.0,
    min_js: float = 0.01,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Keep internal posterior modes from collapsing to identical q(k).

    The final exported measure is still the reconciled single population.  This
    loss only acts on train-time internal mode components so each component can
    specialize before the convex reconciliation step.
    """

    weight = max(float(loss_weight), 0.0)
    if mode_component_weights.ndim != 2 or int(mode_component_weights.shape[0]) < 2:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_diversity_pairs": 0.0,
        }
    components = mode_component_weights.clamp_min(1.0e-12)
    components = components / components.sum(dim=-1, keepdim=True).clamp_min(1.0e-12)
    js_values: list[torch.Tensor] = []
    for left in range(int(components.shape[0])):
        for right in range(left + 1, int(components.shape[0])):
            p = components[left]
            q = components[right]
            m = 0.5 * (p + q)
            js = 0.5 * torch.sum(p * (torch.log(p) - torch.log(m)))
            js = js + 0.5 * torch.sum(q * (torch.log(q) - torch.log(m)))
            js_values.append(js)
    if not js_values:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_diversity_pairs": 0.0,
        }
    js_stack = torch.stack(js_values)
    mean_js = torch.mean(js_stack)
    floor = mode_component_weights.new_tensor(max(float(min_js), 0.0))
    loss = torch.relu(floor - mean_js)
    metrics = {
        "posterior_mode_diversity_pairs": float(len(js_values)),
        "posterior_mode_diversity_js_mean": float(mean_js.detach().cpu()),
        "posterior_mode_diversity_js_min": float(torch.min(js_stack).detach().cpu()),
        "posterior_mode_diversity_loss_value": float(loss.detach().cpu()),
    }
    return loss * weight, metrics


def posterior_shared_q_health_loss(
    weights: torch.Tensor,
    *,
    entropy_loss_weight: float = 0.0,
    entropy_floor: float = 0.0,
    top_mass_cap_enabled: bool = False,
    top_mass_cap: float = 1.0,
    top_mass_loss_weight: float = 0.0,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Discourage the train-time shared q from collapsing to one conformer.

    This guard acts on the generated-support posterior weights themselves.  It
    does not claim acceptance quality; it only keeps the online train signal
    honest enough that CS-reweighted posterior distillation cannot take a
    single-conformer shortcut.
    """

    if weights.numel() == 0:
        return weights.new_tensor(0.0), {
            "posterior_shared_q_health_active": 0.0,
            "posterior_shared_q_health_support": 0.0,
        }
    normalized = torch.nan_to_num(weights, nan=0.0, posinf=0.0, neginf=0.0)
    normalized = normalized.clamp_min(0.0)
    total = normalized.sum()
    if not bool(torch.isfinite(total.detach()).item()) or float(total.detach()) <= 0.0:
        normalized = torch.full_like(normalized, 1.0 / max(int(weights.numel()), 1))
    else:
        normalized = normalized / total.clamp_min(1.0e-12)
    safe = normalized.clamp_min(1.0e-12)
    entropy = -torch.sum(safe * torch.log(safe))
    ess = 1.0 / safe.square().sum().clamp_min(1.0e-12)
    top_mass = torch.amax(normalized)

    loss = weights.sum() * 0.0
    entropy_weight = max(float(entropy_loss_weight), 0.0)
    entropy_floor_value = max(float(entropy_floor), 0.0)
    entropy_gap = torch.relu(
        normalized.new_tensor(entropy_floor_value) - entropy
    )
    if entropy_weight > 0.0 and entropy_floor_value > 0.0:
        loss = loss + normalized.new_tensor(entropy_weight) * entropy_gap.square()

    top_weight = max(float(top_mass_loss_weight), 0.0)
    top_cap_value = min(max(float(top_mass_cap), 0.0), 1.0)
    top_gap = normalized.new_tensor(0.0)
    if top_mass_cap_enabled and top_weight > 0.0 and top_cap_value > 0.0:
        top_gap = torch.relu(
            (top_mass - normalized.new_tensor(top_cap_value))
            / normalized.new_tensor(top_cap_value).clamp_min(1.0e-12)
        )
        loss = loss + normalized.new_tensor(top_weight) * top_gap.square()

    active = float(
        (entropy_weight > 0.0 and entropy_floor_value > 0.0)
        or (top_mass_cap_enabled and top_weight > 0.0 and top_cap_value > 0.0)
    )
    metrics = {
        "posterior_shared_q_health_active": active,
        "posterior_shared_q_health_support": float(int(weights.numel())),
        "posterior_shared_q_health_entropy": float(entropy.detach().cpu()),
        "posterior_shared_q_health_entropy_floor": float(entropy_floor_value),
        "posterior_shared_q_health_entropy_gap": float(entropy_gap.detach().cpu()),
        "posterior_shared_q_health_entropy_loss_weight": float(entropy_weight),
        "posterior_shared_q_health_ess": float(ess.detach().cpu()),
        "posterior_shared_q_health_top_mass": float(top_mass.detach().cpu()),
        "posterior_shared_q_health_top_mass_cap": float(top_cap_value),
        "posterior_shared_q_health_top_mass_gap": float(top_gap.detach().cpu()),
        "posterior_shared_q_health_top_mass_loss_weight": float(top_weight),
        "posterior_shared_q_health_loss_value": float(loss.detach().cpu()),
    }
    return loss, metrics


def posterior_mode_family_oracle_specialization_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    mode_component_weights: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_mode_map: dict[str, int] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Train internal modes against family-specific support oracles.

    This is a train-only symmetry breaker.  Each observed atom-family oracle is
    assigned to an internal component, but inference still exposes only the
    reconciled shared posterior population.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_oracle_cells": 0.0,
        }
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    if mode_component_weights.ndim != 2 or int(mode_component_weights.shape[0]) <= 0:
        return _zero_loss_like(conformer_phi), {
            "posterior_mode_family_oracle_cells": 0.0,
        }
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_oracle_cells": 0.0,
        }
    mode_count = int(mode_component_weights.shape[0])
    mode_components = mode_component_weights.clamp_min(1.0e-12)
    mode_components = mode_components / mode_components.sum(dim=-1, keepdim=True).clamp_min(1.0e-12)
    prior = prior_log_probs.detach() if prior_log_probs is not None else None
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1)
    residual = (conformer_phi.detach() - target.reshape(1, *target.shape)) / scales.clamp_min(1.0e-3)
    family_mode_map = dict(family_mode_map or {})
    losses: list[tuple[torch.Tensor, float]] = []
    kl_values: list[float] = []
    active_modes: set[int] = set()
    cell_total = 0
    scale = max(float(oracle_energy_scale), 0.0)
    configured_family_weights = family_weights or {}
    family_count = min(conformer_phi.shape[-1], len(family_names))
    for family_index in range(family_count):
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        family_name = str(family_names[family_index])
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        assigned_mode = family_mode_map.get(family_name, family_index % mode_count)
        assigned_mode = int(assigned_mode) % mode_count
        family_residual = residual[:, family_mask, family_index]
        family_energy = family_residual.square().mean(dim=1)
        teacher = posterior_weights(prior, scale * family_energy).to(
            device=mode_component_weights.device,
            dtype=mode_component_weights.dtype,
        ).detach()
        student = mode_components[assigned_mode]
        teacher_safe = teacher.clamp_min(1.0e-12)
        student_safe = student.clamp_min(1.0e-12)
        kl = torch.sum(teacher_safe * (torch.log(teacher_safe) - torch.log(student_safe)))
        losses.append((kl, family_weight))
        kl_values.append(float(kl.detach().cpu()))
        active_modes.add(assigned_mode)
        cell_total += cell_count
    if not losses:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_oracle_cells": 0.0,
        }
    weighted_loss = mode_component_weights.new_tensor(0.0)
    weight_sum = 0.0
    for family_loss, family_weight in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        "posterior_mode_family_oracle_cells": float(cell_total),
        "posterior_mode_family_oracle_families": float(len(losses)),
        "posterior_mode_family_oracle_active_modes": float(len(active_modes)),
        "posterior_mode_family_oracle_kl_mean": float(sum(kl_values) / max(len(kl_values), 1)),
        "posterior_mode_family_oracle_kl_max": float(max(kl_values) if kl_values else 0.0),
        "posterior_mode_family_oracle_loss_value": float(loss.detach().cpu()),
    }
    return loss * weight, metrics


def posterior_mode_family_energy_target_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    mode_component_weights: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    family_weights: dict[str, float] | None = None,
    family_mode_map: dict[str, int] | None = None,
    target_clip: float = 6.0,
    huber_beta: float = 0.5,
    std_loss_weight: float = 0.0,
    corr_loss_weight: float = 0.0,
    rank_loss_weight: float = 0.0,
    rank_margin: float = 0.05,
    rank_top_fraction: float = 0.10,
    temperature: float = 1.0,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Align assigned mode energies with family-specific support teachers.

    Unlike the KL-only mode oracle, this loss compares the energy implied by a
    mode component's weights to the family teacher energy.  It is still
    train-only: inference exports the reconciled mixture posterior, not
    family-specific weights.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_energy_target_cells": 0.0,
        }
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    if mode_component_weights.ndim != 2 or int(mode_component_weights.shape[0]) <= 0:
        return _zero_loss_like(conformer_phi), {
            "posterior_mode_family_energy_target_cells": 0.0,
        }
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if int(mode_component_weights.shape[-1]) != int(conformer_phi.shape[0]):
        raise ValueError("mode_component_weights must have K conformer weights")
    if not bool(torch.any(mask)):
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_energy_target_cells": 0.0,
        }

    mode_count = int(mode_component_weights.shape[0])
    components = mode_component_weights.clamp_min(1.0e-12)
    components = components / components.sum(dim=-1, keepdim=True).clamp_min(1.0e-12)
    if prior_log_probs is None:
        prior_log = mode_component_weights.new_zeros(mode_component_weights.shape[-1])
        detached_prior = None
    else:
        prior_log = prior_log_probs.to(
            device=mode_component_weights.device,
            dtype=mode_component_weights.dtype,
        ).detach()
        detached_prior = prior_log
    ppm_scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1).clamp_min(1.0e-3)
    residual = (conformer_phi.detach() - target.reshape(1, *target.shape)) / ppm_scales
    family_mode_map = dict(family_mode_map or {})
    configured_family_weights = family_weights or {}
    scale = max(float(oracle_energy_scale), 0.0)
    temp = max(float(temperature), 1.0e-6)
    clip_value = max(float(target_clip), 0.0)
    base_beta = max(float(huber_beta), 1.0e-6)
    std_weight = max(float(std_loss_weight), 0.0)
    corr_weight = max(float(corr_loss_weight), 0.0)
    rank_weight = max(float(rank_loss_weight), 0.0)

    losses: list[tuple[torch.Tensor, float]] = []
    corr_values: list[float] = []
    std_ratio_values: list[float] = []
    rank_gap_values: list[float] = []
    active_modes: set[int] = set()
    cell_total = 0
    family_count = min(conformer_phi.shape[-1], len(family_names))
    for family_index in range(family_count):
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        family_name = str(family_names[family_index])
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        assigned_mode = int(family_mode_map.get(family_name, family_index % mode_count))
        assigned_mode = assigned_mode % mode_count
        family_residual = residual[:, family_mask, family_index]
        family_energy = family_residual.square().mean(dim=1)
        teacher = posterior_weights(detached_prior, scale * family_energy).to(
            device=mode_component_weights.device,
            dtype=mode_component_weights.dtype,
        ).detach()
        teacher_safe = teacher.clamp_min(1.0e-12)
        student_safe = components[assigned_mode].clamp_min(1.0e-12)
        target_energy = temp * (prior_log - torch.log(teacher_safe))
        target_energy = target_energy - target_energy.mean()
        if clip_value > 0.0:
            target_energy = target_energy.clamp(min=-clip_value, max=clip_value)
        predicted_energy = temp * (prior_log - torch.log(student_safe))
        predicted_energy = predicted_energy - predicted_energy.mean()
        base_loss = F.smooth_l1_loss(
            predicted_energy,
            target_energy.detach(),
            beta=base_beta,
            reduction="mean",
        )
        predicted_std = predicted_energy.std(unbiased=False)
        target_std = target_energy.detach().std(unbiased=False)
        family_loss = base_loss
        if std_weight > 0.0:
            eps = predicted_energy.new_tensor(1.0e-6)
            std_loss = F.smooth_l1_loss(
                torch.log(predicted_std.clamp_min(eps)),
                torch.log(target_std.clamp_min(eps)),
                beta=0.25,
                reduction="mean",
            )
            family_loss = family_loss + std_weight * std_loss
        target_z = target_energy.detach() / target_std.clamp_min(1.0e-6)
        predicted_z = predicted_energy / predicted_std.clamp_min(1.0e-6)
        corr = torch.mean(predicted_z * target_z)
        if corr_weight > 0.0:
            family_loss = family_loss + corr_weight * (1.0 - corr).clamp_min(0.0)
        if rank_weight > 0.0 and int(predicted_energy.numel()) >= 2:
            support_count = int(predicted_energy.numel())
            rank_count = min(
                max(int(round(support_count * max(float(rank_top_fraction), 0.0))), 1),
                support_count // 2,
            )
            if rank_count > 0:
                high_q_indices = torch.topk(-target_energy.detach(), rank_count).indices
                low_q_indices = torch.topk(target_energy.detach(), rank_count).indices
                high_q_energy = predicted_energy.index_select(0, high_q_indices)
                low_q_energy = predicted_energy.index_select(0, low_q_indices)
                pair_gap = low_q_energy[:, None] - high_q_energy[None, :]
                family_loss = family_loss + rank_weight * torch.relu(
                    predicted_energy.new_tensor(max(float(rank_margin), 0.0)) - pair_gap
                ).mean()
                rank_gap_values.append(float(pair_gap.detach().mean().cpu()))
        losses.append((family_loss, family_weight))
        corr_values.append(float(corr.detach().cpu()))
        std_ratio_values.append(
            float((predicted_std.detach() / target_std.detach().clamp_min(1.0e-6)).cpu())
        )
        active_modes.add(assigned_mode)
        cell_total += cell_count

    if not losses:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_energy_target_cells": 0.0,
        }
    weighted_loss = mode_component_weights.new_tensor(0.0)
    weight_sum = 0.0
    for family_loss, family_weight in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        "posterior_mode_family_energy_target_cells": float(cell_total),
        "posterior_mode_family_energy_target_families": float(len(losses)),
        "posterior_mode_family_energy_target_active_modes": float(len(active_modes)),
        "posterior_mode_family_energy_target_loss_value": float(loss.detach().cpu()),
        "posterior_mode_family_energy_target_corr_mean": float(
            sum(corr_values) / max(len(corr_values), 1)
        ),
        "posterior_mode_family_energy_target_std_ratio_mean": float(
            sum(std_ratio_values) / max(len(std_ratio_values), 1)
        ),
        "posterior_mode_family_energy_target_rank_gap_mean": float(
            sum(rank_gap_values) / max(len(rank_gap_values), 1)
        ),
        "posterior_mode_family_energy_target_std_loss_weight": float(std_weight),
        "posterior_mode_family_energy_target_corr_loss_weight": float(corr_weight),
        "posterior_mode_family_energy_target_rank_loss_weight": float(rank_weight),
    }
    return loss * weight, metrics


def posterior_mode_family_prediction_contrast_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    mode_component_weights: torch.Tensor,
    *,
    loss_weight: float = 0.0,
    temperature: float = 0.25,
    family_weights: dict[str, float] | None = None,
    family_mode_map: dict[str, int] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Contrast mode-specific ensemble observables by atom family.

    This train-only objective makes assigned internal modes explain their
    assigned atom-family rows better than sibling modes.  It never exports
    family-specific posterior weights; inference still uses the reconciled
    single population produced by ``PosteriorModeMixture``.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_prediction_contrast_cells": 0.0,
        }
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    if mode_component_weights.ndim != 2 or int(mode_component_weights.shape[0]) < 2:
        return _zero_loss_like(conformer_phi), {
            "posterior_mode_family_prediction_contrast_cells": 0.0,
        }
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_prediction_contrast_cells": 0.0,
        }

    mode_components = mode_component_weights.clamp_min(1.0e-12)
    mode_components = mode_components / mode_components.sum(dim=-1, keepdim=True).clamp_min(
        1.0e-12
    )
    mode_phi = torch.einsum("mk,klf->mlf", mode_components, conformer_phi)
    mode_count = int(mode_components.shape[0])
    family_mode_map = dict(family_mode_map or {})
    configured_family_weights = family_weights or {}
    temp = max(float(temperature), 1.0e-4)

    losses: list[tuple[torch.Tensor, float]] = []
    cell_total = 0
    correct = 0
    assigned_mse_values: list[float] = []
    best_mse_values: list[float] = []
    margin_values: list[float] = []
    family_count = min(conformer_phi.shape[-1], len(family_names))
    ppm_scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).clamp_min(1.0e-3)
    for family_index in range(family_count):
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        family_name = str(family_names[family_index])
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        assigned_mode = int(family_mode_map.get(family_name, family_index % mode_count))
        assigned_mode = assigned_mode % mode_count

        target_values = target[family_mask, family_index].reshape(1, -1)
        prediction_values = mode_phi[:, family_mask, family_index]
        residual = (prediction_values - target_values) / ppm_scales[family_index]
        mode_mse = residual.square().mean(dim=1)
        logits = (-mode_mse / temp).reshape(1, -1)
        label = torch.tensor(
            [assigned_mode],
            device=conformer_phi.device,
            dtype=torch.long,
        )
        contrast = torch.nn.functional.cross_entropy(logits, label)
        losses.append((contrast, family_weight))

        best_mode = int(torch.argmin(mode_mse.detach()).cpu())
        correct += int(best_mode == assigned_mode)
        assigned_mse = float(mode_mse[assigned_mode].detach().cpu())
        best_mse = float(torch.min(mode_mse.detach()).cpu())
        assigned_mse_values.append(assigned_mse)
        best_mse_values.append(best_mse)
        if mode_count > 1:
            other_mask = torch.ones(mode_count, device=mode_mse.device, dtype=torch.bool)
            other_mask[assigned_mode] = False
            other_mean = torch.mean(mode_mse[other_mask])
            margin_values.append(float((other_mean - mode_mse[assigned_mode]).detach().cpu()))
        cell_total += cell_count

    if not losses:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_prediction_contrast_cells": 0.0,
        }
    weighted_loss = mode_component_weights.new_tensor(0.0)
    weight_sum = 0.0
    for family_loss, family_weight in losses:
        weighted_loss = weighted_loss + family_loss * family_weight
        weight_sum += family_weight
    loss = weighted_loss / max(weight_sum, 1.0e-12)
    metrics = {
        "posterior_mode_family_prediction_contrast_cells": float(cell_total),
        "posterior_mode_family_prediction_contrast_families": float(len(losses)),
        "posterior_mode_family_prediction_contrast_accuracy": float(
            correct / max(len(losses), 1)
        ),
        "posterior_mode_family_prediction_contrast_assigned_mse_mean": float(
            sum(assigned_mse_values) / max(len(assigned_mse_values), 1)
        ),
        "posterior_mode_family_prediction_contrast_best_mse_mean": float(
            sum(best_mse_values) / max(len(best_mse_values), 1)
        ),
        "posterior_mode_family_prediction_contrast_margin_mean": float(
            sum(margin_values) / max(len(margin_values), 1)
        ),
        "posterior_mode_family_prediction_contrast_loss_value": float(loss.detach().cpu()),
    }
    return loss * weight, metrics


def posterior_mode_family_mixture_teacher_loss(
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    mode_weights: torch.Tensor,
    mode_component_weights: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    oracle_energy_scale: float = 256.0,
    loss_weight: float = 0.0,
    mode_sharpness: float = 1.0,
    mode_kl_weight: float = 1.0,
    component_kl_weight: float = 1.0,
    mixture_kl_weight: float = 0.5,
    family_weights: dict[str, float] | None = None,
    family_mode_map: dict[str, int] | None = None,
    family_names: tuple[str, ...] | list[str] = CHEMICAL_SHIFT_FAMILIES,
) -> tuple[torch.Tensor, dict[str, float]]:
    """Distill family support oracles into the internal mode mixture.

    Family-specific support oracles are train-only teachers.  They are grouped
    by assigned internal mode, then distilled into component weights and mode
    mixture logits.  The exported inference object remains the reconciled
    single posterior population, not family-specific weights.
    """

    weight = max(float(loss_weight), 0.0)
    if weight <= 0.0:
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_mixture_teacher_cells": 0.0,
        }
    if conformer_phi.ndim != 3 or target_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], target_grid/mask [L,F]")
    if mode_component_weights.ndim != 2 or mode_weights.ndim != 1:
        return _zero_loss_like(conformer_phi), {
            "posterior_mode_family_mixture_teacher_cells": 0.0,
        }
    mode_count = int(mode_component_weights.shape[0])
    if mode_count < 2 or int(mode_weights.shape[0]) != mode_count:
        return _zero_loss_like(conformer_phi), {
            "posterior_mode_family_mixture_teacher_cells": 0.0,
        }
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("target_grid and observed_mask must match conformer_phi [L,F]")
    if not bool(torch.any(mask)):
        return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_mixture_teacher_cells": 0.0,
        }

    components = mode_component_weights.clamp_min(1.0e-12)
    components = components / components.sum(dim=-1, keepdim=True).clamp_min(1.0e-12)
    student_modes = mode_weights.clamp_min(1.0e-12)
    student_modes = student_modes / student_modes.sum().clamp_min(1.0e-12)
    prior = prior_log_probs.detach() if prior_log_probs is not None else None
    ppm_scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1).clamp_min(1.0e-3)
    residual = (conformer_phi.detach() - target.reshape(1, *target.shape)) / ppm_scales
    family_mode_map = dict(family_mode_map or {})
    configured_family_weights = family_weights or {}
    scale = max(float(oracle_energy_scale), 0.0)

    log_terms_by_mode: list[list[tuple[torch.Tensor, float]]] = [
        [] for _ in range(mode_count)
    ]
    mode_mass_values = mode_component_weights.new_zeros(mode_count)
    family_kl_values: list[float] = []
    active_modes: set[int] = set()
    cell_total = 0
    family_count = min(conformer_phi.shape[-1], len(family_names))
    for family_index in range(family_count):
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        family_name = str(family_names[family_index])
        family_weight = max(float(configured_family_weights.get(family_name, 1.0)), 0.0)
        if family_weight <= 0.0:
            continue
        assigned_mode = int(family_mode_map.get(family_name, family_index % mode_count))
        assigned_mode = assigned_mode % mode_count
        family_residual = residual[:, family_mask, family_index]
        family_energy = family_residual.square().mean(dim=1)
        teacher = posterior_weights(prior, scale * family_energy).to(
            device=mode_component_weights.device,
            dtype=mode_component_weights.dtype,
        ).detach()
        log_terms_by_mode[assigned_mode].append((torch.log(teacher.clamp_min(1.0e-12)), family_weight))
        mode_mass_values[assigned_mode] = mode_mass_values[assigned_mode] + float(family_weight)
        student_component = components[assigned_mode].clamp_min(1.0e-12)
        teacher_safe = teacher.clamp_min(1.0e-12)
        family_kl = torch.sum(
            teacher_safe * (torch.log(teacher_safe) - torch.log(student_component))
        )
        family_kl_values.append(float(family_kl.detach().cpu()))
        active_modes.add(assigned_mode)
        cell_total += cell_count

    total_mode_mass = mode_mass_values.sum().clamp_min(1.0e-12)
    if not active_modes or float(total_mode_mass.detach().cpu()) <= 0.0:
            return _zero_loss_like(mode_component_weights), {
            "posterior_mode_family_mixture_teacher_cells": float(cell_total),
            "posterior_mode_family_mixture_teacher_families": 0.0,
        }
    teacher_modes = mode_mass_values / total_mode_mass
    sharpness = max(float(mode_sharpness), 1.0e-6)
    if abs(sharpness - 1.0) > 1.0e-8:
        teacher_modes = teacher_modes.clamp_min(1.0e-12).pow(sharpness)
        teacher_modes = teacher_modes / teacher_modes.sum().clamp_min(1.0e-12)
    teacher_modes = teacher_modes.detach()
    teacher_components = components.detach().clone()
    active_component_losses: list[tuple[torch.Tensor, torch.Tensor]] = []
    for mode_index in sorted(active_modes):
        terms = log_terms_by_mode[mode_index]
        if not terms:
            continue
        weighted_log = mode_component_weights.new_zeros(mode_component_weights.shape[-1])
        term_weight = 0.0
        for log_term, term_family_weight in terms:
            weighted_log = weighted_log + log_term * term_family_weight
            term_weight += term_family_weight
        teacher_component = torch.softmax(weighted_log / max(term_weight, 1.0e-12), dim=-1)
        teacher_components[mode_index] = teacher_component.detach()
        teacher_safe = teacher_component.clamp_min(1.0e-12)
        student_safe = components[mode_index].clamp_min(1.0e-12)
        active_component_losses.append(
            (
                torch.sum(teacher_safe * (torch.log(teacher_safe) - torch.log(student_safe))),
                teacher_modes[mode_index],
            )
        )

    teacher_mode_safe = teacher_modes.clamp_min(1.0e-12)
    student_mode_safe = student_modes.clamp_min(1.0e-12)
    mode_kl = torch.sum(
        teacher_mode_safe * (torch.log(teacher_mode_safe) - torch.log(student_mode_safe))
    )
    component_kl = mode_component_weights.new_tensor(0.0)
    component_weight_sum = mode_component_weights.new_tensor(0.0)
    for component_loss, component_weight in active_component_losses:
        component_kl = component_kl + component_loss * component_weight
        component_weight_sum = component_weight_sum + component_weight
    component_kl = component_kl / component_weight_sum.clamp_min(1.0e-12)
    teacher_mix = torch.sum(teacher_modes.reshape(-1, 1) * teacher_components, dim=0)
    student_mix = torch.sum(student_modes.reshape(-1, 1) * components, dim=0)
    teacher_mix_safe = teacher_mix.clamp_min(1.0e-12)
    student_mix_safe = student_mix.clamp_min(1.0e-12)
    mixture_kl = torch.sum(
        teacher_mix_safe * (torch.log(teacher_mix_safe) - torch.log(student_mix_safe))
    )
    loss = (
        mode_kl * max(float(mode_kl_weight), 0.0)
        + component_kl * max(float(component_kl_weight), 0.0)
        + mixture_kl * max(float(mixture_kl_weight), 0.0)
    )
    entropy = -torch.sum(teacher_mode_safe * torch.log(teacher_mode_safe))
    metrics = {
        "posterior_mode_family_mixture_teacher_cells": float(cell_total),
        "posterior_mode_family_mixture_teacher_families": float(len(family_kl_values)),
        "posterior_mode_family_mixture_teacher_active_modes": float(len(active_modes)),
        "posterior_mode_family_mixture_teacher_mode_kl": float(mode_kl.detach().cpu()),
        "posterior_mode_family_mixture_teacher_component_kl": float(component_kl.detach().cpu()),
        "posterior_mode_family_mixture_teacher_mixture_kl": float(mixture_kl.detach().cpu()),
        "posterior_mode_family_mixture_teacher_family_kl_mean": float(
            sum(family_kl_values) / max(len(family_kl_values), 1)
        ),
        "posterior_mode_family_mixture_teacher_entropy": float(entropy.detach().cpu()),
        "posterior_mode_family_mixture_teacher_top_mass": float(
            torch.max(teacher_mode_safe).detach().cpu()
        ),
        "posterior_mode_family_mixture_teacher_mode_sharpness": float(sharpness),
        "posterior_mode_family_mixture_teacher_loss_value": float(loss.detach().cpu()),
    }
    return loss * weight, metrics


def family_evidence_conflict_gates(
    conformer_phi: torch.Tensor,
    evidence_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    *,
    prior_log_probs: torch.Tensor | None = None,
    conflict_kl_threshold: float = 0.75,
    min_scale: float = 0.25,
) -> tuple[dict[str, float], dict[str, float]]:
    """Return inference-safe family gates from evidence-row oracle conflict.

    The gates use conditioning rows only.  They do not introduce family-specific
    posterior weights; they only scale learned family evidence energies before
    those energies are summed into the single shared posterior.
    """

    if conformer_phi.ndim != 3 or evidence_grid.ndim != 2 or observed_mask.ndim != 2:
        raise ValueError("expected conformer_phi [K,L,F], evidence_grid/mask [L,F]")
    target = evidence_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    mask = observed_mask.to(device=conformer_phi.device, dtype=torch.bool) & torch.isfinite(target)
    if conformer_phi.shape[1:] != target.shape or target.shape != mask.shape:
        raise ValueError("evidence_grid and observed_mask must match conformer_phi [L,F]")
    family_count = min(conformer_phi.shape[-1], len(CHEMICAL_SHIFT_FAMILIES))
    gates = {str(CHEMICAL_SHIFT_FAMILIES[index]): 1.0 for index in range(family_count)}
    metrics: dict[str, float] = {"evidence_conflict_gate_cells": 0.0}
    if not bool(torch.any(mask)):
        return gates, metrics
    prior = prior_log_probs.detach() if prior_log_probs is not None else None
    all_oracle = support_reachability_oracle_predictions(
        conformer_phi.detach(),
        target.detach(),
        mask.detach(),
        prior_log_probs=prior,
    )
    global_teacher = all_oracle.get("weights")
    if not isinstance(global_teacher, torch.Tensor):
        return gates, metrics
    global_teacher = global_teacher.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    global_log = torch.log(global_teacher.clamp_min(1.0e-12))
    scales = conformer_phi.new_tensor(
        ATOM_FAMILY_PPM_SCALES[: conformer_phi.shape[-1]]
    ).reshape(1, 1, -1)
    residual = (conformer_phi.detach() - target.reshape(1, *target.shape)) / scales.clamp_min(1.0e-3)
    threshold = max(float(conflict_kl_threshold), 1.0e-6)
    floor = min(max(float(min_scale), 0.0), 1.0)
    family_gate_values: list[float] = []
    family_kl_values: list[float] = []
    family_cell_total = 0
    for family_index in range(family_count):
        family_name = str(CHEMICAL_SHIFT_FAMILIES[family_index])
        family_mask = mask[:, family_index]
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        if cell_count <= 0:
            continue
        family_residual = residual[:, family_mask, family_index]
        family_energy = family_residual.square().mean(dim=1)
        family_teacher = posterior_weights(prior, 256.0 * family_energy)
        family_teacher = family_teacher.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
        family_log = torch.log(family_teacher.clamp_min(1.0e-12))
        family_kl = torch.sum(
            family_teacher.clamp_min(1.0e-12) * (family_log - global_log)
        )
        agreement = float(torch.exp((-family_kl.detach() / threshold).clamp(min=-50.0)).cpu())
        gate = floor + (1.0 - floor) * max(agreement, 0.0)
        gate = min(max(gate, floor), 1.0)
        gates[family_name] = gate
        kl_value = float(family_kl.detach().cpu())
        safe_family = "cprime" if family_name == "C'" else family_name.lower()
        metrics[f"evidence_conflict_gate_{safe_family}"] = float(gate)
        metrics[f"evidence_conflict_kl_{safe_family}"] = kl_value
        family_gate_values.append(float(gate))
        family_kl_values.append(kl_value)
        family_cell_total += cell_count
    metrics["evidence_conflict_gate_cells"] = float(family_cell_total)
    if family_gate_values:
        metrics["evidence_conflict_gate_mean"] = float(sum(family_gate_values) / len(family_gate_values))
        metrics["evidence_conflict_gate_min"] = float(min(family_gate_values))
        metrics["evidence_conflict_kl_mean"] = float(sum(family_kl_values) / len(family_kl_values))
        metrics["evidence_conflict_kl_max"] = float(max(family_kl_values))
    return gates, metrics


def _update_support_reachability_metrics(
    *,
    accumulator: _SplitAccumulator,
    conformer_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    prior_log_probs: torch.Tensor | None,
) -> dict[str, Any] | None:
    oracle = support_reachability_oracle_predictions(
        conformer_phi,
        target_grid,
        observed_mask,
        prior_log_probs=prior_log_probs,
    )
    mask = oracle["mask"]
    if not isinstance(mask, torch.Tensor) or not bool(torch.any(mask)):
        return None
    target = target_grid.to(device=conformer_phi.device, dtype=conformer_phi.dtype)
    prediction_specs = (
        ("support_shared_q_oracle_by_family", oracle["shared_q_prediction"]),
        ("support_single_conformer_oracle_by_family", oracle["single_prediction"]),
        ("support_rowwise_oracle_by_family", oracle["rowwise_prediction"]),
        ("support_clipped_oracle_by_family", oracle["clipped_prediction"]),
    )
    for family_index, family_name in enumerate(CHEMICAL_SHIFT_FAMILIES):
        family_mask = mask[:, family_index] & torch.isfinite(target[:, family_index])
        if not bool(torch.any(family_mask)):
            continue
        for accumulator_name, prediction in prediction_specs:
            if not isinstance(prediction, torch.Tensor):
                continue
            family_accumulator = getattr(accumulator, accumulator_name)[family_name]
            family_accumulator.update(
                prediction[:, family_index][family_mask],
                target[:, family_index][family_mask],
            )
        family_target = target[:, family_index][family_mask]
        family_min = torch.amin(conformer_phi[:, family_mask, family_index], dim=0)
        family_max = torch.amax(conformer_phi[:, family_mask, family_index], dim=0)
        inside = (family_target >= family_min) & (family_target <= family_max)
        outside_gap = torch.where(
            family_target < family_min,
            family_min - family_target,
            torch.where(
                family_target > family_max,
                family_target - family_max,
                torch.zeros_like(family_target),
            ),
        )
        scale = max(float(ATOM_FAMILY_PPM_SCALES[family_index]), 1.0e-3)
        prefix = "cprime" if family_name == "C'" else family_name.lower()
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        accumulator.update_scalar_metric(
            f"{prefix}_support_within_fraction",
            float(torch.mean(inside.to(dtype=conformer_phi.dtype)).detach().cpu()),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            f"{prefix}_support_outside_gap_norm_mean",
            float(torch.mean(outside_gap / scale).detach().cpu()),
            count=cell_count,
        )
    diagnostics = oracle.get("diagnostics", {})
    if isinstance(diagnostics, dict):
        cell_count = int(diagnostics.get("cell_count", 0))
        accumulator.update_scalar_metric(
            "support_shared_q_oracle_ess",
            float(diagnostics.get("shared_q_oracle_ess", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "support_shared_q_oracle_top_mass",
            float(diagnostics.get("shared_q_oracle_top_mass", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "support_within_fraction",
            float(diagnostics.get("within_support_fraction", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "support_outside_gap_norm_mean",
            float(diagnostics.get("outside_gap_norm_mean", float("nan"))),
            count=cell_count,
        )
    return oracle


def _update_sidecar_support_reachability_metrics(
    *,
    accumulator: _SplitAccumulator,
    sidecar_phi: torch.Tensor,
    target_grid: torch.Tensor,
    observed_mask: torch.Tensor,
    prior_log_probs: torch.Tensor | None,
    oracle_solver: str = "energy_softmax",
    bme_steps: int = 64,
    bme_learning_rate: float = 0.20,
    bme_kl_weight: float = 0.01,
    bme_likelihood_kind: str = "gaussian",
    bme_student_df: float = 4.0,
    bme_good_bad_outlier_prob: float = 0.05,
    bme_good_bad_bad_scale: float = 8.0,
    bme_reference_offset_l2: float = 0.0,
    bme_reference_offset_learning_rate: float = 0.05,
    bme_reference_offset_max_abs_ppm: float = 0.0,
    bme_restart_count: int = 0,
    bme_restart_noise: float = 0.0,
    bme_restart_seed: int = 0,
    bme_energy_warmstart_scales: Sequence[float] | None = None,
    bme_ccc_loss_weight: float = 0.0,
    bme_ccc_floor: float = 0.95,
    bme_ccc_min_points: int = 3,
    bme_ccc_family_weight_mode: str = "cell",
    bme_ccc_dual_gap_learning_rate: float = 0.0,
    bme_ccc_dual_gap_max_multiplier: float = 1.0,
    bme_ccc_dual_gap_update_every: int = 1,
    bme_ccc_dual_gap_warmup_steps: int = 0,
    bme_ccc_dual_gap_loss_kind: str = "quadratic",
    bme_selection_metric: str = "objective",
    bme_ess_floor: float = 0.0,
    bme_ess_loss_weight: float = 0.0,
    bme_top_mass_cap: float = 0.0,
    bme_top_mass_loss_weight: float = 0.0,
    precomputed_oracle: dict[str, Any] | None = None,
) -> None:
    """Track UCBShift sidecar support upper bounds for the fixed x0 ensemble."""

    oracle_reused = precomputed_oracle is not None
    if precomputed_oracle is None:
        oracle = support_reachability_oracle_predictions(
            sidecar_phi,
            target_grid,
            observed_mask,
            prior_log_probs=prior_log_probs,
            oracle_solver=oracle_solver,
            bme_steps=bme_steps,
            bme_learning_rate=bme_learning_rate,
            bme_kl_weight=bme_kl_weight,
            bme_likelihood_kind=bme_likelihood_kind,
            bme_student_df=bme_student_df,
            bme_good_bad_outlier_prob=bme_good_bad_outlier_prob,
            bme_good_bad_bad_scale=bme_good_bad_bad_scale,
            bme_reference_offset_l2=bme_reference_offset_l2,
            bme_reference_offset_learning_rate=bme_reference_offset_learning_rate,
            bme_reference_offset_max_abs_ppm=bme_reference_offset_max_abs_ppm,
            bme_restart_count=bme_restart_count,
            bme_restart_noise=bme_restart_noise,
            bme_restart_seed=bme_restart_seed,
            bme_energy_warmstart_scales=bme_energy_warmstart_scales,
            bme_ccc_loss_weight=bme_ccc_loss_weight,
            bme_ccc_floor=bme_ccc_floor,
            bme_ccc_min_points=bme_ccc_min_points,
            bme_ccc_family_weight_mode=bme_ccc_family_weight_mode,
            bme_ccc_dual_gap_learning_rate=bme_ccc_dual_gap_learning_rate,
            bme_ccc_dual_gap_max_multiplier=bme_ccc_dual_gap_max_multiplier,
            bme_ccc_dual_gap_update_every=bme_ccc_dual_gap_update_every,
            bme_ccc_dual_gap_warmup_steps=bme_ccc_dual_gap_warmup_steps,
            bme_ccc_dual_gap_loss_kind=bme_ccc_dual_gap_loss_kind,
            bme_selection_metric=bme_selection_metric,
            bme_ess_floor=bme_ess_floor,
            bme_ess_loss_weight=bme_ess_loss_weight,
            bme_top_mass_cap=bme_top_mass_cap,
            bme_top_mass_loss_weight=bme_top_mass_loss_weight,
        )
    else:
        oracle = precomputed_oracle
    mask = oracle["mask"]
    if not isinstance(mask, torch.Tensor) or not bool(torch.any(mask)):
        return
    sidecar = sidecar_phi.detach()
    target = target_grid.to(device=sidecar.device, dtype=sidecar.dtype)
    prediction_specs = (
        (
            "sidecar_support_shared_q_oracle_by_family",
            oracle["shared_q_prediction"],
        ),
        (
            "sidecar_support_single_conformer_oracle_by_family",
            oracle["single_prediction"],
        ),
        (
            "sidecar_support_rowwise_oracle_by_family",
            oracle["rowwise_prediction"],
        ),
        (
            "sidecar_support_clipped_oracle_by_family",
            oracle["clipped_prediction"],
        ),
    )
    for family_index, family_name in enumerate(CHEMICAL_SHIFT_FAMILIES):
        family_mask = mask[:, family_index] & torch.isfinite(target[:, family_index])
        if not bool(torch.any(family_mask)):
            continue
        for accumulator_name, prediction in prediction_specs:
            if not isinstance(prediction, torch.Tensor):
                continue
            family_accumulator = getattr(accumulator, accumulator_name)[family_name]
            family_accumulator.update(
                prediction[:, family_index][family_mask],
                target[:, family_index][family_mask],
            )
        family_target = target[:, family_index][family_mask]
        family_min = torch.amin(sidecar[:, family_mask, family_index], dim=0)
        family_max = torch.amax(sidecar[:, family_mask, family_index], dim=0)
        inside = (family_target >= family_min) & (family_target <= family_max)
        outside_gap = torch.where(
            family_target < family_min,
            family_min - family_target,
            torch.where(
                family_target > family_max,
                family_target - family_max,
                torch.zeros_like(family_target),
            ),
        )
        scale = max(float(ATOM_FAMILY_PPM_SCALES[family_index]), 1.0e-3)
        prefix = "cprime" if family_name == "C'" else family_name.lower()
        cell_count = int(torch.count_nonzero(family_mask).detach().cpu())
        accumulator.update_scalar_metric(
            f"sidecar_{prefix}_support_within_fraction",
            float(torch.mean(inside.to(dtype=sidecar.dtype)).detach().cpu()),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            f"sidecar_{prefix}_support_outside_gap_norm_mean",
            float(torch.mean(outside_gap / scale).detach().cpu()),
            count=cell_count,
        )
    diagnostics = oracle.get("diagnostics", {})
    if isinstance(diagnostics, dict):
        cell_count = int(diagnostics.get("cell_count", 0))
        accumulator.update_scalar_metric(
            "sidecar_support_shared_q_oracle_ess",
            float(diagnostics.get("shared_q_oracle_ess", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "sidecar_support_shared_q_oracle_top_mass",
            float(diagnostics.get("shared_q_oracle_top_mass", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "sidecar_support_shared_q_oracle_reused",
            float(oracle_reused),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "sidecar_support_within_fraction",
            float(diagnostics.get("within_support_fraction", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "sidecar_support_outside_gap_norm_mean",
            float(diagnostics.get("outside_gap_norm_mean", float("nan"))),
            count=cell_count,
        )
        accumulator.update_scalar_metric(
            "sidecar_support_shared_q_oracle_solver_is_bme",
            float(diagnostics.get("shared_q_oracle_solver_is_bme", 0.0)),
            count=cell_count,
        )
        for key, value in diagnostics.items():
            if str(key).startswith("shared_q_oracle_bme"):
                accumulator.update_scalar_metric(
                    f"sidecar_support_{key}",
                    float(value),
                    count=cell_count,
                )


def static_residue_context_features(
    sequence_tokens: torch.Tensor,
    *,
    sample_count: int,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Return z_static-style residue identity and positional context."""

    residue_count = int(sequence_tokens.numel())
    if residue_count <= 0:
        return torch.zeros(
            int(sample_count),
            0,
            STATIC_RESIDUE_CONTEXT_DIM,
            dtype=dtype,
            device=device,
        )
    tokens = sequence_tokens.to(device=device).long().clamp(min=0, max=20)
    zero_token = torch.zeros(1, dtype=torch.long, device=device)
    previous_tokens = torch.cat([zero_token, tokens[:-1]], dim=0)
    next_tokens = torch.cat([tokens[1:], zero_token], dim=0)
    one_hot = torch.nn.functional.one_hot(tokens, num_classes=21).to(dtype=dtype)
    previous_one_hot = torch.nn.functional.one_hot(
        previous_tokens,
        num_classes=21,
    ).to(dtype=dtype)
    next_one_hot = torch.nn.functional.one_hot(
        next_tokens,
        num_classes=21,
    ).to(dtype=dtype)
    if residue_count == 1:
        position = torch.zeros(1, dtype=dtype, device=device)
        terminal_distance = torch.zeros(1, dtype=dtype, device=device)
    else:
        position = torch.linspace(0.0, 1.0, residue_count, dtype=dtype, device=device)
        indices = torch.arange(residue_count, dtype=dtype, device=device)
        terminal_distance = torch.minimum(
            indices,
            torch.flip(indices, dims=(0,)),
        ) / float(max(residue_count - 1, 1))
    positional = torch.stack(
        [
            position,
            torch.sin(position * math.pi),
            terminal_distance,
        ],
        dim=-1,
    )
    chemistry_table = _residue_chemistry_table(dtype=dtype, device=device)
    previous_chemistry = chemistry_table[previous_tokens]
    current_chemistry = chemistry_table[tokens]
    next_chemistry = chemistry_table[next_tokens]
    local_context = torch.stack(
        [
            (position <= 0.0).to(dtype=dtype),
            (position >= 1.0).to(dtype=dtype),
            previous_chemistry[:, 1],
            next_chemistry[:, 1],
            0.5 * (previous_chemistry[:, 3] + next_chemistry[:, 3]),
            0.5 * (previous_chemistry[:, 2] + next_chemistry[:, 2]),
            next_chemistry[:, 6] - previous_chemistry[:, 6],
        ],
        dim=-1,
    )
    features = torch.cat(
        [
            one_hot,
            positional,
            previous_one_hot,
            next_one_hot,
            previous_chemistry,
            current_chemistry,
            next_chemistry,
            local_context,
        ],
        dim=-1,
    )
    return features.unsqueeze(0).expand(int(sample_count), -1, -1)


def compact_geometry_edge_tensors(
    residue_latent: torch.Tensor,
    sequence_tokens: torch.Tensor,
    *,
    edge_classes: tuple[str, ...] = COMPACT_X2D_EDGE_CLASSES,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Build compact conformer-specific geometry/x2d-style edge summaries.

    This is an on-the-fly fallback for the x0 decoder path.  It uses the
    conformer-specific coordinate proxy already present in the file-backed
    BioEmu support fixture and emits only ``K x (L * edge_class_count) x F``
    summary rows, never a full ``K x L x L x d`` pair tensor.
    """

    if residue_latent.ndim != 3:
        raise ValueError("residue_latent must have shape [K, L, F]")
    sample_count, residue_count, latent_dim = residue_latent.shape
    device = residue_latent.device
    dtype = residue_latent.dtype
    class_count = len(tuple(edge_classes))
    if sample_count <= 0 or residue_count <= 0 or class_count <= 0:
        return (
            residue_latent.new_zeros(sample_count, 0, COMPACT_GEOMETRY_EDGE_FEATURE_DIM),
            torch.zeros(0, dtype=torch.long, device=device),
            torch.zeros(0, dtype=torch.long, device=device),
            torch.zeros(0, dtype=dtype, device=device),
        )
    if latent_dim >= 9:
        # The v646 file-backed fixture stores centered CA coordinates divided
        # by 50.0 in channels 6:9.  Scaling back makes distance scores match
        # the neighborhood sidecar convention more closely.
        positions = torch.nan_to_num(residue_latent[..., 6:9], nan=0.0) * 50.0
        geometry_available = bool(torch.any(torch.abs(positions) > 1.0e-8).detach().cpu())
    else:
        positions = residue_latent.new_zeros(sample_count, residue_count, 3)
        geometry_available = False
    tokens = sequence_tokens.to(device=device).long().clamp(min=0, max=20)
    if int(tokens.numel()) < residue_count:
        tokens = torch.cat(
            [
                tokens,
                torch.zeros(residue_count - int(tokens.numel()), dtype=torch.long, device=device),
            ],
            dim=0,
        )
    tokens = tokens[:residue_count]
    chemistry = _residue_chemistry_table(dtype=dtype, device=device)[tokens]
    residue_axis = torch.arange(residue_count, device=device)
    denom = float(max(residue_count - 1, 1))
    edge_feature_rows: list[torch.Tensor] = []
    target_indices: list[int] = []
    class_indices: list[int] = []
    edge_masks: list[float] = []

    def class_candidate_mask(edge_class: str, residue_index: int) -> torch.Tensor:
        offsets = residue_axis - int(residue_index)
        nonself = offsets != 0
        if edge_class == "sequence":
            return nonself & (torch.abs(offsets) <= 2)
        if edge_class == "peptide_plane":
            return torch.abs(offsets) == 1
        if edge_class == "spatial_contact":
            return nonself & (torch.abs(offsets) >= 3)
        if edge_class == "hbond":
            return nonself & (chemistry[:, 9] > 0.0)
        if edge_class == "ring":
            return nonself & (chemistry[:, 2] > 0.0)
        if edge_class == "electrostatic":
            return nonself & ((chemistry[:, 3] > 0.0) | (chemistry[:, 7] > 0.0))
        return nonself

    def gather_mean(values: torch.Tensor, indices: torch.Tensor) -> torch.Tensor:
        if values.ndim == 1:
            expanded = values.reshape(1, -1).expand(sample_count, -1)
        elif values.shape[0] == 1 and sample_count != 1:
            expanded = values.expand(sample_count, -1)
        else:
            expanded = values
        return torch.gather(expanded, dim=1, index=indices).mean(dim=1)

    for residue_index in range(residue_count):
        source = positions[:, residue_index : residue_index + 1, :]
        vectors = positions - source
        distances = torch.linalg.norm(vectors, dim=-1).clamp_min(1.0e-6)
        prev_index = max(residue_index - 1, 0)
        next_index = min(residue_index + 1, residue_count - 1)
        tangent = positions[:, next_index, :] - positions[:, prev_index, :]
        tangent = tangent / torch.linalg.norm(tangent, dim=-1, keepdim=True).clamp_min(1.0e-6)
        unit_vectors = vectors / distances.unsqueeze(-1)
        orientation = torch.sum(tangent.unsqueeze(1) * unit_vectors, dim=-1).clamp(-1.0, 1.0)
        offsets = (residue_axis - int(residue_index)).to(dtype=dtype)
        abs_offsets = torch.abs(offsets)
        inv_distance = 1.0 / (1.0 + distances)
        charges = chemistry[:, 5] - chemistry[:, 4] + 0.35 * chemistry[:, 7]

        def append_summary_row(
            *,
            top_indices: torch.Tensor,
            top_values: torch.Tensor,
            candidate_count_value: int,
            peptide_plane_score: torch.Tensor,
        ) -> None:
            finite_top = torch.isfinite(top_values)
            safe_top_values = torch.where(finite_top, top_values, torch.zeros_like(top_values))
            edge_score = safe_top_values.mean(dim=1)
            top_dist = gather_mean(distances, top_indices)
            top_inv_dist = gather_mean(inv_distance, top_indices)
            top_offsets = gather_mean(offsets, top_indices)
            top_abs_offsets = gather_mean(abs_offsets, top_indices)
            top_orientation = gather_mean(orientation, top_indices)
            top_hbond = gather_mean(
                chemistry[:, 9].reshape(1, -1)
                * (0.65 + 0.35 * torch.abs(orientation))
                * inv_distance,
                top_indices,
            )
            top_ring = gather_mean(
                chemistry[:, 2].reshape(1, -1)
                * (0.60 + 0.40 * torch.abs(orientation))
                / (1.0 + distances.pow(3.0)),
                top_indices,
            )
            top_electro = gather_mean(charges.reshape(1, -1) / distances.clamp_min(0.25).square(), top_indices)
            top_plane = gather_mean(peptide_plane_score, top_indices)
            top_aromatic = gather_mean(chemistry[:, 2], top_indices)
            top_polar = gather_mean(chemistry[:, 9], top_indices)
            top_charged = gather_mean(chemistry[:, 3], top_indices)
            top_sulfur = gather_mean(chemistry[:, 7], top_indices)
            edge_feature_rows.append(
                torch.stack(
                    [
                        edge_score.clamp(0.0, 5.0) / 5.0,
                        (top_dist / 20.0).clamp(0.0, 1.0),
                        top_inv_dist.clamp(0.0, 1.0),
                        (top_offsets / denom).clamp(-1.0, 1.0),
                        (top_abs_offsets / denom).clamp(0.0, 1.0),
                        top_orientation.clamp(-1.0, 1.0),
                        top_hbond.clamp(0.0, 5.0) / 5.0,
                        top_ring.clamp(0.0, 5.0) / 5.0,
                        top_electro.clamp(-5.0, 5.0) / 5.0,
                        top_plane.clamp(0.0, 1.0),
                        top_aromatic.clamp(0.0, 1.0),
                        top_polar.clamp(0.0, 1.0),
                        top_charged.clamp(0.0, 1.0),
                        top_sulfur.clamp(0.0, 1.0),
                        torch.full((sample_count,), float(candidate_count_value) / denom, dtype=dtype, device=device).clamp(0.0, 1.0),
                        torch.full((sample_count,), 1.0 if geometry_available else 0.0, dtype=dtype, device=device),
                    ],
                    dim=-1,
                )
            )
            edge_masks.append(1.0)
            target_indices.append(residue_index)
            class_indices.append(class_index)

        for class_index, edge_class in enumerate(edge_classes):
            candidates = class_candidate_mask(str(edge_class), residue_index)
            candidate_count = int(torch.count_nonzero(candidates).detach().cpu())
            if candidate_count <= 0:
                edge_feature_rows.append(
                    residue_latent.new_zeros(sample_count, COMPACT_GEOMETRY_EDGE_FEATURE_DIM)
                )
                edge_masks.append(0.0)
                target_indices.append(residue_index)
                class_indices.append(class_index)
                continue
            if edge_class == "sequence":
                score = 0.75 / (1.0 + abs_offsets.reshape(1, -1)) + 0.25 * inv_distance
                peptide_plane_score = torch.zeros_like(score)
            elif edge_class == "peptide_plane":
                peptide_plane_score = 1.0 / (1.0 + abs_offsets.reshape(1, -1))
                score = peptide_plane_score + 0.15 * inv_distance
            elif edge_class == "spatial_contact":
                peptide_plane_score = torch.zeros_like(inv_distance)
                score = inv_distance + 0.10 * torch.abs(orientation)
            elif edge_class == "hbond":
                peptide_plane_score = torch.zeros_like(inv_distance)
                score = (
                    chemistry[:, 9].reshape(1, -1)
                    * (0.65 + 0.35 * torch.abs(orientation))
                    * inv_distance
                )
            elif edge_class == "ring":
                peptide_plane_score = torch.zeros_like(inv_distance)
                score = (
                    chemistry[:, 2].reshape(1, -1)
                    * (0.60 + 0.40 * torch.abs(orientation))
                    / (1.0 + distances.pow(3.0))
                )
            elif edge_class == "electrostatic":
                peptide_plane_score = torch.zeros_like(inv_distance)
                score = torch.abs(charges).reshape(1, -1) / distances.clamp_min(0.25).square()
            else:
                peptide_plane_score = torch.zeros_like(inv_distance)
                score = inv_distance
            if edge_class == "peptide_plane":
                # Keep previous/next peptide-plane edges as separate sparse
                # rows.  Averaging them before the edge MLP erased the signed
                # carbonyl-backbone direction needed by C' shifts.
                for candidate_index in torch.nonzero(candidates, as_tuple=False).flatten():
                    top_indices = candidate_index.reshape(1, 1).expand(sample_count, 1)
                    top_values = torch.gather(score, dim=1, index=top_indices)
                    append_summary_row(
                        top_indices=top_indices,
                        top_values=top_values,
                        candidate_count_value=1,
                        peptide_plane_score=peptide_plane_score,
                    )
                continue
            masked_score = torch.where(
                candidates.reshape(1, -1),
                score,
                torch.full_like(score, -torch.inf),
            )
            topk = min(
                int(COMPACT_GEOMETRY_EDGE_TOPK.get(str(edge_class), 4)),
                candidate_count,
            )
            top_values, top_indices = torch.topk(masked_score, k=max(topk, 1), dim=1)
            append_summary_row(
                top_indices=top_indices,
                top_values=top_values,
                candidate_count_value=candidate_count,
                peptide_plane_score=peptide_plane_score,
            )

    edge_features = torch.stack(edge_feature_rows, dim=1)
    return (
        edge_features,
        torch.tensor(target_indices, dtype=torch.long, device=device),
        torch.tensor(class_indices, dtype=torch.long, device=device),
        torch.tensor(edge_masks, dtype=dtype, device=device),
    )


def _empty_compact_geometry_edge_tensors_like(
    residue_latent: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    sample_count = int(residue_latent.shape[0]) if residue_latent.ndim >= 1 else 0
    device = residue_latent.device
    dtype = residue_latent.dtype
    return (
        residue_latent.new_zeros(
            sample_count,
            0,
            COMPACT_GEOMETRY_EDGE_FEATURE_DIM,
        ),
        torch.zeros(0, dtype=torch.long, device=device),
        torch.zeros(0, dtype=torch.long, device=device),
        torch.zeros(0, dtype=dtype, device=device),
    )


def _move_compact_geometry_edge_tensors(
    edge_tensors: tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor],
    *,
    device: torch.device,
    dtype: torch.dtype,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    edge_features, edge_targets, edge_classes, edge_mask = edge_tensors
    return (
        edge_features.to(device=device, dtype=dtype),
        edge_targets.to(device=device, dtype=torch.long),
        edge_classes.to(device=device, dtype=torch.long),
        edge_mask.to(device=device, dtype=dtype),
    )


def compact_geometry_edge_tensors_for_latent(
    *,
    entity_uid: str,
    latent: Any,
    sequence_tokens: torch.Tensor,
    edge_cache: dict[str, tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]] | None,
    edge_diagnostics: dict[str, float] | None = None,
    force_empty_edges: bool = False,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Return cached compact geometry edges when frozen file-backed support is used."""

    if force_empty_edges:
        edge_tensors = _empty_compact_geometry_edge_tensors_like(latent.residue_latent)
        _populate_compact_geometry_edge_diagnostics(
            edge_diagnostics,
            edge_tensors,
            sequence_length=int(sequence_tokens.numel()),
            cache_hit=False,
            oom_fallback=False,
            cpu_oom_retry=False,
            empty_oom_fallback=False,
            forced_empty=True,
        )
        return edge_tensors

    metadata = getattr(latent, "provider_metadata", {}) or {}
    cache_key = ""
    if str(metadata.get("provider", "")) == "file_backed":
        cache_key = "|".join(
            [
                str(entity_uid),
                str(tuple(int(dim) for dim in latent.residue_latent.shape)),
                str(latent.residue_latent.device),
                str(latent.residue_latent.dtype),
            ]
        )
    if edge_cache is not None and cache_key and cache_key in edge_cache:
        cached = edge_cache[cache_key]
        _populate_compact_geometry_edge_diagnostics(
            edge_diagnostics,
            cached,
            sequence_length=int(sequence_tokens.numel()),
            cache_hit=True,
            oom_fallback=False,
            cpu_oom_retry=False,
            empty_oom_fallback=False,
            forced_empty=False,
        )
        return cached
    oom_fallback = False
    cpu_oom_retry = False
    empty_oom_fallback = False
    try:
        edge_tensors = compact_geometry_edge_tensors(
            latent.residue_latent,
            sequence_tokens,
        )
    except Exception as exc:
        if not _is_cuda_oom_error(exc):
            raise
        residue_latent = latent.residue_latent
        device = residue_latent.device
        dtype = residue_latent.dtype
        if device.type == "cuda" and torch.cuda.is_available():
            torch.cuda.empty_cache()
        oom_fallback = True
        try:
            # Keep compact HN/C' geometry when GPU memory is exhausted.  The
            # retry is detached because it is a survival path for validation or
            # memory pressure, not the primary differentiable geometry route.
            cpu_edge_tensors = compact_geometry_edge_tensors(
                residue_latent.detach().to(device=torch.device("cpu")),
                sequence_tokens.detach().to(device=torch.device("cpu")),
            )
            if device.type == "cuda" and torch.cuda.is_available():
                torch.cuda.empty_cache()
            edge_tensors = _move_compact_geometry_edge_tensors(
                cpu_edge_tensors,
                device=device,
                dtype=dtype,
            )
            cpu_oom_retry = True
        except Exception as retry_exc:
            if not _is_cuda_oom_error(retry_exc):
                raise
            if device.type == "cuda" and torch.cuda.is_available():
                torch.cuda.empty_cache()
            edge_tensors = _empty_compact_geometry_edge_tensors_like(residue_latent)
            empty_oom_fallback = True
    _populate_compact_geometry_edge_diagnostics(
        edge_diagnostics,
        edge_tensors,
        sequence_length=int(sequence_tokens.numel()),
        cache_hit=False,
        oom_fallback=oom_fallback,
        cpu_oom_retry=cpu_oom_retry,
        empty_oom_fallback=empty_oom_fallback,
        forced_empty=False,
    )
    if edge_cache is not None and cache_key:
        edge_cache[cache_key] = tuple(tensor.detach() for tensor in edge_tensors)
        return edge_cache[cache_key]
    return edge_tensors


def _populate_compact_geometry_edge_diagnostics(
    edge_diagnostics: dict[str, float] | None,
    edge_tensors: tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor],
    *,
    sequence_length: int,
    cache_hit: bool,
    oom_fallback: bool,
    cpu_oom_retry: bool = False,
    empty_oom_fallback: bool = False,
    forced_empty: bool = False,
) -> None:
    if edge_diagnostics is None:
        return
    edge_features, _, _, edge_mask = edge_tensors
    edge_count = (
        int(edge_features.shape[1])
        if torch.is_tensor(edge_features) and edge_features.ndim >= 2
        else 0
    )
    sample_count = (
        int(edge_features.shape[0])
        if torch.is_tensor(edge_features) and edge_features.ndim >= 1
        else 0
    )
    mask_active_fraction = 0.0
    if torch.is_tensor(edge_mask) and edge_mask.numel() > 0:
        mask_active_fraction = float(
            torch.count_nonzero(edge_mask.detach() > 0).cpu()
        ) / float(max(int(edge_mask.numel()), 1))
    edge_diagnostics.clear()
    edge_diagnostics.update(
        {
            "compact_geometry_edge_count": float(edge_count),
            "compact_geometry_edge_sample_count": float(sample_count),
            "compact_geometry_edge_empty": 1.0 if edge_count <= 0 else 0.0,
            "compact_geometry_edge_degraded_empty": (
                1.0 if edge_count <= 0 and int(sequence_length) > 1 else 0.0
            ),
            "compact_geometry_edge_oom_fallback": 1.0 if oom_fallback else 0.0,
            "compact_geometry_edge_cpu_oom_retry": 1.0 if cpu_oom_retry else 0.0,
            "compact_geometry_edge_empty_oom_fallback": (
                1.0 if empty_oom_fallback else 0.0
            ),
            "compact_geometry_edge_forced_empty": 1.0 if forced_empty else 0.0,
            "compact_geometry_edge_cache_hit": 1.0 if cache_hit else 0.0,
            "compact_geometry_edge_mask_active_fraction": float(mask_active_fraction),
        }
    )


def _residue_chemistry_table(
    *,
    dtype: torch.dtype,
    device: torch.device,
) -> torch.Tensor:
    """Return token-level chemistry flags for local HN/C' sequence charts."""

    rows = torch.zeros(21, RESIDUE_CHEMISTRY_FEATURE_DIM, dtype=dtype, device=device)

    def mark(token: int, indices: tuple[int, ...]) -> None:
        for index in indices:
            rows[token, index] = 1.0

    # Feature order: gly, pro, aromatic, charged, acidic, basic, hydrophobic,
    # sulfur, beta-branched, polar. Token IDs follow AA3_VOCAB.
    mark(1, (6,))  # ALA
    mark(2, (3, 5))  # ARG
    mark(3, (9,))  # ASN
    mark(4, (3, 4, 9))  # ASP
    mark(5, (7, 9))  # CYS
    mark(6, (9,))  # GLN
    mark(7, (3, 4, 9))  # GLU
    mark(8, (0,))  # GLY
    mark(9, (2, 3, 5, 9))  # HIS
    mark(10, (6, 8))  # ILE
    mark(11, (6,))  # LEU
    mark(12, (3, 5))  # LYS
    mark(13, (6, 7))  # MET
    mark(14, (2, 6))  # PHE
    mark(15, (1,))  # PRO
    mark(16, (9,))  # SER
    mark(17, (8, 9))  # THR
    mark(18, (2, 6, 9))  # TRP
    mark(19, (2, 6, 9))  # TYR
    mark(20, (6, 8))  # VAL
    return rows


def stage_a_decoder_teacher_loss(
    conformer_target_phi: torch.Tensor,
    teacher_phi: torch.Tensor,
    *,
    family_indices: torch.Tensor | None = None,
    family_scales: torch.Tensor | None = None,
    teacher_weight: float = 1.0,
    family_macro_weight: float = 1.0,
    family_weights: dict[str, float] | None = None,
    support_variance_weight: float = 0.0,
    support_variance_family_weights: dict[str, float] | None = None,
) -> tuple[torch.Tensor, dict[str, int]]:
    """MSE against conformer-level UCBSHIFT teacher rows, ignoring NaNs.

    When family indices are available, the loss is macro-averaged across atom
    families after ppm-scale normalization.  The target metric is per-family
    CCC, so C' rows should not be overwhelmed by more numerous HN/N/CA/CB rows.
    """

    teacher = teacher_phi.to(
        device=conformer_target_phi.device,
        dtype=conformer_target_phi.dtype,
    )
    if teacher.shape != conformer_target_phi.shape:
        raise ValueError(
            "teacher_phi must match conformer_target_phi "
            f"(got {tuple(teacher.shape)} vs {tuple(conformer_target_phi.shape)})"
        )
    mask = torch.isfinite(teacher)
    point_count = int(torch.count_nonzero(mask).detach().cpu())
    row_count = int(torch.count_nonzero(torch.any(mask, dim=0)).detach().cpu())
    if point_count <= 0:
        zero = _zero_loss_like(conformer_target_phi)
        return zero, {"teacher_points": 0, "teacher_rows": 0, "teacher_slots": int(teacher.numel())}
    difference = conformer_target_phi - teacher
    families = None
    if family_indices is not None and family_scales is not None:
        scales = family_scales.to(
            device=conformer_target_phi.device,
            dtype=conformer_target_phi.dtype,
        )
        families = family_indices.to(device=conformer_target_phi.device).long().clamp(
            min=0,
            max=max(int(scales.numel()) - 1, 0),
        )
        row_scales = scales[families].reshape(1, -1)
        difference = difference / row_scales.clamp_min(1.0e-3)
    point_loss = torch.mean(difference[mask].square())
    if families is not None:
        family_losses: list[tuple[torch.Tensor, float]] = []
        for family_index in torch.unique(families).detach().cpu().tolist():
            row_mask = families == int(family_index)
            family_mask = mask[:, row_mask]
            if bool(torch.any(family_mask)):
                family_name = (
                    str(CHEMICAL_SHIFT_FAMILIES[int(family_index)])
                    if int(family_index) < len(CHEMICAL_SHIFT_FAMILIES)
                    else str(family_index)
                )
                family_weight = max(
                    float((family_weights or {}).get(family_name, 1.0)),
                    0.0,
                )
                if family_weight <= 0.0:
                    continue
                family_losses.append(
                    (
                        difference[:, row_mask][family_mask].square().mean(),
                        family_weight,
                    )
                )
        macro_loss = (
            sum(loss_value * weight for loss_value, weight in family_losses)
            / max(sum(weight for _, weight in family_losses), 1.0e-12)
            if family_losses
            else difference.new_tensor(0.0)
        )
        macro_weight = min(max(float(family_macro_weight), 0.0), 1.0)
        loss = point_loss * (1.0 - macro_weight) + macro_loss * macro_weight
    else:
        loss = point_loss
    variance_row_count = 0
    variance_weight = max(float(support_variance_weight), 0.0)
    if variance_weight > 0.0 and families is not None and family_scales is not None:
        variance_losses: list[tuple[torch.Tensor, float]] = []
        safe_teacher = torch.where(mask, teacher, conformer_target_phi.detach())
        pred_std = torch.std(conformer_target_phi, dim=0, unbiased=False)
        teacher_std = torch.std(safe_teacher, dim=0, unbiased=False)
        for row_family in torch.unique(families).detach().cpu().tolist():
            family_index = int(row_family)
            row_mask = families == family_index
            finite_rows = row_mask & torch.any(mask, dim=0)
            if not bool(torch.any(finite_rows)):
                continue
            family_name = (
                str(CHEMICAL_SHIFT_FAMILIES[family_index])
                if family_index < len(CHEMICAL_SHIFT_FAMILIES)
                else str(family_index)
            )
            family_weight = max(
                float((support_variance_family_weights or {}).get(family_name, 1.0)),
                0.0,
            )
            if family_weight <= 0.0:
                continue
            scale = scales[family_index].clamp_min(1.0e-3)
            family_loss = torch.mean(
                ((pred_std[finite_rows] - teacher_std[finite_rows]) / scale).square()
            )
            variance_losses.append((family_loss, family_weight))
            variance_row_count += int(torch.count_nonzero(finite_rows).detach().cpu())
        if variance_losses:
            weighted_variance_loss = conformer_target_phi.new_tensor(0.0)
            weight_sum = 0.0
            for variance_loss, family_weight in variance_losses:
                weighted_variance_loss = weighted_variance_loss + variance_loss * family_weight
                weight_sum += family_weight
            loss = loss + variance_weight * weighted_variance_loss / max(weight_sum, 1.0e-12)
    return loss * float(teacher_weight), {
        "teacher_points": point_count,
        "teacher_rows": row_count,
        "teacher_variance_rows": variance_row_count,
        "teacher_slots": int(teacher.numel()),
    }


def _normalized_sidecar_entity_key(value: object) -> str:
    text = str(value or "").strip().lower()
    if text.startswith("bmrb:"):
        text = text.split(":", 1)[1]
    return "".join(ch for ch in text if ch.isalnum() or ch == "_")


def _teacher_candidate_index(*values: object) -> int | None:
    for value in values:
        text = str(value or "")
        match = _TEACHER_CANDIDATE_INDEX_RE.search(text)
        if match is not None:
            try:
                return int(match.group(1))
            except ValueError:
                pass
        bioemu_match = _TEACHER_BIOEMU_POOL_INDEX_RE.search(text)
        if bioemu_match is None:
            continue
        try:
            # Offline BioEmu pool files are conventionally named BioEmu_1.pdb,
            # while runtime support tensors use zero-based sample indices.
            return max(int(bioemu_match.group(1)) - 1, 0)
        except ValueError:
            continue
    return None


def _teacher_explicit_candidate_index(*values: object) -> int | None:
    for value in values:
        if value in (None, ""):
            continue
        try:
            return int(float(str(value)))
        except (TypeError, ValueError):
            continue
    return None


def _teacher_bioemu_vanilla_sample_alias(value: object) -> str | None:
    text = str(value or "").strip()
    if not text:
        return None
    match = re.search(r"bioemu[_-]?0*(\d+)", text, flags=re.IGNORECASE)
    if match is None:
        return None
    tail = text[match.end() :].strip().lower()
    tail = re.sub(r"\.(pdb|csv|tsv|tab|json|npz)$", "", tail)
    if tail not in {"", ":vanilla", "_vanilla", "-vanilla", "/vanilla"}:
        return None
    try:
        sample_number = int(match.group(1))
    except ValueError:
        return None
    return f"bioemu_sample:{sample_number}"


def _teacher_bioemu_sample_alias_is_nonvanilla(value: object) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    match = re.search(r"bioemu[_-]?0*(\d+)", text, flags=re.IGNORECASE)
    if match is None:
        return False
    tail = text[match.end() :].strip().lower()
    tail = re.sub(r"\.(pdb|csv|tsv|tab|json|npz)$", "", tail)
    return tail not in {"", ":vanilla", "_vanilla", "-vanilla", "/vanilla"}


def _teacher_candidate_id_lookup_keys(value: object) -> tuple[str, ...]:
    text = str(value or "").strip()
    if not text:
        return ()
    keys = [text]
    alias = _teacher_bioemu_vanilla_sample_alias(text)
    if alias and alias not in keys:
        keys.append(alias)
    return tuple(keys)


def _teacher_bioemu_vanilla_alias_index(value: object) -> int | None:
    alias = _teacher_bioemu_vanilla_sample_alias(value)
    if not alias:
        return None
    try:
        return int(alias.rsplit(":", 1)[-1])
    except ValueError:
        return None


def _external_teacher_provider_text_evidence(
    provider_metadata: Mapping[str, Any],
    keys: Sequence[str],
) -> str:
    values: list[str] = []
    for key in keys:
        raw_value = provider_metadata.get(key)
        if raw_value is None:
            continue
        values.append(str(raw_value).strip().lower())
    return " ".join(value for value in values if value)


def _external_teacher_candidate_ids_are_dense_vanilla_identity(
    candidate_ids: Sequence[Any],
    *,
    support_count: int,
) -> bool:
    if not candidate_ids:
        return True
    if len(candidate_ids) < int(support_count):
        return False
    for sample_index in range(int(support_count)):
        alias_index = _teacher_bioemu_vanilla_alias_index(candidate_ids[sample_index])
        if alias_index is None or int(alias_index) != int(sample_index):
            return False
    return True


def _external_teacher_strict_vanilla_source_index_fallback_allowed(
    provider_metadata: Mapping[str, Any],
    *,
    support_count: int,
    config_asserts_vanilla_source_index_identity: bool,
) -> bool:
    if int(support_count) <= 0:
        return False
    candidate_ids = (
        provider_metadata.get("candidate_ids")
        or provider_metadata.get("sample_candidate_ids")
        or provider_metadata.get("support_candidate_ids")
        or []
    )
    candidate_ids = _metadata_sequence(candidate_ids)
    if not _external_teacher_candidate_ids_are_dense_vanilla_identity(
        candidate_ids,
        support_count=int(support_count),
    ):
        return False

    support_count_keys = (
        "support_count",
        "sample_count",
        "candidate_count",
        "bioemu_sample_count",
    )
    for key in support_count_keys:
        raw_value = provider_metadata.get(key)
        if raw_value in (None, ""):
            continue
        try:
            if int(raw_value) != int(support_count):
                return False
        except (TypeError, ValueError):
            return False

    if bool(config_asserts_vanilla_source_index_identity):
        return True

    identity_text = _external_teacher_provider_text_evidence(
        provider_metadata,
        (
            "source_sample_index_alignment",
            "sample_index_alignment",
            "candidate_index_alignment",
            "support_index_alignment",
            "training_alignment_mode",
            "support_identity_mode",
        ),
    )
    vanilla_text = _external_teacher_provider_text_evidence(
        provider_metadata,
        (
            "support_source",
            "source_support",
            "support_source_kind",
            "source_support_kind",
            "candidate_id_mode",
            "support_identity_mode",
            "provider",
        ),
    )
    identity_tokens = (
        "source_sample_index_identity",
        "dense_source_sample_index_identity",
        "dense_identity",
        "same_dense_index",
        "entity_source_sample_index",
        "vanilla_bioemu_source_index",
        "vanilla_bioemu_dense_index",
    )
    identity_ready = any(token in identity_text for token in identity_tokens)
    identity_ready = identity_ready or _teacher_truthy_cell(
        provider_metadata.get("source_sample_index_identity")
    )
    identity_ready = identity_ready or _teacher_truthy_cell(
        provider_metadata.get("candidate_indices_are_dense_identity")
    )
    vanilla_ready = (
        ("bioemu" in vanilla_text and "vanilla" in vanilla_text)
        or _teacher_truthy_cell(provider_metadata.get("bioemu_vanilla_support_source"))
        or _teacher_truthy_cell(provider_metadata.get("same_vanilla_bioemu_support"))
    )
    nonvanilla_markers = ("hybrid", "microstate", "rotamer", "generated", "nonvanilla")
    if any(marker in vanilla_text for marker in nonvanilla_markers):
        return False
    return bool(identity_ready and vanilla_ready)


def _teacher_truthy_cell(value: object) -> bool:
    text = str(value or "").strip().lower()
    return text in {"1", "true", "t", "yes", "y"}


def _teacher_finite_float(value: object, default: float = 0.0) -> float:
    try:
        result = float(str(value).strip())
    except (TypeError, ValueError):
        return float(default)
    return result if math.isfinite(result) else float(default)


def _teacher_valid_json_mapping_cell(value: object) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        return False
    return isinstance(payload, Mapping) and bool(payload)


def _external_global_family_teacher_paper_lineage_rejection_reasons(
    row: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    algorithm = str(row.get("teacher_algorithm") or "").strip().lower()
    if algorithm != _PAPER_CS_REWEIGHTING_TEACHER_ALGORITHM:
        reasons.append("missing_paper_cs_reweighting_algorithm")
    residue_offset = row.get("teacher_residue_offset")
    if residue_offset is None or str(residue_offset).strip() == "":
        reasons.append("missing_teacher_residue_offset")
    atom_offsets = row.get("teacher_atom_offsets_json")
    if not _teacher_valid_json_mapping_cell(atom_offsets):
        reasons.append("missing_teacher_atom_offsets_json")
    if not _teacher_truthy_cell(row.get("teacher_bfgs_success")):
        reasons.append("missing_successful_teacher_bfgs")
    prior_mode = str(row.get("teacher_prior_mode") or "").strip().lower()
    prior_source = str(row.get("teacher_prior_source") or "").strip().lower()
    if prior_mode and prior_mode != "uniform":
        reasons.append("teacher_prior_mode_not_uniform")
    if prior_source and prior_source != "uniform_bioemu_conformer_pool":
        reasons.append("teacher_prior_source_not_uniform_bioemu_conformer_pool")
    return reasons


def _external_global_family_teacher_row_lineage(
    row: Mapping[str, Any],
    *,
    candidate_id: str,
    microstate_id: str,
    backbone_id: str,
    support_id: str,
    candidate_index: int | None,
) -> dict[str, Any]:
    structure_path = _first_nonempty_mapping_value(
        row,
        (
            "structure_path",
            "sample_structure_path",
            "generated_structure_path",
            "output_pdb_path",
            "pdb_path",
            "source_backbone_path",
        ),
    )
    source_backbone_path = _first_nonempty_mapping_value(
        row,
        (
            "source_backbone_path",
            "structure_path",
            "sample_structure_path",
            "generated_structure_path",
            "output_pdb_path",
            "pdb_path",
        ),
    )
    raw_generated_structure_path = _first_nonempty_mapping_value(
        row,
        (
            "raw_generated_structure_path",
            "raw_structure_path",
            "generated_structure_path",
            "structure_path",
            "sample_structure_path",
            "output_pdb_path",
            "pdb_path",
        ),
    )
    source_sample_index = _teacher_explicit_candidate_index(
        row.get("source_sample_index"),
        row.get("bioemu_generated_sample_index"),
        row.get("teacher_sample_index"),
        row.get("sample_index"),
    )
    lineage: dict[str, Any] = {
        "candidate_id": candidate_id or microstate_id or support_id or backbone_id,
        "microstate_id": microstate_id,
        "backbone_id": backbone_id,
        "support_id": support_id,
        "structure_path": structure_path,
        "source_backbone_path": source_backbone_path,
        "raw_generated_structure_path": raw_generated_structure_path,
        "lineage_source": "external_global_family_teacher_weight_row",
    }
    for key in (
        "teacher_algorithm",
        "teacher_residue_offset",
        "teacher_atom_offsets_json",
        "teacher_bfgs_success",
        "teacher_prior_mode",
        "teacher_prior_source",
    ):
        value = str(row.get(key) or "").strip()
        if value:
            lineage[key] = value
    if candidate_index is not None:
        lineage["dense_sample_index"] = int(candidate_index)
    if source_sample_index is not None:
        lineage["source_sample_index"] = int(source_sample_index)
    return lineage


def _first_nonempty_mapping_value(
    row: Mapping[str, Any],
    keys: Sequence[str],
) -> str:
    for key in keys:
        text = str(row.get(key) or "").strip()
        if text:
            return text
    return ""


def _record_external_global_teacher_lineage(
    lineage_index: dict[Any, dict[str, Any]],
    key: Any,
    lineage: Mapping[str, Any],
) -> None:
    if key in (None, ""):
        return
    current = lineage_index.get(key)
    if not isinstance(current, dict):
        lineage_index[key] = dict(lineage)
        return
    for lineage_field, value in lineage.items():
        if str(current.get(lineage_field, "")).strip():
            continue
        if str(value or "").strip():
            current[lineage_field] = value


def _summary_float_values(payload: Mapping[str, Any], key: str) -> list[float]:
    raw_values = payload.get(key)
    if isinstance(raw_values, Mapping):
        iterable = raw_values.values()
    elif isinstance(raw_values, Sequence) and not isinstance(raw_values, str):
        iterable = raw_values
    else:
        return []
    values: list[float] = []
    for raw_value in iterable:
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            values.append(value)
    return values


def _safe_summary_float(payload: dict[str, Any], key: str, default: float) -> float:
    if key in payload:
        try:
            value = float(payload.get(key, default))
        except (TypeError, ValueError):
            value = float("nan")
        if math.isfinite(value):
            return value
    if key == "teacher_ess_mean":
        values = _summary_float_values(payload, "teacher_ess_by_entity")
        if values:
            return float(sum(values) / len(values))
    if key == "teacher_top_mass_max":
        values = _summary_float_values(payload, "teacher_top_mass_by_entity")
        if values:
            return float(max(values))
    if key == "required_family_min_complete_mass_by_entity":
        values = _summary_float_values(
            payload,
            "required_family_complete_mass_by_entity",
        )
        if values:
            return float(min(values))
    return float(default)


def _external_global_family_teacher_diagnostic_probe_rejection_reasons(
    config: StudentTrainingConfig,
    summary: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    if not bool(
        getattr(
            config,
            (
                "bioemu_x0_external_global_family_teacher_"
                "allow_diagnostic_active_subset_probe"
            ),
            False,
        )
    ):
        reasons.append("diagnostic_active_subset_probe_not_enabled")
    status_text = str(
        summary.get("status")
        or summary.get("teacher_status")
        or summary.get("export_status")
        or ""
    ).lower()
    if "diagnostic" not in status_text:
        reasons.append("summary_status_is_not_diagnostic")
    if bool(summary.get("multifamily_cosatisfaction_guard_passed")) is not True:
        reasons.append("multifamily_cosatisfaction_guard_not_passed")
    min_complete_mass = _safe_summary_float(
        dict(summary),
        "required_family_min_complete_mass_by_entity",
        0.0,
    )
    if min_complete_mass < 0.999:
        reasons.append("required_family_complete_mass_below_one")
    if not bool(
        getattr(
            config,
            "bioemu_x0_external_global_family_teacher_require_required_family_complete",
            False,
        )
    ):
        reasons.append("complete_family_row_filter_not_required")
    if bool(
        getattr(config, "bioemu_x0_active_subset_final_acceptance_eligible", False)
    ):
        reasons.append("active_subset_marked_final_acceptance_eligible")
    if not bool(
        getattr(config, "bioemu_x0_active_subset_full_dataset_resume_required", True)
    ):
        reasons.append("full_dataset_resume_not_required")
    train_examples = int(
        getattr(config, "bioemu_x0_active_subset_train_examples", 0)
    )
    val_examples = int(getattr(config, "bioemu_x0_active_subset_val_examples", 0))
    if train_examples <= 0 or val_examples <= 0:
        reasons.append("active_subset_examples_not_configured")
    initial_epochs = max(
        int(getattr(config, "bioemu_x0_active_subset_initial_epochs", 0)),
        1,
    )
    epochs = int(getattr(config, "epochs", initial_epochs))
    if epochs > initial_epochs:
        reasons.append("diagnostic_probe_epochs_exceed_active_subset_window")
    if bool(
        getattr(
            config,
            "bioemu_x0_external_global_family_teacher_reload_at_epoch_boundary",
            False,
        )
    ):
        reasons.append("diagnostic_teacher_reload_enabled")
    non_prior_routes = {
        "bioemu_x0_external_global_family_teacher_distill_weight": 0.0,
        "bioemu_x0_external_global_family_teacher_energy_target_weight": 0.0,
        "bioemu_x0_external_global_family_teacher_contrastive_energy_weight": 0.0,
        "bioemu_cs_reweighting_teacher_prior_kl_weight": 0.0,
        "bioemu_ucbshift_cnnls_teacher_prior_kl_weight": 0.0,
    }
    for name, ceiling in non_prior_routes.items():
        value = float(getattr(config, name, 0.0))
        if value > ceiling:
            reasons.append(f"{name}_must_be_zero")
    if not bool(
        getattr(config, "bioemu_x0_stage_b_train_prior_logit_adapter_only", False)
    ):
        reasons.append("prior_logit_adapter_only_not_enabled")
    if float(getattr(config, "bioemu_x0_prior_logit_adapter_lr_multiplier", 0.0)) <= 0.0:
        reasons.append("prior_logit_adapter_lr_not_positive")
    frozen_route_names = (
        "bioemu_provider_lr_multiplier",
        "bioemu_x0_support_basis_lr_multiplier",
        "bioemu_x0_mechanism_decoder_lr_multiplier",
        "bioemu_x0_capacity_adapter_lr_multiplier",
        "bioemu_x0_capacity_adapter_extra_lr_multiplier",
        "bioemu_x0_capacity_adapter_aux_lr_multiplier",
    )
    for name in frozen_route_names:
        value = float(getattr(config, name, 0.0))
        if value > 0.0:
            reasons.append(f"{name}_must_be_frozen")
    return reasons


def _load_external_global_family_teacher(
    config: StudentTrainingConfig,
) -> dict[str, Any] | None:
    if not bool(
        getattr(config, "bioemu_x0_external_global_family_teacher_enabled", False)
    ):
        return None
    summary_path = Path(
        str(
            getattr(
                config,
                "bioemu_x0_external_global_family_teacher_summary_path",
                "",
            )
            or ""
        )
    )
    weights_path = Path(
        str(
            getattr(
                config,
                "bioemu_x0_external_global_family_teacher_weights_path",
                "",
            )
            or ""
        )
    )
    predictions_path = str(
        getattr(
            config,
            "bioemu_x0_external_global_family_teacher_predictions_path",
            "",
        )
        or ""
    )
    if not summary_path.exists():
        raise ValueError(
            "External global-family teacher is enabled but the summary path is missing: "
            f"{summary_path}"
        )
    if not weights_path.exists():
        raise ValueError(
            "External global-family teacher is enabled but the weights path is missing: "
            f"{weights_path}"
        )
    summary_payload = _read_json(summary_path)
    summary = summary_payload if isinstance(summary_payload, dict) else {}
    diagnostic_active_subset_probe = False
    if bool(summary.get("teacher_safe_for_distillation")) is not True:
        diagnostic_reasons = (
            _external_global_family_teacher_diagnostic_probe_rejection_reasons(
                config,
                summary,
            )
        )
        if diagnostic_reasons:
            raise ValueError(
                "External global-family teacher is not marked safe for "
                f"distillation: {summary_path}; "
                "diagnostic_active_subset_probe_rejection_reasons="
                f"{','.join(diagnostic_reasons)}"
            )
        diagnostic_active_subset_probe = True
    ess_mean = _safe_summary_float(summary, "teacher_ess_mean", 0.0)
    top_mass_max = _safe_summary_float(summary, "teacher_top_mass_max", 1.0)
    pass_rate = _safe_summary_float(summary, "ucbshift_pass_rate", 0.0)
    min_ess = max(
        float(
            getattr(
                config,
                "bioemu_x0_external_global_family_teacher_min_ess_mean",
                0.0,
            )
        ),
        0.0,
    )
    max_top = min(
        max(
            float(
                getattr(
                    config,
                    "bioemu_x0_external_global_family_teacher_max_top_mass",
                    1.0,
                )
            ),
            0.0,
        ),
        1.0,
    )
    min_pass = min(
        max(
            float(
                getattr(
                    config,
                    "bioemu_x0_external_global_family_teacher_min_ucbshift_pass_rate",
                    0.0,
                )
            ),
            0.0,
        ),
        1.0,
    )
    if ess_mean < min_ess or top_mass_max > max_top or pass_rate < min_pass:
        raise ValueError(
            "External global-family teacher failed safety thresholds "
            f"(ESS={ess_mean:.4g} >= {min_ess:.4g}, "
            f"top_mass={top_mass_max:.4g} <= {max_top:.4g}, "
            f"pass_rate={pass_rate:.4g} >= {min_pass:.4g})."
        )

    require_required_family_complete = bool(
        getattr(
            config,
            "bioemu_x0_external_global_family_teacher_require_required_family_complete",
            False,
        )
    )
    coverage_weight_power = max(
        float(
            getattr(
                config,
                "bioemu_x0_external_global_family_teacher_coverage_weight_power",
                0.0,
            )
        ),
        0.0,
    )
    require_paper_lineage = bool(
        getattr(
            config,
            (
                "bioemu_x0_external_global_family_teacher_"
                "require_paper_cs_reweighting_lineage"
            ),
            False,
        )
    )
    complete_annotation_seen = False
    skipped_incomplete_rows = 0
    skipped_zero_coverage_rows = 0
    positive_weight_rows = 0
    paper_lineage_rows = 0
    paper_lineage_rejected_rows = 0
    paper_lineage_rejection_counts: dict[str, int] = {}
    skipped_incomplete_rows_by_entity: dict[str, int] = {}
    skipped_zero_coverage_rows_by_entity: dict[str, int] = {}

    rows_by_entity: dict[str, dict[str, Any]] = {}
    with weights_path.open(newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        for row in reader:
            entity_key = _normalized_sidecar_entity_key(row.get("entity_uid", ""))
            if not entity_key:
                continue
            try:
                teacher_weight = float(
                    row.get("teacher_weight")
                    or row.get("posterior_weight")
                    or 0.0
                )
            except (TypeError, ValueError):
                continue
            if not math.isfinite(teacher_weight) or teacher_weight <= 0.0:
                continue
            positive_weight_rows += 1
            paper_reasons = (
                _external_global_family_teacher_paper_lineage_rejection_reasons(row)
            )
            if paper_reasons:
                paper_lineage_rejected_rows += 1
                for reason in paper_reasons:
                    paper_lineage_rejection_counts[reason] = (
                        int(paper_lineage_rejection_counts.get(reason, 0)) + 1
                    )
                if require_paper_lineage:
                    continue
            else:
                paper_lineage_rows += 1
            complete_text = str(row.get("required_family_complete") or "").strip()
            has_complete_annotation = bool(complete_text)
            if has_complete_annotation:
                complete_annotation_seen = True
            required_family_complete = _teacher_truthy_cell(complete_text)
            if require_required_family_complete and not required_family_complete:
                skipped_incomplete_rows += 1
                skipped_incomplete_rows_by_entity[entity_key] = (
                    int(skipped_incomplete_rows_by_entity.get(entity_key, 0)) + 1
                )
                continue
            coverage = _teacher_finite_float(
                row.get("required_family_coverage_fraction"),
                1.0,
            )
            coverage = min(max(float(coverage), 0.0), 1.0)
            if coverage_weight_power > 0.0:
                teacher_weight *= coverage**coverage_weight_power
                if teacher_weight <= 0.0:
                    skipped_zero_coverage_rows += 1
                    skipped_zero_coverage_rows_by_entity[entity_key] = (
                        int(skipped_zero_coverage_rows_by_entity.get(entity_key, 0))
                        + 1
                    )
                    continue
            entity_rows = rows_by_entity.setdefault(
                entity_key,
                {
                    "by_candidate_id": {},
                    "by_candidate_index": {},
                    "lineage_by_candidate_id": {},
                    "lineage_by_candidate_index": {},
                    "row_count": 0,
                    "weight_sum": 0.0,
                    "required_family_complete_rows": 0,
                    "skipped_incomplete_rows": 0,
                    "skipped_zero_coverage_rows": 0,
                    "paper_lineage_rows": 0,
                    "paper_lineage_rejected_rows": 0,
                    "coverage_weight_power": float(coverage_weight_power),
                },
            )
            candidate_id = str(row.get("candidate_id") or "").strip()
            microstate_id = str(row.get("microstate_id") or "").strip()
            backbone_id = str(row.get("backbone_id") or "").strip()
            support_id = str(row.get("support_id") or "").strip()
            candidate_index = _teacher_explicit_candidate_index(
                row.get("dense_candidate_index"),
                row.get("dense_sample_index"),
                row.get("source_sample_index"),
                row.get("bioemu_generated_sample_index"),
                row.get("teacher_sample_index"),
                row.get("sample_index"),
            )
            if candidate_index is None:
                candidate_index = _teacher_candidate_index(
                    candidate_id,
                    microstate_id,
                    backbone_id,
                    row.get("structure_path"),
                )
            row_lineage = _external_global_family_teacher_row_lineage(
                row,
                candidate_id=candidate_id,
                microstate_id=microstate_id,
                backbone_id=backbone_id,
                support_id=support_id,
                candidate_index=candidate_index,
            )
            candidate_lookup_keys: list[str] = []
            for key in (candidate_id, microstate_id, backbone_id, support_id):
                for lookup_key in _teacher_candidate_id_lookup_keys(key):
                    if lookup_key not in candidate_lookup_keys:
                        candidate_lookup_keys.append(lookup_key)
            for key in candidate_lookup_keys:
                if key:
                    by_id = entity_rows["by_candidate_id"]
                    by_id[key] = float(by_id.get(key, 0.0)) + teacher_weight
                    _record_external_global_teacher_lineage(
                        entity_rows["lineage_by_candidate_id"],
                        key,
                        row_lineage,
                    )
            if candidate_index is not None:
                by_index = entity_rows["by_candidate_index"]
                by_index[candidate_index] = (
                    float(by_index.get(candidate_index, 0.0)) + teacher_weight
                )
                _record_external_global_teacher_lineage(
                    entity_rows["lineage_by_candidate_index"],
                    int(candidate_index),
                    row_lineage,
                )
            entity_rows["row_count"] = int(entity_rows["row_count"]) + 1
            entity_rows["weight_sum"] = float(entity_rows["weight_sum"]) + teacher_weight
            if not paper_reasons:
                entity_rows["paper_lineage_rows"] = int(
                    entity_rows.get("paper_lineage_rows", 0)
                ) + 1
            else:
                entity_rows["paper_lineage_rejected_rows"] = int(
                    entity_rows.get("paper_lineage_rejected_rows", 0)
                ) + 1
            if required_family_complete:
                entity_rows["required_family_complete_rows"] = (
                    int(entity_rows["required_family_complete_rows"]) + 1
                )
    if require_paper_lineage and (
        positive_weight_rows <= 0
        or paper_lineage_rejected_rows > 0
        or paper_lineage_rows != positive_weight_rows
        or not rows_by_entity
    ):
        reason_text = ",".join(
            f"{key}:{value}"
            for key, value in sorted(paper_lineage_rejection_counts.items())
        )
        raise ValueError(
            "External global-family teacher requires paper-style CS-reweighting "
            "lineage, but usable teacher rows were not all produced by "
            f"{_PAPER_CS_REWEIGHTING_TEACHER_ALGORITHM}. "
            f"positive_weight_rows={positive_weight_rows}, "
            f"paper_lineage_rows={paper_lineage_rows}, "
            f"paper_lineage_rejected_rows={paper_lineage_rejected_rows}, "
            f"rejection_counts={reason_text or 'none'}; path={weights_path}"
        )
    if require_required_family_complete and (
        not complete_annotation_seen or not rows_by_entity
    ):
        raise ValueError(
            "External global-family teacher requires required-family-complete "
            "support rows, but no usable complete rows were found in "
            f"{weights_path}."
        )
    if skipped_incomplete_rows or skipped_zero_coverage_rows:
        for entity_key, entity_rows in rows_by_entity.items():
            entity_rows["skipped_incomplete_rows"] = int(
                skipped_incomplete_rows_by_entity.get(entity_key, 0)
            )
            entity_rows["skipped_zero_coverage_rows"] = int(
                skipped_zero_coverage_rows_by_entity.get(entity_key, 0)
            )
    return {
        "weights_path": str(weights_path),
        "summary_path": str(summary_path),
        "predictions_path": predictions_path,
        "summary": summary,
        "rows_by_entity": rows_by_entity,
        "diagnostic_active_subset_probe": bool(diagnostic_active_subset_probe),
        "paper_lineage_required": bool(require_paper_lineage),
        "paper_lineage_rows": int(paper_lineage_rows),
        "paper_lineage_rejected_rows": int(paper_lineage_rejected_rows),
        "positive_weight_rows": int(positive_weight_rows),
    }


def _external_global_family_teacher_signature(
    teacher: dict[str, Any] | None,
) -> dict[str, str]:
    if not teacher:
        return {"summary_path": "", "weights_path": "", "predictions_path": ""}
    return {
        "summary_path": str(teacher.get("summary_path") or ""),
        "weights_path": str(teacher.get("weights_path") or ""),
        "predictions_path": str(teacher.get("predictions_path") or ""),
    }


def _latest_accepted_external_global_family_teacher_config(
    registry_latest_path: str | Path,
) -> dict[str, str] | None:
    path_text = str(registry_latest_path or "").strip()
    if not path_text:
        return None
    path = Path(path_text)
    try:
        payload_raw = path.read_text()
        payload = json.loads(payload_raw)
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(payload, dict):
        return None
    if _accepted_external_global_family_teacher_rejection_reasons(payload):
        return None
    summary_path = str(payload.get("summary_path") or "").strip()
    weights_path = str(payload.get("weights_path") or "").strip()
    predictions_path = str(payload.get("predictions_path") or "").strip()
    if not summary_path or not weights_path or not predictions_path:
        return None
    return {
        "summary_path": summary_path,
        "weights_path": weights_path,
        "predictions_path": predictions_path,
        "round_id": str(payload.get("round_id") or ""),
        "bundle_path": str(path),
        "strict_goal_acceptance_ready": str(
            payload.get("strict_goal_acceptance_ready")
        ),
        "require_paper_cs_reweighting_lineage": str(
            _accepted_external_global_family_teacher_paper_lineage_ready(payload)
        ),
    }


def _accepted_external_global_family_teacher_paper_lineage_ready(
    payload: Mapping[str, Any],
) -> bool:
    evidence = (
        payload.get("goal_acceptance_evidence")
        if isinstance(payload.get("goal_acceptance_evidence"), Mapping)
        else {}
    )
    for source in (payload, evidence):
        if not isinstance(source, Mapping):
            continue
        for key in (
            "paper_cs_reweighting_lineage_ready",
            "teacher_paper_cs_reweighting_lineage_ready",
            "paper_teacher_lineage_ready",
        ):
            if _teacher_truthy_cell(source.get(key)):
                return True
    return False


_STRICT_GOAL_MACRO_FAMILY_CCC_GATE_KEYS = (
    "passes_macro_family_ccc_gate",
    "sidechain_shared_q_macro_family_target",
    "shared_q_macro_family_target",
    "macro_family_ccc_gate_passed",
)
_STRICT_GOAL_MAX_BACKBONE_SIGMA_ANGSTROM = 0.20
_STRICT_GOAL_MIN_SIDECHAIN_CHI_SIGMA_DEGREES = 90.0
_STRICT_GOAL_MIN_SIDECHAIN_MICROSTATES_PER_BACKBONE = 2.0
_STRICT_GOAL_SUPPORT_KEYS = (
    "sidechain_microstate_rows",
    "sidechain_unique_backbones",
    "sidechain_microstates_per_backbone_mean",
    "backbone_constraint_ready",
    "backbone_proposal_sigma_angstrom_max",
    "sigma_split_policy_ready",
    "sidechain_chi_sigma_degrees_min",
    "sidechain_prior_available",
    "shared_q_coupled_perturbation_policy",
    "shared_q_coupled_perturbation_requested_rows",
    "sidechain_or_narrow_relaxation_support_required",
    "sidechain_or_narrow_relaxation_support_rows",
    "same_conformer_cprime_donor_coupled_rows",
    "shared_q_coupled_target_metadata_ready_rows",
    "shared_q_coupled_residue_window_ready_rows",
    "shared_q_coupled_residue_window_missing_rows",
)


def _strict_goal_macro_family_ccc_gate_passed(
    payload: Mapping[str, Any],
    evidence: Mapping[str, Any],
) -> bool:
    explicit_gate_values: list[bool] = []
    for source in (payload, evidence):
        if not isinstance(source, Mapping):
            continue
        for key in _STRICT_GOAL_MACRO_FAMILY_CCC_GATE_KEYS:
            if key not in source:
                continue
            value = source.get(key)
            if isinstance(value, bool):
                explicit_gate_values.append(value)
                continue
            text = str(value).strip().lower()
            if text in {"pass", "passed", "ok", "safe", "true", "1", "yes", "y"}:
                explicit_gate_values.append(True)
            elif text in {
                "fail",
                "failed",
                "unsafe",
                "false",
                "0",
                "no",
                "n",
            }:
                explicit_gate_values.append(False)
    return bool(explicit_gate_values) and all(explicit_gate_values)


def _strict_goal_support_mapping(
    payload: Mapping[str, Any],
    evidence: Mapping[str, Any],
) -> dict[str, Any]:
    support: dict[str, Any] = {}
    for source in (payload, evidence):
        if not isinstance(source, Mapping):
            continue
        for key in _STRICT_GOAL_SUPPORT_KEYS:
            if key in source:
                support[key] = source.get(key)
        nested = source.get("support")
        if isinstance(nested, Mapping):
            for key in _STRICT_GOAL_SUPPORT_KEYS:
                if key in nested:
                    support[key] = nested.get(key)
    return support


def _strict_goal_support_float(
    support: Mapping[str, Any],
    key: str,
    default: float = math.nan,
) -> float:
    try:
        value = float(support.get(key, default))
    except (TypeError, ValueError):
        return float(default)
    return value if math.isfinite(value) else float(default)


def _strict_goal_support_truthy(support: Mapping[str, Any], key: str) -> bool:
    value = support.get(key)
    if isinstance(value, bool):
        return value
    return _teacher_truthy_cell(value)


def _strict_goal_support_rejection_reasons(
    payload: Mapping[str, Any],
    evidence: Mapping[str, Any],
) -> list[str]:
    support = _strict_goal_support_mapping(payload, evidence)
    microstate_rows = _strict_goal_support_float(support, "sidechain_microstate_rows")
    unique_backbones = _strict_goal_support_float(support, "sidechain_unique_backbones")
    microstates_per_backbone = _strict_goal_support_float(
        support,
        "sidechain_microstates_per_backbone_mean",
    )
    backbone_sigma_max = _strict_goal_support_float(
        support,
        "backbone_proposal_sigma_angstrom_max",
    )
    sidechain_sigma_min = _strict_goal_support_float(
        support,
        "sidechain_chi_sigma_degrees_min",
    )
    requested_rows = _strict_goal_support_float(
        support,
        "shared_q_coupled_perturbation_requested_rows",
        default=0.0,
    )
    relaxation_rows = _strict_goal_support_float(
        support,
        "sidechain_or_narrow_relaxation_support_rows",
        default=requested_rows,
    )
    cprime_donor_rows = _strict_goal_support_float(
        support,
        "same_conformer_cprime_donor_coupled_rows",
        default=0.0,
    )
    target_metadata_ready_rows = _strict_goal_support_float(
        support,
        "shared_q_coupled_target_metadata_ready_rows",
        default=0.0,
    )
    residue_window_ready_rows = _strict_goal_support_float(
        support,
        "shared_q_coupled_residue_window_ready_rows",
        default=0.0,
    )
    residue_window_missing_rows = _strict_goal_support_float(
        support,
        "shared_q_coupled_residue_window_missing_rows",
        default=math.inf,
    )
    policy = str(support.get("shared_q_coupled_perturbation_policy") or "").strip()
    reasons: list[str] = []
    if (
        not math.isfinite(microstate_rows)
        or microstate_rows <= 0.0
        or not math.isfinite(unique_backbones)
        or unique_backbones <= 0.0
    ):
        reasons.append("goal_support_sidechain_microensemble_missing")
    if (
        not math.isfinite(microstates_per_backbone)
        or microstates_per_backbone < _STRICT_GOAL_MIN_SIDECHAIN_MICROSTATES_PER_BACKBONE
    ):
        reasons.append("goal_support_sidechain_microstates_per_backbone_below_floor")
    if (
        not _strict_goal_support_truthy(support, "backbone_constraint_ready")
        or not math.isfinite(backbone_sigma_max)
        or backbone_sigma_max > _STRICT_GOAL_MAX_BACKBONE_SIGMA_ANGSTROM
    ):
        reasons.append("goal_support_backbone_constraint_not_ready")
    if (
        not _strict_goal_support_truthy(support, "sigma_split_policy_ready")
        or not math.isfinite(sidechain_sigma_min)
        or sidechain_sigma_min < _STRICT_GOAL_MIN_SIDECHAIN_CHI_SIGMA_DEGREES
    ):
        reasons.append("goal_support_sigma_split_not_ready")
    if not _strict_goal_support_truthy(support, "sidechain_prior_available"):
        reasons.append("goal_support_sidechain_prior_missing")
    if (
        not math.isfinite(requested_rows)
        or requested_rows <= 0.0
        or not _strict_goal_support_truthy(
            support,
            "sidechain_or_narrow_relaxation_support_required",
        )
        or not math.isfinite(relaxation_rows)
        or relaxation_rows < requested_rows
        or not policy
        or policy == "off"
    ):
        reasons.append("goal_support_shared_q_coupled_perturbation_missing")
    if not math.isfinite(cprime_donor_rows) or cprime_donor_rows <= 0.0:
        reasons.append("goal_support_same_conformer_cprime_donor_coupling_missing")
    if (
        not math.isfinite(target_metadata_ready_rows)
        or target_metadata_ready_rows < requested_rows
    ):
        reasons.append("goal_support_shared_q_coupled_target_metadata_missing")
    if (
        not math.isfinite(residue_window_ready_rows)
        or residue_window_ready_rows < requested_rows
        or (
            math.isfinite(residue_window_missing_rows)
            and residue_window_missing_rows > 0.0
        )
    ):
        reasons.append("goal_support_shared_q_coupled_residue_window_missing")
    return reasons


def _accepted_external_global_family_teacher_rejection_reasons(
    payload: Mapping[str, Any],
) -> list[str]:
    reasons: list[str] = []
    if payload.get("accepted") is not True:
        reasons.append("accepted_not_true")
    if payload.get("must_not_update_latest_accepted") is True:
        reasons.append("must_not_update_latest_accepted_true")
    if payload.get("strict_goal_acceptance_ready") is not True:
        reasons.append("strict_goal_acceptance_not_ready")
    strict_reasons = payload.get("strict_goal_rejection_reasons")
    if isinstance(strict_reasons, Sequence) and not isinstance(strict_reasons, str):
        if list(strict_reasons):
            reasons.append("strict_goal_rejection_reasons_present")
    evidence = (
        payload.get("goal_acceptance_evidence")
        if isinstance(payload.get("goal_acceptance_evidence"), Mapping)
        else {}
    )
    if evidence.get("accepted_by_promotion_gate") is not True:
        reasons.append("goal_evidence_not_accepted_by_promotion")
    if evidence.get("strict_goal_acceptance_ready") is not True:
        reasons.append("goal_evidence_strict_goal_not_ready")
    if payload.get("configured_atom_families_explicitly_recorded") is not True:
        reasons.append("configured_atom_families_not_explicit_in_bundle")
    if evidence.get("configured_atom_families_explicitly_recorded") is not True:
        reasons.append("configured_atom_families_not_explicit_in_goal_evidence")
    if not _strict_goal_macro_family_ccc_gate_passed(payload, evidence):
        reasons.append("goal_macro_family_ccc_gate_missing_or_failed")
    if not _accepted_external_global_family_teacher_paper_lineage_ready(payload):
        reasons.append("paper_cs_reweighting_lineage_not_ready")
    reasons.extend(_strict_goal_support_rejection_reasons(payload, evidence))
    for key in ("summary_path", "weights_path", "predictions_path"):
        if not str(payload.get(key) or "").strip():
            reasons.append(f"{key}_missing")
    return reasons


def _maybe_reload_external_global_family_teacher_at_boundary(
    *,
    config: StudentTrainingConfig,
    current_teacher: dict[str, Any] | None,
    epoch: int,
    boundary: str,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    event: dict[str, Any] = {
        "boundary": str(boundary),
        "epoch": int(epoch),
        "reloaded": False,
        "status": "disabled",
        "allowed_boundary_only": True,
    }
    if str(boundary) not in {"epoch_boundary", "validation_boundary"}:
        event["status"] = "disallowed_boundary"
        return current_teacher, event
    if not bool(
        getattr(
            config,
            "bioemu_x0_external_global_family_teacher_reload_at_epoch_boundary",
            False,
        )
    ):
        return current_teacher, event
    registry_path = str(
        getattr(
            config,
            "bioemu_x0_external_global_family_teacher_registry_latest_path",
            "",
        )
        or ""
    )
    event["registry_latest_path"] = registry_path
    latest = _latest_accepted_external_global_family_teacher_config(registry_path)
    if latest is None:
        event["status"] = "no_accepted_registry_payload"
        event["current"] = _external_global_family_teacher_signature(current_teacher)
        return current_teacher, event

    current_signature = _external_global_family_teacher_signature(current_teacher)
    next_signature = {
        "summary_path": latest["summary_path"],
        "weights_path": latest["weights_path"],
        "predictions_path": latest["predictions_path"],
    }
    event["current"] = current_signature
    event["candidate"] = {
        **next_signature,
        "round_id": latest.get("round_id", ""),
        "strict_goal_acceptance_ready": latest.get(
            "strict_goal_acceptance_ready", ""
        ),
    }
    if current_signature == next_signature:
        event["status"] = "unchanged"
        return current_teacher, event

    candidate_config = copy.copy(config)
    candidate_config.bioemu_x0_external_global_family_teacher_enabled = True
    candidate_config.bioemu_x0_external_global_family_teacher_summary_path = latest[
        "summary_path"
    ]
    candidate_config.bioemu_x0_external_global_family_teacher_weights_path = latest[
        "weights_path"
    ]
    candidate_config.bioemu_x0_external_global_family_teacher_predictions_path = latest[
        "predictions_path"
    ]
    candidate_config.bioemu_x0_external_global_family_teacher_require_paper_cs_reweighting_lineage = (
        _teacher_truthy_cell(latest.get("require_paper_cs_reweighting_lineage"))
    )
    try:
        reloaded_teacher = _load_external_global_family_teacher(candidate_config)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        event["status"] = "reload_failed"
        event["error"] = str(exc)
        return current_teacher, event
    config.bioemu_x0_external_global_family_teacher_enabled = True
    config.bioemu_x0_external_global_family_teacher_summary_path = latest[
        "summary_path"
    ]
    config.bioemu_x0_external_global_family_teacher_weights_path = latest[
        "weights_path"
    ]
    config.bioemu_x0_external_global_family_teacher_predictions_path = latest[
        "predictions_path"
    ]
    config.bioemu_x0_external_global_family_teacher_require_paper_cs_reweighting_lineage = (
        _teacher_truthy_cell(latest.get("require_paper_cs_reweighting_lineage"))
    )
    event["status"] = "reloaded"
    event["reloaded"] = True
    event["loaded"] = _external_global_family_teacher_signature(reloaded_teacher)
    return reloaded_teacher, event


def _external_global_family_teacher_oracle(
    teacher: dict[str, Any] | None,
    *,
    entity_uid: str,
    support_count: int,
    sample_index_map: tuple[int, ...] | list[int] | np.ndarray | None,
    provider_metadata: dict[str, Any],
    dtype: torch.dtype,
    device: torch.device,
    config_asserts_vanilla_source_index_identity: bool = False,
) -> dict[str, Any] | None:
    if not teacher or int(support_count) <= 0:
        return None
    rows_by_entity = teacher.get("rows_by_entity", {})
    if not isinstance(rows_by_entity, dict):
        return None
    entity_key = _normalized_sidecar_entity_key(entity_uid)
    entity_rows = rows_by_entity.get(entity_key)
    if entity_rows is None:
        for candidate_key, candidate_rows in rows_by_entity.items():
            normalized_candidate = _normalized_sidecar_entity_key(candidate_key)
            if entity_key.endswith(normalized_candidate) or normalized_candidate.endswith(entity_key):
                entity_rows = candidate_rows
                break
    if not isinstance(entity_rows, dict):
        return None
    by_id = entity_rows.get("by_candidate_id", {})
    by_index = entity_rows.get("by_candidate_index", {})
    lineage_by_id = entity_rows.get("lineage_by_candidate_id", {})
    lineage_by_index = entity_rows.get("lineage_by_candidate_index", {})
    by_id = by_id if isinstance(by_id, dict) else {}
    by_index = by_index if isinstance(by_index, dict) else {}
    lineage_by_id = lineage_by_id if isinstance(lineage_by_id, dict) else {}
    lineage_by_index = lineage_by_index if isinstance(lineage_by_index, dict) else {}
    candidate_ids = (
        provider_metadata.get("candidate_ids")
        or provider_metadata.get("sample_candidate_ids")
        or provider_metadata.get("support_candidate_ids")
        or []
    )
    if not isinstance(candidate_ids, (list, tuple)):
        candidate_ids = []
    support_identity_required = bool(
        teacher.get("paper_lineage_required", False)
        or teacher.get("support_identity_required", False)
    )
    strict_source_index_fallback_allowed = bool(
        support_identity_required
        and sample_index_map is None
        and _external_teacher_strict_vanilla_source_index_fallback_allowed(
            provider_metadata,
            support_count=int(support_count),
            config_asserts_vanilla_source_index_identity=(
                config_asserts_vanilla_source_index_identity
            ),
        )
    )
    weights = torch.zeros(int(support_count), dtype=dtype, device=device)
    matched = 0
    id_matched = 0
    canonical_id_matched = 0
    index_matched = 0
    strict_source_index_fallback_matched = 0
    nonvanilla_index_fallback_blocked = 0
    raw_mass = 0.0
    sample_lineage: dict[int, dict[str, Any]] = {}
    for sample_index in range(int(support_count)):
        sample_weight = 0.0
        sample_lineage_row: dict[str, Any] | None = None
        index_fallback_allowed = (not support_identity_required) or (
            sample_index_map is not None
        ) or (
            strict_source_index_fallback_allowed
        )
        if sample_index < len(candidate_ids):
            candidate_id = str(candidate_ids[sample_index])
            if (
                _teacher_bioemu_sample_alias_is_nonvanilla(candidate_id)
                and sample_index_map is None
            ):
                index_fallback_allowed = False
            for lookup_position, lookup_key in enumerate(
                _teacher_candidate_id_lookup_keys(candidate_id)
            ):
                sample_weight = float(by_id.get(lookup_key, 0.0))
                if sample_weight <= 0.0:
                    continue
                id_matched += 1
                if lookup_position > 0:
                    canonical_id_matched += 1
                lineage = lineage_by_id.get(lookup_key)
                if isinstance(lineage, dict):
                    sample_lineage_row = dict(lineage)
                break
        if sample_weight <= 0.0 and index_fallback_allowed:
            candidate_index = _sidecar_sample_index(sample_index, sample_index_map)
            sample_weight = float(by_index.get(int(candidate_index), 0.0))
            if sample_weight > 0.0:
                index_matched += 1
                if strict_source_index_fallback_allowed:
                    strict_source_index_fallback_matched += 1
                lineage = lineage_by_index.get(int(candidate_index))
                if isinstance(lineage, dict):
                    sample_lineage_row = dict(lineage)
        elif sample_weight <= 0.0 and not index_fallback_allowed:
            nonvanilla_index_fallback_blocked += 1
        if sample_weight <= 0.0:
            continue
        weights[sample_index] = float(sample_weight)
        if isinstance(sample_lineage_row, dict):
            sample_lineage[int(sample_index)] = sample_lineage_row
        raw_mass += float(sample_weight)
        matched += 1
    if matched <= 0 or raw_mass <= 0.0:
        return None
    weights = weights / weights.sum().clamp_min(1.0e-12)
    diagnostics = {
        "cell_count": int(matched),
        "shared_q_oracle_ess": float(
            (1.0 / weights.square().sum().clamp_min(1.0e-12)).detach().cpu()
        ),
        "shared_q_oracle_top_mass": float(torch.max(weights).detach().cpu()),
        "shared_q_oracle_energy_weight_mean": 1.0,
        "shared_q_oracle_energy_weight_max": 1.0,
        "shared_q_oracle_source_is_sidecar": 1.0,
        "shared_q_oracle_source_is_external_global_teacher": 1.0,
        "shared_q_oracle_support_coverage_mean": float(matched) / float(
            max(int(support_count), 1)
        ),
        "shared_q_oracle_solver_is_bme": 0.0,
        "external_global_family_teacher_matched_samples": float(matched),
        "external_global_family_teacher_id_matched_samples": float(id_matched),
        "external_global_family_teacher_canonical_id_matched_samples": float(
            canonical_id_matched
        ),
        "external_global_family_teacher_index_matched_samples": float(index_matched),
        "external_global_family_teacher_strict_source_index_fallback_allowed": float(
            strict_source_index_fallback_allowed
        ),
        "external_global_family_teacher_config_asserts_vanilla_source_index_identity": float(
            bool(config_asserts_vanilla_source_index_identity)
        ),
        "external_global_family_teacher_strict_source_index_fallback_matched_samples": float(
            strict_source_index_fallback_matched
        ),
        "external_global_family_teacher_nonvanilla_index_fallback_blocked_samples": float(
            nonvanilla_index_fallback_blocked
        ),
        "external_global_family_teacher_raw_mass": float(raw_mass),
        "external_global_family_teacher_support_count": float(int(support_count)),
        "external_global_family_teacher_support_identity_required": float(
            support_identity_required
        ),
        "external_global_family_teacher_entity_rows": float(
            entity_rows.get("row_count", 0)
        ),
        "external_global_family_teacher_entity_weight_sum": float(
            entity_rows.get("weight_sum", 0.0)
        ),
        "external_global_family_teacher_required_family_complete_rows": float(
            entity_rows.get("required_family_complete_rows", 0)
        ),
        "external_global_family_teacher_skipped_incomplete_rows": float(
            entity_rows.get("skipped_incomplete_rows", 0)
        ),
        "external_global_family_teacher_skipped_zero_coverage_rows": float(
            entity_rows.get("skipped_zero_coverage_rows", 0)
        ),
        "external_global_family_teacher_paper_lineage_required": float(
            bool(teacher.get("paper_lineage_required", False))
        ),
        "external_global_family_teacher_paper_lineage_rows": float(
            entity_rows.get("paper_lineage_rows", 0)
        ),
        "external_global_family_teacher_paper_lineage_rejected_rows": float(
            entity_rows.get("paper_lineage_rejected_rows", 0)
        ),
        "external_global_family_teacher_global_paper_lineage_rows": float(
            teacher.get("paper_lineage_rows", 0)
        ),
        "external_global_family_teacher_global_paper_lineage_rejected_rows": float(
            teacher.get("paper_lineage_rejected_rows", 0)
        ),
        "external_global_family_teacher_coverage_weight_power": float(
            entity_rows.get("coverage_weight_power", 0.0)
        ),
        "external_global_family_teacher_diagnostic_active_subset_probe": float(
            bool(teacher.get("diagnostic_active_subset_probe", False))
        ),
        "external_global_family_teacher_lineage_matched_samples": float(
            len(sample_lineage)
        ),
        "external_global_family_teacher_structure_lineage_samples": float(
            sum(
                str(row.get("structure_path", "")).strip() != ""
                for row in sample_lineage.values()
            )
        ),
    }
    return {"weights": weights, "diagnostics": diagnostics, "sample_lineage": sample_lineage}


