                    oracle_distill_metrics[
                        "cs_reweighting_teacher_generated_prior_ramp_start_scale"
                    ] = float(min(max(generated_prior_ramp_start_scale, 0.0), 1.0))
                    oracle_distill_metrics[
                        "cs_reweighting_teacher_generated_prior_ramp_power"
                    ] = float(max(generated_prior_ramp_power, 0.0))
                    oracle_distill_metrics[
                        "cs_reweighting_teacher_generated_prior_ramp_scale"
                    ] = float(generated_prior_ramp_scale)
                    oracle_distill_metrics[
                        "cs_reweighting_teacher_generated_prior_ramp_progress"
                    ] = float(generated_prior_ramp_progress)
                    oracle_distill_metrics[
                        "cs_reweighting_teacher_generated_prior_topk_ramp_scale"
                    ] = float(generated_prior_topk_ramp_scale)
                    oracle_distill_metrics[
                        "cs_reweighting_teacher_generated_prior_topk_ramp_progress"
                    ] = float(generated_prior_topk_ramp_progress)
