                        risk_scale=float(
                            getattr(
                                config,
                                "bioemu_x0_rowwise_support_rank_risk_scale",
                                0.0,
                            )
                        ),
                        min_context_weight=float(
                            getattr(
                                config,
                                "bioemu_x0_rowwise_support_rank_min_context_weight",
                                1.0,
                            )
                        ),
                        gap_focus_scale=float(
                            getattr(
                                config,
                                "bioemu_x0_rowwise_support_rank_gap_focus_scale",
                                0.0,
                            )
                        ),
